INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_ffb0ae73166d','bk_ncert_english','12-1-i-sell-my-dreams','12.1 I Sell my Dreams',NULL,'public',70,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_450a643d4fb2','ch_ffb0ae73166d','text','{"text": "One morning at nine o’clock, while we were having breakfast on the terrace of the Havana Riviera Hotel under a bright sun, a huge wave picked up several cars that were driving down the avenue along the seawall or parked on the pavement, and embedded one of them in the side of the hotel. It was like an explosion of dynamite that sowed panic on all twenty floors of the building and turned the great entrance window to dust."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7f9b3db53bcb','ch_ffb0ae73166d','text','{"text": "The many tourists in the lobby were thrown into the air along with the furniture, and some were cut by the hailstorm of glass. The wave must have been immense, because it leaped over the wide twoway street between the seawall and the hotel and still had enough force to shatter the window. The cheerful Cuban volunteers, with the help of the fire department, picked up the debris in less than six hours, and sealed off the gate to the sea and installed another, and everything returned to normal."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba2f714ce43b','ch_ffb0ae73166d','text','{"text": "During the morning nobody worried about the car encrusted in the wall, for people assumed it was one of those that had been parked on the pavement. But when the crane lifted it out of its setting, the body of a woman was found secured behind the steering wheel by a seat belt. The blow had been so brutal that not a single one of her bones was left whole. Her face was destroyed, her boots had been ripped apart, and her clothes were in shreds."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_121943cc346d','ch_ffb0ae73166d','text','{"text": "She wore a gold ring shaped like a serpent, with emerald eyes. The police established that she was the housekeeper for the new Portuguese ambassador and his wife. She had come to Havana with them two weeks before and had left that morning for the market, driving a new car. Her name meant nothing to me when I read it in the newspaper, but I was intrigued by the snake ring and its emerald eyes. I could not find out, however, on which finger she wore it."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dba2dced8424','ch_ffb0ae73166d','text','{"text": "This was a crucial piece of information, because I feared she was an unforgettable woman whose real name I never knew, and who wore a similar ring on her right forefinger which, in those days, was even more unusual than it is now. I had met her thirty-four years earlier in Vienna, eating sausage with boiled potatoes and drinking draft beer in a tavern frequented by Latin American students."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1f99d045d95','ch_ffb0ae73166d','text','{"text": "I had come from Rome that morning, and I still remember my immediate response to her splendid soprano’s bosom, the languid foxtails on her coat collar, and that Egyptian ring in the shape of a serpent. She spoke an elementary Spanish in a metallic accent without pausing for breath, and I thought she was the only Austrian at the long wooden table. But no, she had been born in Colombia and had come to Austria between the wars, when she was little more than a child, to study music and voice."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b94497915449','ch_ffb0ae73166d','text','{"text": "She was about thirty, and did not carry her years well, for she had never been pretty and had begun to age before her time. But she was a charming human being. And one of the most awe-inspiring. Vienna was still an old imperial city, whose geographical position between the two irreconcilable worlds left behind by the Second World War had turned it into a paradise of black marketeering and international espionage."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_246eb7302577','ch_ffb0ae73166d','text','{"text": "I could not have imagined a more suitable spot for my fugitive compatriot, who still ate in the students’ tavern on the corner only out of loyalty to her origins, since she had more than enough money to buy meals for all her table companions. She never told her real name, and we always knew her by the Germanic tongue twister that we Latin American students in Vienna invented for her: Frau Frieda."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d8509f938cc0','ch_ffb0ae73166d','text','{"text": "I had just been introduced to her when I committed the happy impertinence of asking how she had come to be in a world so distant and different from the windy cliffs of Quindio, and she answered with a devastating:"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8fa8bfdd90f0','ch_ffb0ae73166d','text','{"text": "‘I sell my dreams.’"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca23173b8030','ch_ffb0ae73166d','text','{"text": "In reality, that was her only trade. She had been the third of eleven children born to a prosperous shopkeeper in old Caldas, and as soon as she learned to speak she instituted the fine custom in her family of telling dreams before breakfast, the time when their oracular qualities are preserved in their purest form. When she was seven she dreamed that one of her brothers was carried off by a flood."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a6779c2bec4','ch_ffb0ae73166d','text','{"text": "Her mother, out of sheer religious superstition, forbade the boy to swim in the ravine, which was his favourite pastime. But Frau Frieda already had her own system of prophecy."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bfdcc2a5c95e','ch_ffb0ae73166d','text','{"text": "‘What that dream means,’ she said, ‘isn’t that he’s going to drown, but that he shouldn’t eat sweets.’"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_635ed2ca931a','ch_ffb0ae73166d','text','{"text": "Her interpretation seemed an infamy to a five-year-old boy who could not live without his Sunday treats. Their mother, convinced of her daughter’s oracular talents, enforced the warning with an iron hand. But in her first careless moment the boy choked on a piece of caramel that he was eating in secret, and there was no way to save him. Frau Frieda did not think she could earn a living with her talent until life caught her by the throat during the cruel Viennese winters."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fee31df7309b','ch_ffb0ae73166d','text','{"text": "Then she looked for work at the first house where she would have liked to live, and when she was asked what she could do, she told only the truth:"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd1793a7ff65','ch_ffb0ae73166d','text','{"text": "‘I dream.’"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fdb8ae1a6617','ch_ffb0ae73166d','text','{"text": "A brief explanation to the lady of the house was all she needed, and she was hired at a salary that just covered her minor expenses, but she had a nice room and three meals a day—breakfast in particular, when the family sat down to learn the immediate future of each of its members: the father, a refined financier;"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa10ef67d2a9','ch_ffb0ae73166d','text','{"text": "the mother, a joyful woman passionate about Romantic chamber music;"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_137997c7064b','ch_ffb0ae73166d','text','{"text": "and two children, eleven and nine years old."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5f48b2efc1bc','ch_ffb0ae73166d','text','{"text": "They were all religious and therefore inclined to archaic superstitions, and they were delighted to take in Frau Frieda, whose only obligation was to decipher the family’s daily fate through her dreams. She did her job well, and for a long time, above all during the war years, when reality was more sinister than nightmares. Only she could decide at breakfast what each should do that day, and how it should be done, until her predictions became the sole authority in the house."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_674f9b9a1b1d','ch_ffb0ae73166d','text','{"text": "Her control over the family was absolute: even the faintest sigh was breathed by her order. The master of the house died at about the time I was in Vienna, and had the elegance to leave her a part of his estate on the condition that she continue dreaming for the family until her dreams came to an end. I stayed in Vienna for more than a month, sharing the straitened circumstances of the other students while I waited for money that never arrived."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1de00a9f4092','ch_ffb0ae73166d','text','{"text": "Frau Frieda’s unexpected and generous visits to the tavern were like fiestas in our poverty-stricken regime. One night, in a beery euphoria, she whispered in my ear with a conviction that permitted no delay."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5edfd5d17ad5','ch_ffb0ae73166d','text','{"text": "‘I only came to tell you that I dreamed about you last night,’ she said."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4431a7eaa081','ch_ffb0ae73166d','text','{"text": "‘You must leave right away and not come back to Vienna for five years.’"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6e1578d4c56d','ch_ffb0ae73166d','text','{"text": "Her conviction was so real that I boarded the last train to Rome that same night. As for me, I was so influenced by what she said that from then on I considered myself a survivor of some catastrophe I never experienced. I still have not returned to Vienna. Before the disaster in Havana, I had seen Frau Frieda in Barcelona in so unexpected and fortuitous a way that it seemed a mystery to me."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_64000d9b1a01','ch_ffb0ae73166d','text','{"text": "It happened on the day Pablo Neruda stepped on Spanish soil for the first time since the Civil War, on a stopover during a long sea voyage to Valparaiso. He spent a morning with us hunting big game in the second-hand bookstores, and at Porter he bought an old, dried-out volume with a torn binding for which he paid what would have been his salary for two months at the consulate in Rangoon."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1dc68a2071e','ch_ffb0ae73166d','text','{"text": "He moved through the crowd like an invalid elephant, with a child’s curiosity in the inner workings of each thing he saw, for the world appeared to him as an immense wind-up toy with which life invented itself. I have never known anyone closer to the idea one has of a Renaissance pope: He was gluttonous and refined. Even against his will, he always presided at the table."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1464b1a8afba','ch_ffb0ae73166d','text','{"text": "Matilde, his wife, would put a bib around his neck that belonged in a barbershop rather than a dining room, but it was the only way to keep him from taking a bath in sauce. That day at Carvalleiras was typical."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6071b95862ac','ch_ffb0ae73166d','text','{"text": "He ate three whole lobsters, dissecting them with a surgeon’s skill, and at the same time devoured everyone else’s plate with his eyes and tasted a little from each with a delight that made the desire to eat contagious: clams from Galicia, mussels from Cantabria, prawns from Alicante, sea cucumbers from the Costa Brava. In the meantime, like the French, he spoke of nothing but other culinary delicacies, in particular the prehistoric shellfish of Chile, which he carried in his heart."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8df7ba0dbc81','ch_ffb0ae73166d','text','{"text": "All at once he stopped eating, tuned his lobster’s antennae, and said to me in a very quiet voice:"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d611ce6699b4','ch_ffb0ae73166d','text','{"text": "‘There’s someone behind me who won’t stop looking at me.’"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0756208c78f1','ch_ffb0ae73166d','text','{"text": "I glanced over his shoulder, and it was true. Three tables away sat an intrepid woman in an old-fashioned felt hat and a purple scarf, eating without haste and staring at him. I recognised her right away. She had grown old and fat, but it was Frau Frieda, with the snake ring on her index finger. She was travelling from Naples on the same ship as Neruda and his wife, but they had not seen each other on board."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90c1f749514a','ch_ffb0ae73166d','text','{"text": "We invited her to have coffee at our table, and I encouraged her to talk about her dreams in order to astound the poet. He paid no attention, for from the very beginning he had announced that he did not believe in prophetic dreams."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2edcb0eaa9ae','ch_ffb0ae73166d','text','{"text": "‘Only poetry is clairvoyant,’ he said."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a34afaa5b7d5','ch_ffb0ae73166d','text','{"text": "After lunch, during the inevitable stroll along the Ramblas, I lagged behind with Frau Frieda so that we could renew our memories with no other ears listening. She told me she had sold her properties in Austria and retired to Oporto, in Portugal, where she lived in a house that she described as a fake castle on a hill, from which one could see all the way across the ocean to the Americas."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd7a7f42cbf4','ch_ffb0ae73166d','text','{"text": "Although she did not say so, her conversation made it clear that, dream by dream, she had taken over the entire fortune of her ineffable patrons in Vienna. That did not surprise me, however, because I had always thought her dreams were no more than a stratagem for surviving. And I told her so. She laughed her irresistible laugh."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9e2175c0206','ch_ffb0ae73166d','text','{"text": "‘You’re as impudent as ever,’ she said. And said no more, because the rest of the group had stopped to wait for Neruda to finish talking in Chilean slang to the parrots along the Rambla de los Pájaros. When we resumed our conversation, Frau Frieda changed the subject."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f68305ccfe52','ch_ffb0ae73166d','text','{"text": "‘By the way,’ she said, ‘you can go back to Vienna now.’"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec8c5ee8c0d9','ch_ffb0ae73166d','text','{"text": "Only then did I realise that thirteen years had gone by since our first meeting."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e96cddb053be','ch_ffb0ae73166d','text','{"text": "‘Even if your dreams are false, I’ll never go back,’ I told her."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24fde15cdb84','ch_ffb0ae73166d','text','{"text": "‘Just in case.’"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b157ed474ae','ch_ffb0ae73166d','text','{"text": "At three o’clock we left her to accompany Neruda to his sacred siesta, which he took in our house after solemn preparations that in some way recalled the Japanese tea ceremony. Some windows had to be opened and others closed to achieve the perfect degree of warmth, and there had to be a certain kind of light from a certain direction, and absolute silence. Neruda fell asleep right away, and woke ten minutes later, as children do, when we least expected it."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c7f1ba4f7b8','ch_ffb0ae73166d','text','{"text": "He appeared in the living room refreshed, and with the monogram of the pillowcase imprinted on his cheek."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a51b3a186eef','ch_ffb0ae73166d','text','{"text": "‘I dreamed about that woman who dreams,’ he said."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7c7dbe53b69','ch_ffb0ae73166d','text','{"text": "Matilde wanted him to tell her his dream."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90c6bb56d72e','ch_ffb0ae73166d','text','{"text": "‘I dreamed she was dreaming about me,’ he said."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c885ba13800','ch_ffb0ae73166d','text','{"text": "‘That’s right out of Borges,’ I said. He looked at me in disappointment."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab1363f9dcc0','ch_ffb0ae73166d','text','{"text": "‘Has he written it already?’"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d2abdcbb6d6a','ch_ffb0ae73166d','text','{"text": "‘If he hasn’t he’ll write it sometime,’ I said."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f1a0ae3bde53','ch_ffb0ae73166d','text','{"text": "‘It will be one of his labyrinths.’"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1a39f30a444c','ch_ffb0ae73166d','text','{"text": "As soon as he boarded the ship at six that evening, Neruda took his leave of us, sat down at an isolated table, and began to write fluid verses in the green ink he used for drawing flowers and fish and birds when he dedicated his books. At the first"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b7ee5dcd799','ch_ffb0ae73166d','text','{"text": "‘All ashore’ we looked for Frau Frieda, and found her at last on the tourist deck, just as we were about to leave without saying good-bye."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4eb0122e731d','ch_ffb0ae73166d','text','{"text": "She too had taken a siesta."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a6158185fe1b','ch_ffb0ae73166d','text','{"text": "‘I dreamed about the poet,’ she said."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0a33b502b7e','ch_ffb0ae73166d','text','{"text": "In astonishment I asked her to tell me her dream."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ae63411be5f4','ch_ffb0ae73166d','text','{"text": "‘I dreamed he was dreaming about me,’ she said, and my look of amazement disconcerted her."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b0d02a66826','ch_ffb0ae73166d','text','{"text": "‘What did you expect? Sometimes, with all my dreams, one slips in that has nothing to do with real life.’"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c3aa63082c4e','ch_ffb0ae73166d','text','{"text": "I never saw her again or even wondered about her until I heard about the snake ring on the woman who died in the Havana Riviera disaster. And I could not resist the temptation of questioning the Portuguese ambassador when we happened to meet some months later at a diplomatic reception. The ambassador spoke about her with great enthusiasm and enormous admiration."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74f0626e4478','ch_ffb0ae73166d','text','{"text": "‘You cannot imagine how extraordinary she was,’ he said."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_088082a63799','ch_ffb0ae73166d','text','{"text": "‘You would have been obliged to write a story about her.’"}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3591b097640a','ch_ffb0ae73166d','text','{"text": "And he went on in the same tone, with surprising details, but without the clue that would have allowed me to come to a final conclusion."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ee8ffe224ae3','ch_ffb0ae73166d','text','{"text": "‘In concrete terms,’ I asked at last, ‘what did she do?’"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_116db7efba55','ch_ffb0ae73166d','text','{"text": "‘Nothing,’ he said, with a certain disenchantment."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a509fc7ddbae','ch_ffb0ae73166d','text','{"text": "‘She dreamed.’"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2dc6b2566daa','ch_ffb0ae73166d','list','{"ordered": false, "items": ["Gabriel Garcia Marquez"]}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_222d60fc0ccb','ch_ffb0ae73166d','heading','{"level": 2, "text": "About The Author"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4502ebd25b89','ch_ffb0ae73166d','text','{"text": "Gabriel Garcia Marquez was brought up by his grandparents in Northern Columbia because his parents were poor and struggling. A novelist, shortstory writer and journalist, he is widely considered the greatest living Latin American master of narrative. Marquez won the Nobel Prize in Literature in 1982. His two masterpieces are One Hundred Years in Solitude (1967, tr. 1970) and Love in The Time of Cholera (1985, tr. 1988)."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b5cf97074996','ch_ffb0ae73166d','text','{"text": "His themes are violence, solitude and the overwhelming human need for love. This story reflects, like most of his works, a high point in Latin American magical realism; it is rich and lucid, mixing reality with fantasy."}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a277981d0a91','ch_ffb0ae73166d','text','{"text": "Understanding the Text"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7082f97cd61c','ch_ffb0ae73166d','text','{"text": "1. Did the author believe in the prophetic ability of Frau Frieda?"}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eaa242fee52a','ch_ffb0ae73166d','text','{"text": "2. Why did he think that Frau Frieda’s dreams were a stratagem for surviving?"}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_452540d86872','ch_ffb0ae73166d','text','{"text": "3. Why does the author compare Neruda to a Renaissance pope?"}',72);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_f09aa197eaa1','bk_ncert_english','12-2-eveline','12.2 Eveline',NULL,'public',71,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea12e4299fcf','ch_f09aa197eaa1','text','{"text": "She sat at the window watching the evening invade the avenue. Her head was leaned against the window curtains and in her nostrils was the odour of dusty cretonne. She was tired. Few people passed. The man out of the last house passed on his way home;"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a661a89dce7','ch_f09aa197eaa1','text','{"text": "she heard his footsteps clacking along the concrete pavement and afterwards crunching on the cinder path before the new red houses."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2544a5eb71b2','ch_f09aa197eaa1','text','{"text": "One time there used to be a field there in which they used to play every evening with other people’s children. Then a man from Belfast bought the field and built houses in it—not like their little brown houses but bright brick houses with shining roofs. The children of the avenue used to play together in that field—the Devines, the Waters, the Dunns, little Keogh the cripple, she and her brothers and sisters. Ernest, however, never played: he was too grown up."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e33c38fd495a','ch_f09aa197eaa1','text','{"text": "Her father used often to hunt them in and out of the field with his blackthorn stick;"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8c654ec46e1','ch_f09aa197eaa1','text','{"text": "but usually little Keogh used to keep nix* and call out when he saw her father coming. Still they seemed to have been rather happy then. Her father was not so bad then;"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f702a1107308','ch_f09aa197eaa1','text','{"text": "and besides, her mother was alive. That was a long time ago;"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df3980700cca','ch_f09aa197eaa1','text','{"text": "she and her brothers and sisters were all grown up;"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ba328a25ab5','ch_f09aa197eaa1','text','{"text": "her mother was dead. Tizzie Dunn was dead, too, and the Waters had gone back to England. Everything changes."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a23b8c2e52f','ch_f09aa197eaa1','text','{"text": "Now she was going to go away like the others, to leave her home. Home! She looked round the room, reviewing all its familiar objects which she had dusted once a week for so many years, wondering where on earth all the dust came from. Perhaps she would never see again those familiar objects from which she had never dreamed of being divided."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c10b88e133f8','ch_f09aa197eaa1','text','{"text": "And yet during all those years she had never found out the name of the priest whose yellowing photograph hung on the wall above the broken harmonium beside the coloured print of the promises made to Blessed Margaret Mary Alacoque. He had been a school friend of her father. Whenever he showed the photograph to a visitor her father used to pass it with a casual word:"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5416338a7d0c','ch_f09aa197eaa1','text','{"text": "‘He is in Melbourne now.’"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_150932bafc5e','ch_f09aa197eaa1','text','{"text": "She had consented to go away, to leave her home. Was that wise? She tried to weigh each side of the question. In her home anyway she had shelter and food;"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_324c53cf853e','ch_f09aa197eaa1','text','{"text": "she had those whom she had known all her life about her. Of course she had to work hard, both in the house and at business. What would they say of her in the Stores when they found out that she had run away with a fellow? Say she was a fool, perhaps;"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_954efa66397a','ch_f09aa197eaa1','text','{"text": "and her place would be filled up by advertisement. Miss Gavan would be glad."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cbde8eef8b35','ch_f09aa197eaa1','text','{"text": "She had always had an edge on her, especially whenever there were people listening."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7522a38bf17c','ch_f09aa197eaa1','text','{"text": "‘Miss Hill, don’t you see these ladies are waiting?’"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dfeec738fa83','ch_f09aa197eaa1','text','{"text": "‘Look lively, Miss Hill, please.’"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d75c44a34320','ch_f09aa197eaa1','text','{"text": "She wouId not cry many tears at leaving the Stores. But in her new home, in a distant unknown country, it would not be like that. Then she would be married—she, Eveline. People would treat her with respect then. She would not be treated as her mother had been. Even now, though she was over nineteen, she sometimes felt herself in danger of her father’s violence. She knew it was that that had given her the palpitations."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f913dac49490','ch_f09aa197eaa1','text','{"text": "When they were growing up he had never gone for her, like he used to go for Harry and Ernest, because she was a girl;"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e30521040c0','ch_f09aa197eaa1','text','{"text": "but latterly he had begun to threaten her and say what he would do to her only for her dead mother’s sake. And now she had nobody to protect her. Ernest was dead and Harry, who was in the church decorating business, was nearly always down somewhere in the country. Besides, the invariable squabble for money on Saturday nights had begun to weary her unspeakably."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d814e5876a60','ch_f09aa197eaa1','text','{"text": "She always gave her entire wages—seven shillings—and Harry always sent up what he could but the trouble was to get any money from her father. He said she used to squander the money, that she had no head, that he wasn’t going to give her his hard earned money to throw about the streets, and much more, for he was usually fairly bad on Saturday night. In the end he would give her the money and ask her had she any intention of buying Sunday’s dinner."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e65b418f63a','ch_f09aa197eaa1','text','{"text": "Then she had to rush out as quickly as she could and do her marketing, holding her black leather purse tightly in her hand as she elbowed her way through the crowds and returning home late under her load of provisions. She had hard work to keep the house together and to see that the two young children who had been left to her charge went to school regularly and got their meals regularly."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_54ffa0d0f300','ch_f09aa197eaa1','text','{"text": "It was hard work—a hard life—but now that she was about to leave it she did not find it a wholly undesirable life. She was about to explore another life with Frank. Frank was very kind, manly, open-hearted. She was to go away with him by the night boat to be his wife and to live with him in Buenos Aires where he had a home waiting for her. How well she remembered the first time she had seen him;"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_547505752b1c','ch_f09aa197eaa1','text','{"text": "he was lodging in a house on the main road where she used to visit. It seemed a few weeks ago."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_625827dd25c1','ch_f09aa197eaa1','text','{"text": "He was standing at the gate, his peaked cap pushed back on his head and his hair tumbled forward over a face of bronze. Then they had come to know each other. He used to meet her outside the Stores every evening and see her home. He took her to see The Bohemian Girl and she felt elated as she sat in an unaccustomed part of the theatre with him. He was awfully fond of music and sang a little."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b898be95539','ch_f09aa197eaa1','text','{"text": "People knew that they were courting and, when he sang about the lass that loves a sailor, she always felt pleasantly confused. He used to call her Poppens out of fun. First of all it had been an excitement for her to have a fellow and then she had begun to like him. He had tales of distant countries. He had started as a deck boy at a pound a month on a ship of the Allan Line going out to Canada. He told her the names of the ships he had been on and the names of the different services."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ede7756007f6','ch_f09aa197eaa1','text','{"text": "He had sailed through the Straits of Magellan and he told her stories of the terrible Patagonians. He had fallen on his feet in Buenos Aires, he said, and had come over to the old country just for a holiday. Of course, her father had found out the affair and had forbidden her to have anything to say to him."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_468907d219cc','ch_f09aa197eaa1','text','{"text": "‘I know these sailor chaps,’ he said."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c9f44771d9e','ch_f09aa197eaa1','text','{"text": "One day he had quarrelled with Frank and after that she had to meet her lover secretly. The evening deepened in the avenue. The white of two letters in her lap grew indistinct. One was to Harry;"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1d159bc67d4','ch_f09aa197eaa1','text','{"text": "the other was to her father. Ernest had been her favourite but she liked Harry too. Her father was becoming old lately, she noticed;"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d6a8cb74ba34','ch_f09aa197eaa1','text','{"text": "he would miss her. Sometimes he could be very nice."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f5ef95e7b75','ch_f09aa197eaa1','text','{"text": "Not long before, when she had been laid up for a day, he had read her out a ghost story and made toast for her at the fire. Another day, when their mother was alive, they had all gone for a picnic to the Hill of Howth. She remembered her father putting on her mother’s bonnet to make the children laugh. Her time was running out but she continued to sit by the window, leaning her head against the window curtain, inhaling the odour of dusty cretonne."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_553e9916caf7','ch_f09aa197eaa1','text','{"text": "Down far in the avenue she could hear a street organ playing. She knew the air. Strange that it should come that very night to remind her of the promise to her mother, her promise to keep the home together as long as she could. She remembered the last night of her mother’s illness;"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5214c37ce71a','ch_f09aa197eaa1','text','{"text": "she was again in the close dark room at the other side of the hall and outside she heard a melancholy air of Italy. The organ player had been ordered to go away and given six-pence."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1ef62e75e86','ch_f09aa197eaa1','text','{"text": "She remembered her father strutting back into the sickroom saying:"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1ca2540d22cb','ch_f09aa197eaa1','text','{"text": "‘Damned Italians! coming over here!’ As she mused—the pitiful vision of her mother’s life laid its spell on the very quick of her being that life of commonplace sacrifices closing in final craziness. She trembled as she heard again her mother’s voice saying constantly with foolish insistence:"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ddcfc62637f9','ch_f09aa197eaa1','text','{"text": "‘Derevaun Seraun! Derevaun Seraun!’ She stood up in a sudden impulse of terror."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4956fd56ba53','ch_f09aa197eaa1','text','{"text": "Escape! She must escape! Frank would save her. He would give her life, perhaps love, too. But she wanted to live. Why should she be unhappy? She had a right to happiness. Frank would take her in his arms, fold her in his arms. He would save her. She stood among the swaying crowd in the station at the North Wall. He held her hand and she knew that he was speaking to her, saying something about the passage over and over again. The station was full of soldiers with brown baggages."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bb5dfbc9e58e','ch_f09aa197eaa1','text','{"text": "Through the wide doors of the sheds she caught a glimpse of the black mass of the boat, lying in beside the quay wall, with illumined portholes. She answered nothing. She felt her cheek pale and cold and, out of a maze of distress, she prayed to God to direct her, to show her what was her duty. The boat blew a long mournful whistle into the mist. If she went, tomorrow she would be on the sea with Frank, steaming toward Buenos Aires. Their passage had been booked."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_29839c8afc56','ch_f09aa197eaa1','text','{"text": "Could she still draw back after all he had done for her? Her distress awoke a nausea in her body and she kept moving her lips in silent fervent prayer. A bell clanged upon her heart. She felt him seize her hand:"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c79f401b02b9','ch_f09aa197eaa1','text','{"text": "‘Come!’ All the seas of the world tumbled about her heart. He was drawing her into them: he would drown her. She gripped with both hands at the iron railing."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_083f51dc2007','ch_f09aa197eaa1','text','{"text": "‘Come!’ No! No! No! It was impossible. Her hands clutched the iron in frenzy. Amid the seas she sent a cry of anguish."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_319f14405e23','ch_f09aa197eaa1','text','{"text": "‘Eveline! Evvy!’ He rushed beyond the barrier and called to her to follow."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_876ceb51e968','ch_f09aa197eaa1','text','{"text": "He was shouted at to go on but he still called to her. She set her white face to him, passive, like a helpless animal. Her eyes gave him no sign of love or farewell or recognition."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5f772bab99d8','ch_f09aa197eaa1','list','{"ordered": false, "items": ["James Joyce"]}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e382d6ea06fb','ch_f09aa197eaa1','text','{"text": "About the Author"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2046e762a5a0','ch_f09aa197eaa1','text','{"text": "James Joyce is a major literary figure of the first quarter of the twentieth century. He is known for his bold experiments in narrative techniques in fiction, and Ulysses is his most famous work."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f55f7fe2332d','ch_f09aa197eaa1','text','{"text": "‘Eveline’ is one of the fifteen stories of Dublin life that form Dubliners, first published in 1914. It is a sympathetic portrayal of Eveline, who has within her reach escape from the drudgery of her life but cannot gather enough courage to seize it."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a3793a4c9b2','ch_f09aa197eaa1','text','{"text": "Understanding the Text"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1224b0c2164','ch_f09aa197eaa1','text','{"text": "1. Name the two characters in this story whom Eveline liked and loved, and two she did not. What were the reasons for her feelings towards them?"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af0cde826870','ch_f09aa197eaa1','text','{"text": "2. Describe the conflict of emotions felt by Eveline on the day she had decided to elope with Frank."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4af449e2344a','ch_f09aa197eaa1','text','{"text": "3. Why do you think Eveline let go of the opportunity to escape?"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_766581c90a7d','ch_f09aa197eaa1','text','{"text": "4. What are the signs of Eveline’s indecision that we see as the hour of her departure with Frank neared?"}',53);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_dd2dc401890d','bk_ncert_english','12-3-a-wedding-in-brownsville','12.3 A Wedding in Brownsville',NULL,'public',72,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4bd894c006c0','ch_dd2dc401890d','text','{"text": "The wedding had been a burden to Dr Solomon Margolin from the very beginning. True, it was to take place on a Sunday, but Gretl had been right when she said that was the only evening in the week they could spend together. It always turned out that way. His responsibilities to the community made him give away the evenings that belonged to her."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c3692b356e0','ch_dd2dc401890d','text','{"text": "The Zionists had appointed him to a committee;"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80e180b63077','ch_dd2dc401890d','text','{"text": "he was a board member of a Jewish scholastic society;"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d64c71ca95a','ch_dd2dc401890d','text','{"text": "he had become co-editor of an academic Jewish quarterly. And though he often referred to himself as an agnostic and even an atheist, nevertheless for years he had been dragging Gretl to Seders at Abraham Mekheles’, a Landsman from Sencimin. Dr Margolin treated rabbis, refugees, and Jewish writers without charge, supplying them with medicines and, if necessary, a hospital bed."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80a4b757b2c5','ch_dd2dc401890d','text','{"text": "There had been a time when he had gone regularly to the meetings of the Senciminer Society, had accepted positions in their ranks, and had attended all the parties. Now Abraham Mekheles was marrying off his youngest daughter, Sylvia. The minute the invitation arrived, Gretl had announced her decision: she was not going to let herself be carted off to a wedding somewhere out in the wilds of Brownsville."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d4822fb4fddf','ch_dd2dc401890d','text','{"text": "If he, Solomon, wanted to go and gorge himself on all kinds of greasy food, coming home at three o’clock in the morning, that was his prerogative. Dr Margolin admitted to himself that his wife was right. When would he get a chance to sleep? He had to be at the hospital early Monday morning. Moreover he was on a strict fat-free diet. A wedding like this one would be a feast of poisons."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ed6a3a02c859','ch_dd2dc401890d','text','{"text": "Everything about such celebrations irritated him now: the Anglicised Yiddish, the Yiddishised English, the ear-splitting music and unruly dances. Jewish laws and customs were completely distorted;"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_963c554eeb48','ch_dd2dc401890d','text','{"text": "men who had no regard for Jewishness wore skullcaps;"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1fb8b2224ab0','ch_dd2dc401890d','text','{"text": "and the reverend rabbis and cantors aped the Christian ministers. Whenever he took Gretl to a wedding or Bar Mitzvah, he was ashamed. Even she, born a Christian, could see that American Judaism was a mess."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4a28190c4a8','ch_dd2dc401890d','text','{"text": "At least this time he would be spared the trouble of making apologies to her. Usually after breakfast on Sunday, he and his wife took a walk in Central Park, or, when the weather was mild, went to the Palisades. But today Solomon Margolin lingered in bed. During the years, he had stopped attending functions of the Senciminer Society;"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_243802092b63','ch_dd2dc401890d','text','{"text": "meanwhile the town of Sencimin had been destroyed. His family there had been tortured, burned, gassed."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3091a6da497','ch_dd2dc401890d','text','{"text": "Many Senciminers had survived, and, later, come to America from the camps, but most of them were younger people whom he, Solomon, had not known in the old country. Tonight everyone would be there;"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_051b9f993f35','ch_dd2dc401890d','text','{"text": "the Senciminers belonging to the bride’s family and the Tereshpolers belonging to the groom’s. He knew how they would pester him, reproach him for growing aloof, drop hints that he was a snob. They would address him familiarly, slap him on the back, drag him off to dance."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5b6d7fdfbaa','ch_dd2dc401890d','text','{"text": "Well, even so, he had to go to Sylvia’s wedding. He had already sent out the present. The day had dawned, grey and dreary as dusk. Overnight, a heavy snow had fallen. Solomon Margolin had hoped to make up for the sleep he was going to lose, but unfortunately he had woken even earlier than usual. Finally he got up. He shaved himself meticulously at the bathroom mirror and also trimmed the grey hair at his temples."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c18c5c99f9c','ch_dd2dc401890d','text','{"text": "Today of all days he looked his age: there were bags under his eyes, and his face was lined. Exhaustion showed in his features. His nose appeared longer and sharper than usual;"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a35bee271f6f','ch_dd2dc401890d','text','{"text": "there were deep folds at the sides of his mouth. After breakfast he stretched out on the living-room sofa. From there he could see Gretl, who was standing in the kitchen, ironing—blonde, faded, middle-aged. She had on a skimpy petticoat, and her calves were as muscular as a dancer’s."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_732a09496169','ch_dd2dc401890d','text','{"text": "Gretl had been a nurse in the Berlin hospital where he had been a member of the staff. Of her family, one brother, a Nazi, had died of typhus in a Russian prison camp. A second, who was a Communist, had been shot by the Nazis. Her aged father vegetated at the home of his other daughter in Hamburg, and Gretl sent him money regularly. She herself had become almost Jewish in New York. She had made friends with Jewish women, joined Hadassah, learned to cook Jewish dishes. Even her sigh was Jewish."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eac32e6bf497','ch_dd2dc401890d','text','{"text": "And she lamented continually over the Nazi catastrophe. She had her plot waiting for her beside his in that part of the cemetery that the Senciminers had reserved for themselves. Dr Margolin yawned, reached for the cigarette that lay in an ashtray on the coffee table beside him, and began to think about himself. His career had gone well. Ostensibly he was a success. He had an office on West End Avenue and wealthy patients."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c9aebe0908f','ch_dd2dc401890d','text','{"text": "His colleagues respected him, and he was an important figure in Jewish circles in New York. What more could a boy from Sencimin expect? A self-taught man, the son of a poor teacher of Talmud? In person he was tall and quite handsome, and he had always had a way with women. He still pursued them—more than was good for him at his age and with his high blood pressure. But secretly Solomon Margolin had always felt that he was a failure."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3526e05b5cf','ch_dd2dc401890d','text','{"text": "As a child he had been acclaimed a prodigy, reciting long passages of the Bible and studying the Talmud and Commentaries on his own. When he was a boy of eleven, he had sent for a Responsum to the rabbi of Tarnow who had referred to him in his reply as"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32e2a070eb36','ch_dd2dc401890d','text','{"text": "‘great and illustrious’."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_957a1f7c312d','ch_dd2dc401890d','text','{"text": "In his teens he had become a master in the Guide for the Perplexed and the Kuzari. He had taught himself algebra and geometry. At seventeen he had attempted a translation of Spinoza’s Ethics from Latin into Hebrew, unaware that it had been done before. Everyone predicted he would turn out to be a genius. But he had squandered his talents, continually changing his field of study;"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25da6b17ddb9','ch_dd2dc401890d','text','{"text": "and he had wasted years in learning languages, in wandering from country to country."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1bdb1819f917','ch_dd2dc401890d','text','{"text": "Nor had he had any luck with his one great love, Raizel, the daughter of Melekh the watchmaker. Raizel had married someone else and later had been shot by the Nazis. All his life Solomon Margolin had been plagued by the eternal questions. He still lay awake at night trying to solve the mysteries of the universe. He suffered from hypochondria and the fear of death haunted even his dreams."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af7f89ff9562','ch_dd2dc401890d','text','{"text": "Hitler’s carnage and the extinction of his family had rooted out his last hope for better days, had destroyed all his faith in humanity. He had begun to despise the matrons who came to him with their petty ills while millions were devising horrible deaths for one another. Gretl came in from the kitchen."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d2de6ff2dd9','ch_dd2dc401890d','text','{"text": "‘What shirt are you going to put on?’ Solomon Margolin regarded her quietly."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2d22d611384c','ch_dd2dc401890d','text','{"text": "She had had her own share of troubles. She had suffered in silence for her two brothers, even for Hans, the Nazi. She had gone through a prolonged change of life. Now her face was flushed and covered with beads of sweat. He earned more than enough to pay for a maid, yet Gretl insisted on doing all the housework herself, even the laundry. It had become a mania with her. Every day she scoured the oven."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f2c66c1e5749','ch_dd2dc401890d','text','{"text": "She was forever polishing the windows of their apartment on the sixteenth floor and without using a safety belt. All the other housewives in the building ordered their groceries delivered, but Gretl lugged the heavy bags from the supermarket herself. Now husband and wife sized each other up wryly, feeling the strangeness that comes of great familiarity. He was always amazed at how she had lost her looks."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c27578164afa','ch_dd2dc401890d','text','{"text": "No one feature had altered, but something in her aspect had given way: her pride, her hopefulness, her curiosity. He blurted out:"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27e7530ae1ef','ch_dd2dc401890d','text','{"text": "‘What shirt? It doesn’t matter."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e2866c73f5da','ch_dd2dc401890d','text','{"text": "A white shirt.’"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c37a03a81cbc','ch_dd2dc401890d','text','{"text": "‘You’re not going to wear the tuxedo? Wait, I’ll bring you a vitamin.’"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_06568c2422aa','ch_dd2dc401890d','text','{"text": "‘I don’t want a vitamin.’"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e46b033aac7c','ch_dd2dc401890d','text','{"text": "‘But you yourself say they’re good for you.’"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_16bd8cb0a4ca','ch_dd2dc401890d','text','{"text": "‘Leave me alone.’"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_63b7451e14ac','ch_dd2dc401890d','text','{"text": "‘Well, it’s your health, not mine.’"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e9ba820f1773','ch_dd2dc401890d','text','{"text": "And slowly she walked out of the room, hesitating as if she expected him to remember something and call her back. Dr Solomon Margolin took a last look in the mirror and left the house. He felt refreshed by the half-hour nap he had had after dinner. Despite his age, he still wanted to impress people with his appearance—even the Senciminers. He had his illusions."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eed1db828713','ch_dd2dc401890d','text','{"text": "In Germany he had taken pride in the fact that he looked like a Junker, and in New York he was often aware that he could pass for an Anglo-Saxon. He was tall, slim, blond, blue-eyed. His hair was thinning, had turned somewhat grey, but he managed to disguise these signs of age. He stooped a little, but in company was quick to straighten up. Years ago in Germany he had worn a monocle and though in New York that would have been too pretentious, his glance still retained a European severity."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00c0da6a5ba1','ch_dd2dc401890d','text','{"text": "He had his principles. He had never broken the Hippocratic Oath. With his patients he was honourable to an extreme, avoiding every kind of cant;"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e9ffd35fbe51','ch_dd2dc401890d','text','{"text": "and he had refused a number of dubious associations that smacked of careerism. Gretl claimed his sense of honour amounted to a mania. Dr Margolin’s car was in the garage— not a Cadillac like that of most of his colleagues—but he decided to go by taxi. He was unfamiliar with Brooklyn and the heavy snow made driving hazardous."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91ec215362c2','ch_dd2dc401890d','text','{"text": "He waved his hand and at once a taxi pulled over to the curb. He was afraid the driver might refuse to go as far as Brownsville, but he flicked the meter on without a word. Dr Margolin peered through the frosted window into the wintry Sunday night but there was nothing to be seen. The New York streets sprawled out, wet, dirty, impenetrably dark. After a while, Dr Margolin leaned back, shut his eyes, and retreated into his own warmth. His destination was a wedding."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_780dbb5bc0da','ch_dd2dc401890d','text','{"text": "Wasn’t the world, like this taxi, plunging away somewhere into the unknown toward a cosmic destination? May be a cosmic Brownsville, a cosmic wedding? Yes. But why did God—or whatever anyone wanted to call Him—create a Hitler, a Stalin? Why did He need world wars? Why heart attacks, cancers? Dr Margolin took out a cigarette and lit it hesitantly."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25cc1dbe5c39','ch_dd2dc401890d','text','{"text": "What had they been thinking of, those pious uncles of his, when they were digging their own graves? Was immortality possible? Was there such a thing as the soul? All the arguments for and against weren’t worth a pinch of dust. The taxi turned onto the bridge across the East River and for the first time Dr Margolin was able to see the sky. It sagged low, heavy, red as glowing metal. Higher up, a violet glare suffused the vault of the heavens."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_adc2adec8d53','ch_dd2dc401890d','text','{"text": "Snow was sifting down gently, bringing a winter peace to the world, just as it had in the past—forty years ago, a thousand years ago, and perhaps a million years ago. Fiery pillars appeared to glow beneath the East River;"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7972033d745','ch_dd2dc401890d','text','{"text": "on its surface, through black waves jagged as rocks, a tugboat was hauling a string of barges loaded with cars. A front window in the cab was open and icy gusts of wind blew in, smelling of gasoline and the sea."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_271659a3f0b5','ch_dd2dc401890d','text','{"text": "Suppose the weather never changed again? Who then would ever be able to imagine a summer day, a moonlit night, spring? But how much imagination for what it’s worth—does a man actually have? On Eastern Parkway the taxi was jolted and screeched suddenly to a stop. Some traffic accident, apparently. The siren on police car shrieked. A wailing ambulance drew nearer. Dr Margolin grimaced. Another victim."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d222f5b3d6d9','ch_dd2dc401890d','text','{"text": "Someone makes a false turn of the wheel and all a man’s plans in this world are reduced to nothing. A wounded man was carried to the ambulance on a stretcher. Above a dark suit and bloodspattered shirt and bow tie the face had a chalky pallor;"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7da2ffe5803f','ch_dd2dc401890d','text','{"text": "one eye was closed, the other partly open and glazed. Perhaps he, too, had been going to a wedding, Dr Margolin thought. He might even have been going to the same wedding as I... Some time later the taxi started moving again."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_81ce7aced6fe','ch_dd2dc401890d','text','{"text": "Solomon Margolin was now driving through streets he had never seen before. It was New York, but it might just as well have been Chicago or Cleveland. They passed through an industrial district with factory buildings, warehouses of coal, lumber, scrap iron. Negroes, strangely black, stood about on the sidewalks, staring ahead, their great dark eyes full of gloomy hopelessness. Occasionally the car would pass a tavern."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_267d1a906e80','ch_dd2dc401890d','text','{"text": "The people at the bar seemed to have something unearthly about them, as if they were being punished here for sins committed in another incarnation. Just when Solomon Margolin was beginning to suspect that the driver, who had remained stubbornly silent the whole time, had gotten lost or else was deliberately taking him out of his way, the taxi entered a thickly populated neighbourhood."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b624392ae72','ch_dd2dc401890d','text','{"text": "They passed a synagogue, a funeral parlour, and there, ahead, was the wedding hall, all lit up, with its neon Jewish sign and Star of David. Dr Margolin gave the driver a dollar tip and the man took it without uttering a word. Dr Margolin entered the outer lobby and immediately the comfortable intimacy of the Senciminers engulfed him. AII the faces he saw were familiar, though he didn’t recognise individuals. Leaving his hat and coat at the checkroom, he put on a skullcap and entered the hall."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7bd40fa9b07b','ch_dd2dc401890d','text','{"text": "It was filled with people and music, with tables heaped with food, a bar stacked with bottles. The musicians were playing an Israeli march that was a hodge-podge of American jazz with Oriental flourishes. Men were dancing with men, women with women, men with women. He saw black skullcaps, white skullcaps, bare heads. Guests kept arriving, pushing their way through the crowd, some still in their hats and coats, munching hors d’oeuvres, drinking schnapps."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9ad9bc38b2a','ch_dd2dc401890d','text','{"text": "The hall resounded with stamping, screaming, laughing, clapping. Flash bulbs went off blindingly as the photographers made their rounds. Seeming to come from nowhere, the bride appeared, briskly sweeping up her train, followed by a retinue of bridesmaids. Dr Margolin knew everybody, and yet knew nobody. People spoke to him, laughed, winked, and waved, and he answered each one with a smile, a nod, a bow. Gradually he threw off all his worries, all his depression."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_06299e461040','ch_dd2dc401890d','text','{"text": "He became half-drunk on the amalgam of odours: flowers, sauerkraut, garlic, perfume, mustard, and that nameless odour that only Senciminers emit."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_099d2dc8689a','ch_dd2dc401890d','text','{"text": "‘Hello, Doctor!’"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef95d1b114c6','ch_dd2dc401890d','text','{"text": "‘Hello Schloime-Dovid, you don’t recognise me, eh? Look, he forgot!’ There were the encounters, the regrets, the reminiscences of long ago."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_29ac2f0f12f8','ch_dd2dc401890d','text','{"text": "‘But after all, weren’t we neighbours? You used to come to our house to borrow the Yiddish newspaper!’ Someone had already kissed him: a badly shaven snout, a mouth reeking of whiskey and rotten teeth."}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1ba95c830c2c','ch_dd2dc401890d','text','{"text": "One woman was so convulsed with laughter that she lost an earring. Margolin tried to pick it up, but it had already been trampled underfoot."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cfb1f90f4d68','ch_dd2dc401890d','text','{"text": "‘You don’t recognise me, eh? Take a good look! It’s Zissel, the son of Chaye Beyle!’"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e63ef22564a9','ch_dd2dc401890d','text','{"text": "‘Why don’t you eat something?’"}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bbc694d69e1f','ch_dd2dc401890d','text','{"text": "‘Why don’t you have something to drink? Come over here."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5eb639a54f93','ch_dd2dc401890d','text','{"text": "Take a glass. What do you want? Whiskey? Brandy? Cognac? Scotch? With soda? With Coca Cola? Take some, it’s good. Don’t let it stand. So long as you’re here, you might as well enjoy yourself.’"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71d987fab81f','ch_dd2dc401890d','text','{"text": "‘My father? He was killed. They were all killed. I’m the only one left of the entire family.’"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2baf157967f9','ch_dd2dc401890d','text','{"text": "‘Berish the son of Feivish? Starved to death in Russia—they sent him to Kazakhstan. His wife? In Israel. She married a Lithuanian.’"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22a51c100739','ch_dd2dc401890d','text','{"text": "‘Sorele? Shot. Together with her children.’"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_88b29d1b1cfa','ch_dd2dc401890d','text','{"text": "‘Yentl? Here at the wedding. She was standing here just a moment ago. There she is, dancing with that tall fellow.’"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab6cdf8a719c','ch_dd2dc401890d','text','{"text": "‘Abraham Zilberstein? They burned him in the synagogue with twenty others. A mound of charcoal was all that was left, coal and ash.’"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8fb65a57fdee','ch_dd2dc401890d','text','{"text": "‘Yosele Budnik? He passed away years ago. You must mean Yekele Budnik. He has a delicatessen store right here in Brownsville—married a widow whose husband made a fortune in real estate.’"}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1153a24fca1d','ch_dd2dc401890d','text','{"text": "‘Lechayim, Doctor! Lechayim, Schloime-Dovid! It doesn’t offend you that I call you Schloime-Dovid? To me you’re still the same Schloime-Dovid, the little boy with the blond side-curls who recited a whole tractate of the Talmud by heart."}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3663e4a1880e','ch_dd2dc401890d','text','{"text": "You remember, don’t you? It seems like only yesterday. Your father, may he rest in peace, was beaming with pride...’"}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da347147de0a','ch_dd2dc401890d','text','{"text": "‘Your brother Chayim? Your Uncle Oyzer? They killed everyone, everyone. They took a whole people and wiped them out with German efficiency: gleichgeschaltet!’"}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_008b55f285c9','ch_dd2dc401890d','text','{"text": "‘Have you seen the bride yet? Pretty as a picture, but too much make-up. Imagine, a grandchild of Reb Todros of Radzin! And her grandfather used to wear two skullcaps, one in front and one in back."}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a60253ac2859','ch_dd2dc401890d','text','{"text": "‘Do you see that young woman dancing in the yellow dress? It’s Riva’s sister—their father was Moishe the candlemaker."}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c826091e8c70','ch_dd2dc401890d','text','{"text": "Riva herself? Where all the others ended up: Auschwitz. How close we came ourselves! All of us are really dead, if you want to call it that. We were exterminated, wiped out. Even the survivors carry death in the hearts. But it’s a wedding, we should be cheerful.’"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba5a9f4215d1','ch_dd2dc401890d','text','{"text": "‘Lechayim, Schloime-Dovid! I would like to congratulate you. Have you a son or daughter to marry off? No? Well, it’s better that way. What’s the sense of having children if people are such murderers?’ It was already time for the ceremony, but someone still had not come. Whether it was the rabbi, the cantor, or one of the in-laws who was missing, nobody seemed able to find out. Abraham Mekheles, the bride’s father, rushed around, scowled, waved his hand, whispered in people’s ears."}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79b940a4db86','ch_dd2dc401890d','text','{"text": "He looked strange in his rented tuxedo. The Tereshpol mother-in-law was wrangling with one of the photographers. The musicians never stopped playing for an instant. The drum banged, the bass fiddle growled, the saxophone blared. The dances became faster, more abandoned, and more and more people were drawn in. The young men stamped with such force that it seemed the dance floor would break under them. Small boys romped around like goats, and little girls whirled about wildly together."}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_01a51e1d3e0d','ch_dd2dc401890d','text','{"text": "Many of the men were already drunk. They shouted boasts, howled with laughter, kissed strange women. There was so much commotion that Solomon Margolin could no longer grasp what was being said to him and simply nodded yes to everything. Some of the guests had attached themselves to him, wouldn’t move, and kept pulling him in all directions, introducing him to more and more people from Sencimin and Tereshpol."}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5651d5219c52','ch_dd2dc401890d','text','{"text": "A matron with a nose covered with warts pointed a finger at him, wiped her eyes, called him Schloimele. Solomon Margolin inquired who she was and somebody told him. Names were swallowed up in the tumult. He heard the same words over and over again: died, shot, burned. A man from Tereshpol tried to draw him aside and was shouted down by several Senciminers calling him an intruder who had no business there."}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_380e0db60133','ch_dd2dc401890d','text','{"text": "A latecomer arrived, a horse and buggy driver from Sencimin who had become a millionaire in New York. His wife and children had perished, but, already, he had a new wife. The woman, weighted with diamonds, paraded about in a low-cut gown that bared a back, covered with blotches, to the waist. Her voice was husky."}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e71b3a052b8','ch_dd2dc401890d','text','{"text": "‘Where did she come from? Who was she?’"}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ee6798f06299','ch_dd2dc401890d','text','{"text": "‘Certainly no saint. Her first husband was a swindler who amassed a fortune and then dropped dead. Of what? Cancer. Where? In the stomach. First you don’t have anything to eat, then you don’t have anything to eat with. A man is always working for the second husband.’"}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b4db78522b0f','ch_dd2dc401890d','text','{"text": "‘What is life anyway? A dance on the grave.’"}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbcc3aeaf810','ch_dd2dc401890d','text','{"text": "‘Yes, but as long as you’re playing the game, you have to abide by the rules.’"}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c47c8476e43c','ch_dd2dc401890d','text','{"text": "‘Dr Margolin, why aren’t you dancing? You’re not among strangers."}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25f4d001aa8f','ch_dd2dc401890d','text','{"text": "We’re all from the same dust. Over there you weren’t a doctor. You were only Schloime-Dovid, the son of the Talmud teacher. Before you know it, we’ll all be lying side by side.’"}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_868a96c22e99','ch_dd2dc401890d','text','{"text": "Margolin didn’t recall drinking anything but he felt intoxicated all the same. The foggy hall was spinning like a carousel;"}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f6b40f452364','ch_dd2dc401890d','text','{"text": "the floor was rocking. Standing in a corner, he contemplated the dance. What different expressions the dancers wore. How many combinations and permutations of being the Creator had brought together here. Every face told its own story. They were dancing together, these people, but each one had his own philosophy, his own approach."}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bbd379a1085b','ch_dd2dc401890d','text','{"text": "A man grabbed Margolin and for a while he danced in the frantic whirl. Then, tearing himself loose, he stood apart. Who was that woman? He found his eye caught by her familiar form. He knew her! She beckoned to him. He stood baffled. She looked neither young nor old. Where had he known her—that narrow face, those dark eyes, that girlish smile? Her hair was arranged in the old manner, with long braids wound like a wreath around her head."}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eeb745c6d746','ch_dd2dc401890d','text','{"text": "The grace of Sencimin adorned her—something he, Margolin, had long since forgotten. And those eyes, he was in love with those eyes and had been all his life. He half smiled at her and the woman smiled back. There were dimples in her cheeks. She too appeared surprised. Margolin, though he realised he had begun to blush like a boy, went up to her."}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fc9d560d47e6','ch_dd2dc401890d','text','{"text": "‘I know you—but you’re not from Sencimin?’"}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e07573da0ab7','ch_dd2dc401890d','text','{"text": "‘Yes, from Sencimin.’"}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d1524fdcdda','ch_dd2dc401890d','text','{"text": "He had heard that voice long ago. He had been in love with that voice."}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_396aed8cacf4','ch_dd2dc401890d','text','{"text": "‘From Sencimin—who are you, then?’ Her lips trembled."}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be17b8cc03f3','ch_dd2dc401890d','text','{"text": "‘You’ve forgotten me already?’"}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c22f01f2b58c','ch_dd2dc401890d','text','{"text": "‘It’s a long time since I left Sencimin.’"}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d75f20c4914d','ch_dd2dc401890d','text','{"text": "‘You used to visit my father.’"}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_830b4e75e5c9','ch_dd2dc401890d','text','{"text": "‘Who was your father?’"}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2ed5193b85b','ch_dd2dc401890d','text','{"text": "‘Melekh the watchmaker.’"}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dcedc2c34350','ch_dd2dc401890d','text','{"text": "Dr Margolin shivered."}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0dcde461ecfa','ch_dd2dc401890d','text','{"text": "‘If I’m not out of my mind then I’m seeing things.’"}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b81b17f0736','ch_dd2dc401890d','text','{"text": "‘Why do you say that?’"}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c309c9cc1a9e','ch_dd2dc401890d','text','{"text": "‘Because Raizel is dead.’"}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df4d65601e53','ch_dd2dc401890d','text','{"text": "‘I’m Raizel.’"}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_54884612351f','ch_dd2dc401890d','text','{"text": "‘You’re Raizel? Here? Oh my God, if that’s true—then anything is possible! When did you come to New York?’"}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca937749ee55','ch_dd2dc401890d','text','{"text": "‘Some time ago.’"}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8ea01b314895','ch_dd2dc401890d','text','{"text": "‘From where?’"}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_287ce056cbac','ch_dd2dc401890d','text','{"text": "‘From over there.’"}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8132d28ff7da','ch_dd2dc401890d','text','{"text": "‘But everyone told me that you were all dead.’"}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40d66aab2617','ch_dd2dc401890d','text','{"text": "‘My father, my mother, my brother Hershl...’"}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a38297bac218','ch_dd2dc401890d','text','{"text": "‘But you were married!’"}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a264c9c686e4','ch_dd2dc401890d','text','{"text": "‘I was.’"}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5aecdfc51fba','ch_dd2dc401890d','text','{"text": "‘If that’s true, then anything is possible!’ repeated Dr Margolin, still shaken by the incredible happening."}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_93edd8f0368f','ch_dd2dc401890d','text','{"text": "Someone must have purposely deceived him. But why? He was aware there was a mistake somewhere but could not determine where."}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7992d911a628','ch_dd2dc401890d','text','{"text": "‘Why didn’t you let me know? After all...’"}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_201e0aeb3e89','ch_dd2dc401890d','text','{"text": "He fell silent. She too was silent for a moment."}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b28e6fe511d8','ch_dd2dc401890d','text','{"text": "‘I lost everything. But I still had some pride left.’"}',116);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_34c08d540a64','ch_dd2dc401890d','text','{"text": "‘Come with me somewhere quieter—anywhere. This is the happiest day of my life!’"}',117);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_147879949d95','ch_dd2dc401890d','text','{"text": "‘But it’s night...’"}',118);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc30eb6a2402','ch_dd2dc401890d','text','{"text": "‘Then the happiest night! Almost—as if the Messiah had come, as if the dead had come to life!’"}',119);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5112cac21ef5','ch_dd2dc401890d','text','{"text": "‘Where do you want to go? All right, let’s go.’"}',120);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f5fb702b6e8a','ch_dd2dc401890d','text','{"text": "Margolin took her arm and felt at once the thrill, long forgotten, of youthful desire. He steered her away from the other guests, afraid that he might lose her in the crowd, or that someone would break in and spoil his happiness. Everything had returned on the instant: the embarrassment, the agitation, the joy. He wanted to take her away, to hide somewhere alone with her. Leaving the reception hall, they went upstairs to the chapel where the wedding ceremony was to take place."}',121);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7179dcb4d723','ch_dd2dc401890d','text','{"text": "The door was standing open. Inside, on a raised platform stood the permanent wedding canopy. A bottle of wine and a silver goblet were placed in readiness for the ceremony. The chapel with its empty pews and only one glimmering light was full of shadows. The music, so blaring below, sounded soft and distant up here. Both of them hesitated at the threshold. Margolin pointed to the wedding canopy."}',122);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f4887feea1a','ch_dd2dc401890d','text','{"text": "‘We could have stood there.’"}',123);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_278ae26c8613','ch_dd2dc401890d','text','{"text": "‘Yes.’"}',124);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d5530848b083','ch_dd2dc401890d','text','{"text": "‘Tell me about yourself. Where are you now? What are you doing?’"}',125);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de7c532e7f8a','ch_dd2dc401890d','text','{"text": "‘It is not easy to tell.’"}',126);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3806f58b8d1','ch_dd2dc401890d','text','{"text": "‘Are you alone? Are you attached?’"}',127);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5229b1c45929','ch_dd2dc401890d','text','{"text": "‘Attached? No.’"}',128);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f38f2ca1e02e','ch_dd2dc401890d','text','{"text": "‘Would you never have let me hear from you?’ he asked."}',129);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c4d508fb10d','ch_dd2dc401890d','text','{"text": "She didn’t answer. Gazing at her, he knew his love had returned with full force. Already, he was trembling at the thought that they might soon have to part. The excitement and expectancy of youth filled him. He wanted to take her in his arms and kiss her, but at any moment someone might come in. He stood beside her, ashamed that he had married someone else, that he had not personally confirmed the reports of her death."}',130);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0134ddfb3ab9','ch_dd2dc401890d','text','{"text": "‘How could I have suppressed all this love? How could I have accepted the world without her? And what will happen now with Gretl?—I’ll give her everything, my last cent.’"}',131);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_41cacc2143e5','ch_dd2dc401890d','text','{"text": "He looked round toward the stairway to see if any of the guests had started to come up. The thought came to him that by Jewish law he was not married, for he and Gretl had had only a civil ceremony. He looked at Raizel."}',132);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_877031522724','ch_dd2dc401890d','text','{"text": "‘According to Jewish law, I’m a single man.’"}',133);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c10ba76426d9','ch_dd2dc401890d','text','{"text": "‘Is that so?’"}',134);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53612b2ea184','ch_dd2dc401890d','text','{"text": "‘According to Jewish law, I could lead you up there and marry you.’"}',135);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0423eadbc51c','ch_dd2dc401890d','text','{"text": "She seemed to be considering the import of his words."}',136);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f6f99680a9e','ch_dd2dc401890d','text','{"text": "‘Yes, I realise...’"}',137);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce833069b4d9','ch_dd2dc401890d','text','{"text": "‘According to Jewish law, I don’t even need a ring."}',138);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac19fc0f1ed8','ch_dd2dc401890d','text','{"text": "One can get married with a penny.’"}',139);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0341b095af56','ch_dd2dc401890d','text','{"text": "‘Do you have a penny?’ He put his hand to his breast pocket, but his wallet was gone."}',140);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_593f0091b7ba','ch_dd2dc401890d','text','{"text": "He started searching in his other pockets. Have I been robbed? he wondered. But how? I was sitting in the taxi the whole time. Could someone have robbed me here at the wedding? He was not so much disturbed as surprised. He said falteringly:"}',141);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_88a42762828b','ch_dd2dc401890d','text','{"text": "‘Strange, but I don’t have any money.’"}',142);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a27bfdd4f2b9','ch_dd2dc401890d','text','{"text": "‘We’ll get along without it.’"}',143);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4749e1c739b7','ch_dd2dc401890d','text','{"text": "‘But how am I going to get home?’"}',144);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8ef2aa0cc58','ch_dd2dc401890d','text','{"text": "‘Why go home?’ she said, countering with a question."}',145);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49a2819a5737','ch_dd2dc401890d','text','{"text": "She smiled with that homely smile of hers that was so full of mystery. He took her by the wrist and gazed at her. Suddenly it occurred to him that this could not be his Raizel. She was too young. Probably it was her daughter who was playing along with him, mocking him. For God’s sake, I’m completely confused! he thought. He stood bewildered, trying to untangle the years. He couldn’t tell her age from her features. Her eyes were deep, dark, and melancholy."}',146);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b5eb827b3acb','ch_dd2dc401890d','text','{"text": "She also appeared confused, as if she, too, sensed some discrepancy. The whole thing is a mistake, Margolin told himself. But where exactly was the mistake? And what had happened to the wallet? Could he have left it in the taxi after paying the driver? He tried to remember how much cash he had had in it, but was unable to."}',147);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_223ba75f88d9','ch_dd2dc401890d','text','{"text": "‘I must have had too much to drink. These people have made me drunk—dead drunk!’ For a long time he stood silent, lost in some dreamless state, more profound than a narcotic trance. Suddenly he remembered the traffic collision he had witnessed on Eastern Parkway. An eerie suspicion came over him: perhaps he had been more than a witness? Perhaps he himself had been the victim of that accident! That man on the stretcher looked strangely familiar."}',148);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9223841b3db1','ch_dd2dc401890d','text','{"text": "Dr Margolin began to examine himself as though he were one of his own patients. He could find no trace of pulse or breathing. And he felt oddly deflated as if some physical dimension were missing. The sensation of weight, the muscular tension of his limbs, the hidden aches in his bones, all seemed to be gone. It can’t be, it can’t be, he murmured. Can one die without knowing it? And what will Gretl do? He blurted out:"}',149);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_522c606afd4d','ch_dd2dc401890d','text','{"text": "‘You’re not the same Raizel.’"}',150);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b9a4e92b1d65','ch_dd2dc401890d','text','{"text": "‘No? Then who am I?’"}',151);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9ad883f86580','ch_dd2dc401890d','text','{"text": "‘They shot Raizel.’"}',152);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0da6c6beb75','ch_dd2dc401890d','text','{"text": "‘Shot her? Who told you that?’ She seemed both frightened and perplexed."}',153);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_639c72654d12','ch_dd2dc401890d','text','{"text": "Silently she lowered her head like someone receiving the shock of bad news. Dr Margolin continued to ponder. Apparently Raizel didn’t realise her own condition. He had heard of such a state—what was it called? Hovering in the World of Twilight. The Astral Body wandering in semi-consciousness, detached from the flesh, without being able to reach its destination, clinging to the illusions and vanities of the past."}',154);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_30eb6ee6d8b3','ch_dd2dc401890d','text','{"text": "But could there be any truth to all this superstition? No, as far as he was concerned, it was nothing but wishful thinking. Besides, this kind of survival would be less than oblivion."}',155);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24181b1e97a1','ch_dd2dc401890d','text','{"text": "‘I am most probably in a drunken stupor,’ Dr Margolin decided."}',156);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_13ab2927ee9b','ch_dd2dc401890d','text','{"text": "‘All this may be one long hallucination, perhaps a result of food poisoning...’"}',157);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c37961f93ca','ch_dd2dc401890d','text','{"text": "He looked up, and she was still there. He leaned over and whispered in her ear:"}',158);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b3894edfe825','ch_dd2dc401890d','text','{"text": "‘What’s the difference? As long as we’re together.’"}',159);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d5558f1784d','ch_dd2dc401890d','text','{"text": "‘I’ve been waiting for that all these years.’"}',160);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7e949fda01c','ch_dd2dc401890d','text','{"text": "‘Where have you been?’ She didn’t answer, and he didn’t ask again."}',161);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c7f5752484c8','ch_dd2dc401890d','text','{"text": "He looked around. The empty hall was full, all the seats taken. A ceremonious hush fell over the audience. The music played softly. The cantor intoned the benedictions. With measured steps, Abraham Mekheles led his daughter down the aisle."}',162);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c03bef4b86d','ch_dd2dc401890d','list','{"ordered": false, "items": ["Isaac Bashevis Singer (Translated by Chana Faerslein and Elizabeth Pollet)"]}',163);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b0f490894380','ch_dd2dc401890d','text','{"text": "About the Author"}',164);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aaa9a3811378','ch_dd2dc401890d','text','{"text": "Isaac Bashevis Singer was born in Poland. His father and grandfather were rabbis and he was educated at the Warsaw Rabbinical Seminary."}',165);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cfad851f87fe','ch_dd2dc401890d','text','{"text": "In 1935 he emigrated to the US and since then has worked as a regular journalist and columnist for the New York paper, The Jewish Daily Forward. Apart from some early work published in Warsaw, nearly all his fiction has been written in Yiddish for this journal. It is relatively recently that Singer’s work has been translated on any scale and that his merit, and the endurance of his writing, have been recognised by a general audience. He was awarded the Nobel Prize for literature in 1978."}',166);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f22ee93be6e5','ch_dd2dc401890d','text','{"text": "His publications include—A Friend of Kafka, The Seance and Other Stories."}',167);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d9fe05e114af','ch_dd2dc401890d','text','{"text": "Understanding the Text"}',168);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd8997fa116d','ch_dd2dc401890d','text','{"text": "1. What do you understand of Dr Margolin’s past? How does it affect his present life?"}',169);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6bde914fe67c','ch_dd2dc401890d','text','{"text": "2. What was Dr Margolin’s attitude towards his profession?"}',170);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09c310d5f412','ch_dd2dc401890d','text','{"text": "3. What is Dr Margolin’s view of the kind of life the American Jewish community leads?"}',171);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ddfa44d8e5dd','ch_dd2dc401890d','text','{"text": "4. What were the personality traits that endeared Dr Margolin to others in his community?"}',172);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22475c7048de','ch_dd2dc401890d','text','{"text": "5. Why do you think Dr Margolin had the curious experience at the wedding hall?"}',173);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eed819b4e205','ch_dd2dc401890d','text','{"text": "6. Was the encounter with Raizel an illusion or was the carousing at the wedding-hall illusory? Was Dr Margolin the victim of the accident and was his astral body hovering in the world of twilight?"}',174);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_1387ea2de69e','bk_ncert_english','12-4-tomorrow','12.4 Tomorrow',NULL,'public',73,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_875d3d5c1ca3','ch_1387ea2de69e','text','{"text": "What was known of Captain Hagberd in the little seaport of Colebrook was not exactly in his favour. He did not belong to the place."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b18e5da21127','ch_1387ea2de69e','text','{"text": "He had come to settle there under circumstances not at all mysterious—he used to be very communicative about them at the time—but extremely morbid and unreasonable. He was possessed of some little money evidently, because he bought a plot of ground, and had a pair of ugly yellow brick cottages run up very cheaply. He occupied one of them himself and let the other to Josiah Carvil—blind Carvil, the retired boat-builder—a man of evil repute as a domestic tyrant."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ecf49e8badb9','ch_1387ea2de69e','text','{"text": "These cottages had one wall in common, shared in a line of iron railing dividing their front gardens;"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0bd8cdd4b523','ch_1387ea2de69e','text','{"text": "a wooden fence separated their back gardens. Miss Bessie Carvil was allowed, as it were of right, to throw over it the teacloths, blue rags, or an apron that wanted drying."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d179ddc90cf','ch_1387ea2de69e','text','{"text": "‘It rots the wood, Bessie my girl,’ the captain would remark mildly, from his side of the fence, each time he saw her exercising that privilege."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9621bd0ecf45','ch_1387ea2de69e','text','{"text": "She was a tall girl;.2"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9cd679a6bcd1','ch_1387ea2de69e','text','{"text": "the fence was low, and she could spread her elbows on the top. Her hands would be red with the bit of washing she had done, but her forearms were white and shapely, and she would look at her father’s landlord in silence—in an informed silence which had an air of knowledge, expectation and desire."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c92611e5acb','ch_1387ea2de69e','text','{"text": "‘It rots the wood,’ reported Captain Hagberd."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b149224a8c0a','ch_1387ea2de69e','text','{"text": "‘It is the only unthrifty, careless habit I know in you. Why don’t you have a clothes-line out in your back yard?’ Miss Carvil would say nothing to this—she only shook her head negatively. The tiny back yard on her side had a few stone-bordered little beds of black earth, in which the simple flowers she found time to cultivate appeared somehow extravagantly overgrown, as if belonging to an exotic clime;"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e44b4d9f7c6','ch_1387ea2de69e','text','{"text": "and Captain Hagberd’s upright, hale person, clad in No.1"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_212f7cb9407c','ch_1387ea2de69e','text','{"text": "sailcloth from head to foot, would be emerging knee-deep out of rank grass and the tall weeds on his side of the fence. He appeared, with the colour and uncouth stiffness of the extraordinary material in which he chose to clothe himself—‘for the time being’"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_553d807e667d','ch_1387ea2de69e','text','{"text": ", would be his mumbled remark to any observation on the subject—like a man roughened out of granite, standing in a wilderness not big enough for a decent billiard-room. A heavy figure of a man of stone, with a red handsome face, a blue wandering eye, and a great white beard flowing to his waist and never trimmed as far as Colebrook knew. Seven years before, he had seriously answered"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ef40146ca5f','ch_1387ea2de69e','text','{"text": "‘Next month, I think’ to the chaffing attempt to secure his custom made by that distinguished local wit, the Colebrook barber, who happened to be sitting insolently in the tap-room of the New Inn near the harbour, where the captain had entered to buy an ounce of tobacco."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_89c18c5c85a0','ch_1387ea2de69e','text','{"text": "After paying for his purchase with three half-pence extracted from the corner of a handkerchief which he carried in the cuff of his sleeve, Captain Hagberd went out. As soon as the door was shut the barber laughed."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a44d9abc1de2','ch_1387ea2de69e','text','{"text": "‘The old one and the young one will be strolling arm in arm to get shaved in my place presently. The tailor shall be set to work, and the barber, and the candlestick maker. High old times are coming for Colebrook;"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a016e96f34b','ch_1387ea2de69e','text','{"text": "they are coming, to be sure. It used to be"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ce31a30c518','ch_1387ea2de69e','text','{"text": "‘‘next week’"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a563c2b2973a','ch_1387ea2de69e','text','{"text": "’, now it has come to"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b11dc5cd23b','ch_1387ea2de69e','text','{"text": "‘‘next month’"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_42af773664a4','ch_1387ea2de69e','text','{"text": "’, and so on—soon it will be"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e855b832ab4c','ch_1387ea2de69e','text','{"text": "‘‘next spring’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1107afe25db0','ch_1387ea2de69e','text','{"text": "’, for all I know.’"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22db86240bdc','ch_1387ea2de69e','text','{"text": "Noticing a stranger listening to him with a vacant grin, he explained, stretching out his legs cynically, that this queer old Hagberd, a retired coasting-skipper, was waiting for the return of a son of his. The boy had been driven away from home, he shouldn’t wonder;"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9d16c5d3bc4','ch_1387ea2de69e','text','{"text": "had run away to sea and had never been heard of since. Put to rest in Davy Jones’s locker this many a day, as likely as not."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca8806a75293','ch_1387ea2de69e','text','{"text": "That old man came flying to Colebrook three years ago all in black broadcloth (had lost his wife lately then), getting out of a third-class smoker as if the devil had been at his heels;"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec3387d64dbe','ch_1387ea2de69e','text','{"text": "and the only thing that brought him down was a letter—a hoax probably. Some joker had written to him about a seafaring man with some such name who was supposed to be hanging about some girl or other, either in Colebrook or in the neighbourhood."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7774f4adbc20','ch_1387ea2de69e','text','{"text": "‘Funny, ain’t it?’ The old chap had been advertising in the London papers for Harry Hagberd, and offering rewards for any sort of likely information."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef890c8b1bf0','ch_1387ea2de69e','text','{"text": "And the barber would go on to describe with sardonic gusto how that stranger in mourning had been seen exploring the country, in carts, on foot, taking everybody into his confidence, visiting all the inns and alehouses for miles around, stopping people on the road with his questions, looking into the very ditches almost;"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09b78bf9ff71','ch_1387ea2de69e','text','{"text": "first in the greatest excitement, then with a plodding sort of perseverance, growing slower and slower;"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_031ca2746a00','ch_1387ea2de69e','text','{"text": "and he could not even tell you plainly how his son looked."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_88a1ba9c672b','ch_1387ea2de69e','text','{"text": "The sailor was supposed to be one of two that had left a timber ship, and to have been seen dangling after some girl;"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d65fe8d0fd8e','ch_1387ea2de69e','text','{"text": "but the old man described a boy of fourteen or so—‘a clever-looking, high-spirited boy’"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_322b8a67336b','ch_1387ea2de69e','text','{"text": ". And when people only smiled at this he would rub his forehead in a confused sort of way before he slunk off, looking offended. He found nobody, of course;"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_210be7599193','ch_1387ea2de69e','text','{"text": "not a trace of anybody—never heard of anything worth belief, at any rate;"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8e6fc6b98c47','ch_1387ea2de69e','text','{"text": "but he had not been able, somehow, to tear himself away from Colebrook."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac02d3fc477f','ch_1387ea2de69e','text','{"text": "‘It was the shock of this disappointment, perhaps, coming soon after the loss of his wife, that had driven him crazy on that point,’ the barber suggested, with an air of great psychological insight."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5e0bbf136a60','ch_1387ea2de69e','text','{"text": "After a time the old man abandoned the active search. His son had evidently gone away;"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cfdbdf87d74b','ch_1387ea2de69e','text','{"text": "but he settled himself to wait. His son had been once at least in Colebrook in preference to his native place. There must have been some reason for it, he seemed to think, some very powerful inducement, that would bring him back to Colebrook again."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0df506844ffc','ch_1387ea2de69e','text','{"text": "‘Ha, ha, ha! Why, of course, Colebrook. Where else? That’s the only place in the United Kingdom for your longlost sons. So he sold up his old home in Colchester, and down he comes here. Well, it’s a craze, like any other. Wouldn’t catch me going crazy over any of my youngsters clearing out. I’ve got eight of them at home.’"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_01f0d6293d0f','ch_1387ea2de69e','text','{"text": "The barber was showing off his strength of mind in the midst of a laughter that shook the tap-room. Strange though, that sort of thing, he would confess with the frankness of a superior intelligence, seemed to be catching. His establishment, for instance, was near the harbour, and whenever a sailorman came in for a hair-cut or a shave—if it was a strange face he couldn’t help thinking directly, ‘Suppose he’s the son of old Hagberd!’ He laughed at himself for it. It was a strong craze."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1aef5cfc947','ch_1387ea2de69e','text','{"text": "He could remember the time when the whole town was full of it. But he had his hopes of the old chap yet. He would cure him by a course of judicious chaffing. He was watching the progress of the treatment. Next week—next month—next year! When the old skipper had put off the date of that return till next year, he would be well on his way to not saying any more about it. In other matters he was quite rational, so this, too, was bound to come. Such was the barber’s firm opinion."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_101c78e73a90','ch_1387ea2de69e','text','{"text": "Nobody had ever contradicted him;"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b4fa8c0a1324','ch_1387ea2de69e','text','{"text": "his own hair had gone grey since that time, and Captain Hagberd’s beard had turned quite white, and had acquired a majestic flow over the No.1 canvas suit, which he had made for himself secretly with tarred twine, and had assumed suddenly, coming out in it one fine morning, whereas the evening before he had been seen going home in his mourning of broadcloth."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2a5b939f7cc3','ch_1387ea2de69e','text','{"text": "It caused a sensation in the High Street— shopkeepers coming to their doors, people in the houses snatching up their hats to run out—a stir at which he seemed strangely surprised at first, and then scared;"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8ffcf72bd726','ch_1387ea2de69e','text','{"text": "but his only answer to the wondering questions was that startled and evasive"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e8cc3309126','ch_1387ea2de69e','text','{"text": "‘For the present’."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a15e958fb7ff','ch_1387ea2de69e','text','{"text": "That sensation had been forgotten long ago;"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_779f4dbdf031','ch_1387ea2de69e','text','{"text": "and Captain Hagberd himself, if not forgotten, had come to be disregarded—the penalty of dailiness—as the sun itself is disregarded unless it makes its power felt heavily. Captain Hagberd’s movements showed no infirmity;"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a9f46789eef','ch_1387ea2de69e','text','{"text": "he walked stiffly in his suit of canvas, a quaint and remarkable figure;"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_594d57bd7782','ch_1387ea2de69e','text','{"text": "only his eyes wandered more furtively perhaps than of yore."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb3bfaa9a171','ch_1387ea2de69e','text','{"text": "His manner abroad had lost its excitable watchfulness;"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eac76f494991','ch_1387ea2de69e','text','{"text": "it had become puzzled and diffident, as though he had suspected that there was somewhere about him something slightly compromising, some embarrassing oddity;"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02750bc130de','ch_1387ea2de69e','text','{"text": "and yet had remained unable to discover what on earth this something wrong could be. He was unwilling now to talk with the townsfolk. He had earned for himself the reputation of an awful skinflint, of a miser in the matter of living."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0ea5a27b37f','ch_1387ea2de69e','text','{"text": "He mumbled regretfully in the shops, bought inferior scraps of meat after long hesitations;"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9dd3e95fa7e','ch_1387ea2de69e','text','{"text": "and discouraged all allusions to his costume. It was as the barber had foretold. For all one could tell, he had recovered already from the disease of hope;"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_13c63eee34f9','ch_1387ea2de69e','text','{"text": "and only Miss Bessie Carvil knew that he said nothing about his son’s return because with him it was no longer"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_63540cfb2285','ch_1387ea2de69e','text','{"text": "‘next week’, ‘next month’, or even"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7f6abebcead','ch_1387ea2de69e','text','{"text": "‘next year’. It was"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea2fc34ad2c0','ch_1387ea2de69e','text','{"text": "‘tomorrow’. In their intimacy of back yard and front garden he talked with her paternally, reasonably, and dogmatically, with a touch or arbitrariness. They met on the ground of unreserved confidence, which was authenticated by an affectionate wink now and then. Miss Carvil had come to look forward rather to these winks. At first they had discomposed her: the poor fellow was mad. Afterwards she had learned to laugh at them: there was no harm in him."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1be1bbd99c6','ch_1387ea2de69e','text','{"text": "Now she was aware of an unacknowledged, pleasurable, incredulous emotion, expressed by a faint blush. He winked not in the least vulgarly;"}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f74a3a18a53b','ch_1387ea2de69e','text','{"text": "his thin red face with a wellmodelled curved nose had a sort of distinction—the more so that when he talked to her he looked with a steadier and more intelligent glance. A handsome, hale, upright, capable man, with a white beard. You did not think of his age. His son, he affirmed, had resembled him amazingly from his earliest babyhood."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_652a9aa8c702','ch_1387ea2de69e','text','{"text": "Harry would be one-and-thirty next July, he declared. Proper age to get married with a nice, sensible girl that could appreciate a good home. He was a very high-spirited boy. High-spirited husbands were the easiest to manage. These mean, soft chaps, that you would think butter wouldn’t melt in their mouths, were the ones to make a woman thoroughly miserable. And there was nothing like home—a fireside—a good roof: no turning out of your warm bed in all sorts of weather."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_85d066b56d67','ch_1387ea2de69e','text','{"text": "‘Eh, my dear?’ Captain Hagberd had been one of those sailors that pursue their calling within sight of land."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aec2d5b03154','ch_1387ea2de69e','text','{"text": "One of the many children of a bankrupt farmer, he had been apprenticed hurriedly to a coasting-skipper, and had remained on the coast all his sea life. It must have been a hard one at first: he had never taken to it;"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb04ab7107ec','ch_1387ea2de69e','text','{"text": "his affection turned to the land, with its innumerable houses, with its quiet lives gathered round its firesides."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_343c2a536e04','ch_1387ea2de69e','text','{"text": "Many sailors feel and profess a rational dislike for the sea, but his was a profound and emotional animosity—as if the love of the stabler element had been bred into him through many generations."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0101d8381947','ch_1387ea2de69e','text','{"text": "‘People did not know what they let their boys in for when they let them go to sea,’ he expounded to Bessie."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02abcc17c0b5','ch_1387ea2de69e','text','{"text": "‘As soon make convicts of them at once.’"}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_57720d47c5f4','ch_1387ea2de69e','text','{"text": "He did not believe you ever got used to it. The weariness of such a life got worse as you got older. What sort of trade was it in which more than half your time you did not put your foot inside your house? Directly you got out to sea you had no means of knowing what went on at home. One might have thought him weary of distant voyages: and the longest he had ever made had lasted a fortnight, of which the most part had been spent at anchor, sheltering from the weather."}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a1f05360159','ch_1387ea2de69e','text','{"text": "As soon as his wife had inherited a house and enough to live on (from a bachelor uncle who had made some money in the coal business) he threw up his command of an East-coast collier with a feeling as though he had escaped from the galleys. After all these years he might have counted on the fingers of his two hands all the days he had been out of sight of England. He had never known what it was to be out of soundings."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_83a88510a045','ch_1387ea2de69e','text','{"text": "‘I have never been further than eighty fathoms from the land’ was one of his boasts."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d248b64dff4','ch_1387ea2de69e','text','{"text": "Bessie Carvil heard all these things. In front of their cottage grew an undersized ash;"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d35d69ae0e09','ch_1387ea2de69e','text','{"text": "and on summer afternoons she would bring out a chair on the grass-plot and sit down with her sewing. Captain Hagberd, in his canvas suit, leaned on a spade. He dug every day in his front plot. He turned it over and over several times every year, but was not going to plant anything"}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_265f5edbbfe6','ch_1387ea2de69e','text','{"text": "‘just at present’. To Bessie Carvil he would state more explicitly:"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7f2c1358c4a0','ch_1387ea2de69e','text','{"text": "‘Not till our Harry comes home tomorrow.’"}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec1b0e4b9d51','ch_1387ea2de69e','text','{"text": "And she had heard this formula of hope so often that it only awakened the vaguest pity in her heart for that hopeful old man. Everything was put off in that way, and everything was being prepared likewise for tomorrow. There was a boxful of packets of various flower-seeds to choose from, for the front garden."}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_905dcfd15dad','ch_1387ea2de69e','text','{"text": "‘He will doubtless let you have your say about that, my dear,’ Captain Hagberd intimated to her across the railing."}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_771a1a093d24','ch_1387ea2de69e','text','{"text": "Miss Bessie’s head remained bowed over her work. She had heard all this so many times. But now and then she would rise, lay down her sewing, and come slowly to the fence. There was a charm in these gentle ravings. He was determined that his son should not go away again for the want of a home all ready for him. He had been filling the other cottage with all sorts of furniture. She imagined it all new, fresh with varnish, piled up as in a warehouse."}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f5523ad0e750','ch_1387ea2de69e','text','{"text": "There would be tables wrapped up in sacking: rolls of carpets thick and vertical, like fragments of columns;"}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f0e026689e4','ch_1387ea2de69e','text','{"text": "the gleam of white marble tops in the dimness of the drawn blinds. Captain Hagberd always described his purchases to her, carefully, as to a person having a legitimate interest in them. The overgrown yard of his cottage could be laid over with concrete...after tomorrow."}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49ff55b81bff','ch_1387ea2de69e','text','{"text": "‘We may just as well do away with the fence. You could have your drying-line out, quite clear of your flowers.’"}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_13881cd7f27f','ch_1387ea2de69e','text','{"text": "He winked, and she would blush faintly. This madness that had entered her life through the kind impulses of her heart had reasonable details. What if some day his son returned? But she could not even be quite sure that he ever had a son: and if he existed anywhere he had been too long away. When Captain Hagberd got excited in his talk she would steady him by a pretence of belief, laughing a little to salve her conscience."}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a6e539135632','ch_1387ea2de69e','text','{"text": "Only once she had tried pityingly to throw some doubt on that hope doomed to disappointment, but the effect of her attempt had scared her very much. All at once over that man’s face there came an expression of horror and incredulity, as though he had seen a crack open out in the firmament."}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3256c7941379','ch_1387ea2de69e','text','{"text": "‘You—you—you don’t think he’s drowned!’ For a moment he seemed to her ready to go out of his mind, for in his ordinary state she thought him more sane than people gave him credit for."}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1fa64def2762','ch_1387ea2de69e','text','{"text": "On that occasion the violence of the emotion was followed by a most paternal and complacent recovery."}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f5b2fecd212','ch_1387ea2de69e','text','{"text": "‘Don’t alarm yourself, my dear,’ he said a little cunningly, ‘the sea can’t keep him. He does not belong to it. None of us Hagberds ever did belong to it. Look at me;"}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aafce75b306f','ch_1387ea2de69e','text','{"text": "I didn’t get drowned. Moreover, he isn’t a sailor at all;"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7772ec9d204a','ch_1387ea2de69e','text','{"text": "and if he is not a sailor he’s bound to come back. There’s nothing to prevent him coming back...’"}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70c5eae84904','ch_1387ea2de69e','text','{"text": "His eyes began to wander."}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad39b733ced2','ch_1387ea2de69e','text','{"text": "‘Tomorrow.’"}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e03267482cc0','ch_1387ea2de69e','text','{"text": "She never tried again, for fear the man should go out of his mind on the spot. He depended on her. She seemed the only sensible person in the town;"}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d52c7aae081c','ch_1387ea2de69e','text','{"text": "and he would congratulate himself frankly before her face on having secured such a level-headed wife for his son. The rest of the town, he confided to her once, in a fit of temper, was certainly queer. The way they looked at you—the way they talked to you! He had never got on with anyone in the place. Didn’t like the people."}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a80bffde679','ch_1387ea2de69e','text','{"text": "He would not have left his own country if it had not been clear that his son had taken a fancy to Colebrook. She humoured him in silence, listening patiently by the fence;"}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_29982c71c763','ch_1387ea2de69e','text','{"text": "crocheting with downcast eyes. Blushes came with difficulty on her dead-white complexion, under the negligently twisted opulence of mahogany-coloured hair. Her father was frankly carroty. She had a full figure;"}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d69e93f07bba','ch_1387ea2de69e','text','{"text": "a tired, unrefreshed face."}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76cd432e3ca1','ch_1387ea2de69e','text','{"text": "When Captain Hagberd vaunted the necessity and propriety of a home and the delights of one’s own fireside, she smiled a little, with her lips only. Her home delights had been confined to the nursing of her father during the ten best years of her life. A bestial roaring coming out of an upstairs window would interrupt their talk. She would begin at once to roll up her crochet-work or fold her sewing, without the slightest sign of haste."}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0214807052f','ch_1387ea2de69e','text','{"text": "Meanwhile the howls and roars of her name would go on, making the fishermen strolling upon the seawall on the other side of the road turn their heads towards the cottages. She would go in slowly at the front door, and a moment afterwards there would fall a profound silence. Presently she would reappear, leading by the hand a man, gross and unwieldy like a hippopotamus, with a badtempered, surly face."}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_981f387bb6aa','ch_1387ea2de69e','text','{"text": "He was a widowed boat-builder, whom blindness had overtaken years before in the full flush of business. He behaved to his daughter as if she had been responsible for its incurable character. He had been heard to bellow at the top of his voice, as if to defy Heaven, that he did not care: he had made enough money to have ham and eggs for his breakfast every morning. He thanked God for it, in a fiendish tone as though he were cursing."}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17cab111efdd','ch_1387ea2de69e','text','{"text": "Captain Hagberd had been so unfavourably impressed by his tenant that once he told Miss Bessie, ‘He is a very extravagant fellow, my dear.’"}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_651682aafabb','ch_1387ea2de69e','text','{"text": "She was knitting that day, finishing a pair of socks for her father, who expected her to keep up the supply dutifully. She hated knitting, and, as she was just at the heel part, she had to keep her eyes on her needles."}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_473416be14f4','ch_1387ea2de69e','text','{"text": "‘Of course it isn’t as if he had a son to provide for,’ Captain Hagberd went on a little vacantly."}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_55a41fbe6610','ch_1387ea2de69e','text','{"text": "‘Girls, of course, don’t require so much—h’m—h’m."}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d7f0b879d24','ch_1387ea2de69e','text','{"text": "They don’t run away from home, my dear.’"}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c4c00c2b6716','ch_1387ea2de69e','text','{"text": "‘No,’ said Miss Bessie, quietly. Captain Hagberd, amongst the mounds of turned-up earth, chuckled. With his maritime rig, his weather-beaten face, his beard of Father Neptune, he resembled a deposed sea-god who had exchanged the trident for the spade."}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa7a293127e6','ch_1387ea2de69e','text','{"text": "‘And he must look upon you as already provided for, in a manner. That’s the best of it with the girls. The husbands...’"}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43a7532f64a1','ch_1387ea2de69e','text','{"text": "He winked. Miss Bessie, absorbed in her knitting, coloured faintly."}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1c282c133f00','ch_1387ea2de69e','text','{"text": "‘Bessie! my hat!’ old Carvil bellowed out suddenly."}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c3a974faae9c','ch_1387ea2de69e','text','{"text": "He had been sitting under the tree mute and motionless, like an idol of some remarkably monstrous superstition. He never opened his mouth but to howl for her, at her, sometimes about her;"}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6fecca403491','ch_1387ea2de69e','text','{"text": "and then he did not moderate the terms of his abuse. Her system was never to answer him at all;"}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5c11f09412c','ch_1387ea2de69e','text','{"text": "and he kept up his shouting till he got attended to— till she shook him by the arm, or thrust the mouthpiece of his pipe between his teeth. He was one of the few blind people who smoke."}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c907ea7a9778','ch_1387ea2de69e','text','{"text": "When he felt the hat being put on his head he stopped his noise at once. Then he rose, and they passed together through the gate. He weighed heavily on her arm. During their slow, toilful walks she appeared to be dragging with her for a penance the burden of that infirm bulk."}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_87bb125596c2','ch_1387ea2de69e','text','{"text": "Usually they crossed the road at once (the cottages stood in the fields near the harbour, two hundred yards away from the end of the street), and for a long, long time they would remain in view, ascending imperceptibly the flight of wooden steps that led to the top of the sea-wall. It ran on from east to west, shutting out the Channel like a neglected railway embankment, on which no train had ever rolled within memory of man."}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b0fb3178871a','ch_1387ea2de69e','text','{"text": "Groups of sturdy fishermen would emerge upon the sky, walk along for a bit, and sink without haste. Their brown nets, like the cobwebs of gigantic spiders, lay on the shabby grass of the slope;"}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eeadfbc94b5f','ch_1387ea2de69e','text','{"text": "and looking up from the end of the street, the people of the town would recognise the two Carvils, by the creeping slowness of their gait. Captain Hagberd, pottering aimlessly about his cottages, would raise his head to see how they got on in their promenade."}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7eb834c4e6bd','ch_1387ea2de69e','text','{"text": "He advertised still in the Sunday papers for Harry Hagberd. These sheets were read in foreign parts to the end of the world, he informed Bessie. At the same time he seemed to think that his son was in England—so near to Colebrook that he would of course turn up"}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8584d317e5b7','ch_1387ea2de69e','text','{"text": "‘tomorrow’. Bessie, without committing herself to that opinion in so many words, argued that in that case the expense of advertising was unnecessary;"}',116);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d6c842cb7e6','ch_1387ea2de69e','text','{"text": "Captain Hagberd had better spend that weekly half-crown on himself. She declared she did not know what he lived on. Her argumentation would puzzle him and cast him down for a time."}',117);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_560307d3e03b','ch_1387ea2de69e','text','{"text": "‘They all do it,’ he pointed out."}',118);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c180f135ea55','ch_1387ea2de69e','text','{"text": "There was a whole column devoted to appeals after missing relatives. He would bring the newspaper to show her. He and his wife had advertised for years;"}',119);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0dda0b89c08e','ch_1387ea2de69e','text','{"text": "only she was an impatient woman. The news from Colebrook had arrived the very day after her funeral;"}',120);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aace92a6d816','ch_1387ea2de69e','text','{"text": "if she had not been so impatient she might have been here now, with no more than one day more to wait."}',121);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c85170ff1698','ch_1387ea2de69e','text','{"text": "‘You are not an impatient woman, my dear.’"}',122);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_21ec4ecf0f9e','ch_1387ea2de69e','text','{"text": "‘I’ve no patience with you, sometimes,’ she would say. If he still advertised for his son he did not offer rewards for information any more: for, with the muddled lucidity of a mental derangement, he had reasoned himself into a conviction as clear as daylight that he had already attained all that could be expected in that way. What more could he want? Colebrook was the place, and there was no need to ask for more."}',123);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a465949be22','ch_1387ea2de69e','text','{"text": "Miss Carvil praised him for his good sense, and he was soothed by the part she took in his hope, which had become his delusion;"}',124);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3af12ca694a1','ch_1387ea2de69e','text','{"text": "in that idea which blinded his mind to truth and probability, just as the other old man in the other cottage had been made blind, by another disease, to the light and beauty of the world."}',125);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02d57de888e2','ch_1387ea2de69e','text','{"text": "But anything he could interpret as a doubt—any coldness of assent, or even a simple inattention to the development of his projects of a home with his returned son and his son’s wife—would irritiate him into flings and jerks and wicked side glances. He would dash his spade into the ground and walk to and fro before it. Miss Bessie called it his tantrums. She shook her finger at him."}',126);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e9d04204cea','ch_1387ea2de69e','text','{"text": "Then, when she came out again, after he had parted with her in anger, he would watch out of the corner of his eyes for the least sign of encouragement to approach the iron railings and resume his fatherly and patronising relations. For all their intimacy, which had lasted some years now, they had never talked without a fence or a railing between them. He described to her all the splendours accumulated for the setting-up of their housekeeping, but had never invited her to an inspection."}',127);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7536c2bc869','ch_1387ea2de69e','text','{"text": "No human eye was to behold them till Harry had his first look. In fact, nobody had ever been inside his cottage: he did his own housework, and he guarded his son’s privilege so jealously that the small objects of domestic use he bought sometimes in the town were smuggled rapidly across the front garden under his canvas coat. Then, coming out, he would remark apologetically, ‘It was only a small kettle, my dear.’"}',128);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9fdee65226cd','ch_1387ea2de69e','text','{"text": "And, if not too tired with her drudgery, or worried beyond endurance by her father, she would laugh at him with a blush, and say:"}',129);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_325611530153','ch_1387ea2de69e','text','{"text": "‘That’s all right, Captain Hagberd;"}',130);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7823498a8ce4','ch_1387ea2de69e','text','{"text": "I am not impatient.’"}',131);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aaa6e5729295','ch_1387ea2de69e','text','{"text": "‘Well, my dear, you haven’t long to wait now,’ he would answer with a sudden bashfulness, and looking about uneasily, as though he had suspected that there was something wrong somewhere."}',132);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_acca461b058b','ch_1387ea2de69e','text','{"text": "Every Monday she paid him his rent over the railings. He clutched the shillings greedily. He grudged every penny he had to spend on his maintenance, and when he left her to make his purchases his bearing changed as soon as he got into the street. Away from the sanction of her pity, he felt himself exposed without defence. He brushed the walls with his shoulder."}',133);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c7f97095cc3','ch_1387ea2de69e','text','{"text": "He mistrusted the queerness of the people: yet, by then, even the town children had left off calling after him, and the tradesmen served him without a word. The slightest allusion to his clothing had the power to puzzle and frighten especially, as if it were something utterly unwarranted and incomprehensible. In the autumn, the driving rain drummed on his sailcloth suit saturated almost to the stiffness of sheet iron, with its surface flowing with water."}',134);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9888c183f62a','ch_1387ea2de69e','text','{"text": "When the weather was too bad, he retreated under the tiny porch, and, standing close against the door, looked at his spade left planted in the middle of the yard. The ground was so much dug up all over, that as the season advanced it turned to a quagmire. When it froze hard, he was disconsolate."}',135);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5e3442cbcd8','ch_1387ea2de69e','text','{"text": "What would Harry say? And as he could not have so much of Bessie’s company at that time of year, the roars of old Carvil, that came muffled through the closed windows, calling her indoors, exasperated him greatly."}',136);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97e620c8e8c6','ch_1387ea2de69e','text','{"text": "‘Why don’t that extravagant fellow get you a servant?’ he asked impatiently one mild afternoon."}',137);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea610f5da4ed','ch_1387ea2de69e','text','{"text": "She had thrown something over her head to run out for a while."}',138);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_95be835e99eb','ch_1387ea2de69e','text','{"text": "‘I don’t know,’ said the pale Bessie, wearily, staring away with her heavy-lidded, grey, and unexpectant glance."}',139);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09231f708ec1','ch_1387ea2de69e','text','{"text": "There were always smudgy shadows under her eyes, and she did not seem able to see any change or any end to her life."}',140);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3c52f1a13bd1','ch_1387ea2de69e','text','{"text": "‘You wait till you get married, my dear,’ said her only friend, drawing closer to the fence."}',141);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6bdff9fef194','ch_1387ea2de69e','text','{"text": "‘Harry will get you one.’"}',142);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d572e3c05cfe','ch_1387ea2de69e','text','{"text": "His hopeful craze seemed to mock her own want of hope with so bitter an aptness that in her nervous irritation she could have screamed at him outright. But she only said in self-mockery, and speaking to him as though he had been sane, ‘Why, Captain Hagberd, your son may not even want to look at me.’"}',143);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f2eba75a9eb','ch_1387ea2de69e','text','{"text": "He flung his head back and laughed his throaty affected cackle of anger."}',144);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca6b57971042','ch_1387ea2de69e','text','{"text": "‘What! That boy? Not want to look at the only sensible girl for miles around? What do you think I am here for, my dear—my dear—my dear? What? You wait. You just wait. You’ll see tomorrow. I’ll soon—’"}',145);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_88a39c3116b0','ch_1387ea2de69e','text','{"text": "‘Bessie! Bessie! Bessie!’ howled old Carvil inside."}',146);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb96304dfb85','ch_1387ea2de69e','text','{"text": "‘Bessie!—my pipe!’ That fat blind man had given himself up to a very lust of laziness."}',147);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b194c862908a','ch_1387ea2de69e','text','{"text": "He would not lift his hand to reach for the things she took care to leave at his very elbow. He would not move a limb;"}',148);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07bda42e90bb','ch_1387ea2de69e','text','{"text": "he would not rise from his chair, he would not put one foot before another in that parlour (where he knew his way as well as if he had his sight) without calling her to his side and hanging all his atrocious weight on her shoulder. He would not eat one single mouthful of food without her close attendance. He had made himself helpless beyond his affliction, to enslave her better."}',149);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20722f229f67','ch_1387ea2de69e','text','{"text": "She stood still for a moment, setting her teeth in the dusk, then turned and walked slowly indoors. Captain Hagberd went back to his spade. The shouting in Carvil’s cottage stopped, and after a while the window of the parlour downstairs was lit up. A man coming from the end of the street with a firm leisurely step passed on, but seemed to have caught sight of Captain Hagberd, because he turned back a pace or two. A cold white light lingered in the western sky."}',150);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_14a1db352789','ch_1387ea2de69e','text','{"text": "The man leaned over the gate in an interested manner."}',151);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a41b2c48ea0e','ch_1387ea2de69e','text','{"text": "‘You must be Captain Hagberd,’ he said, with easy assurance."}',152);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f754a7e7560','ch_1387ea2de69e','text','{"text": "The old man spun round, pulling out his spade, startled by the strange voice."}',153);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef28dfd08d19','ch_1387ea2de69e','text','{"text": "‘Yes, I am,’ he answered nervously. The other, smiling straight at him, uttered very slowly:"}',154);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c52f5e25eff','ch_1387ea2de69e','text','{"text": "‘You’ve been advertising for your son, I believe?’"}',155);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_31f0d7b6443a','ch_1387ea2de69e','text','{"text": "‘My son Harry,’ mumbled Captain Hagberd, off his guard for once."}',156);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99f46595bb1f','ch_1387ea2de69e','text','{"text": "‘He’s coming home tomorrow.’"}',157);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ecb78c47564','ch_1387ea2de69e','text','{"text": "‘The devil he is!’ The stranger marvelled greatly, and then went on, with only a slight change of tone:"}',158);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e43e5dd1b88','ch_1387ea2de69e','text','{"text": "‘You’ve grown a beard like Father Christmas himself.’"}',159);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a43ddecd4b60','ch_1387ea2de69e','text','{"text": "Captain Hagberd drew a little nearer, and leaned forward over his spade."}',160);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af61a96129ef','ch_1387ea2de69e','text','{"text": "‘Go your way’, he said, resentfully and timidly at the same time, because he was always afraid of being laughed at."}',161);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07815dad7786','ch_1387ea2de69e','text','{"text": "Every mental state, even madness, has its equilibrium based upon self-esteem. Its disturbance causes unhappiness: and Captain Hagberd lived amongst a scheme of settled notions which it pained him to feel disturbed by people’s grins. Yes, people’s grins were awful. They hinted at something wrong: but what? He could not tell;"}',162);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_06a95d8a0fd4','ch_1387ea2de69e','text','{"text": "and that stranger was obviously grinning—had come on purpose to grin. It was bad enough on the streets, but he had never before been outraged like this."}',163);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1dbb3481d199','ch_1387ea2de69e','text','{"text": "The stranger, unaware how near he was of having his head laid open with a spade, said seriously:"}',164);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b1c70bbbe6a','ch_1387ea2de69e','text','{"text": "‘I am not trepassing where I stand, am I? I fancy there’s something wrong about your news."}',165);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0eeabffa9b40','ch_1387ea2de69e','text','{"text": "Suppose you let me come in.’"}',166);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c17ceab67773','ch_1387ea2de69e','text','{"text": "‘You come in!’ murmured old Hagberd, with inexpressible horror."}',167);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09313371c533','ch_1387ea2de69e','text','{"text": "‘I could give you some real information about your son— the very latest tip, if you care to hear.’"}',168);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7821695e964b','ch_1387ea2de69e','text','{"text": "‘No,’ shouted Hagberd. He began to pace wildly to and fro, he shouldered his spade, he gesticulated with his other arm."}',169);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00b89369067f','ch_1387ea2de69e','text','{"text": "‘Here’s a fellow—a grinning fellow, who says there’s something wrong. I’ve got more information than you’re aware of. I’ve all the information I want. I’ve had it for years—for years—for years—enough to last me till tomorrow. Let you come in, indeed! What would Harry say?’ Bessie Carvil’s figure appeared in black silhouette on the parlour window: then, with the sound of an opening door, flitted out before the other cottage, all black, but with something white over her head."}',170);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d5dc1fb5437c','ch_1387ea2de69e','text','{"text": "These two voices beginning to talk suddenly outside (she had heard them indoors) had given her such an emotion that she could not utter a sound. Captain Hagberd seemed to be trying to find his way out of a cage. His feet squelched in the puddles left by his industry. He stumbled in the holes of the ruined grassplot. He ran blindly against the fence."}',171);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49099def95b0','ch_1387ea2de69e','text','{"text": "‘Here, steady a bit!’ said the man at the gate, gravely, stretching his arm over and catching him by the sleeve."}',172);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0bf46f9346f','ch_1387ea2de69e','text','{"text": "‘Somebody’s been trying to get at you. Hallo! what’s this rig you’ve got on? Storm canvas, by George!’ He had a big laugh."}',173);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1ea20699b650','ch_1387ea2de69e','text','{"text": "‘Well, you are a character!’ Captain Hagberd jerked himself free, and began to back away shrinkingly."}',174);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c2a23b9c2e3c','ch_1387ea2de69e','text','{"text": "‘For the present,’ he muttered, in a crestfallen tone."}',175);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d84dca2e9b6','ch_1387ea2de69e','text','{"text": "‘What’s the matter with him?’ The stranger addressed Bessie with the utmost familiarity, in a deliberate, explanatory tone."}',176);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_624bcb1249d6','ch_1387ea2de69e','text','{"text": "‘I didn’t want to startle the old man’."}',177);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4016d098e51e','ch_1387ea2de69e','text','{"text": "He lowered his voice as though he had known her for years."}',178);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2673d262bfe3','ch_1387ea2de69e','text','{"text": "‘I dropped into a barber’s on my way, to get a two penny shave, and they told me there he was something of a character."}',179);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d55bb06c10a','ch_1387ea2de69e','text','{"text": "The old man has been a character all his life.’"}',180);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b8ec1fc161e1','ch_1387ea2de69e','text','{"text": "Captain Hagberd, daunted by the allusion to his clothing, had retreated inside, taking his spade with him;"}',181);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b89781cda49b','ch_1387ea2de69e','text','{"text": "and the two at the gate, startled by the unexpected slamming of the door, heard the bolts being shot, the snapping of the lock, and the echo of an affected gurgling laugh within."}',182);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51a294304885','ch_1387ea2de69e','text','{"text": "‘I didn’t want to upset him,’ the man said, after a short silence."}',183);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44498b9f31c5','ch_1387ea2de69e','text','{"text": "‘What’s the meaning of all this? He isn’t quite crazy?’"}',184);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6867aed9beeb','ch_1387ea2de69e','text','{"text": "‘He has been worrying a long time about his lost son,’ said Bessie, in a low, apologetic tone."}',185);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f2c54bf7dbd6','ch_1387ea2de69e','text','{"text": "‘Well, I am his son.’"}',186);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1de69c7ea9f','ch_1387ea2de69e','text','{"text": "‘Harry!’ she cried—and was profoundly silent."}',187);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d848e8a381c9','ch_1387ea2de69e','text','{"text": "‘Know my name? Friends with the old man, eh?’"}',188);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_beebc12cb6e4','ch_1387ea2de69e','text','{"text": "‘He’s our landlord,’ Bessie faltered out, catching hold of the iron railing."}',189);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_385e3750ba6b','ch_1387ea2de69e','text','{"text": "‘Owns both them rabbit-hutches, does he?’ commented young Hagberd scornfully:"}',190);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_694c72b16485','ch_1387ea2de69e','text','{"text": "‘just the thing he would be proud of. Can you tell me who’s that chap coming tomorrow? You must know something of it. I tell you, it’s a swindle on the old man—nothing else.’"}',191);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff3b8aeebbfa','ch_1387ea2de69e','text','{"text": "She did not answer, helpless before an insurmountable difficulty, appalled before the necessity, the impossibility and the dread of an explanation in which she and madness seemed involved together."}',192);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ae23a70e5a05','ch_1387ea2de69e','text','{"text": "‘Oh—I am so sorry,’ she murmured."}',193);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_56ae93239371','ch_1387ea2de69e','text','{"text": "‘What’s the matter?’ he said, with serenity."}',194);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1a3f22777ebc','ch_1387ea2de69e','text','{"text": "‘You needn’t be afraid of upsetting me."}',195);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3014d75e64f5','ch_1387ea2de69e','text','{"text": "It’s the other fellow that’ll be upset when he least expects it. I don’t care a hang;"}',196);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4a2f2d9a8cdf','ch_1387ea2de69e','text','{"text": "but there will be some fun when he shows his mug tomorrow. I don’t care that for the old man’s pieces, but right is right. You shall see me put a head on that coon—whoever he is!’ He had come nearer, and towered above her on the other side of the railings. He glanced at her hands."}',197);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e2b558b26cc','ch_1387ea2de69e','text','{"text": "He fancied she was trembling, and it occurred to him that she had her part perhaps in that little game that was to be sprung on his old man tomorrow. He had come just in time to spoil their sport. He was entertained by the idea— scornful of the baffled plot. But all his life he had been full of indulgence for all sorts of women’s tricks;"}',198);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f81a4611150','ch_1387ea2de69e','text','{"text": "she really was trembling very much;"}',199);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e491289839fd','ch_1387ea2de69e','text','{"text": "her wrap had slipped off her head."}',200);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92e6bbbd6dcf','ch_1387ea2de69e','text','{"text": "‘Poor devil!’ he thought."}',201);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9a1dd094dab','ch_1387ea2de69e','text','{"text": "‘Never mind about that chap. I daresay he’ll change his mind before tomorrow. But what about me? I can’t loaf about the gate till the morning.’"}',202);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd8bd6b44098','ch_1387ea2de69e','text','{"text": "She burst out:"}',203);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_41bbfa8836c0','ch_1387ea2de69e','text','{"text": "‘It is you—you yourself that he’s waiting for."}',204);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_30bc33300fcc','ch_1387ea2de69e','text','{"text": "It is you who come tomorrow.’"}',205);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90c6ea2d15a6','ch_1387ea2de69e','text','{"text": "He murmured"}',206);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f6c07b1fc13f','ch_1387ea2de69e','text','{"text": "‘Oh! It’s me!’ blankly, and they seemed to become breathless together. Apparently he was pondering over what he had heard;"}',207);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0cfcc0b7b9d5','ch_1387ea2de69e','text','{"text": "then, without irritation, but evidently perplexed, he said:"}',208);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35e897278fda','ch_1387ea2de69e','text','{"text": "‘I don’t understand."}',209);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f1a94ba71302','ch_1387ea2de69e','text','{"text": "I hadn’t written or anything. It’s my chum who saw the paper and told me—this very morning... Eh? what?’ He bent his ear;"}',210);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1502abf5b1db','ch_1387ea2de69e','text','{"text": "she whispered rapidly, and he listened for a while, muttering the words"}',211);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_73c51e081885','ch_1387ea2de69e','text','{"text": "‘yes’ and"}',212);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e60d10c4798','ch_1387ea2de69e','text','{"text": "‘I see’ at times."}',213);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f68ad3f569dd','ch_1387ea2de69e','text','{"text": "Then, ‘But why won’t today do?’ he queried at last."}',214);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_925910894052','ch_1387ea2de69e','text','{"text": "‘You didn’t understand me!’ she exclaimed impatiently."}',215);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e28800d398ea','ch_1387ea2de69e','text','{"text": "The clear streak of light under the clouds died out in the west. Again he stooped slightly to hear better;"}',216);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_127c28d9f5ac','ch_1387ea2de69e','text','{"text": "and the deep night buried everything of the whispering woman and the attentive man, except the familiar contiguity of their faces, with its air of secrecy and caress. He squared his shoulders;"}',217);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a22a9ad3edaf','ch_1387ea2de69e','text','{"text": "the broad-brimmed shadow of a hat sat cavalierly on his head."}',218);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a13ab9d6e9a','ch_1387ea2de69e','text','{"text": "‘Awkward, this, eh?’ he appealed to her."}',219);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98b734ba1bdc','ch_1387ea2de69e','text','{"text": "‘Tomorrow? Well, well! Never heard tell of anything like this. It’s all tomorrow, then, without any sort of today, as far as I can see.’"}',220);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_784e5afa8198','ch_1387ea2de69e','text','{"text": "She remained still and mute."}',221);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_399a2ecc1008','ch_1387ea2de69e','text','{"text": "‘And you have been encouraging this funny notion,’ he said."}',222);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e9f3da4cad99','ch_1387ea2de69e','text','{"text": "‘I never contradicted him.’"}',223);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5a1b6a514bd9','ch_1387ea2de69e','text','{"text": "‘Why didn’t you?’"}',224);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d5ad973844fb','ch_1387ea2de69e','text','{"text": "‘What for should I?’ she defended herself."}',225);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b5857380d1d','ch_1387ea2de69e','text','{"text": "‘It would only have made him miserable. He would have gone out of his mind.’"}',226);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd0ffe045a06','ch_1387ea2de69e','text','{"text": "‘His mind!’ he muttered, and heard a short nervous laugh from her."}',227);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1ca9fa108a4','ch_1387ea2de69e','text','{"text": "‘Where was the harm? Was I to quarrel with the poor old man? It was easier to half believe it myself.’"}',228);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aeb509b0eba0','ch_1387ea2de69e','text','{"text": "‘Aye, aye,’ he meditated intelligently."}',229);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9131909a9d60','ch_1387ea2de69e','text','{"text": "‘I suppose the old chap got around you somehow with his soft talk. You are good-hearted.’"}',230);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c1475752114','ch_1387ea2de69e','text','{"text": "Her hands moved up in the dark nervously."}',231);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b53e30683f9c','ch_1387ea2de69e','text','{"text": "‘And it might have been true. It was true. It has come. Here it is. This is the tomorrow we have been waiting for.’"}',232);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d61b95c43892','ch_1387ea2de69e','text','{"text": "She drew a breath, and he said good-humouredly:"}',233);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d111deee21b2','ch_1387ea2de69e','text','{"text": "‘Aye, with the door shut. I wouldn’t care if... And you think he could be brought round to recognise me... Eh? What?... You could do it? In a week you say? H’m, I daresay you could—but do you think I could hold out a week in this dead-alive place? Not me. I want either hard work, or an all-fired racket, or more space than there is in the whole of England. I have been in this place, though, once before, and for more than a week."}',234);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_19279d8babb4','ch_1387ea2de69e','text','{"text": "The old man was advertising for me then, and a chum I had with me had a notion of getting a couple of quid out of him by writing a lot of silly nonsense in a letter. That lark did not come off, though. We had to clear out—and none too soon. But this time I’ve a chum waiting for me in London, and besides...’"}',235);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b8e7f1459d9','ch_1387ea2de69e','text','{"text": "Bessie Carvel was breathing quickly."}',236);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8bde649ef1c8','ch_1387ea2de69e','text','{"text": "‘What if 1 tried a knock at the door?’ he suggested."}',237);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43915bd65303','ch_1387ea2de69e','text','{"text": "‘Try,’ she said. Captain Hagberd’s gate squeaked, and the shadow of his son moved on, then stopped with another deep laugh in the throat, like the father’s, only soft and gentle, thrilling to the woman’s heart, awakening to her ears."}',238);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_348772c1a3ac','ch_1387ea2de69e','text','{"text": "‘He isn’t frisky—is he? I would be afraid to lay hold of him."}',239);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_325931e351b9','ch_1387ea2de69e','text','{"text": "The chaps are always telling me I don’t know my own strength.’"}',240);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a597f4ee9717','ch_1387ea2de69e','text','{"text": "‘He’s the most harmless creature that ever lived,’ she interrupted."}',241);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e49f68fc2b20','ch_1387ea2de69e','text','{"text": "‘You wouldn’t say so if you had seen him chasing me upstairs with a hard leather strap,’ he said;"}',242);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f14e175bef6b','ch_1387ea2de69e','text','{"text": "‘I haven’t forgotten it in sixteen years.’"}',243);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_496106594398','ch_1387ea2de69e','text','{"text": "She got warm from head to foot under another soft subdued laugh. At the rat-tat-tat of the knocker her heart flew into her mouth."}',244);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_37fd6c2a3785','ch_1387ea2de69e','text','{"text": "‘Hey, dad! Let me in. I am Harry, I am. Straight! Come back home a day too soon.’"}',245);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_37cbd4c6169e','ch_1387ea2de69e','text','{"text": "One of the windows upstairs ran up."}',246);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0aacd8b4ee7d','ch_1387ea2de69e','text','{"text": "‘A grinning information fellow,’ said the voice of old Hagberd, up in the darkness."}',247);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_618b0e381bc4','ch_1387ea2de69e','text','{"text": "‘Don’t you have anything to do with him. It will spoil everything.’"}',248);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b90fb8a8ce2b','ch_1387ea2de69e','text','{"text": "She heard Harry Hagberd say, ‘Hallo, dad’, then a clanging clatter. The window rumbled down, and he stood before her again."}',249);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b553ea9c0e2d','ch_1387ea2de69e','text','{"text": "‘It’s just like old times. Nearly walloped the life out of me to stop me going away, and now I come back he throws a confounded shovel at my head to keep me out. It grazed my shoulder.’"}',250);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a8646405d826','ch_1387ea2de69e','text','{"text": "She shuddered."}',251);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2dcf33af1426','ch_1387ea2de69e','text','{"text": "‘I wouldn’t care,’ he began, ‘only I spent my last shillings on the railway fare and my last twopence on a shave—out of respect for the old man.’"}',252);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ed7b7d079014','ch_1387ea2de69e','text','{"text": "‘Are you really Harry Hagberd?’ she asked swiftly."}',253);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e9d9749fee5','ch_1387ea2de69e','text','{"text": "‘Can you prove it?’"}',254);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7a98897c11f','ch_1387ea2de69e','text','{"text": "‘Can I prove it? Can any one else prove it?’ he said jovially."}',255);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d7f26e4b0fe','ch_1387ea2de69e','text','{"text": "‘Prove with what? What do I want to prove? There isn’t a single corner in the world, barring England, perhaps, where you could not find some man, or more likely a woman, that would remember me for Harry Hagberd."}',256);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad6c46b3ab78','ch_1387ea2de69e','text','{"text": "I am more like Harry Hagberd than any man alive: and I can prove it to you in a minute, if you will let me step inside your gate.’"}',257);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e28c84242e4','ch_1387ea2de69e','text','{"text": "‘Come in,’ she said."}',258);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_400698e5195d','ch_1387ea2de69e','text','{"text": "He entered then the front garden of the Carvils. His tall shadow strode with a swagger;"}',259);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_beff6a767010','ch_1387ea2de69e','text','{"text": "she turned her back on the window and waited, watching the shape, of which the footfalls seemed the most material part. The light fell on a tilted hat;"}',260);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_11657b6302d1','ch_1387ea2de69e','text','{"text": "a powerful shoulder, that seemed to cleave the darkness;"}',261);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18ec1adf01d8','ch_1387ea2de69e','text','{"text": "on a leg stepping out. He swung about and stood still, facing the illuminated parlour window at her back, turning his head from side to side, laughing softly to himself."}',262);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7422597fa446','ch_1387ea2de69e','text','{"text": "‘Just fancy, for a minute, the old man’s beard stuck on to my chin."}',263);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e9f93095897','ch_1387ea2de69e','text','{"text": "Hey? Now say. I was the very spit of him from a boy.’"}',264);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9cdc45198e78','ch_1387ea2de69e','text','{"text": "‘It’s true,’ she murmured to herself."}',265);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_993b93ddabae','ch_1387ea2de69e','text','{"text": "‘And that’s about as far as it goes."}',266);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18e372a0304e','ch_1387ea2de69e','text','{"text": "He was always one of your domestic characters. Why, I remember how he used to go about looking very sick for three days before he had to leave home on one of his trips to South Shields for coal. He had a standing charter from the gas-works. You would think he was off on a whaling cruise—three years and a tail. Ha, ha! Not a bit of it. Ten days on the outside. The Skimmer of the Seas was a smart craft. Fine name, wasn’t it? Mother’s uncle owned her...’"}',267);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db75f862e7d1','ch_1387ea2de69e','text','{"text": "He interrupted himself, and in a lowered voice, ‘Did he ever tell you what mother died of?’ he asked."}',268);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3afc503c573e','ch_1387ea2de69e','text','{"text": "‘Yes,’ said Miss Bessie, bitterly."}',269);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9d992b1154ea','ch_1387ea2de69e','text','{"text": "‘From impatience.’"}',270);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3dbee869bcae','ch_1387ea2de69e','text','{"text": "He made no sound for a while;"}',271);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff0066aedd1c','ch_1387ea2de69e','text','{"text": "then brusquely:"}',272);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de8b950e9ce2','ch_1387ea2de69e','text','{"text": "‘They were so afraid I would turn out badly that they fairly drove me away. Mother nagged at me for being idle, and the old man said he would cut my soul out of my body rather than let me go to sea. Well, it looked as if he would do it too—so I went. It looks to me sometimes as if I had been born to them by a mistake—in that other hutch of a house.’"}',273);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90976ed20337','ch_1387ea2de69e','text','{"text": "‘Where ought you to have been born by rights?’ Bessie Carvil interrupted him defiantly."}',274);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_64c49e8f5ed5','ch_1387ea2de69e','text','{"text": "‘In the open, upon a beach, on a windy night,’ he said, quick as lightning."}',275);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_359d641bb6b5','ch_1387ea2de69e','text','{"text": "Then he mused slowly."}',276);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c3a75ef567c','ch_1387ea2de69e','text','{"text": "‘They were characters, both of them, by George;"}',277);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cbd4b8231d42','ch_1387ea2de69e','text','{"text": "and the old man keeps it up well—don’t he? A damned shovel on the—Hark! who’s that making that row?"}',278);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3ac21d2ac9b','ch_1387ea2de69e','text','{"text": "‘Bessie, Bessie.’"}',279);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ddb261e0c88','ch_1387ea2de69e','text','{"text": "It’s in your house.’"}',280);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad4f1469fa1f','ch_1387ea2de69e','text','{"text": "‘It’s for me,’ she said with indifference. He stepped aside, out of the streak of light."}',281);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_583c518523ea','ch_1387ea2de69e','text','{"text": "‘Your husband?’ he inquired, with the tone of a man accustomed to unlawful trysts."}',282);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d5811aec44ef','ch_1387ea2de69e','text','{"text": "‘Fine voice for a ship’s deck in a thundering squall.’"}',283);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f69f033e0afc','ch_1387ea2de69e','text','{"text": "‘No;"}',284);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8039deb403aa','ch_1387ea2de69e','text','{"text": "my father. I am not married.’"}',285);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c58dd4e521b','ch_1387ea2de69e','text','{"text": "‘You seem a fine girl, Miss Bessie dear,’ he said at once."}',286);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e34d53ba84a','ch_1387ea2de69e','text','{"text": "She turned her face away."}',287);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44e5a1f9794e','ch_1387ea2de69e','text','{"text": "‘Oh, I say,—what’s up? Who’s murdering him?’"}',288);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff3051466a41','ch_1387ea2de69e','text','{"text": "‘He wants his tea.’"}',289);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_335fa40bf543','ch_1387ea2de69e','text','{"text": "She faced him, still and tall, with averted head, with her hands hanging clasped before her."}',290);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b740a957e8c0','ch_1387ea2de69e','text','{"text": "‘Hadn’t you better go in?’ he suggested, after watching for a while the nape of her neck, a patch of dazzling white skin and soft shadow above the sombre line of her shoulders. Her wrap had slipped down to her elbows."}',291);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_28c396b3c1af','ch_1387ea2de69e','text','{"text": "‘You’ll have all the town coming out presently. I’ll wait here a bit.’"}',292);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_36b20775b4fb','ch_1387ea2de69e','text','{"text": "Her wrap fell to the ground, and he stooped to pick it up: she had vanished. He threw it over his arm, and approaching the window squarely he saw a monstrous form of a fat man in an armchair, an unshaded lamp, the yawning of an enormous mouth in a big feat face encircled by a ragged halo of hair,—Miss Bessie’s head and bust. The shouting stopped;"}',293);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17a06e51da90','ch_1387ea2de69e','text','{"text": "the blind ran down. He lost himself in thinking how awkward it was. Father mad;"}',294);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75550769a3f4','ch_1387ea2de69e','text','{"text": "no getting into the house."}',295);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a23df0248a73','ch_1387ea2de69e','text','{"text": "No money to get back;"}',296);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_564223364aef','ch_1387ea2de69e','text','{"text": "a hungry chum in London who would begin to think he had been given the go-by."}',297);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b7f2ca8aef71','ch_1387ea2de69e','text','{"text": "‘Damn!’ he muttered. He could break the door in, certainly;"}',298);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d1a4dbae642b','ch_1387ea2de69e','text','{"text": "but they would perhaps bundle him into chokey for that without asking questions—no great matter, only he was confoundedly afraid of being locked up, even in mistake. He turned cold at the thought. He stamped his feet on the sodden grass."}',299);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be6f69c59fa3','ch_1387ea2de69e','text','{"text": "‘What are you?—a sailor?’ said an agitated voice."}',300);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75a74b7a354a','ch_1387ea2de69e','text','{"text": "She had flitted out, a shadow herself, attracted by the reckless shadow waiting under the wall of her home."}',301);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_11ddcf9b05ef','ch_1387ea2de69e','text','{"text": "‘Anything. Enough of a sailor to be worth my salt before the mast. Came home that way this time.’"}',302);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_440aed2568a1','ch_1387ea2de69e','text','{"text": "‘Where do you come from?’ she asked."}',303);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_637177868e8a','ch_1387ea2de69e','text','{"text": "‘Right away from a jolly good spree,’ he said, ‘by the London train—see? Ough! I hate being shut up in a train."}',304);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_acb143dcf12a','ch_1387ea2de69e','text','{"text": "I don’t mind a house so much.’"}',305);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d08eacc283d3','ch_1387ea2de69e','text','{"text": "‘Ah,’ she said;"}',306);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8562a996ab50','ch_1387ea2de69e','text','{"text": "‘that’s lucky.’"}',307);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5295271aec68','ch_1387ea2de69e','text','{"text": "‘Because in a house you can at any time open the blamed door and walk away straight before you.’"}',308);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f47cb6ff1e0a','ch_1387ea2de69e','text','{"text": "‘And never come back?’"}',309);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9aab53a3c77f','ch_1387ea2de69e','text','{"text": "‘Not for sixteen years at least,’ he laughed."}',310);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0beaaeafaf7','ch_1387ea2de69e','text','{"text": "‘To a rabbit hutch, and get a confounded old shovel...’"}',311);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_749130f2f921','ch_1387ea2de69e','text','{"text": "‘A ship is not so very big,’ she taunted."}',312);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b3560d584ac','ch_1387ea2de69e','text','{"text": "‘No, but the sea is great.’"}',313);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05c1aaa0116f','ch_1387ea2de69e','text','{"text": "She dropped her head, and as if her ears had been opened to the voices of the world, she heard beyond the rampart of sea-wall the swell of yesterday’s gale breaking on the beach with monotonous and solemn vibrations, as if all the earth had been a tolling bell."}',314);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d2def7f2b29','ch_1387ea2de69e','text','{"text": "‘And then, why, a ship’s a ship."}',315);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_545e2fabf34c','ch_1387ea2de69e','text','{"text": "You love her and leave her;"}',316);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbb948a3c0ff','ch_1387ea2de69e','text','{"text": "and a voyage isn’t a marriage.’"}',317);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb9bf010e68f','ch_1387ea2de69e','text','{"text": "He quoted the sailor’s saying lightly."}',318);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bfea9ef4dcd5','ch_1387ea2de69e','text','{"text": "‘It is not a marriage,’ she whispered."}',319);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4fffa21c8a7f','ch_1387ea2de69e','text','{"text": "‘I never took a false name, and I’ve never yet told a lie to a woman."}',320);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb20d79d797d','ch_1387ea2de69e','text','{"text": "What lie? Why, the lie—. Take me or leave me, I say: and if you take me, then it is...’"}',321);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_69f06f169be9','ch_1387ea2de69e','text','{"text": "He hummed a snatch very low, leaning against the wall. Oh, oh, ho! Rio!... And fare thee well, My bonnie young girl, We’re bound to Rio... Grande."}',322);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a7e276926a5a','ch_1387ea2de69e','text','{"text": "‘Capstan song,’ he explained."}',323);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_123c5132ee43','ch_1387ea2de69e','text','{"text": "Her teeth chattered."}',324);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02bf6effa07a','ch_1387ea2de69e','text','{"text": "‘You are cold,’ he said."}',325);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9be225b64123','ch_1387ea2de69e','text','{"text": "‘Here’s that affair of yours I picked up.’"}',326);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_60cbd0b776eb','ch_1387ea2de69e','text','{"text": "She felt his hands about her, wrapping her closely."}',327);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e60aea93676','ch_1387ea2de69e','text','{"text": "‘Hold the ends together in front,’ he commanded."}',328);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd6e1f6381d5','ch_1387ea2de69e','text','{"text": "‘What did you come here for?’ she asked, repressing a shudder."}',329);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cce0df725088','ch_1387ea2de69e','text','{"text": "‘Five quid,’ he answered promptly."}',330);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b76116e603fd','ch_1387ea2de69e','text','{"text": "‘We let our spree go on a little too long and got hard up.’"}',331);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b10ae287f231','ch_1387ea2de69e','text','{"text": "‘You’ve been drinking?’ she said."}',332);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e69f2948160','ch_1387ea2de69e','text','{"text": "‘Blind three days;"}',333);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2204037e68b4','ch_1387ea2de69e','text','{"text": "on purpose. I am not given that way— don’t you think. There’s nothing and nobody that can get over me unless I like. I can be as steady as a rock. My chum sees the paper this morning and says he to me:"}',334);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e6d4cc8c2e28','ch_1387ea2de69e','text','{"text": "‘Go on, Harry: loving parent. That’s five quid sure.’"}',335);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_831ba98cc169','ch_1387ea2de69e','text','{"text": "So we scraped all our pockets for the fare. Devil of a lark!’"}',336);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b13991d171ca','ch_1387ea2de69e','text','{"text": "‘You have a hard heart, I am afraid,’ she sighed."}',337);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c29e217f2453','ch_1387ea2de69e','text','{"text": "‘What for? For running away? Why! he wanted to make a lawyer’s clerk of me—just to please himself."}',338);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f47c0f8a64c7','ch_1387ea2de69e','text','{"text": "Master in his own house;"}',339);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab2c0b9fe004','ch_1387ea2de69e','text','{"text": "and my poor mother egged him on—for my good, I suppose. Well, then—so long;"}',340);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04c1e4313f6d','ch_1387ea2de69e','text','{"text": "and I went. No, I tell you: the day I cleared out, I was all black and blue from his great fondness for me. Ah! he was always a bit of a character. Look at that shovel, now. Off his chump? Not much. That’s just exactly like my dad. He wants me here just to have somebody to order about. However, we two were hard up;"}',341);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a4fdb4d0864','ch_1387ea2de69e','text','{"text": "and what’s five quid to him—once in sixteen hard years?’"}',342);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da2915c56b5f','ch_1387ea2de69e','text','{"text": "‘Oh, but I am sorry for you. Did you never wait to come back home?’"}',343);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a9df58ea7b5','ch_1387ea2de69e','text','{"text": "‘Be a lawyer’s clerk and rot here—in some such place as this?’ he cried in contempt."}',344);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b3faf434865','ch_1387ea2de69e','text','{"text": "‘What! if the old man set me up in a home today, I would kick it down about my ears— or else die there before the third day was out.’"}',345);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c4d89c7a316','ch_1387ea2de69e','text','{"text": "‘And where else is it that you hope to die?’"}',346);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_004eadfe4133','ch_1387ea2de69e','text','{"text": "‘In the bush somewhere;"}',347);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4139b28572fc','ch_1387ea2de69e','text','{"text": "in the sea;"}',348);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f40e091b5fd','ch_1387ea2de69e','text','{"text": "on a blamed mountain-top for choice. At home? Yes! the world’s my home;"}',349);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25c4bc55ee9c','ch_1387ea2de69e','text','{"text": "but I expect I’ll die in a hospital some day. What of that? Any place is good enough, as long as I’ve lived;"}',350);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_78b41c045197','ch_1387ea2de69e','text','{"text": "and I’ve been everything you can think of almost but a tailor or soldier. I’ve been a boundary rider;"}',351);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c21fa6c65a7d','ch_1387ea2de69e','text','{"text": "I’ve sheared sheep;"}',352);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_200c2c68e8ad','ch_1387ea2de69e','text','{"text": "and humped my swag;"}',353);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4bab6036d956','ch_1387ea2de69e','text','{"text": "and harpooned a whale."}',354);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0138b35a50f7','ch_1387ea2de69e','text','{"text": "I’ve rigged ships, and prospected for gold, and skinned dead bullocks,—and turned my back on more money than the old man would have scraped in his whole life. Ha, ha!’ He overwhelmed her. She pulled herself together and managed to utter, ‘Time to rest now.’"}',355);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_45c666b97b71','ch_1387ea2de69e','text','{"text": "He straightened himself up, away from the wall, and in a severe voice said, ‘Time to go.’"}',356);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f91fe0c5b0a','ch_1387ea2de69e','text','{"text": "But he did not move. He leaned back again, and hummed thoughtfully a bar or two of an outlandish tune. She felt as if she were about to cry."}',357);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_daab0c10fbaf','ch_1387ea2de69e','text','{"text": "‘That’s another of your cruel songs,’ she said."}',358);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40c4a9bb11fe','ch_1387ea2de69e','text','{"text": "‘Learned it in Mexico—in Sonora.’"}',359);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9470b7f5916c','ch_1387ea2de69e','text','{"text": "He talked easily."}',360);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44a28c1a6eee','ch_1387ea2de69e','text','{"text": "‘It is the song of the Gambusinos. You don’t know? The song of restless men. Nothing could hold them in one place— not even a woman. You used to meet one of them now and again, in the old days, on the edge of the gold country, away north there beyond the Rio Gila. I’ve seen it. A prospecting engineer in Mazatlan took me along with him to help look after the waggons. A sailor’s a handy chap to have about you anyhow."}',361);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7517158bd9f3','ch_1387ea2de69e','text','{"text": "It’s all a desert: cracks in the earth that you can’t see the bottom of;"}',362);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51ba8ff20065','ch_1387ea2de69e','text','{"text": "and mountains— sheer rocks standing up high like walls and church spires, only a hundred times bigger. The valleys are full of boulders and black stones. There’s not a blade of grass to see;"}',363);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dedc40cea233','ch_1387ea2de69e','text','{"text": "and the sun sets more red over that country than I have seen it anywhere—blood-red and angry. It is fine.’"}',364);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4da34a22bbaa','ch_1387ea2de69e','text','{"text": "‘You do not want to go back there again?’ she stammered out."}',365);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9d1b7d3030a1','ch_1387ea2de69e','text','{"text": "He laughed a little."}',366);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7da8b2471d45','ch_1387ea2de69e','text','{"text": "‘No. That’s the blamed gold country. It gave me the shivers sometimes to look at it—and we were a big lot of men together, mind;"}',367);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f187d6a36e07','ch_1387ea2de69e','text','{"text": "but these Gambusinos wandered alone. They knew that country before anybody had ever heard of it. They had a sort of gift for prospecting, and the fever of it was on them too;"}',368);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02da88b07c89','ch_1387ea2de69e','text','{"text": "and they did not seem to want the gold very much."}',369);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6947446b5845','ch_1387ea2de69e','text','{"text": "They would find some rich spot, and then turn their backs on it;"}',370);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a0c0f0c20cb','ch_1387ea2de69e','text','{"text": "pick up perhaps a little—enough for a spree—and then be off again, looking for more. They never stopped long where there were houses: they had no wife, no chick, no home, never a chum. You couldn’t be friends with a Gambusino;"}',371);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e90ef24770aa','ch_1387ea2de69e','text','{"text": "they were too restless—here today, and gone, God knows where, tomorrow. They told no one of their finds, and there has never been a Gambusino well off."}',372);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca20eead267f','ch_1387ea2de69e','text','{"text": "It was not for the gold they cared;"}',373);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ffea6cdfaff','ch_1387ea2de69e','text','{"text": "it was the wandering about looking for it in the stony country that got into them and wouldn’t let them rest: so that no woman yet born could hold a Gambusino for more than a week. That’s what the song says. It’s all about a pretty girl that tried hard to keep hold of a Gambusino lover, so that he should bring her lots of gold. No fear! Off he went, and she never saw him again.’"}',374);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_12bda5086fa3','ch_1387ea2de69e','text','{"text": "‘What became of her?’ she breathed out."}',375);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8924afe8e062','ch_1387ea2de69e','text','{"text": "‘The song don’t tell."}',376);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dca41e2e0ea6','ch_1387ea2de69e','text','{"text": "Cried a bit, I daresay. They were the fellows: kiss and go. But it’s the looking for a thing—a something... Sometimes I think I am a sort of Gambusino myself.’"}',377);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9d70f021635a','ch_1387ea2de69e','text','{"text": "‘No woman can hold you, then, she began in a brazen voice, which quavered suddenly before the end."}',378);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3374cddcb26','ch_1387ea2de69e','text','{"text": "‘No longer than a week,’ he joked, playing upon her very heartstrings with the gay, tender note of his laugh;"}',379);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a6224f1dae0b','ch_1387ea2de69e','text','{"text": "‘and yet I am fond of them all. Anything for a woman of the right sort. The scrapes they got me into, and the scrapes they got me out of! I love them at first sight. I’ve fallen in love with you already, Miss—Bessie’s your name—eh?’ She backed away a little, and with a trembling laugh:"}',380);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50cf7c4b3955','ch_1387ea2de69e','text','{"text": "‘You haven’t seen my face yet.’"}',381);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8ebee45d4eec','ch_1387ea2de69e','text','{"text": "He bent forward gallantly."}',382);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8484b8e16d5a','ch_1387ea2de69e','text','{"text": "‘A little pale: it suits some. But you are a fine figure of a girl. Miss Bessie.’"}',383);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a0f044462a2','ch_1387ea2de69e','text','{"text": "She was all in a flutter. Nobody had ever said so much to her before. His tone changed."}',384);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4388925d32d','ch_1387ea2de69e','text','{"text": "‘I am getting middling hungry, though. Had no breakfast today. Couldn’t you scare up some bread from that tea for me, or—’ She was gone already. He had been on the point of asking her to let him come inside. No matter. Anywhere would do. Devil of a fix! What would his chum think?"}',385);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b0cddeb236f8','ch_1387ea2de69e','text','{"text": "‘I didn’t ask you as a beggar,’ he said jestingly, taking a piece of bread-and-butter from the plate she held before him."}',386);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cbb994abaac1','ch_1387ea2de69e','text','{"text": "‘I asked as a friend. My dad is rich, you know.’"}',387);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c300d31b942','ch_1387ea2de69e','text','{"text": "‘He starves himself for your sake.’"}',388);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59fe7fca337e','ch_1387ea2de69e','text','{"text": "‘And I have starved for his whim,’ he said, taking up another piece."}',389);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8ec93fb7960e','ch_1387ea2de69e','text','{"text": "‘All he has in the world is for you,’ she pleaded."}',390);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_69b41e1dc557','ch_1387ea2de69e','text','{"text": "‘Yes, if I come here to sit on it like a dam’ toad in a hole."}',391);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c98153ba8950','ch_1387ea2de69e','text','{"text": "Thank you;"}',392);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_06b6f8ab5ce6','ch_1387ea2de69e','text','{"text": "and what about the shovel, eh? He always had a queer way of showing his love.’"}',393);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_501094805f59','ch_1387ea2de69e','text','{"text": "‘I could bring him round in a week,’ she suggested timidly."}',394);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8bc87770c89d','ch_1387ea2de69e','text','{"text": "He was too hungry to answer her;"}',395);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ade83d74bfb5','ch_1387ea2de69e','text','{"text": "and, holding the plate submissively to his hand, she began to whisper up to him in a quick, panting voice. He listened, amazed, eating slower and slower, till at last his jaws stopped altogether."}',396);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc3e515e3131','ch_1387ea2de69e','text','{"text": "‘That’s his game, is it?’ he said, in a rising tone of scathing contempt. An ungovernable movement of his arm sent the plate flying out of her fingers. He shot out a violent curse. She shrank from him, putting her hand against the wall."}',397);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_714cd3d94d48','ch_1387ea2de69e','text','{"text": "‘No!’ he raged."}',398);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c86497245356','ch_1387ea2de69e','text','{"text": "‘He expects! Expects me—for his rotten money!... Who wants his home? Mad—not he! Don’t you think. He wants his own way. He wanted to turn me into a miserable lawyer’s clerk, and now he wants to make of me a blamed tame rabbit in a cage. Of me! Of me! His subdued angry laugh frightened her now."}',399);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0237634b279','ch_1387ea2de69e','text','{"text": "‘The whole world ain’t a bit too big for me to spread my elbows in, I can tell you—what’s your name—Bessie—let alone a dam’ parlour in a hutch."}',400);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8181b7e42c8a','ch_1387ea2de69e','text','{"text": "Marry! He wants me to marry and settle! And as likely as not he has looked out the girl too—dash my soul! And do you know the Judy, may I ask?’ She shook all over with noiseless dry sobs;"}',401);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d175545590c','ch_1387ea2de69e','text','{"text": "but he was fuming and fretting too much to notice her distress. He bit his thumb with rage at the mere idea. A window rattled up."}',402);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32bb505369f3','ch_1387ea2de69e','text','{"text": "‘A grinning, information fellow,’ pronounced old Hagberd dogmatically, in measured tones."}',403);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46a20e9a6a68','ch_1387ea2de69e','text','{"text": "And the sound of his voice seemed to Bessie to make the night itself mad— to pour insanity and disaster on the earth."}',404);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00a73b6fd01f','ch_1387ea2de69e','text','{"text": "‘Now I know what’s wrong with the people here, my dear."}',405);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_14e851c3d368','ch_1387ea2de69e','text','{"text": "Why, of course! With this mad chap going about. Don’t you have anything to do with him, Bessie. Bessie, I say!’ They stood as if dumb. The old man fidgeted and mumbled to himself at the window. Suddenly he cried piercingly:"}',406);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4dadb6d590cd','ch_1387ea2de69e','text','{"text": "‘Bessie—I see you. I’ll tell Harry.’"}',407);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c9d42516796','ch_1387ea2de69e','text','{"text": "She made a movement as if to run away, but stopped and raised her hands to her temples. Young Hagberd, shadowy and big, stirred no more than a man of bronze. Over their heads the crazy night whimpered and scolded in an old man’s voice."}',408);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f846f0fcb39','ch_1387ea2de69e','text','{"text": "‘Send him away, my dear. He’s only a vagabond. What you want is a good home of your own. That chap has no home—he’s not like Harry. He can’t be Harry. Harry is coming tomorrow. Do you hear? One day more,’ he babbled more excitedly;"}',409);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6418d13d74b6','ch_1387ea2de69e','text','{"text": "‘never you fear—Harry shall marry you.’"}',410);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_55062453b0b0','ch_1387ea2de69e','text','{"text": "His voice rose very shrill and mad against the regular deep soughing of the swell coiling heavily about the outer face of the sea-wall."}',411);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb2029de77a4','ch_1387ea2de69e','text','{"text": "‘He will have to. I shall make him, or if not’—he swore a great oath—‘I’"}',412);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_73f04b75d234','ch_1387ea2de69e','text','{"text": "ll cut him off with a shilling tomorrow, and leave everything to you. I shall. To you. Let him starve.’"}',413);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d118db14ee96','ch_1387ea2de69e','text','{"text": "The window rattled down. Harry drew a deep breath, and took one step towards Bessie."}',414);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb205a9ced36','ch_1387ea2de69e','text','{"text": "‘So it’s you—the girl,’ he said, in a lowered voice."}',415);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3830d8d24a68','ch_1387ea2de69e','text','{"text": "She had not moved, and she remained half turned away from him, pressing her head in the palms of her hands."}',416);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3396ca0aaf71','ch_1387ea2de69e','text','{"text": "‘My word!’ he continued, with an invisible half-smile on his lips."}',417);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_828b9dc71780','ch_1387ea2de69e','text','{"text": "‘I have a great mind to stop...’"}',418);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4cdbbbbfbe10','ch_1387ea2de69e','text','{"text": "Her elbows were trembling violently."}',419);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a2df8917f863','ch_1387ea2de69e','text','{"text": "‘For a week,’ he finished without a pause."}',420);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6590ed2183b5','ch_1387ea2de69e','text','{"text": "She clapped her hands to her face. He came up quite close, and took hold of her wrists gently. She felt his breath on her ear."}',421);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da36a5e2c7cc','ch_1387ea2de69e','text','{"text": "‘It’s a scrape I am in—this, and it is you that must see me through.’"}',422);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_306f5d096280','ch_1387ea2de69e','text','{"text": "He was trying to uncover her face. She resisted. He let her go then, and stepping back a little, ‘Have you got any money?’ he asked."}',423);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5429073defa','ch_1387ea2de69e','text','{"text": "‘I must be off now.’"}',424);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f191fcba27e5','ch_1387ea2de69e','text','{"text": "She nodded quickly her shamefaced head, and he waited, looking away from her, where, trembling all over and bowing her neck, she tried to find the pocket of her dress."}',425);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af80f9e9f1b1','ch_1387ea2de69e','text','{"text": "‘Here it is!’ she whispered."}',426);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d663967edf15','ch_1387ea2de69e','text','{"text": "‘Oh, go away! go away for God’s sake! If I had more—more—I would give it all to forget—to make you forget.’"}',427);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09025a41a976','ch_1387ea2de69e','text','{"text": "He extended his hand."}',428);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1c2e3f20f3dd','ch_1387ea2de69e','text','{"text": "‘No fear! I haven’t forgotten a single one of you in the world."}',429);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cbbc0d2e8f87','ch_1387ea2de69e','text','{"text": "Some gave me more than money—but I am a beggar now—and you women always had to get me out of my scrapes.’"}',430);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2689e89a59bf','ch_1387ea2de69e','text','{"text": "He swaggered up to the parlour window, and in the dim light filtering through the blind, looked at the coin lying in his palm. It was a half-sovereign. He slipped it into his pocket. She stood a little on one side, with her head drooping, as if wounded;"}',431);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_95423f6ff005','ch_1387ea2de69e','text','{"text": "with her arms hanging passive by her side, as if dead."}',432);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_102b6da7b4ab','ch_1387ea2de69e','text','{"text": "‘You can’t buy me in,’ he said, ‘and you can’t buy yourself out.’"}',433);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53b0a6448510','ch_1387ea2de69e','text','{"text": "He set his hat firmly with a little tap, and next moment she felt herself lifted up in the powerful embrace of his arms. Her feet lost the ground;"}',434);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58655d204329','ch_1387ea2de69e','text','{"text": "her head hung back;"}',435);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f52ab95df50','ch_1387ea2de69e','text','{"text": "he showered kisses on her face with a silent and overmastering ardour, as if in haste to get at her very soul. He kissed her pale cheeks, her hard forehead, her heavy eyelids, her faded lips;"}',436);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b59b270b0a32','ch_1387ea2de69e','text','{"text": "and the measured blows and sighs of the rising tide accompanied the enfolding power of his arms, the overwhelming might of his caresses."}',437);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2224ce9ee8b1','ch_1387ea2de69e','text','{"text": "It was as if the sea, breaking down the wall protecting all the homes of the town, had sent a wave over her head. It passed on;"}',438);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_11ac58f5201f','ch_1387ea2de69e','text','{"text": "she staggered backwards, with her shoulders against the wall, exhausted, as if she had been stranded there after a storm and a shipwreck. She opened her eyes after a while;"}',439);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f4b0e148790','ch_1387ea2de69e','text','{"text": "and, listening to the firm, leisurely footsteps going away with their conquest, began to gather her skirts, staring all the time before her."}',440);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a189c0df9d77','ch_1387ea2de69e','text','{"text": "Suddenly she darted through the open gate into the dark and deserted street."}',441);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a139e48d6d22','ch_1387ea2de69e','text','{"text": "‘Stop!’ she shouted."}',442);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2da53015ef76','ch_1387ea2de69e','text','{"text": "‘Don’t go!’ And listening with an attentive poise of the head, she could not tell whether it was the beat of the swell or his fateful tread that seemed to fall cruelly upon her heart. Presently every sound grew fainter, as though she were slowly turning into stone. A fear of this awful silence came to her—worse than the fear of death. She called upon her ebbing strength for the final appeal:"}',443);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c05f25cfa321','ch_1387ea2de69e','text','{"text": "‘Harry!’ Not even the dying echo of a footstep. Nothing. The thundering of the surf, the voice of the restless sea itself, seemed stopped. There was not a sound—no whisper of life, as though she were alone, and lost in that stony country of which she had heard, where madmen go looking for gold and spurn the find. Captain Hagberd, inside his dark house, had kept on the alert."}',444);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ba82d0dc92a','ch_1387ea2de69e','text','{"text": "A window ran up;"}',445);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_15f835681c5f','ch_1387ea2de69e','text','{"text": "and in the silence of the stony country a voice spoke above her head, high up in the black air—the voice of madness, lies and despair—the voice of inextinguishable hope."}',446);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5960cc076f0','ch_1387ea2de69e','text','{"text": "‘Is he gone yet—that information fellow? Do you hear him about, my dear?’ She burst into tears."}',447);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3e2c160f128','ch_1387ea2de69e','text','{"text": "‘No! no! no! I don’t hear him any more,’ she sobbed."}',448);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f28fe3dd38d9','ch_1387ea2de69e','text','{"text": "He began to chuckle up there triumphantly."}',449);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dddbda8b6f44','ch_1387ea2de69e','text','{"text": "‘You frightened him away. Good girl. Now we shall be all right. Don’t you be impatient, my dear. One day more.’"}',450);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e066bcf0638','ch_1387ea2de69e','text','{"text": "In the other house old Carvil, wallowing regally in his arm-chair, with a globe lamp burning by his side on the table, yelled for her in a fiendish voice:"}',451);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d5530877c27','ch_1387ea2de69e','text','{"text": "‘Bessie! Bessie! You, Bessie!’ She heard him at last, and, as if overcome by fate, began to totter silently back towards her stuffy little inferno of a cottage."}',452);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_85236c014402','ch_1387ea2de69e','text','{"text": "It had no lofty portal, no terrific inscription of forfeited hopes—she did not understand wherein she had sinned. Captain Hagberd had gradually worked himself into a state of noisy happiness up there."}',453);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51c4405d9698','ch_1387ea2de69e','text','{"text": "‘Go in! Keep quiet!’ she turned upon him tearfully, from the doorstep below. He rebelled against her authority in his great joy at having got rid at last of that"}',454);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_08ba6940c315','ch_1387ea2de69e','text','{"text": "‘something wrong’."}',455);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf84e43714b1','ch_1387ea2de69e','text','{"text": "It was as if all the hopeful madness of the world had broken out to bring terror upon her heart, with the voice of that old man shouting of his trust in an everlasting tomorrow."}',456);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac4c9cf24bb0','ch_1387ea2de69e','list','{"ordered": false, "items": ["Joseph Conrad"]}',457);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eecb4d4e9108','ch_1387ea2de69e','text','{"text": "About the author"}',458);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d075e3da58c8','ch_1387ea2de69e','text','{"text": "Joseph Conrad, born of Polish parents in the Russian Ukraine, began a seafaring life in 1874. He learnt English at the age of 21, and in 1886 became a British citizen. His famous works include The Nigger of the Narcissus (1898), Lord Jim (1900) and Nostromo (1904)."}',459);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fda4812788dd','ch_1387ea2de69e','text','{"text": "His greatest skill lies in his capacity to evoke an atmosphere through careful attention to detail. He uses the method of story within a story to convey his sense of the inexplicable inner character of life and the shifting quality of the mind. All Conrad’s characters suffer from a sense of isolation."}',460);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_afadd305b570','ch_1387ea2de69e','text','{"text": "Understanding the text"}',461);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_81df6304d916','ch_1387ea2de69e','text','{"text": "1. What is the consistency one finds in the old man’s madness?"}',462);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b9c5de94666','ch_1387ea2de69e','text','{"text": "2. How does Captain Hagberd prepare for Harry’s homecoming?"}',463);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea0a2a30e39a','ch_1387ea2de69e','text','{"text": "3. How did Bessie begin to share Hagberd’s insanity regarding his son?"}',464);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1a6136e4b332','ch_1387ea2de69e','text','{"text": "4. What were Harry’s reasons for coming to meet old Hagberd?"}',465);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0df52e400e9','ch_1387ea2de69e','text','{"text": "5. Why does Harry’s return prove to be a disappointment for Bessie?"}',466);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_57c9c111c80a','bk_ncert_english','12-5-one-centimetre','12.5 One Centimetre',NULL,'public',74,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8587bd753c62','ch_57c9c111c80a','text','{"text": "When Tao Ying rides on the bus alone, quite often she does not bother to buy a ticket. Why should she? Without her, the bus would still be stopping at every stop, a driver and a conductor would still have to be employed, and the same amount of petrol used. Clearly Tao Ying has to be astute. When the bus conductor looked like the responsible type, she would buy a ticket as soon as she got on board."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_420268ec1ad4','ch_57c9c111c80a','text','{"text": "But if he appeared to be casual and careless, she would not dream of paying, considering it a small punishment for him and a little saving for herself. Tao Ying works as a cook in the canteen of a factory. She spends all day next to an open fire, baking screwshaped wheat cakes with sesame butter. Today she is with her son Xiao Ye. She follows him onto the bus. As the doors shut her jacket is caught, ballooning up like a tent behind her."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a545775de7c','ch_57c9c111c80a','text','{"text": "She twists this way and that, finally wrenching herself free."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a8b0205d26c3','ch_57c9c111c80a','text','{"text": "‘Mama, tickets!’ Xiao Ye says."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04e886259d46','ch_57c9c111c80a','text','{"text": "Children are often more conscious of rituals than adults. Without a ticket in his hand, the ride doesn’t count as a proper ride. On the peeling paint of the door somebody has painted the shape of a pale finger. It points at a number: 1.10 m. Xiao Ye pushed through. His hair looks as fluffy as a bundle of straw—dry and without lustre. As a rule, Tao Ying is very careful with her purse, but she has never skimped on her child’s diet."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_833c787d66b0','ch_57c9c111c80a','text','{"text": "Nonetheless the goodness in his food refuses to advance beyond his hairline. As a result Xiao Ye is healthy and clever, but his hair is a mess. Tao Ying tries to smooth it down, as if she was brushing away topsoil to get to a firm foundation. She can feel the softness of her son’s skull, rubbery and elastic to the touch. Apparently there is a gap on the top of everyone’s head, where the two halves meet. If they don’t meet properly, a person can end up with a permanently gaping mouth."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_981b86768f11','ch_57c9c111c80a','text','{"text": "Even when the hemispheres are a perfect match, it still takes a while for them to seal. This is the door to life itself—if it remains open, the world outside will feel like water, flowing into the body through this slit. Every time Tao Ying happens upon this aperture on her son’s head, she would be overwhelmed by a sense of responsibility. It was she who had brought this delicate creature into the world after all."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2299549ff404','ch_57c9c111c80a','text','{"text": "Although she senses her own insignificance in the world, that her existence makes no difference to anyone else, she also realises that to this little boy she is the centre of the universe and she must try to be the most perfect, flawless mother possible. Between Xiao Ye’s round head and the tip of the painted digit setting out the height requirement for a ticket rests the beautiful slender fingers of Tao Ying."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7245f6dd010','ch_57c9c111c80a','text','{"text": "Since she is in contact with oil all day, her nails are shiny, glistening like the smooth curved back of a sea shell."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d719647f77e','ch_57c9c111c80a','text','{"text": "‘Xiao Ye, you are not quite tall enough, still one centimetre away,’ she tells him softly."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dcbf11167417','ch_57c9c111c80a','text','{"text": "Tao Ying does not come from a privileged background, and has not read very many books. But she likes to be gentle and gracious, to set an example for her son and make a good impression. This elevates her sense of self-worth and makes her feel like an aristocrat."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40450550e90a','ch_57c9c111c80a','text','{"text": "‘Mama! I’m tall enough, I’m tall enough!’ Xiao Ye shouts at the top of his voice, stamping on the floor as if it were a tin drum."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17f2fcdd2bd6','ch_57c9c111c80a','text','{"text": "‘You told me the last time I could have a ticket the next time, this is the next time. You don’t keep your word!’ He looks up at his mother angrily. Tao Ying looks down at her son. A ticket costs twenty cents. Twenty cents is not to be scoffed at. It can buy a cucumber, two tomatoes or, at a reduced price, three bunches of radishes or enough spinach to last four days. But Xiao Ye’s face is raised up like a half-open blossom, waiting to receive his promise from the sun."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e296f3fc818','ch_57c9c111c80a','text','{"text": "‘Get in! Don’t block the entrance! This is not a train, where you stand from Beijing to Bao Ding."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6230c05f8f46','ch_57c9c111c80a','text','{"text": "We’re almost at the next stop...!’ the conductor bellows. Normally, an outburst like this would certainly have discouraged Tao Ying from buying a ticket. But today she says, ‘Two tickets, please.’"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35f63454e608','ch_57c9c111c80a','text','{"text": "The fierce conductor has beady eyes."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49a14836f7e6','ch_57c9c111c80a','text','{"text": "‘This child is one centimetre short of requiring a ticket.’"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_34e5a3d1e9ac','ch_57c9c111c80a','text','{"text": "Xiao Ye shrinks, not just one but several centimetres— the need for a ticket has all of a sudden become interwoven with the pride of a small child. To be able to purchase self-esteem with twenty cents is something that can only happen in childhood and certainly no mother can resist an opportunity to make her son happy."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bdb6e2480394','ch_57c9c111c80a','text','{"text": "‘I would like to buy two tickets,’ she says politely."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd22d6e5130c','ch_57c9c111c80a','text','{"text": "Xiao Ye holds the two tickets close to his lips and blows, making a sound like a paper windmill. They had entered through the central doors of the bus, but alight towards the front. Here another conductor is poised to examine their tickets. Tao Ying thinks that this man can’t be very bright. What mother accompanied by a child would try to avoid paying the correct fare? However poor she would never have allowed herself to lose face in front of her own son. She hands over the tickets nonchalantly."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5a82fa686cf','ch_57c9c111c80a','text','{"text": "The conductor asks:"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32a99f4013b4','ch_57c9c111c80a','text','{"text": "‘Are you going to claim these back?’"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c93c6f6204bf','ch_57c9c111c80a','text','{"text": "‘No.’"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20b190a40d21','ch_57c9c111c80a','text','{"text": "In fact Tao Ying ought to have kept the tickets so that the next time there is a picnic or an outing at work she could use her bicycle and then claim back the fare with the stubs. Both she and her husband are blue-collar workers, and any saving would have been a help. But Xiao Ye is a smart boy, and might well question her aloud, ‘Mama, can we claim back tickets even when we are on a private outing?’ In front of the child, she would never lie."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc707845c989','ch_57c9c111c80a','text','{"text": "It is exhausting to follow rules dictated by parental guide-books all the time, but Tao Ying is determined to be the ideal mother and create a perfect example for her son to look up to. She needs really to concentrate—living this way is not unlike carrying an audience with you wherever you go. But her actions are full of love and tenderness."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c9cc184228c','ch_57c9c111c80a','text','{"text": "For instance, whenever she eats a watermelon in front of Xiao Ye, she would take care not to bite too close to the rind even though she doesn’t actually think there is much difference between the flesh and the skin. True, the sweetness gradually diminishes as you work your way through the red towards the green, but every part of the melon is equally refreshing. In any case the skin of a melon is supposed to have a beneficial cooling effect, and is often used as medicine."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80c27a4e6489','ch_57c9c111c80a','text','{"text": "One day, she came across her son eating a melon in the same manner she did. When Xiao Ye looked up, Tao Ying could see a white melon seed stuck to his forehead. She was furious:"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_859ee642e5ad','ch_57c9c111c80a','text','{"text": "‘Who taught you to gnaw at a melon like that? Are you going to wash your face in it too?’ Xiao Ye was terrified."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_057c0a97216f','ch_57c9c111c80a','text','{"text": "The small hand holding the melon began to tremble, but the big round eyes remained defiant. Children are the best imitators in the world. From then on Tao Ying realised that if she wanted her son to behave as if he were the product of a cultured home, then she must concentrate and never fail in her own example. This was very difficult, like"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d9f0e7db5a03','ch_57c9c111c80a','text','{"text": "‘shooting down aeroplanes with a small gun’—but with determination, she knew that nothing was impossible."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d51e6fca91f','ch_57c9c111c80a','text','{"text": "With this clear objective in mind, Tao Ying found her life becoming more focused, more challenging. Today she is taking Xiao Ye to visit a big temple. He has never seen the Buddha before. Tao Ying is not a believer and she does not intend to ask him to kow-tow. That is superstition, she knows. The tickets cost five dollars a piece—these days even temples are run like businesses. Tao Ying’s ticket was a gift from Lao Chiang, who worked at the meat counter."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fe4275e9c879','ch_57c9c111c80a','text','{"text": "The ticket was valid for a month, and today was the last day. Lao Chiang was one of those people who seemed to know everybody. Occasionally he would produce a battered coverless month-old magazine and say:"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_47b5f9e59f9a','ch_57c9c111c80a','text','{"text": "‘Seen this before? This is called the Big Reference, not meant for the eyes of the common people.’"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9234ca1900ee','ch_57c9c111c80a','text','{"text": "Tao Ying had never seen anything like this before and wondered how such a small rag, smaller even than a regular newspaper, could be called a Big Reference. She asked Lao Chiang but he seemed confused. He said everybody called it that—perhaps if you were to take out the pages and laid them flat they would end up bigger than a normal newspaper. It seemed to make sense."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8868844b4c47','ch_57c9c111c80a','text','{"text": "Studying this publication written in large print, Tao Ying could see that it was full of speculation about the war in the Middle East. Foremost on everyone’s mind seemed to be whether the export of dates from Iraq to China would continue as it did in the sixties during the famine. In any case, Tao Ying was full of admiration for Lao Chiang. In return for her indiscriminate respect, Lao Chiang decided to reward her with a ticket for the temple."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_31e652be3513','ch_57c9c111c80a','text','{"text": "‘Is there just the one?’ Tao asked, not without gratitude but with some uncertainty."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_38b8ff558097','ch_57c9c111c80a','text','{"text": "‘Forget your husband, take your son and open his eyes! Children under 110 centimeters do not need a ticket. If you don’t want to go, sell it at the door and you’ll earn enough to buy a couple of watermelons!’ Lao Chiang had always been a practical man. Tao Ying decided to take the day off and go on an outing with Xiao Ye. It is rare to find such a large patch of grass in the middle of the city."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f238c070407b','ch_57c9c111c80a','text','{"text": "Even before they got there, there was something refreshing, something green in the air, as if they were approaching a valley, or a waterfall. Xiao Ye snatches the ticket from his mother’s hand, puts it between his lips, and flies towards the gilded gates of the temple. A little animal rushing to quench his thirst. Tao Ying suddenly feels a little sad."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_868cd66d4015','ch_57c9c111c80a','text','{"text": "Is the mere attraction of a temple enough for Xiao Ye to abandon his mother? But almost immediately she banishes the thought— hasn’t she brought her son here today to make him happy? The guard at the gate is a young man dressed in a red top and black trousers. Tao Ying feels somehow that he ought to have been in yellow. This uniform makes him look somewhat like a waiter. Xiao Ye knows exactly what he has to do."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad9445e3bfdb','ch_57c9c111c80a','text','{"text": "Moving amongst the crowd, he seems like a tiny drop of water in the current of a large river. The young man takes the ticket from his mouth, plucking a leaf from a spring branch. Tao Ying’s gaze softly envelopes her son, a strand of silk unwinding towards him, following his every gesture."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05f46db36438','ch_57c9c111c80a','text','{"text": "‘Ticket.’"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce840082a98a','ch_57c9c111c80a','text','{"text": "The youth in red bars her way with one arm, his voice as pithy as if he was spitting out a date stone. Tao Ying points at her son with infinite tenderness. She feels that everybody should see how lovely he is."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a84f5fd6f9bf','ch_57c9c111c80a','text','{"text": "‘I am asking for your ticket.’"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ae06bc0df976','ch_57c9c111c80a','text','{"text": "The red youth does not budge."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d507ebb0ceb9','ch_57c9c111c80a','text','{"text": "‘Didn’t the child just give it to you?’ Tao Ying’s voice is peaceful. This boy is too young, years away from being a father, she thinks. Tao Ying is not working today and is in a really good mood. She is happy to be patient."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d2062ba6fb73','ch_57c9c111c80a','text','{"text": "‘That was his ticket, now I need to see yours.’"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_902099d365c2','ch_57c9c111c80a','text','{"text": "The youth remains unmoved. Tao Ying has to pause for a moment before it sinks in—there are two of them and they need a ticket each."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_16a8597f24ea','ch_57c9c111c80a','text','{"text": "‘I thought that children were exempt?’ She is confused."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f86cc1a2af9f','ch_57c9c111c80a','text','{"text": "‘Mama, hurry up!’ Xiao Ye shouts to her from inside the doors."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bca2f19c240c','ch_57c9c111c80a','text','{"text": "‘Mama is coming!’ Tao Ying shouts back."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c78a511f024e','ch_57c9c111c80a','text','{"text": "A crowd is beginning to gather, so many fishes swarming towards a bright light. Tao Ying starts to panic. She wants this fracas to end, her child is waiting for her."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cff806092fec','ch_57c9c111c80a','text','{"text": "‘Who told you he doesn’t need a ticket?’ The guard tilts his head—the more onlookers the better."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db39ffb4e89a','ch_57c9c111c80a','text','{"text": "‘It says so on the back of the ticket.’"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_468cd8cabb43','ch_57c9c111c80a','text','{"text": "‘Exactly what does it say?’ This boy is obviously not a professional."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82b692bf8b74','ch_57c9c111c80a','text','{"text": "‘It says that children under 110 centimetres do not have to pay.’"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_94d2ade449d0','ch_57c9c111c80a','text','{"text": "Tao Ying is full of confidence. She moves to pick up one of the tickets from a box next to the guard and reads out what is printed on the back for all to hear."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32fb807b486e','ch_57c9c111c80a','text','{"text": "‘Stop right there!’ The youth has turned nasty."}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f5c6ae501dbc','ch_57c9c111c80a','text','{"text": "Tao Ying realises she should not have touched the box and quickly withdraws her hand."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35659c1b6747','ch_57c9c111c80a','text','{"text": "‘So you are familiar with the rules and regulations are you?’ Now the young man addresses her with the formal"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3eeb70e99f27','ch_57c9c111c80a','text','{"text": "‘you’. Tao Ying detects the sarcasm in his tone but she simply nods."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c3d8ebd6ef54','ch_57c9c111c80a','text','{"text": "‘Well, your son is over 110 centimetres,’ he says with certainty."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e4674c17fe4','ch_57c9c111c80a','text','{"text": "‘No he isn’t.’"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b839a543bf03','ch_57c9c111c80a','text','{"text": "Tao Ying is still smiling. Everybody begins to look at the mother with suspicion."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02a3d46f7d74','ch_57c9c111c80a','text','{"text": "‘He just ran past the mark. I saw it clearly.’"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_551845dab724','ch_57c9c111c80a','text','{"text": "The guard is equally firm, pointing at a red line on the wall which looks like an earthworm inching across the road after a rainstorm."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92ef8ea62d9b','ch_57c9c111c80a','text','{"text": "‘Mama, why are you taking so long? I thought I had lost you!’ Xiao Ye shouts to her affectionately."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e1046f2dbff','ch_57c9c111c80a','text','{"text": "He runs towards his mother, as if she was one of his favourite toys. The crowd titters. Good, they think, here is proof, the whole matter can be cleared up at once. The youth is getting a little nervous. He is just doing his job. He is certain he is right. But this woman seems very confident, perhaps that would be awful... Tao Ying remains calm. In fact, she feels a little smug. Her son loves excitement. This is turning into something of an event so it is bound to delight him."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da23e7c6ded6','ch_57c9c111c80a','text','{"text": "‘Come over here,’ the youth commands."}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3373d707d27','ch_57c9c111c80a','text','{"text": "The crowd holds its breath. Xiao Ye looks at his mother. Tao Ying gives him a little nod. He walks over to the guard graciously, coughs a little, adjusts his jacket. In front of the gaze of the crowd, Xiao Ye is every inch the hero as he approaches the earthworm. Then—the crowd looks, and sees—the worm comes to Xiao Ye’s ear. How is this possible? Tao Ying is by his side in two paces."}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c58947293a10','ch_57c9c111c80a','text','{"text": "The flat of her hand lands heavily on the little boy’s head, making a sound as crisp as a ping-pong ball popping underfoot. Xiao Ye stares at his mother. He is not crying. He is shocked by the pain. He has never been hit before. The crowd draws its breath."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0fca823ccb44','ch_57c9c111c80a','text','{"text": "‘Punishing a child is one thing, hitting him on the head is totally unacceptable!’"}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb974c9a4b58','ch_57c9c111c80a','text','{"text": "‘What a way for a mother to behave! So what if you have to buy another ticket? This is a disgrace, hitting a child to cover up your own mistake!’"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ba82ba2d75a','ch_57c9c111c80a','text','{"text": "‘She can’t be his natural mother...’"}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_569f3121a388','ch_57c9c111c80a','text','{"text": "Everybody has an opinion. Tao Ying is feeling a little agitated now. She had not meant to hit Xiao Ye. She meant to smooth down his hair, But she realises that even if Xiao Ye were bald at this instant, he would still be towering above the worm on the wall."}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b29c9277686f','ch_57c9c111c80a','text','{"text": "‘Xiao Ye, don’t stand on tip-toe!’ Tao Ying’s voice is severe."}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e58350597338','ch_57c9c111c80a','text','{"text": "‘Mama, I’m not...’"}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b136d6965b0b','ch_57c9c111c80a','text','{"text": "Xiao Ye begins to cry. It’s true. He isn’t. The worm crawls somewhere next to his brow. The guard stretches himself lazily. His vision is sharp, he has caught quite a few people who had tried to get through without paying."}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0c57478e199','ch_57c9c111c80a','text','{"text": "‘Go get a ticket!’ he screams at Tao Ying."}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eef7bdedeab0','ch_57c9c111c80a','text','{"text": "All pretence of courtesy has by now been eaten up by the worm."}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b2966d04898','ch_57c9c111c80a','text','{"text": "‘But my son is less than one meter ten!’ Tao Ying insists even though she realises she stands alone."}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c0fdb178f47','ch_57c9c111c80a','text','{"text": "‘Everyone who tries to escape paying always says the same thing. Do you think these people are going to believe you, or are they going to believe me? This is a universally accepted measurement. The International Standard Ruler is in Paris, made of pure platinum. Did you know that?’ Tao is flummoxed. All she knows is that to make a dress she needs two metres eighty centimetres, she does not know where the International Ruler is kept."}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_861ea35ebd0f','ch_57c9c111c80a','text','{"text": "She is only astonished at the power of the Buddha which can make her son grow several centimetres within minutes!"}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_83a662ee55eb','ch_57c9c111c80a','text','{"text": "‘But we were on the bus just now and he wasn’t as tall...’"}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91e12dffdd15','ch_57c9c111c80a','text','{"text": "‘No doubt when he was born he wasn’t as tall either!’ the youth sneers, chilling the air."}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f1e69f680b0b','ch_57c9c111c80a','text','{"text": "Standing in the middle of the jeering crowd, Tao Ying’s face has turned as white as her ticket."}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a7ea7fcfdf0f','ch_57c9c111c80a','text','{"text": "‘Mama, what is happening?’ Xiao Ye comes away from the earthworm to hold his mother’s frozen hand with his own little warm one."}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c27c517d735f','ch_57c9c111c80a','text','{"text": "‘It’s nothing. Mama has forgotten to buy a ticket for you.’"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51af5e0a8efa','ch_57c9c111c80a','text','{"text": "Tao Ying can barely speak."}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_263c8360d861','ch_57c9c111c80a','text','{"text": "‘Forgotten? That’s a nice way of putting it! Why don’t you forget you have a son as well?’ The youth will not forgive her calm confidence of a moment ago."}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_300899352920','ch_57c9c111c80a','text','{"text": "‘What more do you want?’ Tao Ying’s temper rises."}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a621be62a8b5','ch_57c9c111c80a','text','{"text": "In front of her child, she must preserve her dignity."}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e92534af0d1','ch_57c9c111c80a','text','{"text": "‘You have a nerve! This is not to do with what I want, clearly you must apologise! God knows how you had managed to get hold of a complimentary ticket in the first place. To get in free is not enough, now you want to sneak in an extra person. Have you no shame? Don’t think you can get away with this, go, get yourself a valid ticket!’ The youth is now leaning on the wall, facing the crowd as if he is pronouncing an edict from on high. Tao Ying’s hands are trembling like the strings on a pei-pa."}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c12b8fe4562a','ch_57c9c111c80a','text','{"text": "What should she do? Should she argue with him? She is not afraid of a good fight but she doesn’t want her child to be witness to such a scene. For the sake of Xiao Ye, she will swallow her pride."}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e16d3d3a858','ch_57c9c111c80a','text','{"text": "‘Mama is going to buy a ticket. You wait here, don’t run off.’"}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8e68965d025e','ch_57c9c111c80a','text','{"text": "Tao Ying tries to smile. This outing is such a rare occasion, whatever happens she mustn’t spoil the mood. She is determined to make everything all right."}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a3c01145b53','ch_57c9c111c80a','text','{"text": "‘Mama, did you really not buy a ticket?’ Xiao Ye looks at her, full of surprise and bewilderment."}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b8b35805cecc','ch_57c9c111c80a','text','{"text": "The expression on her child’s face frightens her. She cannot buy this ticket today! If she went ahead, she would never be able to explain herself to her son."}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_060abb9e5873','ch_57c9c111c80a','text','{"text": "‘Let’s go!’ She gives Xiao Ye a yank. Thankfully the child has strong bones, or his arm might have fallen off."}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1ee7b720b6cc','ch_57c9c111c80a','text','{"text": "‘Let’s go and play in the park.’"}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_61bc06820401','ch_57c9c111c80a','text','{"text": "Tao Ying wants her son to be happy, but the little boy has fallen silent, sullen. Xiao Ye has suddenly grown up. As they walk past an ice-cream seller, Xiao Ye says, ‘Mama, give me money!’ Taking the money, Xiao Ye runs towards an old woman behind the stall and says to her:"}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_828ba4c1c491','ch_57c9c111c80a','text','{"text": "‘Please measure me!’ It is only then that Tao Ying notices the old lady sitting next to a pair of scales for measuring weight and height."}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd69ad5cfc12','ch_57c9c111c80a','text','{"text": "The old woman extends with difficulty the measuring pole, pulling it out centimetre by centimetre. She strains to make out the numbers:"}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_23aff3ab3922','ch_57c9c111c80a','text','{"text": "‘One metre eleven.’"}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab72b51afcbe','ch_57c9c111c80a','text','{"text": "Tao Ying begins to wonder if she has encountered a ghost or is her son beginning to resemble a shoot of bamboo, growing every time you look at him? Something moist begins to glisten in Xiao Ye’s eyes. Leaving his mother behind and without a backward glance, he starts to run away. He trips. One moment he is in the air, taking flight like a bird, another and he has dropped to the ground with a heavy thud."}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6626ef00fcbf','ch_57c9c111c80a','text','{"text": "Tao Ying rushes over to lend a hand but just as she is about to reach him Xiao Ye has picked himself up and is off again. Tao Ying stops in her tracks. If she gives chase Xiao Ye will only keep falling. Watching her son’s vanishing silhouette, her heart begins to break: Xiao Ye, aren’t you going to look back at your mother? Xiao Ye runs for a long time and eventually comes to a halt. He throws a quick glance backwards to find his mother, but the moment he can see her, he takes off once more..."}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6e2944119bc5','ch_57c9c111c80a','text','{"text": "Tao Ying finds the whole incident incomprehensible. She wanders back to the old woman and asks politely:"}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02edc3268548','ch_57c9c111c80a','text','{"text": "‘Excuse me, these scales you have...’"}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04ba4fc3e51a','ch_57c9c111c80a','text','{"text": "‘My scales are here to make you happy! Don’t you want your son to grow tall? Every mother wants her sons to shoot up, but don’t forget when he is tall, that means you’ll be old! Mine are flattering scales,’ the old woman explains kindly, but Tao Ying remains baffled."}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1c666468a284','ch_57c9c111c80a','text','{"text": "‘You see my scales are old and not very accurate and they make people seem lighter than they really are. I have also adjusted it to make them seem taller. These days it is fashionable to be long and lean—mine are fitness scales!’ The old woman might be kind, but she is not without cunning."}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd4975b626ea','ch_57c9c111c80a','text','{"text": "So that is the reason! Xiao Ye should have heard this speech! But he is a long way away and in any case would he have understood the convoluted logic? Xiao Ye still looks suspicious, as if mother has turned into a big bad wolf, ready to eat him up. Later when they are back at home, Tao Ying takes out her own tape measure and insists on measuring him again."}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_424ae71c1de2','ch_57c9c111c80a','text','{"text": "‘I don’t want to! Everybody says I am tall enough except you."}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce23e66690ce','ch_57c9c111c80a','text','{"text": "It’s because you don’t want to buy me a ticket, don’t think I don’t know. If you measure me I am bound to get shorter again. I don’t trust you! I don’t trust you!’ The yellow tape in Tao Ying’s hands has turned into a poisonous viper."}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e14b212262ea','ch_57c9c111c80a','text','{"text": "‘Chef! Your cakes look as if they are wearing camouflage uniforms, all black and brown!’ a customer queuing in front of her counter shouts out."}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4501d81b6da','ch_57c9c111c80a','text','{"text": "The cakes are ruined. They are full of burnt marks, and look like tiny terrapins, Sorry sorry sorry. Tao Ying feels very guilty. She is usually very conscientious in her work, but these couple of days she often finds herself distracted. She must rescue the situation! At night, after Xiao Ye has gone to sleep, Tao Ying straightens his little legs so that he is lying as flat as a piece of newly shrunken fabric."}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a50771218acc','ch_57c9c111c80a','text','{"text": "Tao Ying then stretches her tape from the soles of his feet to the top of his head—one metre nine centimetres. She decides to write a letter to the administrators at the temple. She picks up her brush but suddenly realises that this is harder than she thinks! Seeing her deep in thought with knitted brows, her husband says, ‘So what do you imagine might happen even if you wrote to them?’ He is right, she doesn’t know if anything would come of it."}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_63c501c1e45a','ch_57c9c111c80a','text','{"text": "But in order to melt the ice in her son’s eyes, she must do something. At last the letter is done. There is a man in the factory nicknamed"}',116);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab06c9a82f2f','ch_57c9c111c80a','text','{"text": "‘the Writer’."}',117);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8fdb295f620e','ch_57c9c111c80a','text','{"text": "People say he has had some small articles published at the back of a news rag once. Tao Ying finds him and respectfully offers up her literary work."}',118);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_766ceefd246a','ch_57c9c111c80a','text','{"text": "‘This sounds like an official communication. Not lively enough, not moving.’"}',119);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9bc7b38fe3e4','ch_57c9c111c80a','text','{"text": "The Writer traces the letter with his nicotine-stained fingers. Tao Ying doesn’t know what an official communication is but she detects a tone of dissatisfaction in the scholar’s voice. She looks at the lines he is pointing to, and nods in agreement."}',120);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b55490a7027a','ch_57c9c111c80a','text','{"text": "‘What you need to do is this. You must open with a strong and righteous claim, fawned by a passage of stunning originality so that your work stands out and grabs the attention of the editor. This would make him pick it out of a large pile on his desk. It has to catch his eyes like a blinding light, an apple in a mound of potatoes. But most important of all, your letter must touch his heart. Have you heard of the saying, grieving soldiers always win?’ Tao Ying keeps nodding."}',121);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8166fa528955','ch_57c9c111c80a','text','{"text": "The Writer is encouraged to continue:"}',122);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f7c31c5db22','ch_57c9c111c80a','text','{"text": "‘Let us look at the opening paragraph—it should go something like this:"}',123);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b6a41485e77','ch_57c9c111c80a','text','{"text": "‘‘The power of the Buddha is surely infinite! The foot of a five-year-old boy has scarcely touched the threshold of the temple and he has grown two centemetres;"}',124);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05beaf6b373d','ch_57c9c111c80a','text','{"text": "but alas, the power of the Buddha is finite after all—on his return home the boy shrinks back to his original size...’"}',125);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c516ffdd3b5c','ch_57c9c111c80a','text','{"text": "’ I know this is not yet perfect, but have a think about it along these lines...’"}',126);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1385414474f','ch_57c9c111c80a','text','{"text": "Tao Ying tries to memorise the words of the Writer, but she finds it hard to recall all of it. Back home she makes a few corrections as best she can, and sends out the letter. *** The Writer comes by her stall at lunch-time. Tao Ying’s face is framed in a small window where she is collecting vouchers. She looks like a photograph, staring out at the camera with a sombre expression."}',127);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70ea24c4a709','ch_57c9c111c80a','text','{"text": "‘Please wait a moment,’ and she disappears behind the frame."}',128);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa6f39d95e92','ch_57c9c111c80a','text','{"text": "The Writer suspects the cakes are burnt again. Perhaps Tao Ying has gone to find a few which are less burnt than others, to thank him for pointing her in the right direction."}',129);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3033940b209','ch_57c9c111c80a','text','{"text": "‘This is for you, with extra sugar and sesame,’ Tao Ying says shyly."}',130);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d450d9f2d495','ch_57c9c111c80a','text','{"text": "This is the greatest gift a baker could offer a friend as a token of gratitude. *** Then comes the long wait. Tao Ying looks through the newspapers every day, reading everything from cover to cover including small classified advertisements for videos. In the meantime she would listen to the radio, imagining that one morning she will hear her own letter read out by one of those announcers with a beautiful voice."}',131);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd70555bd63f','ch_57c9c111c80a','text','{"text": "Afterwards she would go down to the post office, in case the administrative department of the temple has replied to her letter, apologising for their misdeed... She has imagined a hundred different scenarios, but not what actually happens. The days have been like the white flour she works with, one very much like another. Xiao Ye appears to have recovered from the ordeal but Tao Ying firmly believes that he has not really forgotten."}',132);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e1d6055551d','ch_57c9c111c80a','text','{"text": "Finally, one day, she hears a question, ‘Which way is it to comrade Tao’s home?’"}',133);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_003233e1c308','ch_57c9c111c80a','text','{"text": "‘I know, I’ll take you.’"}',134);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b4e82c5b2b7c','ch_57c9c111c80a','text','{"text": "Xiao Ye excitedly shows two elderly gentlemen in uniform through the front door."}',135);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_150defcda3f8','ch_57c9c111c80a','text','{"text": "‘Mama, we have visitors!’ Tao Ying is doing the laundry, immersed in soap up to her armpits."}',136);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d42d623a9d0','ch_57c9c111c80a','text','{"text": "‘We are from the administrative office at the temple. The local newspaper has forwarded your letter to us and we have come to ascertain the truth.’"}',137);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a73fecd0b949','ch_57c9c111c80a','text','{"text": "Tao Ying is very nervous, and somewhat depressed. Chiefly because her house is very messy, and she has not had the time to tidy up. If they think that she is prone to laziness they might not believe her."}',138);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e36afed2f5cc','ch_57c9c111c80a','text','{"text": "‘Xiao Ye, why don’t you go out to play?’ In Tao Ying’s fantasies, Xiao Ye would be in the room to witness the revelation of the truth."}',139);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c1297a121db','ch_57c9c111c80a','text','{"text": "Now that the moment has finally arrived, she feels uncomfortable having him there. She cannot predict what will happen. These are after all the people who employed the youth in red, so how reasonable can they be? The younger of the two speaks."}',140);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2dcbae38bca5','ch_57c9c111c80a','text','{"text": "‘We have investigated the matter with the party concerned, and he insisted he was in the right. Don’t tell the boy to leave, we want to measure him.’"}',141);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c2f3f130940','ch_57c9c111c80a','text','{"text": "Xiao Ye obeys and stands next to the wall. The white of the wall looks like a virgin canvas and Xiao Ye a painting filling up the space. He leans tightly against the wall as if the act of measuring his height has once again stirred up some terrifying memory in the recesses of his mind. The men are very serious. First of all they draw a bold line across the wall from the top of Xiao Ye’s head. Then they take out a metallic tape and take the measurement from the line to the floor."}',142);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e5abb5123cc','ch_57c9c111c80a','text','{"text": "The metal of the tape glistens like a flowing stream in sunlight. Tao Ying regains her calm."}',143);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd9fd35e5445','ch_57c9c111c80a','text','{"text": "‘What does it say?’"}',144);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ccce06a3896','ch_57c9c111c80a','text','{"text": "‘One metre ten, just so,’ the younger man answers."}',145);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2814a31dfbd8','ch_57c9c111c80a','text','{"text": "‘This is not just so. There was a delay of one month and nine days before you came. A month ago he wasn’t this tall.’"}',146);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3deba6f23ac3','ch_57c9c111c80a','text','{"text": "The two officials look at each other. This is a statement they cannot refute. They produce a five-dollar bill from a pocket. The note pokes out of an envelope. They have evidently come prepared. Before they left the temple, they must have checked the height of the earthworm, and realised it was not drawn accurately."}',147);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c7db0cf274db','ch_57c9c111c80a','text','{"text": "‘The other day you and your son were unable to enter. This is a small token to redress the situation.’"}',148);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9b9edef170b','ch_57c9c111c80a','text','{"text": "This time it is the elder of the two gentlemen who speaks. His demeanour is kind, so he must be the more senior of the two. Tao Ying remains still. That day’s happiness can never be bought again."}',149);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f5bd6fcc481','ch_57c9c111c80a','text','{"text": "‘If you don’t want the money, here are two tickets."}',150);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d942a922fb15','ch_57c9c111c80a','text','{"text": "You and your son are welcome to visit the temple any time.’"}',151);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c25e154f918e','ch_57c9c111c80a','text','{"text": "The younger man is even more polite. This is a tempting proposition indeed, but Tao Ying shakes her head. To her, to her son, that place will always be associated with unhappy memories now."}',152);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_560a80c8f5c9','ch_57c9c111c80a','text','{"text": "‘So which would you prefer,’ both men ask in unison."}',153);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc9af7dcf58f','ch_57c9c111c80a','text','{"text": "In fact Tao Ying is asking herself the same question. She is gracious by nature—if the youth in red had come in person to apologise today, she would not have made him feel awkward. So what is it that she wants? She shoves Xiao Ye in front of the two elderly officials."}',154);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8e22a95e528f','ch_57c9c111c80a','text','{"text": "‘Say Grandpa,’ she tells him."}',155);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1719710ae159','ch_57c9c111c80a','text','{"text": "‘Grandpa.’"}',156);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b446018e263','ch_57c9c111c80a','text','{"text": "Xiao Ye sounds infinitely sweet."}',157);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8dc903d58f6d','ch_57c9c111c80a','text','{"text": "‘Dear Leaders, please take back the money, and the tickets. Kindly do not punish the guard on duty, he was only doing his job...’"}',158);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fc4f15fac0cd','ch_57c9c111c80a','text','{"text": "The two officials are puzzled. Tao Ying nudges Xiao Ye closer:"}',159);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c34781455450','ch_57c9c111c80a','text','{"text": "‘Gentlemen, would you be so kind as to explain to my son exactly what happened on that day. Please tell him that his mother has not done anything wrong...’"}',160);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1847a955c28b','ch_57c9c111c80a','list','{"ordered": false, "items": ["Bi Shu-min"]}',161);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18507e9b2fef','ch_57c9c111c80a','text','{"text": "About the author"}',162);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4b76374aea6','ch_57c9c111c80a','text','{"text": "Bi Shu-min has been serving her country, China, as a doctor for over twenty years. She also has a Master’s degree in literature from the Beijing Teacher’s College. Bi Shu-min is one of the best known writers currently working in China. Her works have been translated into many languages. She has won innumerable literary awards both in China and in Taiwan."}',163);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_250094557b6d','ch_57c9c111c80a','text','{"text": "‘One Centimetre’ is a fine example of a mature artist working at the height of her powers."}',164);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c084eb29a20','ch_57c9c111c80a','text','{"text": "Understanding the text"}',165);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fe5e5aee031d','ch_57c9c111c80a','text','{"text": "1. How did Tao Ying’s son influence the way she led her life?"}',166);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_060207eab596','ch_57c9c111c80a','text','{"text": "2. Pick out instances from the story to show that official rules are often arbitrary."}',167);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_772ab5a91302','ch_57c9c111c80a','text','{"text": "3. Tao Ying was very careful about spending money. What were her reasons for refusing the compensation offered by the temple officials?"}',168);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f643f7c371e1','ch_57c9c111c80a','text','{"text": "4. Why was her final vindication important to Tao Ying?"}',169);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_0372d4acf113','bk_ncert_english','poetry','Poetry',NULL,'public',75,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67109766786b','ch_0372d4acf113','text','{"text": "A poem is a composition in verse, usually characterised by concentrated and heightened language in which words are chosen for their sound and suggestive power as well as for their meaning, and using techniques such as rhythm and metre. To read and hear good poetry is to appreciate the subtleties of cadence and rhythm, the variety of pace and pattern and all that goes to make up the music of poetry. Every poem that we read adds to, in some degree, our total conception of poetry."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_790172c44b2d','ch_0372d4acf113','text','{"text": "Of the eight poets in this selection, four are from the classical tradition: Donne, Milton, Blake and Coleridge. The other four are closer to contemporary times: Yeats, A.K.Ramanujan, Emily Dickinson and Kamala Das."}',2);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_51505a30dad7','bk_ncert_english','12-6-a-lecture-upon-the-shadow','12.6  A Lecture Upon the Shadow',NULL,'public',76,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e10799e8477','ch_51505a30dad7','text','{"text": "Stand still and I will read to thee"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6550f9b70afb','ch_51505a30dad7','text','{"text": "A Lecture, Love, in loves philosophy,"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91d103786bb9','ch_51505a30dad7','text','{"text": "These three houres that we have spent,"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ad11486f74e','ch_51505a30dad7','text','{"text": "Walking here, Two shadowes went"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_690d98570b2b','ch_51505a30dad7','text','{"text": "Along with us, which we our selves produc’d;"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf9cb04e49d9','ch_51505a30dad7','text','{"text": "But, now the Sunne is just above our head,"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_013295db4cd2','ch_51505a30dad7','text','{"text": "We doe those shadowes tread;"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_64e9779c3607','ch_51505a30dad7','text','{"text": "And to brave clearnesse all things are reduc’d."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca338680caf5','ch_51505a30dad7','text','{"text": "So whilst our infant loves did grow,"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_205c5b7e1483','ch_51505a30dad7','text','{"text": "Disguises did, and shadowes, flow,"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9755e5a41411','ch_51505a30dad7','text','{"text": "From us, and our cares; but now ’tis not so."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4297fa7095f4','ch_51505a30dad7','text','{"text": "That love hath not attain’d the high’st degree,"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6e7314768874','ch_51505a30dad7','text','{"text": "Which is still diligent lest others see."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46cef54b7961','ch_51505a30dad7','text','{"text": "Except our loves at this noone stay,"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1f5aca3d6b4','ch_51505a30dad7','text','{"text": "We shall new shadowes make the other way."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_10f5f7eabc1d','ch_51505a30dad7','text','{"text": "As the first were made to blinde"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0e9b75d4f08','ch_51505a30dad7','text','{"text": "Others; these which come behinde"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cac71f6ed8c4','ch_51505a30dad7','text','{"text": "Will worke upon our selves, and blind our eyes."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fbb2a0b85178','ch_51505a30dad7','text','{"text": "If our loves faint, and westwardly decline;"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a051584b4ec','ch_51505a30dad7','text','{"text": "To me thou, falsely thine;"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8637dc869f58','ch_51505a30dad7','text','{"text": "And I to thee mine actions shall disguise."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_016567fb691b','ch_51505a30dad7','text','{"text": "The morning shadowes were away,"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b6229bc95f1f','ch_51505a30dad7','text','{"text": "But these grow longer all the day,"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_93bad1c52c1e','ch_51505a30dad7','text','{"text": "But oh, loves day is short, if love decay."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3de75affc281','ch_51505a30dad7','text','{"text": "Love is a growing, or full constant light;"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_222898991774','ch_51505a30dad7','text','{"text": "And his first minute, after noone, is night."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_324d3985ca56','ch_51505a30dad7','list','{"ordered": false, "items": ["John Donne"]}',27);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_8ddb40bbe959','bk_ncert_english','12-7-poems-by-milton','12. 7 Poems by Milton',NULL,'public',77,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f294bb1de5e','ch_8ddb40bbe959','heading','{"level": 2, "text": "I"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d6807f38db43','ch_8ddb40bbe959','text','{"text": "On Time"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cae7287b8d10','ch_8ddb40bbe959','text','{"text": "Fly envious Time, till thou run out thy race,"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4bee718e2059','ch_8ddb40bbe959','text','{"text": "Call on the lazy leaden-stepping hours,"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99d37b9b5401','ch_8ddb40bbe959','text','{"text": "Whose speed is but the heavy Plummets pace;"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce7c565fafef','ch_8ddb40bbe959','text','{"text": "And glut thy self with what thy womb devours,"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c85982babe00','ch_8ddb40bbe959','text','{"text": "Which is no more than what is false and vain,"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b52ed719a894','ch_8ddb40bbe959','text','{"text": "And merely mortal dross;"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bdfddfafa402','ch_8ddb40bbe959','text','{"text": "So little is our loss,"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80a4787688f6','ch_8ddb40bbe959','text','{"text": "So little is thy gain."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbb31cc32505','ch_8ddb40bbe959','text','{"text": "For when as each thing bad thou hast entomb’d,"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d5722f072103','ch_8ddb40bbe959','text','{"text": "And last of all, thy greedy self consum’d,"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f6fadcc8cdd','ch_8ddb40bbe959','text','{"text": "Then long Eternity shall greet our bliss"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9bb5ee528960','ch_8ddb40bbe959','text','{"text": "With an individual kiss;"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b5c14f0f290','ch_8ddb40bbe959','text','{"text": "And Joy shall overtake us as a flood,"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_847c40317bf4','ch_8ddb40bbe959','text','{"text": "When every thing that is sincerely good"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d564594a780','ch_8ddb40bbe959','text','{"text": "And perfectly divine,"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e56526171005','ch_8ddb40bbe959','text','{"text": "With Truth, and Peace, and Love shall ever shine"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_170cdff2aae4','ch_8ddb40bbe959','text','{"text": "About the supreme Throne"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b90e28c90c0c','ch_8ddb40bbe959','text','{"text": "Of him, t’whose happy-making sight alone,"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_85419a21ca49','ch_8ddb40bbe959','text','{"text": "When once our heav’nly guided soul shall clime,"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b085df352e4','ch_8ddb40bbe959','text','{"text": "Then all this Earthy grossnes quit,"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5d04dc1da75','ch_8ddb40bbe959','text','{"text": "Attir’d with Stars, we shall for ever sit,"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c689333c4164','ch_8ddb40bbe959','text','{"text": "Triumphing over Death, and Chance, and thee O Time."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_513484df84c8','ch_8ddb40bbe959','heading','{"level": 2, "text": "Ii"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd42af02b67c','ch_8ddb40bbe959','text','{"text": "On Shakespear.* 1630"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca9e521afe74','ch_8ddb40bbe959','text','{"text": "What needs my Shakespear for his honour’d Bones,"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2151ebf73256','ch_8ddb40bbe959','text','{"text": "The labour of an age in piled Stones,"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24591f4f5aff','ch_8ddb40bbe959','text','{"text": "Or that his hallow’d reliques should be hid"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0608a5ca3b32','ch_8ddb40bbe959','text','{"text": "Under a Star-ypointing Pyramid?"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a4c13728347c','ch_8ddb40bbe959','text','{"text": "Dear son of memory, great heir of Fame,"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c93a7af94cd4','ch_8ddb40bbe959','text','{"text": "What need’st thou such weak witness of thy name?"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e42e61ad500','ch_8ddb40bbe959','text','{"text": "Thou in our wonder and astonishment"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_52f32bbfe1cd','ch_8ddb40bbe959','text','{"text": "Hast built thy self a live-long Monument."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e4fa2f3229d','ch_8ddb40bbe959','text','{"text": "For whilst to th’shame of slow endeavouring art,"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25108b29910c','ch_8ddb40bbe959','text','{"text": "Thy easie numbers flow, and that each heart"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e76b9c207746','ch_8ddb40bbe959','text','{"text": "Hath from the leaves of thy unvalu’d Book,"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ed37836cca6','ch_8ddb40bbe959','text','{"text": "Those Delphic lines with deep impression took,"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0cfdc3d49d3e','ch_8ddb40bbe959','text','{"text": "Then thou our fancy of it self bereaving"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d82cd6b78f17','ch_8ddb40bbe959','text','{"text": "Dost make us Marble with too much conceaving;"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d4dc1a30398a','ch_8ddb40bbe959','text','{"text": "And so Sepulcher’d in such pomp dost lie,"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e502b6b19e2','ch_8ddb40bbe959','text','{"text": "That Kings for such a Tomb would wish to die."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2aa3f3d330f8','ch_8ddb40bbe959','text','{"text": "*Notice the spelling of ‘Shakespear’ and of the words ‘easie’, ‘conceaving’."}',43);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_c32e86aa3ea7','bk_ncert_english','12-8-poems-by-blake','12.8 Poems by Blake',NULL,'public',78,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_12c6cf90c48a','ch_c32e86aa3ea7','heading','{"level": 2, "text": "I"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_61e4874ab3d1','ch_c32e86aa3ea7','text','{"text": "The Divine Image"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c3a52d8b8cc6','ch_c32e86aa3ea7','text','{"text": "To Mercy, Pity, Peace, and Love"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a0d2a8f264d5','ch_c32e86aa3ea7','text','{"text": "All pray in their distress;"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd749f4cf641','ch_c32e86aa3ea7','text','{"text": "And to these virtues of delight"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f9f64c4b4f3','ch_c32e86aa3ea7','text','{"text": "Return their thankfulness."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27d7d4eb8de3','ch_c32e86aa3ea7','text','{"text": "For Mercy, Pity, Peace, and Love"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8fbc16e1ed21','ch_c32e86aa3ea7','text','{"text": "Is God our father dear,"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af6b42efab2c','ch_c32e86aa3ea7','text','{"text": "And Mercy, Pity, Peace, and Love"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ea4ffd5e998','ch_c32e86aa3ea7','text','{"text": "Is Man, his child and care."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd69dc5f735c','ch_c32e86aa3ea7','text','{"text": "For Mercy has a human heart,"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d39c052fa74a','ch_c32e86aa3ea7','text','{"text": "Pity a human face,"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9563fb9e0e20','ch_c32e86aa3ea7','text','{"text": "And Love, the human form divine,"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58bb1dd06c4a','ch_c32e86aa3ea7','text','{"text": "And Peace, the human dress."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79642b374a46','ch_c32e86aa3ea7','text','{"text": "Then every man, of every clime,"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b252ee7c7cc0','ch_c32e86aa3ea7','text','{"text": "That prays in his distress,"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ee4fad65ae68','ch_c32e86aa3ea7','text','{"text": "Prays to the human form divine,"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c16631a6d64','ch_c32e86aa3ea7','text','{"text": "Love, Mercy, Pity, Peace."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5764a1569491','ch_c32e86aa3ea7','text','{"text": "And all must love the human form,"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f188b931bdc5','ch_c32e86aa3ea7','text','{"text": "In heathen, turk, or jew;"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2eeb81a800b3','ch_c32e86aa3ea7','text','{"text": "Where Mercy, Love, and Pity dwell"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_36bbd688ff6e','ch_c32e86aa3ea7','text','{"text": "There God is dwelling too."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbc18504a78a','ch_c32e86aa3ea7','heading','{"level": 2, "text": "Ii"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_72175a1ffb99','ch_c32e86aa3ea7','text','{"text": "The Human Abstract"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2d223124e25e','ch_c32e86aa3ea7','text','{"text": "Pity would be no more"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_681286eaab2a','ch_c32e86aa3ea7','text','{"text": "If we did not make somebody Poor;"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c528d571dfe','ch_c32e86aa3ea7','text','{"text": "And Mercy no more could be"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7bbd65a1c999','ch_c32e86aa3ea7','text','{"text": "If all were as happy as we."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f56e29587fea','ch_c32e86aa3ea7','text','{"text": "And mutual fear brings peace,"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac9150844b79','ch_c32e86aa3ea7','text','{"text": "Till the selfish loves increase:"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cee042015210','ch_c32e86aa3ea7','text','{"text": "Then Cruelty knits a snare,"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b69711b642aa','ch_c32e86aa3ea7','text','{"text": "And spreads his baits with care."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f203e80e4cce','ch_c32e86aa3ea7','text','{"text": "He sits down with holy fears,"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f97e1fc3c45','ch_c32e86aa3ea7','text','{"text": "And waters the ground with tears;"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9bc3ee729ed7','ch_c32e86aa3ea7','text','{"text": "Then Humility takes its root"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb73b0f1b6e1','ch_c32e86aa3ea7','text','{"text": "Underneath his foot."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3f027dd8adb','ch_c32e86aa3ea7','text','{"text": "Soon spreads the dismal shade"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53383eea7cdb','ch_c32e86aa3ea7','text','{"text": "Of Mystery over his head;"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82e911d34529','ch_c32e86aa3ea7','text','{"text": "And the Caterpillar and Fly"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ff5ffbcc38c','ch_c32e86aa3ea7','text','{"text": "Feed on the Mystery."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c449989663fe','ch_c32e86aa3ea7','text','{"text": "And it bears the fruit of Deceit,"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7d29281b0726','ch_c32e86aa3ea7','text','{"text": "Ruddy and sweet to eat;"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fabc9a59ecba','ch_c32e86aa3ea7','text','{"text": "And the Raven his nest has made"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3859534f60db','ch_c32e86aa3ea7','text','{"text": "In its thickest shade."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07731bf14270','ch_c32e86aa3ea7','text','{"text": "The Gods of the earth and sea"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_564ea94b3605','ch_c32e86aa3ea7','text','{"text": "Sought thro’ Nature to find this Tree;"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e760c3964e6c','ch_c32e86aa3ea7','text','{"text": "But their search was all in vain:"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05381dd249fa','ch_c32e86aa3ea7','text','{"text": "There grows one in the Human Brain."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50f7661e4776','ch_c32e86aa3ea7','text','{"text": "Note: Blake’s poetry was published in a manner most unusual in literature and art history; he personally manufactured each copy. The verses were not typeset but were, with the engravings that illustrated them, cut into copper plates. The pages themselves he illuminated in water colours. Thus Blake can be called the first multi-media artist."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2acf49f76b30','ch_c32e86aa3ea7','heading','{"level": 2, "text": "Ii"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a4147815106f','ch_c32e86aa3ea7','text','{"text": "The Human Abstract"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3da0087c44ec','ch_c32e86aa3ea7','text','{"text": "Pity would be no more"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_37048f847b67','ch_c32e86aa3ea7','text','{"text": "If we did not make somebody Poor;"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_13724fe2afcc','ch_c32e86aa3ea7','text','{"text": "And Mercy no more could be"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b8bacfe27d05','ch_c32e86aa3ea7','text','{"text": "If all were as happy as we."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f399ca0db89','ch_c32e86aa3ea7','text','{"text": "And mutual fear brings peace,"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f6a2adb94505','ch_c32e86aa3ea7','text','{"text": "Till the selfish loves increase:"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_150eae06dd61','ch_c32e86aa3ea7','text','{"text": "Then Cruelty knits a snare,"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_089437eca659','ch_c32e86aa3ea7','text','{"text": "And spreads his baits with care."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3054bb6dcb73','ch_c32e86aa3ea7','text','{"text": "He sits down with holy fears,"}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_56194fe8ada3','ch_c32e86aa3ea7','text','{"text": "And waters the ground with tears;"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f136284f88d','ch_c32e86aa3ea7','text','{"text": "Then Humility takes its root"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc01d97cf85b','ch_c32e86aa3ea7','text','{"text": "Underneath his foot."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40681938bfbd','ch_c32e86aa3ea7','text','{"text": "Soon spreads the dismal shade"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2245ef563e1','ch_c32e86aa3ea7','text','{"text": "Of Mystery over his head;"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8fc1ce48dba9','ch_c32e86aa3ea7','text','{"text": "And the Caterpillar and Fly"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d18703e83c39','ch_c32e86aa3ea7','text','{"text": "Feed on the Mystery."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0665a2a5387','ch_c32e86aa3ea7','text','{"text": "And it bears the fruit of Deceit,"}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e9608a6cb54','ch_c32e86aa3ea7','text','{"text": "Ruddy and sweet to eat;"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc5a92418dc0','ch_c32e86aa3ea7','text','{"text": "And the Raven his nest has made"}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1484036e40dc','ch_c32e86aa3ea7','text','{"text": "In its thickest shade."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_508f1cbfdaa6','ch_c32e86aa3ea7','text','{"text": "The Gods of the earth and sea"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3edb7506f10f','ch_c32e86aa3ea7','text','{"text": "Sought thro’ Nature to find this Tree;"}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_62e08ded5339','ch_c32e86aa3ea7','text','{"text": "But their search was all in vain:"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e4464f09f95','ch_c32e86aa3ea7','text','{"text": "There grows one in the Human Brain."}',75);
