INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_b63abdc3a4ae','bk_ncert_english','12-9-kubla-khan-or-a-vision-in-a-dream-a-fragment','12.9 Kubla Khan Or A Vision in a Dream: A Fragment',NULL,'public',79,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_041df026a535','ch_b63abdc3a4ae','text','{"text": "* Kubla Khan founded the Mongol dynasty in China in the thirteenth century."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e99e80a8f666','ch_b63abdc3a4ae','text','{"text": "* You will notice that this poem is incomplete. There is a reason behind this. In 1797, when Coleridge fell ill, some medicine was prescribed, from the effects of which he fell asleep in his chair while reading about Kubla Khan. In the three hours of profound sleep, he had a wonderful dream. On awakening he distinctly recollected it, and began to write it down, when he was interrupted by a chance visitor. The poem thus remained incomplete."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6fe71c8f63a1','ch_b63abdc3a4ae','text','{"text": "In Xanadu did Kubla Khan"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fcfe5e9eef9e','ch_b63abdc3a4ae','text','{"text": "A stately pleasure-dome decree:"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fc5281f05e3f','ch_b63abdc3a4ae','text','{"text": "Where Alph, the sacred river, ran"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4487abe713b4','ch_b63abdc3a4ae','text','{"text": "Through caverns measureless to man"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b7c9d0ee887','ch_b63abdc3a4ae','text','{"text": "Down to a sunless sea."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3927c3b29261','ch_b63abdc3a4ae','text','{"text": "So twice five miles of fertile ground"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ac7ca1630f2','ch_b63abdc3a4ae','text','{"text": "With walls and towers were girdled round:"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_45bf8c17107a','ch_b63abdc3a4ae','text','{"text": "And there were gardens bright with sinuous rills,"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d10c30d4ae9','ch_b63abdc3a4ae','text','{"text": "Where blossomed many an incense-bearing tree;"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9857e7026d9a','ch_b63abdc3a4ae','text','{"text": "And here were forests ancient as the hills,"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c78eca1a964','ch_b63abdc3a4ae','text','{"text": "Enfolding sunny spots of greenery."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd70682df9a5','ch_b63abdc3a4ae','text','{"text": "But oh! that deep romantic chasm which slanted"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db095fecfbd6','ch_b63abdc3a4ae','text','{"text": "Down the green hill athwart a cedarn cover!"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff884f6712f4','ch_b63abdc3a4ae','text','{"text": "A savage place! as holy and enchanted"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b892560cf3c','ch_b63abdc3a4ae','text','{"text": "As e’er beneath a waning moon was haunted"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_805772150141','ch_b63abdc3a4ae','text','{"text": "By woman wailing for her demon-lover!"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d223a2bce335','ch_b63abdc3a4ae','text','{"text": "And from this chasm, with ceaseless turmoil seething,"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_08f1281a0f08','ch_b63abdc3a4ae','text','{"text": "As if this earth in fast thick pants were breathing,"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ffbdf5b3a7e9','ch_b63abdc3a4ae','text','{"text": "A mighty fountain momently was forced;"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_13192fd7f7e7','ch_b63abdc3a4ae','text','{"text": "Amid whose swift half-intermitted burst"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7412a1e2a56e','ch_b63abdc3a4ae','text','{"text": "Huge fragments vaulted like rebounding hail,"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d2292a7f197','ch_b63abdc3a4ae','text','{"text": "Or chaffy grain beneath the thresher’s flail:"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8e2a4a5a4d6f','ch_b63abdc3a4ae','text','{"text": "And ’mid these dancing rocks at once and ever"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbd998c37f87','ch_b63abdc3a4ae','text','{"text": "It flung up momently the sacred river."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e68f9f2a7de7','ch_b63abdc3a4ae','text','{"text": "Five miles meandering with a mazy motion"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_620b006f6b54','ch_b63abdc3a4ae','text','{"text": "Through wood and dale the sacred river ran,"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_38a9e06d3cf7','ch_b63abdc3a4ae','text','{"text": "Then reached the caverns measureless to man,"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_840b2d69514c','ch_b63abdc3a4ae','text','{"text": "And sank in tumult to a lifeless ocean:"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb7d12f3b6cb','ch_b63abdc3a4ae','text','{"text": "And ’mid this tumult Kubla heard from far"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_85df917da644','ch_b63abdc3a4ae','text','{"text": "Ancestral voices prophesying war!"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1418d803997','ch_b63abdc3a4ae','text','{"text": "The shadow of the dome of pleasure"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_645dfab887fa','ch_b63abdc3a4ae','text','{"text": "Floated midway on the waves;"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c4149ab84297','ch_b63abdc3a4ae','text','{"text": "Where was heard the mingled measure"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8e1d3464365','ch_b63abdc3a4ae','text','{"text": "From the fountain and the caves."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e01f803ef568','ch_b63abdc3a4ae','text','{"text": "It was a miracle of rare device,"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b4d68a00532b','ch_b63abdc3a4ae','text','{"text": "A sunny pleasure dome with caves of ice!"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f865a5760571','ch_b63abdc3a4ae','text','{"text": "A damsel with a dulcimer"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a86c8f1eb1d','ch_b63abdc3a4ae','text','{"text": "In a vision once I saw:"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_72b1171a55e0','ch_b63abdc3a4ae','text','{"text": "It was an Abyssinian maid,"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68c1a3b2c898','ch_b63abdc3a4ae','text','{"text": "And on her dulcimer she played,"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_262aa885d679','ch_b63abdc3a4ae','text','{"text": "Singing of Mount Abora."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68f16a6c0b0e','ch_b63abdc3a4ae','text','{"text": "Could I revive within me"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_87f2d30a82aa','ch_b63abdc3a4ae','text','{"text": "Her symphony and song,"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5a385a4a0fcd','ch_b63abdc3a4ae','text','{"text": "To such a deep delight, ’twould win me,"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71ca789d9076','ch_b63abdc3a4ae','text','{"text": "That with music loud and long,"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d7dd4bae8e5','ch_b63abdc3a4ae','text','{"text": "I would build that dome in air,"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e921592a0954','ch_b63abdc3a4ae','text','{"text": "That sunny dome! those caves of ice!"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_400376cfe8a9','ch_b63abdc3a4ae','text','{"text": "And all who heard should see them there,"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea6aa0436809','ch_b63abdc3a4ae','text','{"text": "And all should cry, Beware! Beware!"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70a7ff61da27','ch_b63abdc3a4ae','text','{"text": "His flashing eyes, his floating hair!"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7f003415b78','ch_b63abdc3a4ae','text','{"text": "Weave a circle round him thrice,"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b6eeadf9dd72','ch_b63abdc3a4ae','text','{"text": "And close your eyes with holy dread,"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2d85e60f9b23','ch_b63abdc3a4ae','text','{"text": "For he on honeydew hath fed,"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2605b095d35b','ch_b63abdc3a4ae','text','{"text": "And drunk the milk of Paradise."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_127b7a2dcee8','ch_b63abdc3a4ae','list','{"ordered": false, "items": ["S.T.Coleridge"]}',57);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_9164d5d00a3d','bk_ncert_english','12-10-trees','12.10 Trees',NULL,'public',80,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd7d300187d1','ch_9164d5d00a3d','text','{"text": "The Trees like Tassels hit – and – swung –"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f9edf51d1674','ch_9164d5d00a3d','text','{"text": "There seemed to rise a Tune"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb6417b1a964','ch_9164d5d00a3d','text','{"text": "From Miniature Creatures"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_39d4b2cd18cf','ch_9164d5d00a3d','text','{"text": "Accompanying the Sun –"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20ae529470a7','ch_9164d5d00a3d','text','{"text": "Far Psalteries of Summer –"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d46ae1124b9','ch_9164d5d00a3d','text','{"text": "Enamoring the Ear"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abcdd3aad7cf','ch_9164d5d00a3d','text','{"text": "They never yet did satisfy –"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fabfbef42b98','ch_9164d5d00a3d','text','{"text": "Remotest – when most fair"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a7bc51001d6','ch_9164d5d00a3d','text','{"text": "The Sun shone whole at intervals –"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c13844e7756','ch_9164d5d00a3d','text','{"text": "Then Half – then utter hid –"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e22e6fdacc0','ch_9164d5d00a3d','text','{"text": "As if Himself were optional"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2248d15cba04','ch_9164d5d00a3d','text','{"text": "And had Estates of Cloud"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0864251ed1d','ch_9164d5d00a3d','text','{"text": "Sufficient to enfold Him"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c9c23c643ad','ch_9164d5d00a3d','text','{"text": "Eternally from view –"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6084fbff392f','ch_9164d5d00a3d','text','{"text": "Except it were a whim of His"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bff5e778d967','ch_9164d5d00a3d','text','{"text": "To let the Orchards grow –"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71043bfdeae2','ch_9164d5d00a3d','text','{"text": "A Bird sat careless on the fence –"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1528ddb7740d','ch_9164d5d00a3d','text','{"text": "One gossiped in the Lane"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9423a21ce2a5','ch_9164d5d00a3d','text','{"text": "On silver matters charmed a Snake"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba85ae111e11','ch_9164d5d00a3d','text','{"text": "Just winding round a Stone –"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db6b6399b683','ch_9164d5d00a3d','text','{"text": "Bright Flowers slit a Calyx"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5bceb06b5914','ch_9164d5d00a3d','text','{"text": "And soared upon a Stem"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f4dff32ee071','ch_9164d5d00a3d','text','{"text": "Like Hindered Flags – Sweet hoisted –"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b7ad44e4b8d2','ch_9164d5d00a3d','text','{"text": "With Spices – in the Hem –"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51b5f5d15d3c','ch_9164d5d00a3d','text','{"text": "’Twas more – I cannot mention –"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb5cde0ca4f1','ch_9164d5d00a3d','text','{"text": "How mean – to those that see"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db3cca71cae8','ch_9164d5d00a3d','text','{"text": "Vandyke’s Delineation"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b23f0053551','ch_9164d5d00a3d','text','{"text": "Of Nature’s – Summer Day!"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53cc845e1e68','ch_9164d5d00a3d','list','{"ordered": false, "items": ["Emily Dickinson"]}',29);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_17b925ee8208','bk_ncert_english','12-11-the-wild-swans-at-coole','12.11 The Wild Swans at Coole',NULL,'public',81,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f9e70bede0b','ch_17b925ee8208','text','{"text": "The trees are in their autumn beauty,"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b8dac3b1127f','ch_17b925ee8208','text','{"text": "The woodland paths are dry,"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e7d7b9713ce','ch_17b925ee8208','text','{"text": "Under the October twilight the water"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c3df045400f2','ch_17b925ee8208','text','{"text": "Mirrors a still sky;"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5db584cbe94d','ch_17b925ee8208','text','{"text": "Upon the brimming water among the stones"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_280bd60acab5','ch_17b925ee8208','text','{"text": "Are nine-and-fifty swans."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd08d8ff90b0','ch_17b925ee8208','text','{"text": "The nineteenth autumn has come upon me"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1f7d69cbbcd','ch_17b925ee8208','text','{"text": "Since I first made my count;"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1bb2c499e32','ch_17b925ee8208','text','{"text": "I saw, before I had well finished,"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_60394053fdd5','ch_17b925ee8208','text','{"text": "All suddenly mount"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22864088cd9b','ch_17b925ee8208','text','{"text": "And scatter wheeling in great broken rings"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d1c169a2c4d1','ch_17b925ee8208','text','{"text": "Upon their clamorous wings."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b7208956b76','ch_17b925ee8208','text','{"text": "I have looked upon those brilliant creatures,"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d5d2bdef188e','ch_17b925ee8208','text','{"text": "And now my heart is sore."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a3d3f67e3cc','ch_17b925ee8208','text','{"text": "All’s changed since I, hearing at twilight,"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_94accedce83a','ch_17b925ee8208','text','{"text": "The first time on this shore,"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_379dd93668b1','ch_17b925ee8208','text','{"text": "The bell-beat of their wings above my head,"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_714d6d8c4009','ch_17b925ee8208','text','{"text": "Trod with a lighter tread."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_441d4f031995','ch_17b925ee8208','text','{"text": "Unwearied still, lover by lover,"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92ac02bfab08','ch_17b925ee8208','text','{"text": "They paddle in the cold"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67fb7b2e6d12','ch_17b925ee8208','text','{"text": "Companionable streams or climb the air;"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f10cd81c464b','ch_17b925ee8208','text','{"text": "Their hearts have not grown old;"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_379ed081efb4','ch_17b925ee8208','text','{"text": "Passion or conquest, wander where they will,"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c292ffc70e18','ch_17b925ee8208','text','{"text": "Attend upon them still."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_77b632bb8c09','ch_17b925ee8208','text','{"text": "But now they drift on the still water,"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b540676129b','ch_17b925ee8208','text','{"text": "Mysterious, beautiful;"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd479f5937c5','ch_17b925ee8208','text','{"text": "Among what rushes will they build,"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4fa88c2f654','ch_17b925ee8208','text','{"text": "By what lake’s edge or pool"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e61b2aaab808','ch_17b925ee8208','text','{"text": "Delight men’s eyes when I awake some day"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af6bb3f3b9b7','ch_17b925ee8208','text','{"text": "To find they have flown away?"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_796bed93eafa','ch_17b925ee8208','list','{"ordered": false, "items": ["W.B.Yeats"]}',31);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_b94ad4d8a371','bk_ncert_english','12-12-time-and-time-again','12.12 Time and Time Again',NULL,'public',82,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd54b7b3c877','ch_b94ad4d8a371','text','{"text": "Or listen to the clocktowers"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_caa5b87c70f5','ch_b94ad4d8a371','text','{"text": "of any old well-managed city"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f58ce1b2990e','ch_b94ad4d8a371','text','{"text": "beating their gongs round the clock, each slightly"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c78fab7535f7','ch_b94ad4d8a371','text','{"text": "off the others’ time, deeper or lighter"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dad9bb8e43b8','ch_b94ad4d8a371','text','{"text": "in its bronze, beating out a different"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_61e0a08cd5ae','ch_b94ad4d8a371','text','{"text": "sequence each half-hour, out of the accidents"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b8f359b56195','ch_b94ad4d8a371','text','{"text": "of alloy, a maker’s shaking hand"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_729ff20a6f86','ch_b94ad4d8a371','text','{"text": "in Switzerland, or the mutual distances"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4555b5f06747','ch_b94ad4d8a371','text','{"text": "commemorating a donor’s whim,"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_88dda5bf3dee','ch_b94ad4d8a371','text','{"text": "the perennial feuds and seasonal alliance"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f4412af8d8d1','ch_b94ad4d8a371','text','{"text": "of Hindu, Christian, and Muslim—"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_faf75eddbb8e','ch_b94ad4d8a371','text','{"text": "cut off sometimes by a change of wind,"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_322ad51eabc5','ch_b94ad4d8a371','text','{"text": "a change of mind, or a siren"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1563def568fe','ch_b94ad4d8a371','text','{"text": "between the pieces of a backstreet quarrel."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67326ff3292f','ch_b94ad4d8a371','text','{"text": "One day you look up and see one of them"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7b6885d202b6','ch_b94ad4d8a371','text','{"text": "eyeless, silent, a zigzag sky showing"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a6e836e98e7','ch_b94ad4d8a371','text','{"text": "through the knocked-out clockwork, after a riot,"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3c72fcb9385','ch_b94ad4d8a371','text','{"text": "a peace-march time bomb, or a precise act"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_30b492bcf0bc','ch_b94ad4d8a371','text','{"text": "Of nature in a night of lightnings."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f7f454799b9','ch_b94ad4d8a371','list','{"ordered": false, "items": ["A.K.Ramanujan"]}',20);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_03bed2dd8e45','bk_ncert_english','12-13-blood','12.13 Blood',NULL,'public',83,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ebc98f4e458','ch_03bed2dd8e45','text','{"text": "When we were children"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44d8f4f09cd2','ch_03bed2dd8e45','text','{"text": "My brother and I"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bf2c15dbdf3d','ch_03bed2dd8e45','text','{"text": "And always playing on the sands"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e18a88ec342','ch_03bed2dd8e45','text','{"text": "Drawing birds and animals"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d36bfde3c113','ch_03bed2dd8e45','text','{"text": "Our great-grandmother said one day,"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fda0fe3a7033','ch_03bed2dd8e45','text','{"text": "You see this house of ours"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67fdee408360','ch_03bed2dd8e45','text','{"text": "Now three hundred years old,"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a0342cc6e51e','ch_03bed2dd8e45','text','{"text": "It’s falling to little bits"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_deb8be3fc8a9','ch_03bed2dd8e45','text','{"text": "Before our very eyes"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef07f5aeb53b','ch_03bed2dd8e45','text','{"text": "The walls are cracked and torn"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44710d97bf9b','ch_03bed2dd8e45','text','{"text": "And moistened by the rains,"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_981d6966d2a0','ch_03bed2dd8e45','text','{"text": "The tiles have fallen here and there"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c6eac8f2fa7','ch_03bed2dd8e45','text','{"text": "The windows whine and groan"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f13f75e3c34','ch_03bed2dd8e45','text','{"text": "And every night"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_95f933f3e892','ch_03bed2dd8e45','text','{"text": "The rats come out of the holes"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd7d7d3ec609','ch_03bed2dd8e45','text','{"text": "And scamper past our doors."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e9331dae4649','ch_03bed2dd8e45','text','{"text": "The snake-shrine is dark with weeds"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c032ffb0a60','ch_03bed2dd8e45','text','{"text": "And all the snake-gods in the shrine"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a329cdf9430e','ch_03bed2dd8e45','text','{"text": "Have lichen on their hoods."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3c45ced2ebb4','ch_03bed2dd8e45','text','{"text": "O it hurts me she cried,"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67fd423c3e18','ch_03bed2dd8e45','text','{"text": "Wiping a reddened eye"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b0671d7f1a6','ch_03bed2dd8e45','text','{"text": "For I love this house, it hurts me much"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a662ea25d4ef','ch_03bed2dd8e45','text','{"text": "To watch it die."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7caa317fb128','ch_03bed2dd8e45','text','{"text": "When I grow old, I said,"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4fc47cf1953b','ch_03bed2dd8e45','text','{"text": "And very very rich"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_782fc25f5cdc','ch_03bed2dd8e45','text','{"text": "I shall rebuild the fallen walls"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b90c313229d','ch_03bed2dd8e45','text','{"text": "And make new this ancient house."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0529adf294cc','ch_03bed2dd8e45','text','{"text": "My great-grandmother"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_242ef73a42dc','ch_03bed2dd8e45','text','{"text": "Touched my cheeks and smiled."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_81872c1100b2','ch_03bed2dd8e45','text','{"text": "She was really simple."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f13c7ae087c8','ch_03bed2dd8e45','text','{"text": "Fed on God for years"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4be2fe56b928','ch_03bed2dd8e45','text','{"text": "All her feasts were monotonous"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2d8cc1b45878','ch_03bed2dd8e45','text','{"text": "For the only dish was always God"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad95315df3bf','ch_03bed2dd8e45','text','{"text": "And the rest mere condiments."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_85998ca2bf1b','ch_03bed2dd8e45','text','{"text": "She told us how she rode her elephant"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbc4efba94f8','ch_03bed2dd8e45','text','{"text": "When she was ten or eleven"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27f319783b31','ch_03bed2dd8e45','text','{"text": "Every Monday without fail"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c5ef24eeb66','ch_03bed2dd8e45','text','{"text": "To the Siva shrine"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f670c4280e62','ch_03bed2dd8e45','text','{"text": "And back to home again"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51582bf8aa8d','ch_03bed2dd8e45','text','{"text": "And, told us of the jewel box"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c19b00c6676','ch_03bed2dd8e45','text','{"text": "And the brocade from the north"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b0f254fbbf3','ch_03bed2dd8e45','text','{"text": "And the perfumes and the oils"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44fe287685e0','ch_03bed2dd8e45','text','{"text": "And the sandal for her breasts"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_412d8dd2c44b','ch_03bed2dd8e45','text','{"text": "And her marriage to a prince"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_155338f93e3f','ch_03bed2dd8e45','text','{"text": "Who loved her deeply for a lovely short year"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa8fc51f6541','ch_03bed2dd8e45','text','{"text": "And died of fever, in her arms"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_673986109550','ch_03bed2dd8e45','text','{"text": "She told us"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5d27deba9d2','ch_03bed2dd8e45','text','{"text": "That we had the oldest blood"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a8c101bd2be3','ch_03bed2dd8e45','text','{"text": "My brother and she and I"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc63b4e03717','ch_03bed2dd8e45','text','{"text": "The oldest blood in the world"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f8556cd16e35','ch_03bed2dd8e45','text','{"text": "A blood thin and clear and fine"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9129608176f0','ch_03bed2dd8e45','text','{"text": "While in the veins of the always poor"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d520e18561bf','ch_03bed2dd8e45','text','{"text": "And in the veins"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90f17073a71c','ch_03bed2dd8e45','text','{"text": "Of the new-rich men"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_31d659e0467b','ch_03bed2dd8e45','text','{"text": "Flowed a blood thick as gruel"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3417555b158d','ch_03bed2dd8e45','text','{"text": "And muddy as a ditch."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2024b9d23cf3','ch_03bed2dd8e45','text','{"text": "Finally she lay dying"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_212c359cf818','ch_03bed2dd8e45','text','{"text": "In her eighty sixth year"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c994788d96d4','ch_03bed2dd8e45','text','{"text": "A woman wearied by compromise"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a01431878653','ch_03bed2dd8e45','text','{"text": "Her legs quilted with arthritis"}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_546930175a86','ch_03bed2dd8e45','text','{"text": "And with only a hard cough"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3b1ed81f48c','ch_03bed2dd8e45','text','{"text": "For comfort"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7cbfebc32b6d','ch_03bed2dd8e45','text','{"text": "I looked deep into her eyes"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cfa4fa89c248','ch_03bed2dd8e45','text','{"text": "Her poor bleary eyes"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74727067be17','ch_03bed2dd8e45','text','{"text": "And prayed that she would not grieve"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_269e0ddaba8a','ch_03bed2dd8e45','text','{"text": "So much about the house."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4a21ff6e62ef','ch_03bed2dd8e45','text','{"text": "I had learnt by then"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b7f71239f422','ch_03bed2dd8e45','text','{"text": "Most lessons of defeat,"}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44db471e4b16','ch_03bed2dd8e45','text','{"text": "Had found out that to grow rich"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0dc9606cbffd','ch_03bed2dd8e45','text','{"text": "Was a difficult feat."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0f36370988b','ch_03bed2dd8e45','text','{"text": "The house was crouching"}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ccf5646b7cb6','ch_03bed2dd8e45','text','{"text": "On its elbows then,"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_15a9a607c446','ch_03bed2dd8e45','text','{"text": "It looked that night in the pallid moon"}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aca3ba65aa8c','ch_03bed2dd8e45','text','{"text": "So grotesque and alive."}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_14486ab21d02','ch_03bed2dd8e45','text','{"text": "When they burnt my great grandmother"}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09f03d0a6d11','ch_03bed2dd8e45','text','{"text": "Over logs of the mango tree"}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51c0af9ddbaa','ch_03bed2dd8e45','text','{"text": "I looked once at the house"}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6cdd852b45e9','ch_03bed2dd8e45','text','{"text": "And then again and again"}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b6565524c284','ch_03bed2dd8e45','text','{"text": "For I thought I saw the windows close"}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8164b0dc95e1','ch_03bed2dd8e45','text','{"text": "Like the closing of the eyes"}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_969541e18329','ch_03bed2dd8e45','text','{"text": "I thought I heard the pillars groan"}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e61512d8d63','ch_03bed2dd8e45','text','{"text": "And the dark rooms heave a sigh."}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e48fb7e110e6','ch_03bed2dd8e45','text','{"text": "I set forth again"}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0abb9350894','ch_03bed2dd8e45','text','{"text": "For other towns,"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f4dd39e2a89c','ch_03bed2dd8e45','text','{"text": "Left the house with the shrine"}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce015645591d','ch_03bed2dd8e45','text','{"text": "And the sands"}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_553495fc07c2','ch_03bed2dd8e45','text','{"text": "And the flowering shrubs"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de3308d98f01','ch_03bed2dd8e45','text','{"text": "And the wide rabid mouth of the Arabian Sea."}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8682e155af50','ch_03bed2dd8e45','text','{"text": "* * *"}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70d1aac0a9ac','ch_03bed2dd8e45','text','{"text": "I know the rats are running now"}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e007413a393','ch_03bed2dd8e45','text','{"text": "Across the darkened halls"}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d871cdafd6f','ch_03bed2dd8e45','text','{"text": "They do not fear the dead"}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_896fb6a182ac','ch_03bed2dd8e45','text','{"text": "I know the white ants have reached my home"}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_136f2cf187a5','ch_03bed2dd8e45','text','{"text": "And have raised on walls"}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1ba8a69fd233','ch_03bed2dd8e45','text','{"text": "Strange totems of burial."}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a2de097aeda','ch_03bed2dd8e45','text','{"text": "At night, in stillness,"}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_318a56744fae','ch_03bed2dd8e45','text','{"text": "From every town I live in"}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_191c758e9886','ch_03bed2dd8e45','text','{"text": "I hear the rattle of its death"}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dfd2fb3fab24','ch_03bed2dd8e45','text','{"text": "The noise of rafters creaking"}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1bcc88e3041','ch_03bed2dd8e45','text','{"text": "And the windows’ whine."}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e1fb1a1e2de','ch_03bed2dd8e45','text','{"text": "I have let you down"}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_965dec457044','ch_03bed2dd8e45','text','{"text": "Old house, I seek forgiveness"}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_590fc94e8e14','ch_03bed2dd8e45','text','{"text": "O mother’s mother’s mother"}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27386c950f84','ch_03bed2dd8e45','text','{"text": "I have plucked your soul"}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f55c6a2eac64','ch_03bed2dd8e45','text','{"text": "Like a pip from a fruit"}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fea969b16bb5','ch_03bed2dd8e45','text','{"text": "And have flung it into your pyre"}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8525eb05588b','ch_03bed2dd8e45','text','{"text": "Call me callous"}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_77ca0ac342d3','ch_03bed2dd8e45','text','{"text": "Call me selfish"}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5640e24606c','ch_03bed2dd8e45','text','{"text": "But do not blame my blood"}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b5d80d8fa17','ch_03bed2dd8e45','text','{"text": "So thin, so clear, so fine"}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50a37f9eb57a','ch_03bed2dd8e45','text','{"text": "The oldest blood in the world"}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_408378ca9694','ch_03bed2dd8e45','text','{"text": "That remembers as it flows"}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0eab42d7142','ch_03bed2dd8e45','text','{"text": "All the gems and all the gold"}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be4a1293adb3','ch_03bed2dd8e45','text','{"text": "And all the perfumes and the oils"}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_196b04d97533','ch_03bed2dd8e45','text','{"text": "And the stately"}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d38718e794df','ch_03bed2dd8e45','text','{"text": "Elephant ride..."}',116);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82cd40a0f012','ch_03bed2dd8e45','list','{"ordered": false, "items": ["Kamala Das"]}',117);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_20283ed490af','bk_ncert_english','non-fiction','Non-fiction',NULL,'public',84,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17c0e9b9b976','ch_20283ed490af','heading','{"level": 2, "text": "Introduction"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0210709393c4','ch_20283ed490af','text','{"text": "Non-fiction is virtually everything that we read as literature but that does not come under the categories of novel, short story, play or poem. Nonfiction, then, is writing that is factually true. It can include articles, editorials, reports, critical essays and interviews, humorous sketches, biographies and autobiographies, lectures, speeches and sermons."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0006a4e795c8','ch_20283ed490af','text','{"text": "This section contains six non-fiction pieces, three by established writers of the canon: George Bernard Shaw, Virginia Woolf and D.H.Lawrence; one each by Ingmar Bergman, Amartya Sen and Isaac Asimov. The themes are: freedom, stream of consciousness, importance of the novel as a creative form, the details that make film-making a creative art and the argumentative tradition in Indian culture based on the famous dialogue between Krishna and Arjuna in the Bhagavad Gita."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90b52def51f6','ch_20283ed490af','text','{"text": "Asimov’s piece talks of the universe of science fiction, correlating it to accounts of mythical superhuman beings in the pre-scientific universe which served to fulfil the same emotional needs as science fiction does. The purpose of such writing is to explain, analyse, define or clarify something—to provide us with information and to show the how and why of things."}',4);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_67d157e1179d','bk_ncert_english','12-14-freedom','12.14 Freedom',NULL,'public',85,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fbd8624ec960','ch_67d157e1179d','text','{"text": "What is a perfectly free person? Evidently a person who can do what he likes, when he likes, and where he likes, or do nothing at all if he prefers it. Well, there is no such person, and there never can be any such person. Whether we like it or not, we must all sleep for one third of our lifetime—wash and dress and undress—we must spend a couple of hours eating and drinking—we must spend nearly as much in getting about from place to place."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0e935f53919','ch_67d157e1179d','text','{"text": "For half the day we are slaves to necessities which we cannot shirk, whether we are monarchs with a thousand slaves or humble labourers with no servants but their wives. And the wives must undertake the additional heavy slavery of childbearing, if the world is still to be peopled. These natural jobs cannot be shirked. But they involve other jobs which can."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25a593e2ce7f','ch_67d157e1179d','text','{"text": "As we must eat we must first provide food;"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ac3c462950e','ch_67d157e1179d','text','{"text": "as we must sleep, we must have beds, and bedding in houses with fireplaces and coals;"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_007c30cb6616','ch_67d157e1179d','text','{"text": "as we must walk through the streets, we must have clothes to cover our nakedness. Now, food and houses and clothes can be produced by human labour. But when they are produced they can be stolen. If you like honey you can let the bees produce it by their labour, and then steal it from them."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa6ab232afb6','ch_67d157e1179d','text','{"text": "If you are too lazy to get about from place to place on your own legs you can make a slave of a horse. And what you do to a horse or a bee, you can also do to a man or woman or a child, if you can get the upper hand of them by force or fraud or trickery of any sort, or even by teaching them that it is their religious duty to sacrifice their freedom to yours."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d8f4339a6385','ch_67d157e1179d','text','{"text": "So beware! If you allow any person, or class of persons, to get the upper hand of you, he will shift all that part of his slavery to Nature that can be shifted on to your shoulders;"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4a9fdb86e852','ch_67d157e1179d','text','{"text": "and you will find yourself working from eight to fourteen hours a day when, if you had only yourself and your family to provide for, you could do it quite comfortably in half the time or less. The object of all honest governments should be to prevent your being imposed on in this way."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef94524b1429','ch_67d157e1179d','text','{"text": "But the object of most actual governments, I regret to say, is exactly the opposite. They enforce your slavery and call it freedom. But they also regulate your slavery, keeping the greed of your masters within certain bounds."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_94592aa0e8b6','ch_67d157e1179d','text','{"text": "When chattel slavery of the negro sort costs more than wage slavery, they abolish chattel slavery and make you free to choose between one employment or one master and another and this they call a glorious triumph for freedom, though for you it is merely the key of the street. When you complain, they promise that in future you shall govern the country for yourself. They redeem this promise by giving you a vote, and having a general election every five years or so."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24616ea79402','ch_67d157e1179d','text','{"text": "At the election two of their rich friends ask for your vote and you are free to choose which of them you will vote for to spite the other—a choice which leaves you no freer than you were before, as it does not reduce your hours of labour by a single minute. But the newspapers assure you that your vote has decided the election, and that this constitutes you a free citizen in a democratic country. The amazing thing about it is that you are fool enough to believe them."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2dc9ffda2bac','ch_67d157e1179d','text','{"text": "Now mark another big difference between the natural slavery of man to Nature and the unnatural slavery of man to man. Nature is kind to her slaves. If she forces you to eat and drink, she makes eating and drinking so pleasant that when we can afford it we eat and drink too much. We must sleep or go mad: but then sleep is so pleasant that we have great difficulty in getting up in the morning."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51a99e56c07d','ch_67d157e1179d','text','{"text": "And firesides and families seem so pleasant to the young that they get married and join building societies to realise their dreams. Thus, instead of resenting our natural wants as slavery, we take the greatest pleasure in their satisfaction. We write sentimental songs in praise of them. A tramp can earn his supper by singing Home, Sweet Home. The slavery of man to man is the very opposite of this. It is hateful to the body and to the spirit."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c84009f0d60a','ch_67d157e1179d','text','{"text": "Our poets do not praise it: they proclaim that no man is good enough to be another man’s master. The latest of the great Jewish prophets, a gentleman named Marx, spent his life in proving that there is no extremity of selfish cruelty at which the slavery of man to man will stop if it be not stopped by law."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a95bf6dbc106','ch_67d157e1179d','text','{"text": "You can see for yourself that it produces a state of continual civil war—called the class war—between the slaves and their masters, organised as Trade Unions on one side and Employers’ Federations on the other."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a30f16f2c230','ch_67d157e1179d','text','{"text": "Saint Thomas More, who has just been canonized, held that we shall never have a peaceful and stable society until this struggle is ended by the abolition of slavery altogether, and the compulsion of everyone to do his share of the world’s work with his own hands and brains, and not to attempt to put it on anyone else. Naturally the master class, through its parliaments and schools and newspapers, makes the most desperate efforts to prevent us from realising our slavery."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a8da1e17cd56','ch_67d157e1179d','text','{"text": "From our earliest years we are taught that our country is the land of the free, and that our freedom was won for us by our forefathers when they made King John sign Magna Charta (also spelt Carta)—when they defeated the Spanish Armada—when they cut off King Charles’s head—when they made King William accept the Bill of Rights—when they issued and made good the American Declaration of Independence—when they won the battles of Waterloo and Trafalgar on the playing-fields of Eton—and when, only the other day, they quite unintentionally changed the German, Austrian, Russian, and Ottoman empires into republics. When we grumble, we are told that all our miseries are our own doing because we have the vote. When we say"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_412b220de9db','ch_67d157e1179d','text','{"text": "‘What good is the vote?’ we are told that we have the Factory Acts, and the Wages Boards, and free education, and the New Deal, and the dole;"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c667e8c49455','ch_67d157e1179d','text','{"text": "and what more could any reasonable man ask for? We are reminded that the rich are taxed a quarter—a third—or even a half and more of their incomes;"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b707ae497bf5','ch_67d157e1179d','text','{"text": "but the poor are never reminded that they have to pay that much of their wages as rent in addition to having to work twice as long every day as they would need if they were free."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_629b78ce9824','ch_67d157e1179d','text','{"text": "Whenever famous writers protest against this imposture—say Voltaire and Rousseau and Tom Paine in the eighteenth century, or Cobbett and Shelley, Karl Marx and Lassalle in the nineteenth, or Lenin and Trotsky in the twentieth—you are taught that they are atheists and libertines, murderers and scoundrels, and often it is made a criminal offence to buy or sell their books."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0dea2d230e60','ch_67d157e1179d','text','{"text": "If their disciples make a revolution, England immediately makes war on them and lends money to the other Powers to join her in forcing the revolutionists restore the slave order. When this combination was successful at Waterloo, the victory was advertised as another triumph for British freedom;"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af858a613ad7','ch_67d157e1179d','text','{"text": "and the British wage-slaves, instead of going into mourning like Lord Byron, believed it all and cheered enthusiastically."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e7ddbe903aa','ch_67d157e1179d','text','{"text": "When the revolution wins, as it did in Russia in 1922, the fighting stops;"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b8ffaeacfd8','ch_67d157e1179d','text','{"text": "but the abuse, the calumnies, the lies continue until the revolutionised State grows into a firstrate military power. Then our diplomatists, after having for years denounced the revolutionary leaders as the most abominable villains and tyrants, have to do a right turn and invite them to dinner."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_502ec911c356','ch_67d157e1179d','text','{"text": "Now, though this prodigious mass of humbug is meant to delude the enslaved masses only, it ends in deluding the master class much more completely."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d44606694290','ch_67d157e1179d','text','{"text": "A gentleman whose mind has been formed at a preparatory school for the sons of gentlemen, followed by a public school and university course, is much more thoroughly taken in by the falsified history and dishonest political economy and the snobbery taught in these places than any worker can possibly be, because the gentleman’s education teaches him that he is a very fine fellow, superior to the common run of men whose duty it is to brush his clothes, carry his parcels, and earn his income for him, and as he thoroughly agrees with this view of himself, he honestly believes that the system which has placed him in such an agreeable situation and done such justice to his merits is the best of all possible systems, and that he should shed his blood, and yours, to the last drop in its defence. But the great mass of our rack-rented, underpaid, treated-as-inferiors cast-off-onthe- dole workers cannot feel so sure about it as the gentleman. The facts are too harshly against it. In hard times, such as we are now passing through, their disgust and despair sometimes lead them to kick over the traces, upset everything, and they have to be rescued from mere gangsterism by some Napoleonic genius who has a fancy for being an emperor, and who has the courage and brains and energy to jump at the chance. But the slaves who give three cheers for the emperor might just as well have made a cross on a British or American ballot paper as far as their freedom is concerned. So far I have mentioned nothing but plain natural and historical facts. I draw no conclusions, for that would lead me into controversy, and controversy would not be fair when you cannot answer me back. I am never controversial over the wireless. I do not even ask you to draw your own conclusions, for you might draw some very dangerous ones, unless you have the right sort of head for it. Always remember that though nobody likes to be called a slave, it does not follow that slavery is a bad thing. Great men, like Aristotle, have held that the law and order and government would be impossible unless the persons the people have to obey are beautifully dressed and decorated, robed and uniformed, speaking with a special accent, travelling in first-class carriages or the most expensive cars, or on the best-groomed and best-bred horses, and never cleaning their own boots, not doing anything for themselves that can possibly be done by ringing a bell and ordering some common person to do it. And this means, of course, that they must be made very rich without any obligation other than to produce an impression of almost godlike superiority on the minds of common people. In short, it is contended, you must make men ignorant idolaters before they will become obedient workers and law-abiding citizens. To prove this, we are reminded that, although nine out of ten voters are common workers, it is with the greatest difficulty that a few of them can be persuaded to vote for the members of their own class. When women were enfranchised and given the right to sit in Parliament, the first use they made of their votes was to defeat all the women candidates who stood for the freedom of the workers and had given them years of devoted and distinguished service. They elected only one woman—a titled lady of great wealth and exceptionally fascinating personality. Now this, it is said, is human nature, and you cannot change human nature. On the other hand, it is maintained that human nature is the easiest thing in the world to change if you catch it young enough, and that the idolatry of the slave class and the arrogance of the master class are themselves entirely artificial products of education and of a propaganda that plays upon our infants long before they have left their cradles. An opposite mentality could, it is argued, be produced by a contrary education and propaganda. You can turn the point over in your mind for yourself;"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b7d6cbe9d96','ch_67d157e1179d','text','{"text": "do not let me prejudice you one way or the other. The practical question at the bottom of it all is how the income of the whole country can best be distributed from day to day. If the earth is cultivated agriculturally in vast farms with motor ploughs and chemical fertilisers, and industrially in huge electrified factories full of machinery that a girl can handle, the product may be so great that an equal distribution of it would provide enough to give the unskilled labourers as much as the managers and the men of the scientific staff. But do not forget, when you hear tales of modern machinery enabling one girl to produce as much as a thousand men could produce in the reign of good Queen Anne, that this marvelous increase includes things like needles and steel pins and matches, which we can neither eat nor drink nor wear. Very young children will eat needles and matches eagerly—but the diet is not a nourishing one. And though we can now cultivate the sky as well as the earth, by drawing nitrogen from it to increase and improve the quality of our grass and, consequently, of our cattle and milk and butter and eggs, Nature may have tricks up her sleeve to check us if the chemists exploit her too greedily. And now to sum up. Wipe out from your dreams of freedom the hope of being able to do as you please all the time. For at least twelve hours of your day Nature orders you to do certain things, and will kill you if you don’t do them. This leaves twelve hours for working;"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7100e8fa492a','ch_67d157e1179d','text','{"text": "and here again Nature will kill you unless you either earn your living or get somebody else to earn it for you. If you live in a civilised country your freedom is restricted by the laws of the land enforced by the police, who oblige you to do this, and not to do that, and to pay rates and taxes. If you do not obey these laws the courts will imprison you, and, if you go too far, kill you. If the laws are reasonable and are impartially administered you have no reason to complain, because they increase your freedom by protecting you against assault, highway robbery, and disorder generally. But as society is constituted at present, there is another far more intimate compulsion on you: that of your landlord and that of your employer. Your landlord may refuse to let you live on his estate if you go to chapel instead of to church, or if you vote for anyone but his nominee, or if you practise osteopathy, or if you open a shop. Your employer may dictate the cut, colour, and condition of your clothes, as well as your hours of work. He can turn you into the street at any moment to join the melancholy band of lost spirits called the Unemployed. In short, his power over you is far greater than that of any political dictator could possibly be. Your only remedy at present is the Trade Union weapon of the strike, which is only the old Oriental device of starving on your enemy’s doorstep until he does you justice. Now, as the police in this country will not allow you to starve in your employer’s doorstep, you must starve on your own—if you have one. The extreme form of the strike—the general strike of all workers at the same moment—is also the extreme form of human folly, as, if completely carried out, it would extinguish the human race in a week. And the workers would be the first to perish. The general strike is Trade Unionism gone mad. Sane Trade Unionism would never sanction more than one big strike at a time, with all the other trades working overtime to support it. Now let us put the case in figures. If you have to work for twelve hours a day you have four hours a day to do what you like with, subject to the laws of the land, and your possession of money enough to buy an interesting book or pay for a seat at the pictures, or, on a half-holiday, at a football match, or whatever your fancy may be. But even here Nature will interfere a good deal, for, if your eight hours’ work has been of a hard physical kind, and when you get home you want to spend your four hours in reading my books to improve your mind, you will find yourself fast asleep in half a minute, and your mind will remain in its present benighted condition. I take it, then, that nine out of ten of us desire more freedom, and that this is why we listen to wireless talks about it. As long as we go on as we are—content with a vote and a dole—the only advice we can give one another is that of Shakespeare’s Iago:"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_23e76de0a259','ch_67d157e1179d','text','{"text": "‘Put money in thy purse.’"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_37f12c5024f4','ch_67d157e1179d','text','{"text": "But as we get very little money into our purses on pay-day, and all the rest of the week other people are taking money out of it, Iago’s advice is not very practical. We must change our politics before we can get what we want;"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9bfa3df5f60','ch_67d157e1179d','text','{"text": "and meanwhile we must stop gassing about freedom, because the people of England in the lump don’t know what freedom is, never having had any."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df6a6a74dcca','ch_67d157e1179d','text','{"text": "Always call freedom by its old English name of leisure, and keep clamouring for more leisure and more money to enjoy it in return for an honest share of work. And let us stop singing Rule, Britannia! until we make it true."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3c9266f117f7','ch_67d157e1179d','text','{"text": "Until we do, let us never vote for a parliamentary candidate who talks about our freedom and our love of liberty, for, whatever political name he may give himself, he is sure to be at bottom an Anarchist who wants to live on our labour without being taken up by the police for it as he deserves. And now suppose we at last win a lot more leisure and a lot more money than we are accustomed to."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8dab46cec7ea','ch_67d157e1179d','text','{"text": "What are we going to do with them? I was taught in my childhood that Satan will find mischief still for idle hands to do. I have seen men come into a fortune and lose their happiness, their health, and finally their lives by it as certainly as if they had taken daily doses of rat poison instead of champagne and cigars. It is not at all easy to know what to do with leisure unless we have been brought up to it. I will, therefore, leave you with a conundrum to think over."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a0fcac7f1945','ch_67d157e1179d','text','{"text": "If you had your choice, would you work for eight hours a day and retire with a full pension at forty-five, or would you rather work four hours a day and keep on working until you are seventy? Now don’t send the answer to me, please talk it over with your wife. The problem of discipline is really quite complex, because most of us think that through some form of discipline we shall eventually have freedom."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_631b6c608b29','ch_67d157e1179d','text','{"text": "Discipline is the cultivation of resistance, is it not? By resisting, by building a barrier within ourselves against something which we consider wrong, we think we shall be more capable of understanding and of being free to live fully;"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_15c4fb0a1963','ch_67d157e1179d','text','{"text": "but that is not a fact, is it? Surely, it is only when there is freedom, real freedom to think, to discover—that you can find out anything. But freedom obviously cannot exist in a frame."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6441967ca23d','ch_67d157e1179d','text','{"text": "And most of us live in a frame, in a world enclosed by ideas, do we not? For instance, you are told by your parents and your teachers what is right and what is wrong. You know what people say, what the priest says, what tradition says, and what you have learned in school. All this forms a kind of enclosure within which you live;"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_577492be6efc','ch_67d157e1179d','text','{"text": "and, living in that enclosure, you say you are free."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e91161639843','ch_67d157e1179d','text','{"text": "Are you? Can a man ever be free as long as he lives in a prison? So, one has to break down the prison walls of tradition. One has to experiment and discover on one’s own, and not merely follow somebody, however good, however noble and exciting that person may be, and however happy one may feel in his presence. What has significance is to be able to examine and not just accept all the values created by tradition, all the things that people have said are good, beneficial, worthwhile."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e9d2abc160a8','ch_67d157e1179d','text','{"text": "The moment you accept, you begin to conform, to imitate;"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9758a1d912d4','ch_67d157e1179d','text','{"text": "and conforming, imitating, following, can never make one free and happy. Our elders say that you must be disciplined. Discipline is imposed upon you by yourself, and by others from outside. But what is important is to be free to think, to inquire, so that you begin to find out for yourself."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_85f5e4b57c8d','ch_67d157e1179d','text','{"text": "To think deeply, to go into things and discover for oneself what is true, is very difficult;"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b475675069e','ch_67d157e1179d','text','{"text": "it requires alert perception, constant inquiry, and most people have neither the inclination nor the energy for that. They say, ‘You know better than I do;"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a0823da462c','ch_67d157e1179d','text','{"text": "you are my guru, my teacher, and I shall follow you.’"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca386c3cb5b0','ch_67d157e1179d','text','{"text": "So, it is very important that from the tenderest age you are free to find out, and are not enclosed by a wall of do’s and don’ts;"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_678ce869b05e','ch_67d157e1179d','text','{"text": "for if you are constantly told what to do and what not to do, what will happen to your intelligence? You will be a thoughtless entity who just walks into some career, who is told by his parents whom to marry or not to marry;"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_57b0e0a909ac','ch_67d157e1179d','text','{"text": "and that is obviously not the action of intelligence."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05cf8ab79366','ch_67d157e1179d','text','{"text": "You may pass your examinations and be very well off, you may have good clothes and plenty of jewels, you may have friends and prestige;"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b24a948a9792','ch_67d157e1179d','text','{"text": "but as long as you are bound by tradition, there can be no intelligence. Surely, intelligence comes into being only when you are free to question, free to think out and discover, so that your mind becomes very active, very alert and clear."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a0ce4f45a9eb','ch_67d157e1179d','text','{"text": "Then you are a fully integrated individual—not a frightened entity who, not knowing what to do, inwardly feels one thing and outwardly conforms to something different. Intelligence demands that you break away from tradition and live on your own;"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_64b67423ca45','ch_67d157e1179d','text','{"text": "but you are enclosed by your parents’ ideas and by the traditions of society. So there is a conflict going on inwardly, is there not? You are all young, but I don’t think you are too young to be aware of this."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b187492c10f','ch_67d157e1179d','text','{"text": "So there is an inward struggle going on; and as long as you do not resolve that struggle you are going to be caught in conflict, in pain, in sorrow, everlastingly wanting to do something and being prevented from doing it. If you go into it very carefully you will see that discipline and freedom are contradictory, and that in seeking real freedom there is set going quite a different process which brings its own clarification so that you just do not do certain things."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e33c08f357d4','ch_67d157e1179d','text','{"text": "While you are young it is very important that you be free to find out, and be helped to find out, what you really want to do in life. If you don’t find out while you are young, you will never find out, you will never be free and happy individuals. The seed must be sown now, so that you begin now to take the initiative."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_64f19d61b08f','ch_67d157e1179d','text','{"text": "On the road you have often passed villagers carrying heavy loads, have you not? Those poor women with torn and dirty clothes, with insufficient food, working day after day for a pittance—do you have any feeling for them? Or are you so frightened, so concerned about yourself, about your examinations, about your looks, about your saris, that you never pay any attention to them? Do you feel you are much better than they, that you belong to a higher class and therefore need have no regard for them? Don’t you want to help them? No? That indicates how you are thinking. Are you so dulled by centuries of tradition, by what your fathers and mothers say, so conscious of belonging to a certain class, that you do not even look at the villagers? Are you actually so blinded that you do not know what is happening around you? It is fear—fear of what your parents will say, of what the teachers will say, fear of tradition, fear of life—that gradually destroys sensitivity, is it not? To be sensitive is to feel, to receive impressions, to have sympathy for those who are suffering, to have affection, to be aware of the things that are happening around you. When the temple bell is ringing, are you aware of it? Do you listen to the sound? Do you ever see the sunlight on the water? Are you aware of the poor people, the villagers who have been controlled, trodden down for centuries by exploiters? When you see a servant carrying a heavy carpet, do you give him a helping hand? All this implies sensitivity. But, you see, sensitivity is destroyed when one is disciplined, when one is fearful or concerned with oneself. To be concerned about one’s looks, about one’s saris, to think about oneself all the time— which most of us do in some form or other—is to be insensitive, for then the mind and heart are enclosed and one loses all appreciation of beauty. To be really free implies great sensitivity. There is no freedom if you are enclosed by self-interest or by various walls of discipline. As long as your life is a process of imitation there can be no sensitivity, no freedom. It is very important, while you are here, to sow the seed of freedom, which is to awaken intelligence; for with that intelligence you can tackle all the problems of life."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1eea51a653f','ch_67d157e1179d','list','{"ordered": false, "items": ["George Bernard Shaw"]}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4bcd392cc1d9','ch_67d157e1179d','text','{"text": "About the Author"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b1ae2069e1e','ch_67d157e1179d','text','{"text": "George Bernard Shaw was a dramatist and critic. His work as a London newspaper critic of music and drama resulted in The Quintessence of Ibsenism. His famous plays include Arms and the Man, Candida and Man and Superman. His works present a fearless intellectual criticism, sugar-coated by a pretended lightness of tone. He rebelled against muddled thinking, and sought to puncture hollow pretensions."}',59);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_6c3197d7bcd7','bk_ncert_english','12-15-the-mark-on-the-wall','12.15 The Mark on the Wall',NULL,'public',86,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd6f926bd3cc','ch_6c3197d7bcd7','text','{"text": "Perhaps it was the middle of January in the present year that I first looked up and saw the mark on the wall. In order to fix a date it is necessary to remember what one saw. So now I think of the fire;"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a86de7d58dee','ch_6c3197d7bcd7','text','{"text": "the steady film of yellow light upon the page of my book;"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ebafa674eea7','ch_6c3197d7bcd7','text','{"text": "the three chrysanthemums in the round glass bowl on the mantelpiece. Yes, it must have been the winter time, and we had just finished our tea, for I remember that I was smoking a cigarette when I looked up and saw the mark on the wall for the first time. I looked up through the smoke of my cigarette and my eye lodged for a moment upon the burning coals, and that old fancy of the crimson flag flapping from the castle tower came into my mind, and I thought of the cavalcade of red knights riding up the side of the black rock. Rather to my relief the sight of the mark interrupted the fancy, for it is an old fancy, an automatic fancy, made as a child perhaps. The mark was a small round mark, black upon the white wall, about six or seven inches above the mantelpiece. How readily our thoughts swarm upon a new object, lifting it a little way, as ants carry a blade of straw so feverishly, and then leave it... If that mark was made by a nail, it can’t have been for a picture;"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fcd0ce804bca','ch_6c3197d7bcd7','text','{"text": "it must have been for a miniature—the miniature of a lady with white powdered curls, powder-dusted cheeks, and lips like red carnations. A fraud of course, for the people who had this house before us would have chosen pictures in that way—an old picture for an old room. That is the sort of people they were—very interesting people, and I think of them so often, in such queer places, because one will never see them again, never know what happened next. They wanted to leave this house because they wanted to change their style of furniture, so he said, and he was in process of saying that in his opinion art should have ideas behind it when we were torn asunder, as one is torn from the old lady about to pour out tea and the young man about to hit the tennis ball in the back garden of the suburban villa as one rushes past in the train. But for that mark, I’m not sure about it;"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abf0ed6caeb9','ch_6c3197d7bcd7','text','{"text": "I don’t believe it was made by a nail after all;"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17765d5fa78e','ch_6c3197d7bcd7','text','{"text": "it’s too big, too round, for that. I might get up, but if I got up and looked at it, ten to one I shouldn’t be able to say for certain;"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3aa50728250b','ch_6c3197d7bcd7','text','{"text": "because once a thing’s done, no one ever knows how it happened. Oh! dear me, the mystery of life;"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec11f11f4fca','ch_6c3197d7bcd7','text','{"text": "the inaccuracy of thought! The ignorance of humanity! To show how very little control of our possessions we have—what an accidental affair this living is after all our civilization—let me just count over a few of the things lost in one lifetime, beginning, for that seems always the most mysterious of losses—what cat would gnaw, what rat would nibble—three pale blue canisters of book-binding tools? Then there were the bird cages, the iron hoops, the steel skates, the Queen Anne coal-scuttle, the bagatelle board, the hand organ—all gone, and jewels, too. Opals and emeralds, they lie about the roots of turnips. What a scraping paring affair it is to be sure! The wonder is that I’ve any clothes on my back, that I sit surrounded by solid furniture at this moment. Why, if one wants to compare life to anything, one must liken it to being blown through the Tube at fifty miles an hour— landing at the other end without a single hairpin in one’s hair! Shot out at the feet of God entirely naked! Tumbling head over heels in the asphodel meadows like brown paper parcels pitched down a shoot in the post office! With one’s hair flying back like the tail of a race-horse. Yes, that seems to express the rapidity of life, the perpetual waste and repair;"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0aa2a3fce7cc','ch_6c3197d7bcd7','text','{"text": "all so casual, all so haphazard... But after life. The slow pulling down of thick green stalks so that the cup of the flower, as it turns over, deluges one with purple and red light. Why, after all, should one not be born there as one is born here, helpless, speechless, unable to focus one’s eyesight, groping at the roots of the grass, at the toes of the Giants? As for saying which are trees and which are men and women, or whether there are such things, that one won’t be in a condition to do for fifty years or so. There will be nothing but spaces of light and dark, intersected by thick stalks, and rather higher up perhaps, rose-shaped blots of an indistinct colour—dim pinks and blues—which will, as time goes on, become more definite, become—I don’t know what... And yet that mark on the wall is not a hole at all. It may even be caused by some round black substance, such as a small rose leaf, left over from the summer, and I, not being a very vigilant housekeeper—look at the dust on the mantelpiece, for example, the dust which, so they say, buried Troy three times over, only fragments of pots utterly refusing annihilation, as one can believe. The tree outside the window taps very gently on the pane... I want to think quietly, calmly, spaciously, never to be interrupted, never to have to rise from my chair, to slip easily from one thing to another, without any sense of hostility, or obstacle. I want to sink deeper and deeper, away from the surface, with its hard separate facts. To steady myself, let me catch hold of the first idea that passes... Shakespeare... Well, he will do as well as another. A man who sat himself solidly in an armchair, and looked into the fire, so—a shower of ideas fell perpetually from some very high Heaven down through his mind. He leant his forehead on his hand, and people, looking in through the open door—for this scene is supposed to take place on a summer’s evening—but how dull this is, this historical fiction! It doesn’t interest me at all. I wish I could hit upon a pleasant track of thought, a track indirectly reflecting credit upon myself, for those are the pleasantest thoughts, and very frequent even in the minds of modest mousecoloured people, who believe genuinely that they dislike to hear their own praises. They are not thoughts directly praising oneself;"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25f4221906c4','ch_6c3197d7bcd7','text','{"text": "that is the beauty of them;"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3f67415fbc3','ch_6c3197d7bcd7','text','{"text": "they are thoughts like this:"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43ba434f4fe7','ch_6c3197d7bcd7','text','{"text": "‘And then I came into the room. They were discussing botany. I said how I’d seen a flower growing on a dust heap on the site of an old house in Kingsway. The seed, I said, must have been sown in the reign of Charles the First. What flowers grew in the reign of Charles the First? I asked—(but I don’t remember the answer). Tall flowers with purple tassels to them perhaps. And so it goes on."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c95daf84031','ch_6c3197d7bcd7','text','{"text": "All the time I’m dressing up the figure of myself in my own mind, lovingly, stealthily, not openly adoring it, for if I did that, I should catch myself out, and stretch my hand at once for a book in self-protection. Indeed, it is curious how instinctively one protects the image of oneself from idolatry or any other handling that could make it ridiculous, or too unlike the original to be believed in any longer. Or is it not so very curious after all? It is a matter of great importance."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b5f44b8a74bf','ch_6c3197d7bcd7','text','{"text": "Suppose the looking glass smashes, the image disappears, and the romantic figure with the green of forest depths all about it is there no longer, but only that shell of a person which is seen by other people—what an airless, shallow, bald, prominent world it becomes! A world not to be lived in. As we face each other in omnibuses and underground railways we are looking into the mirror;"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e08c8dd693c','ch_6c3197d7bcd7','text','{"text": "that accounts for the vagueness, the gleam of glassiness, in our eyes."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c73533fd06ce','ch_6c3197d7bcd7','text','{"text": "And the novelists in future will realise more and more the importance of these reflections, for of course there is not one reflection but an almost infinite number;"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_28db952d1e4c','ch_6c3197d7bcd7','text','{"text": "those are the depths they will explore, those the phantoms they will pursue, leaving the description of reality more and more out of their stories, taking a knowledge of it for granted, as the Greeks did and Shakespeare perhaps—but these generalisations are very worthless. The military sound of the word is enough."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d914a4420c9','ch_6c3197d7bcd7','text','{"text": "It recalls leading articles, cabinet ministers—a whole class of things indeed which, as a child, one thought the thing itself, the standard thing, from which one could not depart save at the risk of nameless damnation. Generalisations bring back somehow Sunday in London, Sunday afternoon walks, Sunday luncheons, and also ways of speaking of the dead, clothes, and habits— like the habit of sitting all together in one room until a certain hour, although nobody liked it."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fdbb4af6f31d','ch_6c3197d7bcd7','text','{"text": "There was a rule for everything. The rule for tablecloths at that particular period was that they should be made of tapestry with little yellow compartments marked upon them, such as you may see in photographs of the carpets in the corridors of the royal palaces. Tablecloths of a different kind were not real tablecloths."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8ed1dc13bd1c','ch_6c3197d7bcd7','text','{"text": "How shocking, and yet how wonderful it was to discover that these real things, Sunday luncheons, Sunday walks, country houses, and tablecloths were not entirely real, were indeed half phantoms, and the damnation which visited the disbeliever in them was only a sense of illegitimate freedom."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_acf937756493','ch_6c3197d7bcd7','text','{"text": "What now takes the place of those things I wonder, those real standard things? Men perhaps, should you be a woman;"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9205173a0e2','ch_6c3197d7bcd7','text','{"text": "the masculine point of view which governs our lives which sets the standard, which established Whitaker’s Table of Precedency, which has become, I suppose, since the war, half a phantom to many men and women, which soon, one may hope, will be laughed into the dustbin where the phantoms go, the mahogany sideboards and the Landseer prints, Gods and Devils, Hell and so forth, leaving us all with an intoxicating sense of illegitimate freedom—if freedom exists... In certain lights that mark on the wall seems actually to project from the wall. Nor is it entirely circular. I cannot be sure, but it seems to cast a perceptible shadow, suggesting that if I ran my finger down that strip of the wall it would, at a certain point, mount and descend a small tumulus, a smooth tumulus like those barrows on the South Downs which are, they say, either tombs or camps. Of the two I should prefer them to be tombs, desiring melancholy like most English people, and finding it natural at the end of a walk to think of the bones stretched beneath the turf... There must be some book about it. Some antiquary must have dug up those bones and given them a name... What sort of a man is an antiquary, I wonder? Retired Colonels for the most part, I dare say, leading parties of aged labourers to the top here, examining clods of earth and stone, and getting into correspondence with the neighbouring clergy, which, being opened at breakfast time, gives them a feeling of importance, and the comparison of arrow-heads necessitates cross-country journeys to the county towns, an agreeable necessity both to them and to their elderly wives, who wish to make plum jam or to clean out the study, and have every reason for keeping that great question of the camp or the tomb in perpetual suspension, while the Colonel himself feels agreeably philosophic in accumulating evidence on both sides of the question. It is true that he does finally incline to believe in the camp;"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5305b07a56c4','ch_6c3197d7bcd7','text','{"text": "and, being opposed, indites a pamphlet which he is about to read at the quarterly meeting of the local society when a stroke lays him low, and his last conscious thoughts are not of wife or child, but of the camp and that arrow-head there, which is now in the case at the local museum, together with the foot of a Chinese murderess, a handful of Elizabethan nails, a great many Tudor clay pipes, a picture of Roman pottery, and the wineglass that Nelson drank out of—proving I really don’t know what. No, no, nothing is proved, nothing is known. And if I were to get up at this very moment and ascertain that the mark on the wall is really—what shall we say? the head of a gigantic old nail, driven in two hundred years ago, which has now, owing to the patient attrition of many generations of housemaids, revealed its head above the coat of paint, and is taking its first view of modern life in the sight of a white walled fire-lit room, what should I gain?—Knowledge? Matter for further speculation? I can think sitting still as well as standing up. And what is knowledge? What are our learned men save the descendants of witches and hermits who crouched in caves and in woods brewing herbs, interrogating shrew-mice and writing down the language of the stars? And the less we honour them as our superstitions dwindle and our respect for beauty and health of mind increases... Yes, one could imagine a very pleasant world. A quiet, spacious world, with the flowers so red and blue in the open fields. A world without professors or specialists or house-keepers with the profiles of policemen, a world which one could slice with one’s thought as a fish slices the water with his fin, grazing the stems of the waterlilies, hanging suspended over nests of white sea eggs... How peaceful it is down here, rooted in the centre of the world and gazing up through the grey waters, with their sudden gleams of light, and their reflections—if it were not for Whitaker’s Almanack*—if it were not for the Table of Precedency! I must jump up and see for myself what that mark on the wall really is—a nail, a rose-leaf, a crack in the wood? Here is Nature once more at her old game of self preservation. This train of thought, she perceives, is threatening mere waste of energy, even some collision with reality, for who will ever be able to lift a finger against Whitaker’s Table of Precedency? The Archbishop of Canterbury is followed by the Lord High Chancellor;"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e423118b9cf','ch_6c3197d7bcd7','text','{"text": "the Lord High Chancellor is followed by the Archbishop of York. Everybody follows somebody, such is the philosophy of Whitaker;"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5a3a64b7cd5','ch_6c3197d7bcd7','text','{"text": "and the great thing is to know who follows whom. Whitaker knows, and let that, so Nature counsels, comfort you, instead of enraging you;"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a1a74ce3a60','ch_6c3197d7bcd7','text','{"text": "and if you can’t be comforted, if you must shatter this hour of peace, think of the mark on the wall. I understand Nature’s game—her prompting to take action as a way of ending any thought that threatens to excite or to pain. Hence, I suppose, comes our slight contempt for men of action—men, we assume, who don’t think. Still there’s no harm in putting a full stop to one’s disagreeable thoughts by looking at a mark on the wall. Indeed, now that I have fixed my eyes upon it, I feel that I have grasped a plank in the sea;"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c9d74ba47fd','ch_6c3197d7bcd7','text','{"text": "I feel a satisfying sense of reality which at once turns the two Archbishops and the Lord High Chancellor to the shadows of shades. Here is something definite, something real. Thus, waking from a midnight dream of horror, one hastily turns on the light and lies quiescent, worshipping the chest of drawers, worshipping solidity, worshipping reality, worshipping the impersonal world which is a proof of some existence other than ours. That is what one wants to be sure of... Wood is a pleasant thing to think about. It comes from a tree;"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2d048fb57bfc','ch_6c3197d7bcd7','text','{"text": "and trees grow, and we don’t know how they grow. For years and years they grow, without paying any attention to us, in meadows, in forests, and by the side of rivers—all things one likes to think about. The cows swish their tails beneath them on hot afternoons;"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5a5812db3681','ch_6c3197d7bcd7','text','{"text": "they paint rivers so green that when a moorhen dives one expects to see its feathers all green when it comes up again. I like to think of the fish balanced against the stream like flags blown out;"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_36ad9be32ba7','ch_6c3197d7bcd7','text','{"text": "and of water beetles slowly raising domes of mud upon the bed of the river. I like to think of the tree itself: first the close dry sensation of being wood;"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_52575dad9877','ch_6c3197d7bcd7','text','{"text": "then the grinding of the storm;"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb0609625892','ch_6c3197d7bcd7','text','{"text": "then the slow, delicious ooze of sap. I like to think of it, too, on winter’s nights standing in the empty field with all leaves close-furled, nothing tender exposed to the iron bullets of the moon, a naked mast upon an earth that goes tumbling, tumbling all night long. The song of birds must sound very loud and strange in June;"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_452b9fc8c889','ch_6c3197d7bcd7','text','{"text": "and how cold the feet of insects must feel upon it, as they make laborious progresses up the creases of the bark, or sun themselves upon the thin green awning of the leaves, and look straight in front of them with diamond-cut red eyes... One by one the fibres snap beneath the immense cold pressure of the earth, then the last storm comes and, falling, the highest branches drive deep into the ground again. Even so, life isn’t done with;"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd621f130981','ch_6c3197d7bcd7','text','{"text": "there are a million patient, watchful lives still for a tree, all over the world, in bedrooms, in ships, on the pavement, living rooms, where men and women sit after tea, smoking cigarettes. It is full of peaceful thoughts, happy thoughts, this tree. I should like to take each one separately—but something is getting in the way... Where was I? What has it all been about? A tree? A river? The Downs? Whitaker’s Almanack? The fields of asphodel? I can’t remember a thing. Everything’s moving, falling, slipping, vanishing... There is a vast upheaval of matter. Someone is standing over me and saying:"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bcb473a90aff','ch_6c3197d7bcd7','text','{"text": "‘I’m going out to buy a newspaper.’"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a39bf562918a','ch_6c3197d7bcd7','text','{"text": "‘Yes?’"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c19df84a7210','ch_6c3197d7bcd7','text','{"text": "‘Though it’s no good buying newspapers..."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4771f0154e03','ch_6c3197d7bcd7','text','{"text": "Nothing ever happens. Curse this war;"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b5424b5f9004','ch_6c3197d7bcd7','text','{"text": "God damn this war!... All the same, I don’t see why we should have a snail on our wall.’"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_34c62de161cc','ch_6c3197d7bcd7','text','{"text": "Ah, the mark on the wall! It was a snail..."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09ec4e4aaf8d','ch_6c3197d7bcd7','list','{"ordered": false, "items": ["Virginia Woolf"]}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7761033018d2','ch_6c3197d7bcd7','text','{"text": "About the Author"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_399d912a65a0','ch_6c3197d7bcd7','text','{"text": "Virginia Woolf was a novelist and essayist. She grew up in a literary atmosphere and was educated in her father’s extensive library. The famous group of intellectuals which came to be known as the Bloomsbury Group originated in gatherings of Cambridge University graduates and their friends in Virginia’s home. Along with her husband, Virginia started the Hogarth Press which became a successful publishing house."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9fd3262c038a','ch_6c3197d7bcd7','text','{"text": "In her novels, Mrs Dalloway and To the Lighthouse, she experimented with new techniques, particularly new ways of capturing the flow of time. She believed that much imaginative literature is false to life because it relates episodes in a straight line, whereas our experiences actually flow together like a stream. This essay records fleeting impressions and delicate shades of mental experience."}',44);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_b8e745ff5d32','bk_ncert_english','12-16-film-making','12.16 Film-making',NULL,'public',87,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca24b1abb883','ch_b8e745ff5d32','text','{"text": "During the shooting of The Virgin Spring, we were up in the northern province of Dalarna in May and it was early in the morning, about half past seven. The landscape there is rugged, and our company was working by a little lake in the forest. It was very cold, about 30 degrees, and from time to time a few snowflakes fell through the grey, rain dimmed sky."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9077baf4093b','ch_b8e745ff5d32','text','{"text": "The company was dressed in a strange variety of clothing—raincoats, oil slickers, Icelandic sweater jackets, old blankets, coachmen’s coats, medieval robes. Our men had laid some ninety feet of rusty, buckling rail over the difficult terrain, to dolly the camera on. We were all helping with the equipment—actors, electricians, makeup men, script girl, sound crew—mainly to keep warm. Suddenly someone shouted and pointed toward the sky."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e651dd5fb3d7','ch_b8e745ff5d32','text','{"text": "Then we saw a crane floating high above the fir trees, and then another, and then several cranes floating majestically in a circle above us. We all dropped what we were doing and ran to the top of a nearby hill to see the cranes better. We stood there for a long time, until they turned westward and disappeared over the forest. And suddenly I thought: this is what it means to make a movie in Sweden."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3cfc78d93d4f','ch_b8e745ff5d32','text','{"text": "This is what can happen, this is how we work together with our old equipment and little money, and this is how we can suddenly drop everything for the love of four cranes floating above the tree tops."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e49090e7df91','ch_b8e745ff5d32','text','{"text": "Childhood Foretells Future"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb04c88e7637','ch_b8e745ff5d32','text','{"text": "My association with film goes back to the world of childhood. My grandmother had a very large old apartment in Uppsala. I used to sit under the dining-room table there, ‘listening’ to the sunshine which came in through the gigantic windows."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b14f33c1e55e','ch_b8e745ff5d32','text','{"text": "The cathedral bells went ding-dong, and the sunlight moved about and ‘sounded’ in a special way. One day, when winter was giving way to spring and I was five years old, a piano was being played in the next apartment. It played waltzes, nothing but waltzes. On the wall hung a large picture of Venice. As the sunlight moved across the picture the water in the canal began to flow, the pigeons flew up from the square, people talked and gesticulated. Bells sounded, not those of Uppsala Cathedral but from the picture itself."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_14a752a67af1','ch_b8e745ff5d32','text','{"text": "And the piano music also came from that remarkable picture of Venice. A child who is born and brought up in a vicarage acquires an early familiarity with life and death behind the scenes. Father performed funerals, marriages, baptisms, gave advice and prepared sermons. The devil was an early acquaintance, and in the child’s mind there was a need to personify him. This is where my magic lantern came in."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_059a0b5ecf4e','ch_b8e745ff5d32','text','{"text": "It consisted of a small metal box with a carbide lamp—I can still remember the smell of the hot metal—and coloured glass slides: Red Riding Hood and the Wolf, and all the others. And the wolf was the Devil, without horns but with a tail and a gaping red mouth, strangely real yet incomprehensible, a picture of wickedness and temptation on the flowered wall of the nursery. When I was ten years old I received my first, rattling film projector, with its chimney and lamp."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_78f11f72d48a','ch_b8e745ff5d32','text','{"text": "I found it both mystifying and fascinating. The first film I had was nine feet long and brown in colour. It showed a girl lying asleep in a meadow, who woke up and stretched out her arms, then disappeared to the right. That was all there was to it. The film was a great success and was projected every night until it broke and could not be mended any more. This little rickety machine was my first conjuring set."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_60da113446b7','ch_b8e745ff5d32','text','{"text": "And even today I remind myself with childish excitement that I am really a conjurer, since cinematography is based on deception of the human eye. I have worked it out that if I see a film which has a running time of one hour, I sit through twenty-seven minutes of complete darkness—the blankness between frames. When I show a film I am guilty of deceit."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e14c9078dee','ch_b8e745ff5d32','text','{"text": "I use an apparatus which is constructed to take advantage of a certain human weakness, an apparatus with which I can sway my audience in a highly emotional manner—make them laugh, scream with fright, smile, believe in fairy stories, become indignant, feel shocked, charmed, deeply moved or perhaps yawn with boredom. Thus I am either an impostor or, when the audience is willing to be taken in, a conjurer."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa311642550c','ch_b8e745ff5d32','text','{"text": "I perform conjuring tricks with apparatus so expensive and so wonderful that any entertainer in history would have given anything to have it."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_34e54685cc5d','ch_b8e745ff5d32','text','{"text": "Split Second Impressions"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_747707489722','ch_b8e745ff5d32','text','{"text": "A film for me begins with something very vague—a chance remark or a bit of conversation, a hazy but agreeable event unrelated to any particular situation. It can be a few bars of music, a shaft of light across the street. Sometimes in my work at the theatre I have envisioned actors made up for yet unplayed roles."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d32692e24027','ch_b8e745ff5d32','text','{"text": "These are split second impressions that disappear as quickly as they come, yet leave behind a mood—like pleasant dreams. It is a mental state, not an actual story, but one abounding in fertile associations and images. Most of all, it is a brightly coloured thread sticking out of the dark sack of the unconscious. If I begin to wind up this thread, and do it carefully, a complete film will emerge."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_406b406d87ff','ch_b8e745ff5d32','text','{"text": "This primitive nucleus strives to achieve definite form, moving in a way that may be lazy and half asleep at first. Its stirring is accompanied by vibrations and rhythms which are very special and unique to each film. The picture sequences then assume a pattern in accordance with these rhythms, obeying laws born out of and conditioned by my original stimulus. If that embryonic substance seems to have enough strength to be made into a film, I decide to materialise it."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8f5a9f9766f','ch_b8e745ff5d32','text','{"text": "Then comes something very complicated and difficult: the transformation of rhythms, moods, atmosphere, tensions, sequences, tones and scents into words and sentences, into an understandable screenplay. This is an almost impossible task. The only thing that can be satisfactorily transferred from that original complex of rhythms and moods is the dialogue, and even dialogue is a sensitive substance which may offer resistance."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44a4130428e5','ch_b8e745ff5d32','text','{"text": "Written dialogue is like a musical score, almost incomprehensible to the average person. Its interpretation demands a technical knack plus a certain kind of imagination and feeling— qualities which are so often lacking, even among actors. One can write dialogue, but how it should be delivered, its rhythm and tempo, what is to take place between lines—all this must be omitted for practical reasons. Such a detailed script would be unreadable."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_38fc2d25280f','ch_b8e745ff5d32','text','{"text": "I try to squeeze instructions as to location, characterisation and atmosphere into my screenplays in understandable terms, but the success of this depends on my writing ability and the perceptiveness of the reader, which are not always predictable."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_397189e1f7c3','ch_b8e745ff5d32','text','{"text": "The Rhythm of a Film"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96018b80ebeb','ch_b8e745ff5d32','text','{"text": "Now we come to essentials, by which I mean montage, rhythm and the relation of one picture to another—the vital third dimension without which the film is merely a dead product from a factory."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00cfb8975eef','ch_b8e745ff5d32','text','{"text": "Here I cannot clearly give a key, as in a musical score, nor a specific idea of the tempo which determines the relationship of the elements involved. It is quite impossible for me to indicate the way in which the film"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5d9c6324958','ch_b8e745ff5d32','text','{"text": "‘breathes’ and pulsates. I have often wished for a kind of notation which would enable me to put on paper all the shades and tones of my vision, to record distinctly the inner structure of a film."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7ede64a91f4','ch_b8e745ff5d32','text','{"text": "For when I stand in the artistically devastating atmosphere of the studio, my hands and head full of all the trivial and irritating details that go with motion-picture production, it often takes a tremendous effort to remember how I originally saw and thought out this or that sequence, or what was the relation between the scene of four weeks ago and that of today."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5f4142e3f988','ch_b8e745ff5d32','text','{"text": "If I could express myself clearly, in explicit symbols, then this problem would be almost eliminated and I could work with absolute confidence that whenever I liked I could prove the relationship between the part and the whole and put my finger on the rhythm, the continuity of the film. Thus the script is a very imperfect technical basis for a film. And there is another important point in this connection which I should like to mention."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_319a5f7ce376','ch_b8e745ff5d32','text','{"text": "Film has nothing to do with literature;"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76d16b6a64f5','ch_b8e745ff5d32','text','{"text": "the character and substance of the two art forms are usually in conflict. This probably has something to do with the receptive process of the mind. The written word is read and assimilated by a conscious act of the will in alliance with the intellect;"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7be9e629a192','ch_b8e745ff5d32','text','{"text": "little by little it affects the imagination and the emotions. The process is different with a motion picture. When we experience a film, we consciously prime ourselves for illusion."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2a2c8f4bef22','ch_b8e745ff5d32','text','{"text": "Putting aside will and intellect, we make way for it in our imagination. The sequence of pictures plays directly on our feelings. Music works in the same fashion;"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5d4040d6e23','ch_b8e745ff5d32','text','{"text": "I would say that there is no art form that has so much in common with film as music. Both affect our emotions directly, not via the intellect. And film is mainly rhythm;"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d17161dc7d17','ch_b8e745ff5d32','text','{"text": "it is inhalation and exhalation in continuous sequence."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_26fce57be446','ch_b8e745ff5d32','text','{"text": "Ever since childhood, music has been my great source of recreation and stimulation, and I often experience a film or play musically."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_10f48ea3254d','ch_b8e745ff5d32','text','{"text": "Film and Written Literature"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_89a28a10c9e6','ch_b8e745ff5d32','text','{"text": "It is mainly because of this difference between film and literature that we should avoid making films out of books. The irrational dimension of a literary work, the germ of its existence, is often untranslatable into visual terms— and it, in turn, destroys the special, irrational dimension of the film."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d84a41ed72e','ch_b8e745ff5d32','text','{"text": "If, despite this, we wish to translate something literary into film terms, we must make an infinite number of complicated adjustments which often bear little or no fruit in proportion to the effort expended. I myself have never had any ambition to be an author. I do not want to write novels, short stories, essays, biographies, or even plays for the theatre."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_272578d1ddea','ch_b8e745ff5d32','text','{"text": "I only want to make films—films about conditions, tensions, pictures, rhythms and characters which are in one way or another important to me. The motion picture, with its complicated process of birth, is my method of saying what I want to my fellow men. I am a film-maker, not an author. Thus the writing of the script is a difficult period but a useful one, for it compels me to prove logically the validity of my ideas."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7109a9347988','ch_b8e745ff5d32','text','{"text": "In doing this, I am caught in a conflict—a conflict between my need to transmit a complicated situation through visual images, and my desire for absolute clarity. I do not intend my work to be solely for the benefit of myself or the few, but for the entertainment of the general public. The wishes of the public are imperative. But sometimes I risk following my own impulse, and it has been shown that the public can respond with surprising sensitivity to the most unconventional line of development."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db0b12da061a','ch_b8e745ff5d32','text','{"text": "When shooting begins, the most important thing is that those who work with me feel a definite contact, that all of us somehow cancel out our conflicts through working together. We must pull in one direction for the sake of the work at hand. Sometimes this leads to dispute. But the more definite and clear the"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_241830f951c2','ch_b8e745ff5d32','text','{"text": "‘marching orders’, the easier it is to reach the goal which has been set."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c11e07a29a7a','ch_b8e745ff5d32','text','{"text": "This is the basis for my conduct as director, and perhaps the explanation of much of the nonsense that has been written about me. While I cannot let myself be concerned with what people think and say about me personally, I believe that reviewers and critics have every right to interpret my films as they like. I refuse to interpret my work to others, and I cannot tell the critic what to think;"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_642c024beda5','ch_b8e745ff5d32','text','{"text": "each person has the right to understand a film as he sees it. Either he is attracted or repelled."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_afd75f7456ee','ch_b8e745ff5d32','text','{"text": "A film is made to create reaction. If the audience does not react one way or another, it is an indifferent work and worthless. I do not mean by this that I believe in being"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7743d24dce25','ch_b8e745ff5d32','text','{"text": "‘different’ at any price. A lot has been said about the value of originality, and I find this foolish. Either you are original or you are not. It is completely natural for artists to take from and give to each other, to borrow from and experience one another. In my own life, my great literary experience was Strindberg. There are works of his which can still make my hair stand on end—The People of Hemso, for example. And it is my dream to produce Dream Play some day."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f6521d3be4d','ch_b8e745ff5d32','text','{"text": "Olof Molander’s production of it in 1934 was for me a fundamental dramatic experience."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8616fad7425f','ch_b8e745ff5d32','text','{"text": "Significant Persons"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fff7b79a983a','ch_b8e745ff5d32','text','{"text": "On a personal level, there are many people who have meant a great deal to me. My father and mother were certainly of vital importance, not only in themselves but because they created a world for me to revolt against. In my family there was an atmosphere of hearty wholesomeness which I, a sensitive young plant, scorned and rebelled against."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_30cf8529f15f','ch_b8e745ff5d32','text','{"text": "But that strict middle-class home gave me a wall to pound on, something to sharpen myself against. At the same time they taught me a number of values—efficiency, punctuality, a sense of financial responsibility—which may be"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_42d21068bf7b','ch_b8e745ff5d32','text','{"text": "‘bourgeois’ but are nevertheless important to the artist. They are part of the process of setting oneself severe standards. Today as a film maker I am conscientious, hard-working and extremely careful;"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e47e504e1dab','ch_b8e745ff5d32','text','{"text": "my films involve good craftsmanship, and my pride is the pride of a good craftsman. Among the people who have meant something in my professional development is Torsten Hammaren of Gothenburg. I went there from Hälsingborg, where I had been head of the municipal theatre for two years."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e6eec83fa27f','ch_b8e745ff5d32','text','{"text": "I had no conception of what theatre was;"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_93c0c2512ee5','ch_b8e745ff5d32','text','{"text": "Hammaren taught me during the four years I stayed in Gothenburg. Then, when I made my first attempts at film, Alf Sjöberg—who directed Torment—taught me a great deal. And there was Lorens Marmstedt, who really taught me filmmaking from scratch after my first unsuccessful movie."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ceb516cf8ec8','ch_b8e745ff5d32','text','{"text": "Among other things I learned from Marmstedt is the one unbreakable rule: you must look at your own work very coldly and clearly;"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eff9a45b1836','ch_b8e745ff5d32','text','{"text": "you must be a devil to yourself in the screening room when watching the day’s rushes. Then there is Herbert Grevenius, one of the few who believed in me as a writer. I had trouble with script-writing, and was reaching out more and more to the drama, to dialogue, as a means of expression. He gave me great encouragement."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d661fe54de28','ch_b8e745ff5d32','text','{"text": "Finally, there is Carl Anders Dymling, my producer. He is crazy enough to place more faith in the sense of responsibility of a creative artist than in calculations of profit and loss. I am thus able to work with an integrity that has become the very air I breathe, and one of the main reasons I do not want to work outside of Sweden. The moment I lose this freedom I will cease to be a film-maker, because I have no skill in the art of compromise."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a0963c4eb6b2','ch_b8e745ff5d32','text','{"text": "My only significance in the world of film lies in the freedom of my creativity."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e89b9d81be35','ch_b8e745ff5d32','text','{"text": "The Tightrope of Film-making"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d115a02a555c','ch_b8e745ff5d32','text','{"text": "Today, the ambitious film-maker is obliged to walk a tightrope without a net. He may be a conjurer, but no one conjures the producer, the bank director or the theatre owners when the public refuses to go see a film and lay down the money by which producer, bank director, theatre owner and conjurer can live."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2eb463124bcb','ch_b8e745ff5d32','text','{"text": "The conjurer may then be deprived of his magic wand;"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c026061823e','ch_b8e745ff5d32','text','{"text": "I would like to be able to measure the amount of talent, initiative and creative ability which has been destroyed by the film industry in its ruthlessly efficient sausage machine. What was play to me once has now become a struggle. Failure, criticism, public indifference all hurt more today than yesterday. The brutality of the industry is undisguised—yet that can be an advantage. So much for people and the film business."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1379dad3fdb0','ch_b8e745ff5d32','text','{"text": "I have been asked, as a clergyman’s son, about the role of religion in my thinking and film-making. To me, religious problems are continuously alive. I never cease to concern myself with them;"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_03576aa51bd1','ch_b8e745ff5d32','text','{"text": "it goes on every hour of every day. Yet this does not take place on the emotional level, but on an intellectual one. Religious emotion, religious sentimentality, is something I got rid of long ago—I hope. The religious problem is an intellectual one to me: the relationship of my mind to my intuition."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_84ba21971e2c','ch_b8e745ff5d32','text','{"text": "The result of this conflict is usually some kind of tower of Babel. Philosophically, there is a book which was a tremendous experience for me: Eiono Kaila’s Psychology of the Personality. His thesis that man lives strictly according to his needs— negative and positive—was shattering to me, but terribly true. And I built on this ground."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f868e6a9d2d1','ch_b8e745ff5d32','text','{"text": "Cathedral-building"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9408ff5ff278','ch_b8e745ff5d32','text','{"text": "People ask what are my intentions with my films—my aims."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dcc4ef5692ce','ch_b8e745ff5d32','text','{"text": "It is a difficult and dangerous question, and I usually give an evasive answer: I try to tell the truth about the human condition, the truth as I see it. This answer seems to satisfy everyone, but it is not quite correct. I prefer to describe what I would like my aim to be. There is an old story of how the cathedral of Chartres was struck by lightning and burned to the ground."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a2627516648b','ch_b8e745ff5d32','text','{"text": "Then thousands of people came from all points of the compass, like a giant procession of ants, and together they began to rebuild the cathedral on its old site. They worked until the building was completed—master builders, artists, labourers, clowns, noblemen, priests, burghers. But they all remained anonymous and no one knows to this day who built the cathedral of Chartres."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2dd1db0765fc','ch_b8e745ff5d32','text','{"text": "Regardless of my own beliefs and my own doubts, which are unimportant in this connection, it is my opinion that art lost its basic creative drive the moment it was separated from worship. It severed an umbilical cord and now lives its own sterile life, generating and degenerating itself. In former days the artist remained unknown and his work was to the glory of God. He lived and died without being more or less important than other artisans; ‘eternal values’, ‘immortality’ and ‘masterpiece’ were terms not applicable in his case. The ability to create was a gift. In such a world flourished invulnerable assurance and natural humility. Today the individual has become the highest form and the greatest bane of artistic creation. The smallest wound or pain of the ego is examined under a microscope as if it were of eternal importance. The artist considers his isolation, his subjectivity, his individualism almost holy."}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bafa2fd86405','ch_b8e745ff5d32','text','{"text": "Thus we finally gather in one large pen, where we stand and bleat about our loneliness without listening to each other and without realising that we are smothering each other to death. The individualists stare into each other’s eyes and yet deny the existence of each other. We walk in circles, so limited by our anxieties that we can no longer distinguish between true and false, between the gangster’s whim and the purest ideal."}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b61d959f2f2','ch_b8e745ff5d32','text','{"text": "Thus if I am asked what I would like the general purpose of my films to be, I would reply that I want to be one of the artists in the cathedral on the great plain. I want to make a dragon’s head, an angel, a devil—or perhaps a saint—out of stone. It does not matter which;"}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b33a741d8ad9','ch_b8e745ff5d32','text','{"text": "it is the sense of satisfaction that counts. Regardless of whether I believe or not, whether I am a Christian or not, I would play my part in the collective building of the cathedral."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4667306c8990','ch_b8e745ff5d32','text','{"text": "Interview with Umberto Eco"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0383514a90b0','ch_b8e745ff5d32','text','{"text": "With over 30 honorary doctorates and a string of literary and academic awards, Umberto Eco has the reputation of being one of the world’s foremost intellectuals. A professor at the University of Bologna in Italy, Umberto Eco is known for his ideas on semiotics, literary interpretation and medieval aesthetics. He is a distinguished novelist and writer. His novel, The Name of the Rose, published in 1980 sold over ten million copies."}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_126ff48789bb','ch_b8e745ff5d32','text','{"text": "Here is an excerpt from an interview with Eco where he expresses his views on the filming of books."}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8dfb083ec511','ch_b8e745ff5d32','text','{"text": "The Name of the Rose is a very serious novel. It’s a detective yarn at one level but it also delves into metaphysics, theology, and medieval history. Yet it enjoyed a huge mass audience. Were you puzzled at all by this?"}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35f161158b40','ch_b8e745ff5d32','text','{"text": "No. Journalists are puzzled. And sometimes publishers. And this is because journalists and publishers believe that people like trash and don’t like difficult reading experiences."}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_924fe6d7c962','ch_b8e745ff5d32','text','{"text": "Consider there are six billion people in this planet. The Name of the Rose sold between 10 and 15 million copies. So in a way I reached only a small percentage of readers. But it is exactly these kinds of readers who don’t want easy experiences. Or at least don’t always want this. I myself, at 9 pm after dinner, watch television and want to see either ‘Miami Vice’ or ‘Emergency Room’."}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_30506b37f26f','ch_b8e745ff5d32','text','{"text": "I enjoy it and I need it. But not all day."}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f885c944afc1','ch_b8e745ff5d32','text','{"text": "Could the huge success of the novel have anything to do with the fact that it dealt with a period of medieval history that..."}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5e6fda4d48a','ch_b8e745ff5d32','text','{"text": "That’s possible. But let me tell you another story, because I often tell stories like a Chinese wise man. My American publisher said while she loved my book, she didn’t expect to sell more than 3,000 copies in a country where nobody has seen a cathedral or studies Latin."}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3bf42acf19b4','ch_b8e745ff5d32','text','{"text": "So I was given an advance for 3,000 copies, but in the end it sold two or three million in the U.S. A lot of books have been written about the medieval past far before mine. I think the success of the book is a mystery. Nobody can predict it. I think if I had written The Name of the Rose ten years earlier or ten years later, it wouldn’t have been the same. Why it worked at that time is a mystery."}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b02c7ddbf92','ch_b8e745ff5d32','text','{"text": "What did you think about the film [directed by Jean Jacques Annaud and starring Sean Connery]? Why weren’t you happy with it?"}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d780eb6f2e1','ch_b8e745ff5d32','text','{"text": "I expected the film to be different. My novel is a kind of club sandwich—lettuce, tomato, cheese..."}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_809e3e6fe039','ch_b8e745ff5d32','text','{"text": "Different layers of meaning?"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5bb8dcb707e','ch_b8e745ff5d32','text','{"text": "Yes. A film cannot select all the layers. It has to make do with jambon or cheese... I didn’t react like authors who, immediately after the film is made, say it is not at all like my book."}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd6a3c8f898c','ch_b8e745ff5d32','text','{"text": "But after that experience, I asked my publisher not to sell the rights of the novel to cinema. I did this because I discovered that 80 per cent of readers read the book after the movie. And that is very painful for a novelist."}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9ff188238d86','ch_b8e745ff5d32','text','{"text": "But surely this also means greater success, greater remuneration?"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7768cdcc58bd','ch_b8e745ff5d32','text','{"text": "Yes. But it is embarrassing to know that somebody else has already told the reader that the novel should be read in a particular way. That he should imagine the face of a character in a particular way."}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e504ecedc7b','ch_b8e745ff5d32','text','{"text": "The only enviable position is that of Homer’s who had the film made more than 2000 years after the book (laughs)."}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a94429a57d52','ch_b8e745ff5d32','text','{"text": "So this is why Stanley Kubrick never got to make Foucault’s Pendulum?"}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_935f7d75b64e','ch_b8e745ff5d32','text','{"text": "Since I had laid down a general rule, the publisher said no. Then Stanley Kubrick died. But it may have been a great movie (laughs)."}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dfbcd03bc4c9','ch_b8e745ff5d32','text','{"text": "Talking about Foucault’s Pendulum, there is a sense in which you did the Da Vinci Code before Dan Brown did. Of course, you did it as a myth that takes on a strange reality and he did it as it was historical truth."}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aadc3aec5146','ch_b8e745ff5d32','text','{"text": "I told Dan Brown’s story. My characters are his. I gave the broad picture of this kind of literature."}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a942148ff1b8','ch_b8e745ff5d32','list','{"ordered": false, "items": ["Ingmar Bergman"]}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_60802b793264','ch_b8e745ff5d32','text','{"text": "About the author"}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c92ae3ad46b','ch_b8e745ff5d32','text','{"text": "Ingmar Bergman is a well known Swedish director of films noted for their starkness, their subtle use of black and white and"}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98d802979712','ch_b8e745ff5d32','text','{"text": "‘shades’ of those extremes, the ambiguity of their content, and a certain brooding presence that seems to pervade them all. The list of Bergman films is long;"}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b624cb524314','ch_b8e745ff5d32','text','{"text": "his best known include The Seventh Seal (1957), Wild Strawberries (1958), The Virgin Spring (1960), The Silence (1963), Persona (1967), The Passion of Anna (1970), and Cries and Whispers (1973)—this last film in colour, though emphasising red in all its shadings."}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_934d84d4d4e3','ch_b8e745ff5d32','text','{"text": "In the following selection, the Introduction to Four Screen-plays by Ingmar Bergman (1960), Bergman discusses how he views the art of film-making."}',99);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_2ef7bf7196b7','bk_ncert_english','12-17-why-the-novel-matters','12.17 Why the Novel Matters',NULL,'public',88,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b8f10685e02','ch_2ef7bf7196b7','text','{"text": "We have curious ideas of ourselves. We think of ourselves as a body with a spirit in it, or a body with a soul in it, or a body with a mind in it. Mens sana in corpore sano. The years drink up the wine, and at last throw the bottle away, the body, of course, being the bottle. It is a funny sort of superstition."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b40513b56239','ch_2ef7bf7196b7','text','{"text": "Why should I look at my hand, as it so cleverly writes these words, and decide that it is a mere nothing compared to the mind that directs it? Is there really any huge difference between my hand and my brain? Or my mind? My hand is alive, it flickers with a life of its own. It meets all the strange universe in touch, and learns a vast number of things, and knows a vast number of things."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c83dd2f82b7f','ch_2ef7bf7196b7','text','{"text": "My hand, as it writes these words, slips gaily along, jumps like a grasshopper to dot an i, feels the table rather cold, gets a little bored if I write too long, has its own rudiments of thought, and is just as much me as is my brain, my mind, or my soul. Why should I imagine that there is a me which is more me than my hand is? Since my hand is absolutely alive, me alive. Whereas, of course, as far as I am concerned, my pen isn’t alive at all. My pen isn’t me alive."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d2927c22702c','ch_2ef7bf7196b7','text','{"text": "Me alive ends at my fingertips. Whatever is me alive is me. Every tiny bit of my hands is alive, every little freckle and hair and fold of skin. And whatever is me alive is me. Only my finger-nails, those ten little weapons between me and an inanimate universe, they cross the mysterious Rubicon between me alive and things like my pen, which are not alive, in my own sense."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c6170599556f','ch_2ef7bf7196b7','text','{"text": "So, seeing my hand is all alive and me alive, wherein is it just a bottle, or a jug, or a tin can, or a vessel of clay, or any of the rest of that nonsense? True, if I cut it will bleed, like a can of cherries. But then the skin that is cut, and the veins that bleed, and the bones that should never be seen, they are all just as alive as the blood that flows. So the tin can business, or vessel of clay, is just bunk. And that’s what you learn, when you’re a novelist."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d55d41052b8','ch_2ef7bf7196b7','text','{"text": "And that’s what you are very liable not to know, if you’re a parson, or a philosopher, or a scientist, or a stupid person. If you’re a parson, you talk about souls in heaven. If you’re a novelist, you know that paradise is in the palm of your hand, and on the end of your nose, because both are alive;"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b247d87cc15','ch_2ef7bf7196b7','text','{"text": "and alive, and man alive, which is more than you can say, for certain, of paradise. Paradise is after life, and I for one am not keen on anything that is after life."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92d631bafbf2','ch_2ef7bf7196b7','text','{"text": "If you are a philosopher, you talk about infinity;"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_533fe3ab9ec5','ch_2ef7bf7196b7','text','{"text": "and the pure spirit which knows all things. But if you pick up a novel, you realise immediately that infinity is just a handle to this self-same jug of a body of mine;"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0eff1fdc8c90','ch_2ef7bf7196b7','text','{"text": "while as for knowing, if I find my finger in the fire, I know that fire burns with a knowledge so emphatic and vital, it leaves Nirvana merely a conjecture. Oh, yes, my body, me alive, knows, and knows intensely."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d61b4c0f1f83','ch_2ef7bf7196b7','text','{"text": "And as for the sum of all knowledge, it can’t be anything more than an accumulation of all the things I know in the body, and you, dear reader, know in the body. These damned philosophers, they talk as if they suddenly went off in steam, and were then much more important than they are when they’re in their shirts. It is nonsense. Every man, philosopher included, ends in his own finger-tips. That’s the end of his man alive."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d19a98582613','ch_2ef7bf7196b7','text','{"text": "As for the words and thoughts and sighs and aspirations that fly from him, they are so many tremulations in the ether, and not alive at all. But if the tremulations reach another man alive, he may receive them into his life, and his life may take on a new colour, like a chameleon creeping from a brown rock on to a green leaf. All very well and good."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f92aae360227','ch_2ef7bf7196b7','text','{"text": "It still doesn’t alter the fact that the so-called spirit, the message or teaching of the philosopher or the saint, isn’t alive at all, but just a tremulation upon the ether, like a radio message. All this spirit stuff is just tremulations upon the ether. If you, as man alive, quiver from the tremulation of the other into new life, that is because you are man alive, and you take sustenance and stimulation into your alive man in a myriad ways."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bca6a2d9ad86','ch_2ef7bf7196b7','text','{"text": "But to say that the message, or the spirit which is communicated to you, is more important than your living body, is nonsense. You might as well say that the potato at dinner was more important. Nothing is important but life. And for myself, I can absolutely see life nowhere but in the living. Life with a capital L is only man alive. Even a cabbage in the rain is cabbage alive. All things that are alive are amazing. And all things that are dead are subsidiary to the living."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_11f3286478d2','ch_2ef7bf7196b7','text','{"text": "Better a live dog than a dead lion. But better a live lion than a live dog. C’est la vie! It seems impossible to get a saint, or a philosopher, or a scientist, to stick to this simple truth. They are all, in a sense, renegades. The saint wishes to offer himself up as spiritual food for the multitude. Even Frances of Assisi turns himself into a sort of angel-cake, of which anyone may take a slice. But an angel-cake is rather less than man alive. And poor St."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b44ce8a59c1','ch_2ef7bf7196b7','text','{"text": "Francis might well apologise to his body, when he is dying:"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbf0c5dd0563','ch_2ef7bf7196b7','text','{"text": "‘Oh, pardon me, my body, the wrong I did you through the years!’ It was no wafer, for others to eat."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a23e602f7e5','ch_2ef7bf7196b7','text','{"text": "The philosopher, on the other hand, because he can think, decides that nothing but thoughts matter. It is as if a rabbit, because he can make little pills, should decide that nothing but little pills matter. As for the scientist, he has absolutely no use for me so long as I am man alive. To the scientist, I am dead. He puts under the microscope a bit of dead me, and calls it me. He takes me to pieces, and says first one piece, and then another piece, is me."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b5f353ba68e5','ch_2ef7bf7196b7','text','{"text": "My heart, my liver, my stomach have all been scientifically me, according to the scientist;"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7253bc27cf98','ch_2ef7bf7196b7','text','{"text": "and nowadays I am either a brain, or nerves, or glands, or something more up-to-date in the tissue line. Now I absolutely flatly deny that I am a soul, or a body, or a mind, or an intelligence, or a brain, or a nervous system, or a bunch of glands, or any of the rest of these bits of me. The whole is greater than the part."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7a7dd426ef1','ch_2ef7bf7196b7','text','{"text": "And therefore, I, who am man alive, am greater than my soul, or spirit, or body, or mind, or consciousness, or anything else that is merely a part of me. I am a man, and alive. I am man alive, and as long as I can, I intend to go on being man alive. For this reason I am a novelist. And being a novelist, I consider myself superior to the saint, the scientist, the philosopher, and the poet, who are all great masters of different bits of man alive, but never get the whole hog."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce90cfaa0d81','ch_2ef7bf7196b7','text','{"text": "The novel is the one bright book of life. Books are not life. They are only tremulations on the ether. But the novel as a tremulation can make the whole man alive tremble. Which is more than poetry, philosophy, science, or any other book tremulation can do. The novel is the book of life. In this sense, the Bible is a great novel. You may say, it is about God. But it is really about man alive. I do hope you begin to get my idea, why the novel is supremely important, as a tremulation on the ether."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_afdf2384ef38','ch_2ef7bf7196b7','text','{"text": "Plato makes the perfect ideal being tremble in me. But that’s only a bit of me. Perfection is only a bit, in the strange make-up of man alive. The Sermon on the Mount makes the selfless spirit of me quiver. But that, too, is only a bit of me. The Ten Commandments set the old Adam shivering in me, warning me that I am a thief and a murderer, unless I watch it. But even the old Adam is only a bit of me. I very much like all these bits of me to be set trembling with life and the wisdom of life."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_663b59eeb4cf','ch_2ef7bf7196b7','text','{"text": "But I do ask that the whole of me shall tremble in its wholeness, some time or other. And this, of course, must happen in me, living. But as far as it can happen from a communication, it can only happen when a whole novel communicates itself to me. The Bible—but all the Bible—and Homer, and Shakespeare: these are the supreme old novels. These are all things to all men. Which means that in their wholeness they affect the whole man alive, which is the man himself, beyond any part of him."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_975648b3699a','ch_2ef7bf7196b7','text','{"text": "They set the whole tree trembling with a new access of life, they do not just stimulate growth in one direction. I don’t want to grow in any one direction any more. And, if I can help it, I don’t want to stimulate anybody else into some particular direction. A particular direction ends in a cul-de-sac. We’re in a cul-de-sac at present. I don’t believe in any dazzling revelation, or in any supreme Word."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49aa1dcc8b51','ch_2ef7bf7196b7','text','{"text": "‘The grass withereth, the flower fadeth, but the Word of the Lord shall stand for ever.’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b6c542de270','ch_2ef7bf7196b7','text','{"text": "That’s the kind of stuff we’ve drugged ourselves with. As a matter of fact, the grass withereth, but comes up all the greener for that reason, after the rains. The flower fadeth, and therefore the bud opens. But the Word of the Lord, being man-uttered and a mere vibration on the ether, becomes staler and staler, more and more boring, till at last we turn a deaf ear and it ceases to exist, far more finally than any withered grass. It is grass that renews its youth like the eagle, not any Word."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_425845cd88a0','ch_2ef7bf7196b7','text','{"text": "We should ask for no absolutes, or absolute. Once and for all and for ever, let us have done with the ugly imperialism of any absolute. There is no absolute good, there is nothing absolutely right. All things flow and change, and even change is not absolute. The whole is a strange assembly of apparently incongruous parts, slipping past one another. Me, man alive, I am a very curious assembly of incongruous parts. My yea! of today is oddly different from my yea! of yesterday."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_06afc97fc5a2','ch_2ef7bf7196b7','text','{"text": "My tears of tomorrow will have nothing to do with my tears of a year ago. If the one I love remains unchanged and unchanging, I shall cease to love her. It is only because she changes and startles me into change and defies my inertia, and is herself staggered in her inertia by my changing, that I can continue to love her. If she stayed put, I might as well love the pepper-pot. In all this change, I maintain a certain integrity. But woe betide me if I try to put my figure on it."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a46a287f18b5','ch_2ef7bf7196b7','text','{"text": "If I say of myself, I am this, I am that—then, if I stick to it, I turn into a stupid fixed thing like a lamp-post. I shall never know wherein lies my integrity, my individuality, my me. I can never know it. It is useless to talk about my ego. That only means that I have made up an idea of myself, and that I am trying to cut myself out to pattern. Which is no good. You can cut your cloth to fit your coat, but you can’t clip bits off your living body, to trim it down to your idea."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_41a2c244394e','ch_2ef7bf7196b7','text','{"text": "True, you can put yourself into ideal corsets. But even in ideal corsets, fashions change. Let us learn from the novel. In the novel, the characters can do nothing but live. If they keep on being good, according to pattern, or bad, according to pattern, or even volatile, according to pattern, they cease to live, and the novel falls dead. A character in a novel has got to live, or it is nothing. We, likewise, in life have got to live, or we are nothing."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ab37ff28ee0','ch_2ef7bf7196b7','text','{"text": "What we mean by living is, of course, just as indescribable as what we mean by being. Men get ideas into their heads, of what they mean by Life, and they proceed to cut life out to pattern. Sometimes they go into the desert to seek God, sometimes they go into the desert to seek cash, sometimes it is wine, woman, and song, and again it is water, political reform, and votes."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1c34bc669fa','ch_2ef7bf7196b7','text','{"text": "You never know what it will be next: from killing your neighbour with hideous bombs and gas that tears the lungs, to supporting a Foundlings Home and preaching infinite Love, and being co-respondent in a divorce. In all this wild welter, we need some sort of guide. It’s no good inventing Thou Shalt Nots! What then? Turn truly, honourably to the novel, and see wherein you are man alive, and wherein you are dead man in life. You may eat your dinner as man alive, or as mere masticating corpse."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_774d243c8ce6','ch_2ef7bf7196b7','text','{"text": "As man alive you may have a shot at your enemy. But as a ghastly simulacrum of life you may be firing bombs into men who are neither your enemies nor your friends, but just things you are dead to. Which is criminal, when the things happen to be alive. To be alive, to be man alive, to be whole man alive: that is the point. And at its best, the novel, and the novel supremely, can help you. It can help you not to be dead man in life."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a2362c403493','ch_2ef7bf7196b7','text','{"text": "So much of a man walks about dead and a carcass in the street and house, today: so much of women is merely dead. Like a pianoforte with half the notes mute. But in the novel you can see, plainly, when the man goes dead, the woman goes inert. You can develop an instinct for life, if you will, instead of a theory of right and wrong, good and bad. In life, there is right and wrong, good and bad, all the time. But what is right in one case is wrong in another."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49eb2e13838a','ch_2ef7bf7196b7','text','{"text": "And in the novel you see one man becoming a corpse, because of his so-called goodness;"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7ed188ddb88','ch_2ef7bf7196b7','text','{"text": "another going dead because of his so-called wickedness. Right and wrong is an instinct: but an instinct of the whole consciousness in a man, bodily, mental, spiritual at once. And only in the novel are all things given full play, or at least, they may be given full play, when we realise that life itself, and not inert safety, is the reason for living."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25172e9c3c19','ch_2ef7bf7196b7','text','{"text": "For out of the full play of all things emerges the only thing that is anything, the wholeness of a man, the wholeness of a woman, man alive, and live woman."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a9536246fe4','ch_2ef7bf7196b7','list','{"ordered": false, "items": ["D.H. Lawrence"]}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1677cb016011','ch_2ef7bf7196b7','text','{"text": "About the Author"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f062e0d92bd4','ch_2ef7bf7196b7','text','{"text": "D.H. Lawrence was born in a coal-mining town. He was the son of an uneducated miner and an ambitious mother who was a teacher. His wife was German, and the couple lived, at various times, in Italy, Germany, Australia, Tahiti and Mexico."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_538298459029','ch_2ef7bf7196b7','text','{"text": "Lawrence’s writings reflect a revolt against puritanism, mediocrity and the dehumanisation of an industrial society."}',42);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_8202b5b650d6','bk_ncert_english','12-18-the-argumentative-indian','12.18 The Argumentative Indian',NULL,'public',89,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4cdd6dcd97d','ch_8202b5b650d6','text','{"text": "Prolixity is not alien to us in India. We are able to talk at some length. Krishna Menon’s* record of the longest speech ever delivered at the United Nations (nine hours non-stop), established half a century ago (when Menon was leading the Indian delegation), has not been equalled by anyone from anywhere. Other peaks of loquaciousness have been scaled by other Indians. We do like to speak. This is not a new habit."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_698e39335c8b','ch_8202b5b650d6','text','{"text": "The ancient Sanskrit epics, the Ramayana and the Mahabharata, which are frequently compared with the Iliad and the Odyssey, are colossally longer than the works that the modest Homer could manage. Indeed, the Mahabharata alone is about seven times as long as the Iliad and the Odyssey put together."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b8dee9f7af6','ch_8202b5b650d6','text','{"text": "The Ramayana and the Mahabharata are certainly great epics: I recall with much joy how my own life was vastly enriched when I encountered them first as a restless youngster looking for intellectual stimulation as well as sheer entertainment. But they proceed from stories to stories woven around their principal tales, and are engagingly full of dialogues, dilemmas and alternative perspectives."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f8915e0bbed2','ch_8202b5b650d6','text','{"text": "And we encounter masses of arguments and counterarguments spread over incessant debates and disputations."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8aed8a56fffe','ch_8202b5b650d6','text','{"text": "Dialogue and Significance"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e702838b6a9','ch_8202b5b650d6','text','{"text": "The arguments are also, often enough, quite substantive. For example, the famous Bhagavad Gita, which is one small section of the Mahabharata, presents a tussle between two contrary moral positions —Krishna’s emphasis on doing one’s duty, on one side, and Arjuna’s focus on avoiding bad consequences (and generating good ones), on the other."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce9250bafd50','ch_8202b5b650d6','text','{"text": "The debate occurs on the eve of the great war that is a central event in the Mahabharata. Watching the two armies readying for war, profound doubts about the correctness of what they are doing are raised by Arjuna, the peerless and invincible warrior in the army of the just and honourable royal family (the Pandavas) who are about to fight the unjust usurpers (the Kauravas)."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75fc0f9e7836','ch_8202b5b650d6','text','{"text": "Arjuna questions whether it is right to be concerned only with one’s duty to promote a just cause and be indifferent to the misery and the slaughter—even of one’s kin—that the war itself would undoubtedly cause. Krishna, a divine incarnation in the form of human being (in fact, he is also Arjuna’s charioteer), argues against Arjuna."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8863b4a69e15','ch_8202b5b650d6','text','{"text": "His response takes the form of articulating principles of action— based on the priority of doing one’s duty—which have been repeated again and again in Indian philosophy. Krishna insists on Arjuna’s duty to fight, irrespective of his evaluation of the consequences. It is a just cause, and, as a warrior and a general on whom his side must rely, Arjuna cannot waver from his obligations, no matter what the consequences are."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb2c7b9542f7','ch_8202b5b650d6','text','{"text": "Krishna’s hallowing of the demands of duty wins the argument, at least as seen in the religious perspective. Indeed, Krishna’s conversations with Arjuna, the Bhagavad Gita, became a treatise of great theological importance in Hindu philosophy, focusing particularly on the ‘removal’ of Arjuna’s doubts. Krishna’s moral position has also been eloquently endorsed by many philosophical and literary commentators across the world, such as Christopher Isherwood and T. S. Eliot. Isherwood in fact translated the Bhagavad Gita into English. This admiration for the Gita, and for Krishna’s arguments in particular, has been a lasting phenomenon in parts of European culture. It was spectacularly praised in the early nineteenth century by Wilhelm von Humboldt as"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3306ec0cb21d','ch_8202b5b650d6','text','{"text": "‘the most beautiful, perhaps the only true philosophical song existing in any known tongue’. In a poem in Four Quartets, Eliot summarises Krishna’s view in the form of an admonishment:"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c2bc44e013ac','ch_8202b5b650d6','text','{"text": "‘And do not think of the fruit of action! Fare forward’. Eliot explains:"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a30449ec5df','ch_8202b5b650d6','text','{"text": "‘Not fare well/But fare forward, voyagers’."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c278d69334a3','ch_8202b5b650d6','text','{"text": "And yet, as a debate in which there are two reasonable sides, the epic Mahabharata itself presents, sequentially, each of the two contrary arguments with much care and sympathy. Indeed, the tragic desolation that the postcombat and post-carnage land—largely the Indo-Gangetic plain—seems to face towards the end of the Mahabharata can even be seen as something of a vindication of Arjuna’s profound doubts. Arjuna’s contrary arguments are not really vanquished, no matter what the"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e830f307f69a','ch_8202b5b650d6','text','{"text": "‘message’ of the Bhagavad Gita is meant to be. There remains a powerful case for"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e85933beacca','ch_8202b5b650d6','text','{"text": "‘faring well’, and not just"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c94997efd54','ch_8202b5b650d6','text','{"text": "‘forward’.* J. Robert Oppenheimer, the leader of the American team that developed the ultimate"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e19b9c814a85','ch_8202b5b650d6','text','{"text": "‘weapon of mass destruction’ during the Second World War, was moved to quote Krishna’s words (‘I am become death, the destroyer of worlds’"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c39017a007c','ch_8202b5b650d6','text','{"text": ") as he watched, on 16 July 1945, the awesome force of the first nuclear explosion devised by man. Like the advice that Arjuna had received about his duty as a warrior fighting for a just cause, Oppenheimer, the physicist, could well find justification in his technical commitment to develop a bomb for what was clearly the right side. Scrutinizing—indeed criticising—his own actions, Oppenheimer said later on:"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c023509e590','ch_8202b5b650d6','text','{"text": "‘When you see something that is technically sweet, you go ahead and do it and you argue about what to do about it only after you have had your technical success.’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_700a973e7ee5','ch_8202b5b650d6','text','{"text": "Despite that compulsion to"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d6e8fecd5506','ch_8202b5b650d6','text','{"text": "‘fare forward’, there was reason also for reflecting on Arjuna’s concerns: How can good come from killing so many people? And why should I seek victory, kingdom or happiness for my own side? These arguments remain thoroughly relevant in the contemporary world."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db72bba62ea7','ch_8202b5b650d6','text','{"text": "The case for doing what one sees as one’s duty must be strong, but how can we be indifferent to the consequences that may follow from our doing what we take to be our just duty? As we reflect on the manifest problems of our global world (from terrorism, wars and violence to epidemics, insecurity and gruelling poverty), or on India’s special concerns (such as economic development, nuclear confrontation or regional peace), it is important to take on board Arjuna’s consequential analysis, in addition to considering Krishna’s arguments for doing one’s duty. The univocal"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_11e938e5e862','ch_8202b5b650d6','text','{"text": "‘message of the Gita’ requires supplementation by the broader argumentative wisdom of the Mahabharata, of which the Gita is only one small part."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9cf5638f14c7','ch_8202b5b650d6','text','{"text": "Gender, Caste and Voice"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40310f9b44b8','ch_8202b5b650d6','text','{"text": "There is, however, a serious question to be asked as to whether the tradition of arguments and disputations has been confined to an exclusive part of the Indian population—perhaps just to the members of the male elite."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c627710b3620','ch_8202b5b650d6','text','{"text": "It would, of course, be hard to expect that argumentational participation would be uniformly distributed over all segments of the population, but India has had deep inequalities along the lines of gender, class, caste and community (on which more presently). The social relevance of the argumentative tradition would be severely limited if disadvantaged sections were effectively barred from participation. The story here is, however, much more complex than a simple generalisation can capture."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f6933ed93b2','ch_8202b5b650d6','text','{"text": "I begin with gender. There can be little doubt that men have tended, by and large, to rule the roost in argumentative moves in India. But despite that, the participation of women in both political leadership and intellectual pursuits has not been at all negligible. This is obvious enough today, particularly in politics. Indeed, many of the dominant political parties in India—national as well as regional—are currently led by women and have been so led in the past."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5755055f18c','ch_8202b5b650d6','text','{"text": "But even in the national movement for Indian independence, led by the Congress Party, there were many more women in positions of importance than in the Russian and Chinese revolutionary movements put together. It is also perhaps worth noting that Sarojini Naidu, the first woman President of the Indian National Congress, was elected in 1925, fifty years earlier than the election of the first woman leader of a major British political party (Margaret Thatcher in 1975).*"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04b7a0c6e45a','ch_8202b5b650d6','text','{"text": "The second woman head of the Indian National Congress, Nellie Sengupta, was elected in 1933. Earlier or later, these developments are products of relatively recent times. But what about the distant past? Women’s traditional role in debates and discussions has certainly been much less pronounced than that of men in India (as would also be true of most countries in the world)."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02f17d28d0a0','ch_8202b5b650d6','text','{"text": "But it would be a mistake to think that vocal leadership by women is completely out of line with anything that has happened in India’s past. Indeed, even if we go back all the way to ancient India, some of the most celebrated dialogues have involved women, with the sharpest questionings often coming from women interlocutors."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d98f184255c3','ch_8202b5b650d6','text','{"text": "This can be traced back even to the Upanisads—the dialectical treatises that were composed from about the eighth century BCE and which are often taken to be foundations of Hindu philosophy. For example, in the Brihadaranyaka Upanisad we are told about the famous"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6074f0db8f67','ch_8202b5b650d6','text','{"text": "‘arguing combat’ in which Yajnavalkya, the outstanding scholar and teacher, has to face questions from the assembled gathering of pundits, and here it is a woman scholar, Gargi, who provides the sharpest edge to the intellectual interrogation. She enters the fray without any special modesty:"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_64614b5a513e','ch_8202b5b650d6','text','{"text": "‘Venerable Brahmins, with your permission I shall ask him two questions only. If he is able to answer those questions of mine, then none of you can ever defeat him in expounding the nature of God.’"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef6d89316182','ch_8202b5b650d6','text','{"text": "Even though Gargi, as an intellectual and pedagogue, is no military leader (in the mode, for example, of the Rani of Jhansi—another feminine hero—who fought valiantly along with the"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd92f6f099f9','ch_8202b5b650d6','text','{"text": "‘mutineers’ in the middle of the nineteenth century against British rule—one of the great"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8e48b37ff325','ch_8202b5b650d6','text','{"text": "‘warriorqueens’ of the world, as Antonia Fraser describes her), her use of imagery is strikingly militant:"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_55be862fed37','ch_8202b5b650d6','text','{"text": "‘Yajnavalkya, I have two questions for you. Like the ruler of Videha or Kasi [Benares], coming from a heroic line, who strings his unstrung bow, takes in hand two penetrating arrows and approaches the enemy, so do I approach you with two questions, which you have to answer.’"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a363e551151a','ch_8202b5b650d6','text','{"text": "Yajnavalkya does, however, manage to satisfy Gargi with his answers (I am not competent to examine the theological merits of this interchange and will refrain from commenting on the substantive content of their discussion). Gargi acknowledges this handsomely, but again without undue modesty:"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4007d3a0b029','ch_8202b5b650d6','text','{"text": "‘Venerable Brahmins, you should consider it an achievement if you can get away after bowing to him. Certainly, none of you can ever defeat him in expounding the nature of God.’"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ac4304c0ff1','ch_8202b5b650d6','text','{"text": "Interestingly, Yajnavalkya’s wife Maitreyi raises a profoundly important motivational question when the two discuss the reach of wealth in the context of the problems and predicaments of human life, in particular what wealth can or cannot do for us. Maitreyi wonders whether it could be the case that if"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c4949912eabe','ch_8202b5b650d6','text','{"text": "‘the whole earth, full of wealth’ were to belong just to her, she could achieve immortality through it."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_905072f1c946','ch_8202b5b650d6','text','{"text": "‘No’, responds Yajnavalkya, ‘like the life of rich people will be your life. But there is no hope of immortality by wealth’. Maitreyi remarks:"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc4f4848086a','ch_8202b5b650d6','text','{"text": "‘What should I do with that by which I do not become immortal?’ Maitreyi’s rhetorical question has been repeatedly cited in Indian religious philosophy to illustrate both the nature of the human predicament and the limitations of the material world."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1144cc83073c','ch_8202b5b650d6','text','{"text": "But there is another aspect of this exchange that has, in some ways, more immediate interest. This concerns the relation—and the distance—between income and achievement, between the commodities we can buy and the actual capabilities we can enjoy, between our economic wealth and our ability to live as we would like.* While there is a connection between opulence and our ability to achieve what we value, the linkage may or may not be very close."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24a3ecd1dc9b','ch_8202b5b650d6','text','{"text": "Maitreyi’s worldly worries might well have some transcendental relevance (as Indian religious commentators have discussed over many centuries), but they certainly have worldly interest as well. If we are concerned with the freedom to live long and live well, our focus has to be directly on life and death, and not just on wealth and economic opulence."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a077bebd5343','ch_8202b5b650d6','text','{"text": "The arguments presented by women speakers in epics and classical tales, or in recorded history, do not always conform to the tender and peace-loving image that is often assigned to women. In the epic story of the Mahabharata, the good King Yudhisthira, reluctant to engage in a bloody battle, is encouraged to fight the usurpers of his throne with"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d8ef5d02537','ch_8202b5b650d6','text','{"text": "‘appropriate anger’, and the most eloquent instigator is his wife, Draupadi."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6dccc8e8fdf8','ch_8202b5b650d6','text','{"text": "In the sixth-century version of this dialogue, presented in the Kiratarjuniya by Bharavi, Draupadi speaks thus—"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f49b1604773','ch_8202b5b650d6','text','{"text": "For a woman to advise men like you"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ceee30bb6c5','ch_8202b5b650d6','text','{"text": "is almost an insult."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3c8ce7f5bd3a','ch_8202b5b650d6','text','{"text": "And yet, my deep troubles compel me"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b731b137b88b','ch_8202b5b650d6','text','{"text": "to overstep the limits of womanly conduct,"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_570675547ecc','ch_8202b5b650d6','text','{"text": "make me speak up."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_39a9fb674d58','ch_8202b5b650d6','text','{"text": "The kings of your race, brave as Indra,"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_faa6f9ed2827','ch_8202b5b650d6','text','{"text": "have for a long time ruled the earth without a break."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d1af9964323','ch_8202b5b650d6','text','{"text": "But now with your own hand"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e5fcf6e2f95','ch_8202b5b650d6','text','{"text": "you have thrown it away,"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d846f94eef14','ch_8202b5b650d6','text','{"text": "like a rutting elephant tearing off"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f9655c54703c','ch_8202b5b650d6','text','{"text": "his garland with his trunk..."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bfa38f14a3b2','ch_8202b5b650d6','text','{"text": "If you choose to reject heroic action"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_60442c756f42','ch_8202b5b650d6','text','{"text": "and see forbearance as the road to future happiness,"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7d3053021bfe','ch_8202b5b650d6','text','{"text": "then throw away your bow, the symbol of royalty,"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_225d5f0f391c','ch_8202b5b650d6','text','{"text": "wear your hair matted in knots,"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ecf89df040f','ch_8202b5b650d6','text','{"text": "stay here and make offerings in the sacred fire!"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e1eac8cacdc','ch_8202b5b650d6','text','{"text": "It is not hard to see which side Draupadi was on in the Arjuna-Krishna debate, which deals with a later stage of the same sequence of events, by which time Yudhisthira had made his choice to fight (rather than embrace the life of a local hermit, mockingly assigned to him by his wife, with unconcealed derision)."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3606a65fe042','ch_8202b5b650d6','text','{"text": "If it is important not to see the Indian argumentative tradition as the exclusive preserve of men, it is also necessary to understand that the use of argumentative encounters has frequently crossed the barriers of class and caste. Indeed, the challenge to religious orthodoxy has often come from spokesmen of socially disadvantaged groups. Disadvantage is, of course, a comparative concept."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24d031604214','ch_8202b5b650d6','text','{"text": "When Brahminical orthodoxy was disputed in ancient India by members of other groups (including merchants and craftsmen), the fact that the protesters were often quite affluent should not distract attention from the fact that, in the context of Brahmin-dominated orthodoxy, they were indeed distinctly underprivileged. This may be particularly significant in understanding the class basis of the rapid spread of Buddhism, in particular, in India."}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb19a04aa003','ch_8202b5b650d6','text','{"text": "The undermining of the superiority of the priestly caste played quite a big part in these initially rebellious religious movements, which include Jainism as well as Buddhism. It included a"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09de102123d1','ch_8202b5b650d6','text','{"text": "‘levelling’ feature that is not only reflected in the message of human equality for which these movements stood, but is also captured in the nature of the arguments used to undermine the claim to superiority of those occupying exalted positions. Substantial parts of early Buddhist and Jain literatures contain expositions of protest and resistance."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cfebe9249438','ch_8202b5b650d6','text','{"text": "Movements against caste divisions that have figured repeatedly in Indian history, with varying degrees of success, have made good use of engaging arguments to question orthodox beliefs. Many of these counterarguments are recorded in the epics, indicating that opposition to hierarchy was not absent even in the early days of caste arrangements."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8285327204e3','ch_8202b5b650d6','text','{"text": "We do not know whether the authors to whom the sceptical arguments are attributed were the real originators of the doubts expressed, or mere vehicles of exposition of already established questioning, but the prominent presence of these anti-inequality arguments in the epics as well as in other classical documents gives us a fuller insight into the reach of the argumentative tradition than a monolithic exposition of the so-called, ‘Hindu point of view’ can possibly provide."}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f25b9f429d42','ch_8202b5b650d6','text','{"text": "For example, when, in the Mahabharata, Bhrigu tells Bharadvaja that caste divisions relate to differences in physical attributes of different human beings, reflected in skin colour, Bharadvaja responds not only by pointing to the considerable variations in skin colour within every caste (‘if different colours indicate different castes, then all castes are mixed castes’"}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a4b819c36593','ch_8202b5b650d6','text','{"text": "), but also by the more profound question:"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40df51a8e9c4','ch_8202b5b650d6','text','{"text": "‘We all seem to be affected by desire, anger, fear, sorrow, worry, hunger, and labour;"}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de04beb86e23','ch_8202b5b650d6','text','{"text": "how do we have caste differences then?’ There is also a genealogical scepticism expressed in another ancient document, the Bhavisya Purana:"}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3fc4ab468cd','ch_8202b5b650d6','text','{"text": "‘Since members of all the four castes are children of God, they all belong to the same caste. All human beings have the same father, and children of the same father cannot have different castes.’"}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d79eb007d57f','ch_8202b5b650d6','text','{"text": "These doubts do not win the day, but nor are their expressions obliterated in the classical account of the debates between different points of view. To look at a much later period, the tradition of"}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc9ad565d7d5','ch_8202b5b650d6','text','{"text": "‘medieval mystical poets’, well established by the fifteenth century, included exponents who were influenced both by the egalitarianism of the Hindu Bhakti movement and by that of the Muslim Sufis, and their far-reaching rejection of social barriers brings out sharply the reach of arguments across the divisions of caste and class."}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d306d29e89c','ch_8202b5b650d6','text','{"text": "Many of these poets came from economically and socially humble backgrounds, and their questioning of social divisions as well as of the barriers of disparate religions reflected a profound attempt to deny the relevance of these artificial restrictions. It is remarkable how many of the exponents of these heretical points of views came from the working class: Kabir, perhaps the greatest poet of them all, was a weaver, Dadu a cottoncarder, Ravi-das a shoe-maker, Sena a barber, and so on.*"}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e2908c45097e','ch_8202b5b650d6','text','{"text": "Also, many leading figures in these movements were women, including of course the famous Mira Bai (whose songs are still very popular, after four hundred years), but also Andal, Daya-bai, Sahajo-bai and Ksema, among others. In dealing with issues of contemporary inequality, the relevance and reach of the argumentative tradition must be examined in terms of the contribution it can make today in resisting and undermining these inequities which characterise so much of contemporary Indian society."}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a9c9dfc4d1e','ch_8202b5b650d6','text','{"text": "It would be a great mistake in that context to assume that because of the possible effectiveness of well-tutored and disciplined arguments, the argumentative tradition must, in general, favour the privileged and the well educated, rather than the dispossessed and the deprived."}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_10ef10721de1','ch_8202b5b650d6','text','{"text": "Some of the most powerful arguments in Indian intellectual history have, in fact, been about the lives of the least privileged groups, which have drawn on the substantive force of these claims, rather than on the cultivated brilliance of welltrained dialectics. Democracy as Public Reasoning Does the richness of the tradition of argument make much difference to subcontinental lives today? I would argue it does, and in a great many different ways."}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa6b69550823','ch_8202b5b650d6','text','{"text": "It shapes our social world and the nature of our culture. It has helped to make heterodoxy the natural state of affairs in India;"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02ff4d9d7ead','ch_8202b5b650d6','text','{"text": "persistent arguments are an important part of our public life. It deeply influences Indian politics, and is particularly relevant, I would argue, to the development of democracy in India and the emergence of its secular priorities."}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b3825eca1fc6','ch_8202b5b650d6','text','{"text": "The historical roots of democracy in India are well worth considering, if only because the connection with public argument is often missed, through the temptation to attribute the Indian commitment to democracy simply to the impact of British influence (despite the fact that such an influence should have worked similarly for a hundred other countries that emerged from an empire on which the sun used not to set)."}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a50fb28137c9','ch_8202b5b650d6','text','{"text": "The point at issue, however, is not specific to India only: in general, the tradition of public reasoning is closely related to the roots of democracy across the globe. But since India has been especially fortunate in having a long tradition of public arguments, with toleration of intellectual heterodoxy, this general connection has been particularly effective in India."}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1cdddaed5bd','ch_8202b5b650d6','text','{"text": "When, more than half a century ago, independent India became the first country in the non-Western world to choose a resolutely democratic constitution, it not only used what it had learned from the institutional experiences in Europe and America (particularly Great Britain), it also drew on its own tradition of public reasoning and argumentative heterodoxy."}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99bdbfa11b01','ch_8202b5b650d6','text','{"text": "It is very important to avoid the twin pitfalls of (1) taking democracy to be just a gift of the Western world that India simply accepted when it became independent, and (2) assuming that there is something unique in Indian history that makes the country singularly suited to democracy. The point, rather, is that democracy is intimately connected with public discussion and interactive reasoning. Traditions of public discussion exist across the world, not just in the West."}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_210514a32fd0','ch_8202b5b650d6','text','{"text": "And to the extent that such a tradition can be drawn on, democracy becomes easier to institute and also to preserve."}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09eb6540bf0b','ch_8202b5b650d6','list','{"ordered": false, "items": ["Amartya Sen"]}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2cbdfbb7fe5a','ch_8202b5b650d6','text','{"text": "About the Author"}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fea01e3de10f','ch_8202b5b650d6','text','{"text": "Amartya Sen was awarded the Nobel Prize in Economics in 1998 for his contribution in the field of welfare economics. He is Lamont Professor at Harvard. This text forms the opening sections of the first essay in Sen’s book of the same title published in 2005. The sub-title of the book is ‘Writings on Indian Culture, History and Identity’."}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_29ee73cf82b2','ch_8202b5b650d6','text','{"text": "Sen argues in this essay that in India there has been a long tradition of questioning the truth of ideas through discussion and dialogue."}',94);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_19468f4b4360','bk_ncert_english','12-19-on-science-fiction','12.19 On Science Fiction',NULL,'public',90,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d1c550053b02','ch_19468f4b4360','heading','{"level": 2, "text": "I"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b117eea0495','ch_19468f4b4360','text','{"text": "The Prescience Universe"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_224898a303d4','ch_19468f4b4360','text','{"text": "Foreword"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbe19e318881','ch_19468f4b4360','text','{"text": "To every history there is a prehistoric period. In the case of science fiction, the prehistory lingers on even today in some of the aspects of the field. But what of that? Just as Ice Age art can hold up its head with any form of art produced by sophisticated modern man, so can the prehistoric aspects of science fiction prove an accomplished literary form."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f49549b2b13a','ch_19468f4b4360','text','{"text": "I have often made the point that true science fiction is a creature of the last two centuries. Science fiction cannot exist as a picture of the future unless, and until, people get the idea that it is science and technology that produce the future;"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_edbe05cac01b','ch_19468f4b4360','text','{"text": "that it is advances in science and technology (or, at the very least, changes in them) that are bound to make the future different from the present and the past, and that thereby hangs a tale."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc09b6942305','ch_19468f4b4360','text','{"text": "Naturally, no one could possibly get that idea until the rate of scientific and technological change became great enough to be noticed by people in the course of their lifetime. That came about with the Industrial Revolution say, by 1800—and it was only thereafter that science fiction could be written. And yet there must have been something that came before science fiction, something that was not science fiction and yet filled the same emotional needs."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3c5c1b377ce7','ch_19468f4b4360','text','{"text": "There must have been tales of the strange and different, of life not as we know it, and of powers transcending our own. Let’s consider— The respect that people have for science and for scientists (or the fear that people have or a combination of both) rests on the certain belief that science is the key to the understanding of the Universe and that scientists can use science to manipulate that key."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5cbedb3b8e6','ch_19468f4b4360','text','{"text": "Through science, people can make use of the laws of nature to control the environment and enhance human powers. By the steadily increasing understanding of the details of those laws, human powers will be greater in the future than in the past. If we can imagine the different ways in which they will be greater, we can write our stories. In previous centuries, however, most men had but a dim understanding, if any at all, of such things as laws of nature."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e8363bb4740','ch_19468f4b4360','text','{"text": "They did not know of rules that were unbreakable;"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a329cb30d94','ch_19468f4b4360','text','{"text": "of things-as-they-must-be that could serve neither to help us nor to thwart us but that might allow themselves to be ridden to glory, if we but knew how. Instead, there was the notion that the Universe was the plaything of life and the will;"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7d6ebabe2181','ch_19468f4b4360','text','{"text": "that if there were events that seemed analogous to human deeds but that were far greater in magnitude, they were carried through by lifeform’s resembling those we know but greater in size and power."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f1d35060804','ch_19468f4b4360','text','{"text": "The beings who controlled natural phenomena were therefore pictured in human form, but of superhuman strength, size, abilities, and length of life. Sometimes they were pictured as superanimal, or as supercombinations of animals. (The constant reference to the ordinary in the invention of the unusual is only to be expected, for imaginations are sharply limited, even among the best of us, and it is hard to think of anything really new or unusual—as Hollywood"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dcff1bbc56d5','ch_19468f4b4360','text','{"text": "‘Sci-fi’ constantly demonstrates.) Since the phenomena of the Universe don’t often make sense, the gods are usually pictured as whimsical and unpredictable;"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c27f690be5cb','ch_19468f4b4360','text','{"text": "frequently little better than childish. Since natural events are often disastrous, the gods must be easily offended. Since natural events are often helpful, the gods are basically kindly, provided they are well-treated and that their anger is not roused."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c219c71c912','ch_19468f4b4360','text','{"text": "It is only too reasonable to suppose that people would invent formulas for placating the gods and persuading them to do the right thing. Nor can the validity of these formulas be generally disproven by events. If the formulas don’t work, then undoubtedly someone has done something to offend the gods."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_19ac5ea4536b','ch_19468f4b4360','text','{"text": "Those who had invented or utilised the formulas had no problems in finding guilty parties on whom to blame the failure of the formula in specific instances, so that faith in the formulas themselves never wavered. (We needn’t sneer. By the same principle, we continue to have faith in economists, sociologists, and meteorologists today, even though their statements seem to match reality only erratically at best.)"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b36b0a9a5fda','ch_19468f4b4360','text','{"text": "In prescientific times, then, it was the priest, magician, wizard, shaman (again the name doesn’t matter) who filled the function of the scientist today. It was the priest, etc., who was perceived as having the secret of controlling the Universe, and it was advances in the knowledge of magical formulas that could enhance power. The ancient myths and legends are full of stories of human beings with supernormal powers."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_869e6e4d35d5','ch_19468f4b4360','text','{"text": "There are the legendary heroes, for instance, who learn to control winged horses or flying carpets. Those ancient pieces of magic still fascinate us today, and I imagine a youngster could thrill to such mystical methods of aeronavigation and long for the chance to partake in it, even if he were reading the tales while on a jet plane."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4895651e62b7','ch_19468f4b4360','text','{"text": "Think of the crystal ball, into which one can see things that are happening many miles away, and magic shells that can allow us to hear the whisperings of humans many miles away. How much more wonderful than the television sets and the telephones of today! Consider the doors that open with"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_808c095a5b26','ch_19468f4b4360','text','{"text": "‘Open sesame’ rather than by the click of a remote-control device."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07735b7783dd','ch_19468f4b4360','text','{"text": "Consider the seven-league boots that can transport you across the countryside almost as quickly as an automobile can. Or, for that matter, think of the monsters of legend, the powerful travesties of life invented by combining animal characteristics: the man-horse Centaur, the man-goat Satyr, the woman-lion Sphinx, the woman-hawk Harpy, the eagle-lion Gryphon, the snake-woman Gorgon, and so on. In science fiction we have extraterrestrials that are often built up on the same principle."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4452f0cc801d','ch_19468f4b4360','text','{"text": "The goals of these ancient stories are the same as those of modern science fiction—the depiction of life as we don’t know it. The emotional needs that are fulfilled are the same— the satisfaction of the longing for wonder."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e12a66b6a77','ch_19468f4b4360','text','{"text": "The difference is that the ancient myths and legends fulfil those needs and meet those goals against the background of a Universe that is controlled by gods and demons who can, in turn, be controlled by magical formulas either in the form of enchantments to coerce, or prayers to cajole."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b35fd3bc3b60','ch_19468f4b4360','text','{"text": "Science fiction, on the other hand, fulfils those needs against the background of a Universe that is controlled by impersonal and unswervable laws of nature, which can, in turn, be controlled by an understanding of their nature. In a narrow sense, only science fiction is valid for today since, as far as we can tell, the Universe does follow the dictates of the laws of nature and is not at the mercy of gods and demons."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f38890817f85','ch_19468f4b4360','text','{"text": "Nevertheless, there are times when we shouldn’t be two narrow or haughty in our definitions. It would be wrong to throw out a style of literature that has tickled the human fancy for thousands of years for the trivial reason that it is not in accord with reality. Reality isn’t all there is, after all."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d41c402927d','ch_19468f4b4360','text','{"text": "Shall we no longer thrill to the climactic duel of Achilles and Hector because people no longer fight with spears and shields? Shall we no longer feel the excitement of the naval battles of the War of 1812 and of the Napoleonic Wars because our warships are no longer made of wood and are no longer equipped with sails? Never! Why, then, shouldn’t people who enjoy an exciting science fiction adventure story not enjoy a rousing mythological fiction adventure story? The two are set in different kinds of Universes but follow analogous paths. So though I am sufficiently stick-in-the-muddish to be narrow in my definition of science fiction and would not be willing to consider sword-and-sorcery examples of science fiction, I am willing to consider it the equivalent of science fiction set in another kind of Universe—a prescientific Universe. I don’t even ask that they be wrenched out of context and somehow be made to fit the universe of reality by being given a scientific or pseudoscientific gloss. I ask only that they be self-consistent in their prescientific Universe— and that they be well-written and exciting stories."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9d260a250cb','ch_19468f4b4360','heading','{"level": 2, "text": "Ii"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fad210f8cdc4','ch_19468f4b4360','text','{"text": "The Universe of Science Fiction"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4530dbc7eec0','ch_19468f4b4360','text','{"text": "Foreword"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_495370f546a5','ch_19468f4b4360','text','{"text": "Of late I have taken to the preparation of science fiction anthologies, which is perhaps a sign of literary senescence, though I like to think of it, rather, as putting my mature wisdom and expertise at the service of the science fiction reading public. After all, I am by no means ceasing, or even slowing, my own proper output. Besides, I must admit I generally make use of coeditors, and sweet-talk them into taking care of the more turgid aspects of the job—correspondence, bookkeeping, and so on. One of these recent anthologies was The 13 Crimes of Science Fiction (Doubleday, 1979) in which my coeditors were Martin Harry Greenberg and Charles G. Waugh. For the anthology, I wrote an introduction relating science fiction to other specialised fields of writing, especially mysteries, and here it is."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74017b37bd7f','ch_19468f4b4360','text','{"text": "Science fiction is a literary universe of no mean size because science fiction is what it is, not through its content but through its background. Let me explain the difference that makes. A ‘sports story’ must have, as part of its content, some competitive activity, generally of an athletic nature. A ‘Western story’ must have, as part of its content, the nomadic life of the cowboy of the American West in the latter half of the nineteenth century. The ‘jungle story’ must have, as part of its content, the dangers implicit in a forested tropical wilderness."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b3325820867','ch_19468f4b4360','text','{"text": "Take the content of any of these and place it against a background that involves a society significantly different from our own and you have not changed the nature of the story—you have merely added to it. A story may involve, not the clash of baseball and bat, or of hockeystick and puck, but of gas gun and sphere in an atmosphere enclosed on a space station under zero gravity. It is still a sports story by the strictest definition you care to make, but it is science fiction also."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b24f895f7f2','ch_19468f4b4360','text','{"text": "In place of the nomadic life of a cowboy and his horse herding cattle, you might have the nomadic life of a fishboy and his dolphin, herding his schools of mackerel and cod. It could still have the soul of a Western story and be science fiction also. In place of the Matto Grosso, you can have the jungle on a distant planet, different in key factors of the environment, with exotic dangers in atmosphere, in vegetation, in planetary characteristics never encountered on Earth."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd23aa00a53c','ch_19468f4b4360','text','{"text": "It would still be a jungle story and be science fiction also. For that matter, you needn’t confine yourself to category fiction. Take the deepest novel you can imagine, one that most amply plumbs the secret recesses of the soul and holds up a picture that illuminates nature and the human condition, and place it in a society in which interplanetary travel is common, and give it a plot which involves such travel and it is not only great literature—it is science fiction also. John W."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d32834686a42','ch_19468f4b4360','text','{"text": "Campbell, the late great science fiction editor, used to say that science fiction took as its domain, all conceivable societies, past and future, probable or improbable, realistic or fantastic, and dealt with all events and complications that were possible in all those societies. As for"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ecd9f49fe31','ch_19468f4b4360','text','{"text": "‘mainstream fiction’ which deals with the here and now and introduces only the small novelty of make believe events and characters, that forms only an inconsiderable fraction of the whole."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd475f400f04','ch_19468f4b4360','text','{"text": "And I agree with him. In only one respect did John retreat from this grand vision of the limitless boundaries of science fiction. In a moment of failure of nerve, he maintained that it was impossible to write a science fiction mystery. The opportunities in science fiction were so broad, he said, that the strict rules that made the classical mystery story fair to the reader could not be upheld."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3763cbeebf3','ch_19468f4b4360','text','{"text": "I imagine that what he expected was the sudden change of rules without warning in the midst of the story. Something like this, I suppose—"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ee646291150e','ch_19468f4b4360','text','{"text": "‘Ah, Watson, what that scoundrel did not count on was that with this pocket-frannistan which I have in my pocket-frannistan Container I can see through the lead lining and tell what is inside the casket.’"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_932ada578b6f','ch_19468f4b4360','text','{"text": "‘Amazing, Holmes, but how does it work?’"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2d38428795a','ch_19468f4b4360','text','{"text": "‘By the use of Q-rays, a little discovery of my own which I have never revealed to the world.’"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_55416916b7a3','ch_19468f4b4360','text','{"text": "Naturally, there is the temptation to do this. Even in the classical mystery story that is not science fiction there is the temptation to give the detective extraordinary abilities in order to advance the plot. Sherlock Holmes’s ability to distinguish, at sight, the ashes of hundreds of different kinds of tobacco, while not perhaps in the same class as the invention of a Q-ray at a moment’s notice, is certainly a step in the direction of the unfair."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_921242d6bed7','ch_19468f4b4360','text','{"text": "Then, too, there is nothing to prevent even the strictest of strict mystery writers from using actual science, even using the latest available findings of science, which the reader may not have heard of. That is still considered fair. There are dangers to that, however, since many mystery writers know no science and cannot prevent themselves from making bloopers."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d1c3ee687b6','ch_19468f4b4360','text','{"text": "John Dickson Carr, in one book, revealed that he didn’t know the difference between the element, antimony, and the compound, antimony potassium tartrate. That was only irritating, but in another book, he demonstrated that he couldn’t tell the difference between carbon monoxide and carbon dioxide and reduced the plot to a shambles."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_12cf07a314f8','ch_19468f4b4360','text','{"text": "One of Dorothy Sayers’ more grisly short stories involved the effect of thyroid hormones and, though she had the right idea, she made the effects impossibly rapid and extreme. Writing a scientific mystery, then, has its extraordinary pitfalls and difficulties;"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a6b28bc6e65','ch_19468f4b4360','text','{"text": "how much more so the writing of a science fiction mystery. In science fiction, you not only must know your science, but you must also have a rational notion as to how to modify or extrapolate that science."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_199927070183','ch_19468f4b4360','text','{"text": "That, however, only means that writing a science fiction mystery is difficult;"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_490c0c41fea4','ch_19468f4b4360','text','{"text": "it does not mean that it is conceptually impossible as John Campbell thought. After all, it is as perfectly possible to cling to the rules of the game in science fiction mysteries as in ordinary ones."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fbfc4ceb71ca','ch_19468f4b4360','text','{"text": "The science fiction mystery may be set in the future and in the midst of a society far different from ours;"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_262bd6aa86bd','ch_19468f4b4360','text','{"text": "one in which human beings have developed telepathy, for instance, or in which light-speed mass transport is possible, or in which all human knowledge is computerized for instant retrieval—but the rules still hold. The writer must carefully explain to the reader all their boundary conditions of the imaginary society."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5abadf637fe2','ch_19468f4b4360','text','{"text": "It must be perfectly clear what can be done and what can’t be done and with those boundaries fixed, the reader must then see and hear everything the investigator sees and hears, and he must be aware of every clue the investigator comes across. There may be misdirection and red herrings to obscure and confuse, but it must remain possible for the reader to introduce the investigator, however outré the society."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c23576bf9cd','ch_19468f4b4360','text','{"text": "Can it be done? You bet! Modestly, I refer you to my own science fiction mysteries, The Caves of Steel and The Naked Sun which I wrote, back in the 1950s, in order to show John that he was being too modest about science fiction."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f655c8f4020a','ch_19468f4b4360','list','{"ordered": false, "items": ["Isaac Asimov"]}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8596baa99c91','ch_19468f4b4360','text','{"text": "About the Author"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c60de14271d1','ch_19468f4b4360','text','{"text": "Isaac Asimov was a Russian born American author and biochemist. He was a highly successful and exceptionally prolific writer best known for his works on science fiction and for his popular science books."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aea4fe53d17f','ch_19468f4b4360','text','{"text": "Most of Asimov’s popularised science books explain science concepts in a historical way, going back as far as possible to a time when the science in question was at its simplest stage. He also lent his name to the magazine, Asimov’s Science Fiction."}',57);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_b5606ea56d01','bk_ncert_english','drama','Drama',NULL,'public',91,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e99b31e822e0','ch_b5606ea56d01','heading','{"level": 2, "text": "Introduction"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80ebe4533216','ch_b5606ea56d01','text','{"text": "A drama is a composition in prose or verse presenting in dialogue a story of life or character, especially one intended to be acted on the stage. The essence of drama is the make-believe by which an actor impersonates a character of the play. The element of make-believe in drama is much greater than the average play-goer realises. For instance, we must regard it as entirely natural that rooms and houses have one wall"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e62f0e7dd726','ch_b5606ea56d01','text','{"text": "‘missing’ that enables the audience to witness the action. Drama is usually divided into tragedy and comedy, but within this general framework a number of types and subtypes have been developed. The tragicomedy, for instance, mixes elements of both tragedy and comedy;"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8834f090bc18','ch_b5606ea56d01','text','{"text": "the modern"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76673a90bfd2','ch_b5606ea56d01','text','{"text": "‘problem-play’ deals with neither of these but with middle class life and problems. Furthermore, drama is the literary form most viable with the modern mass media;"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e323cd9f2784','ch_b5606ea56d01','text','{"text": "and film, radio and television are producing a vast quantity of it, ranging from"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1301010b715e','ch_b5606ea56d01','text','{"text": "‘soap opera’ and farce to serious new works and fine productions of old ones."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b798ebbac453','ch_b5606ea56d01','text','{"text": "Two plays find a place in the section: Chandalika by Tagore which describes the angst of an untouchable woman;"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22ec5ae79019','ch_b5606ea56d01','text','{"text": "and an excerpt from Broken Images by Girish Karnad, which is a monologue by a celebrity writer that plumbs the depths of her psyche and recreates her life for the TV viewer."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8588ab13f97c','ch_b5606ea56d01','text','{"text": "*********"}',10);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_08b9d3bd59db','bk_ncert_english','12-20-chandalika','12.20 Chandalika',NULL,'public',92,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca7b35cddf79','ch_08b9d3bd59db','heading','{"level": 2, "text": "Introduction"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3465be424795','ch_08b9d3bd59db','text','{"text": "This short drama is based on the following Buddhist legend."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79e9a9ffeac2','ch_08b9d3bd59db','text','{"text": "Ananda, the famous disciple of the Buddha, was one day returning from a visit when he felt thirsty and, approaching a well on the way, asked for water from a chandalika, a girl belonging to the lowest untouchable caste. The girl gave him water and fell in love with the beautiful monk. Unable to restrain herself, she made her mother, who knew the art of magic, work her spell on him."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c851e229d242','ch_08b9d3bd59db','text','{"text": "The spell proved stronger than Ananda’s will and the spell-bound monk presented himself at their house at night;"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_10e12b12cfd4','ch_08b9d3bd59db','text','{"text": "but, as he saw the girl spread the couch for him, he was overcome with shame and remorse and prayed inwardly to his master to save him. The Buddha heard the prayer and broke the magic spell and Ananda went away, as pure as he came."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09431be7a30d','ch_08b9d3bd59db','text','{"text": "This crude plot of the popular tale, showing how the psychic power of the Buddha saves his devotee from the lust of a chandal girl, has been transformed by the poet into a psychological drama of intense spiritual conflict."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76eaa8fb0aac','ch_08b9d3bd59db','text','{"text": "It is not the story of a wicked girl roused to lust by the physical beauty of the monk, but of a very sensitive girl, condemned by her birth to a despised caste, who is suddenly awakened to a consciousness of her full rights as a woman by the humanity of a follower of the Buddha, who accepts water from her hand and teaches her to judge herself not by the artificial values that society attaches to the accidents of birth, but by her capacity for love and service."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d180da52a440','ch_08b9d3bd59db','text','{"text": "This is a great revelation for her, which she calls a new birth;"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab355382126a','ch_08b9d3bd59db','text','{"text": "for she is washed clean of her self-degradation and rises up a full human being with her right to love and to give. And since her own self is the most she can give, and since none is more worthy of the gift of her surrender than the bhikshu who has redeemed, or, as she puts it, created her, she yearns to offer herself to him."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa59fb96199b','ch_08b9d3bd59db','text','{"text": "But Ananda, detached from all earthly cares and immersed in his inner self, knows nothing of all this and passes by without recognising her. She is humiliated, wounded in her newly awakened sensibility, and determines to drag the monk from his pride of renunciation to the abjectness of desire for her. She has lost all religious scruple or fear, for she owed nothing to religion save her humiliation."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7f5a3924fb9e','ch_08b9d3bd59db','text','{"text": "‘A religion that insults is a false religion. Everyone united to make me conform to a creed that blinds and gags. But since that day something forbids me to conform any longer. I’m afraid of nothing now.’"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51b2a5884aa8','ch_08b9d3bd59db','text','{"text": "She forces her mother to exercise her art of magic on Ananda. She refers to it as the primeval spell, the spell of the earth, which is far more potent than the immature sadhana of the monks. The"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ca07ceeeb78','ch_08b9d3bd59db','text','{"text": "‘spell of the earth’ proves its force and Ananda is dragged to their door, his face distorted with agony and shame."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e05d8722b5e4','ch_08b9d3bd59db','text','{"text": "Seeing her redeemer, so noble and resplendent before, thus cruelly transformed and degraded, she is horrified at the selfish and destructive nature of her desire. The hero to whom she yearned to dedicate herself was not this creature, blinded by lust and darkened with shame, but Ananda of the radiant form, who had given her the gift of a new birth and had revealed her own true humanity. In remorse she curses herself and falls at his feet, begging for forgiveness."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd1a6a77a0c9','ch_08b9d3bd59db','text','{"text": "The mother revokes the spell and willingly pays the price of such revocation, which is death. The chandalika is thus redeemed for the second time, purged of the pride and egoism that had made her forget that love does not claim possession, but gives freedom. Chandalika is a tragedy of self-consciousness overreaching its limit."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_168176c80e08','ch_08b9d3bd59db','text','{"text": "Self-consciousness, up to a point, is necessary to self-development;"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_102def906be8','ch_08b9d3bd59db','text','{"text": "for, without an awareness of the dignity of one’s own role or function, one cannot give one’s best to the world. Without rights there can be no obligations, and service and virtue when forced become marks of slavery. But self-consciousness, like good wine, easily intoxicates, and it is difficult to control the dose and have just enough of it."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d9e194e810c8','ch_08b9d3bd59db','text','{"text": "Vanity and pride get the upper hand and he who clings to his rights very often trespasses on those of others. This is what happened to the heroine. Prakriti, in her eagerness to give, forgot that Ananda need not take;"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ef9c228f25e','ch_08b9d3bd59db','text','{"text": "her devotion grew so passionate that she could not make her surrender without first possessing. Yet it was inevitable that it should be so;"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eede573300d8','ch_08b9d3bd59db','text','{"text": "for a new consciousness, after ages of suppression, is overpowering and one learns restraint only after suffering. Hence the tragedy."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc28887058e7','ch_08b9d3bd59db','text','{"text": "The good mother who, so unwillingly, worked the spell to please her importunate daughter, and who so willingly revoked it to save Ananda, dies in the process. The daughter, though chastened and made wise by suffering, has paid a heavy price;"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20c98e291625','ch_08b9d3bd59db','text','{"text": "for wisdom is not happiness and renunciation is not fulfilment."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e951a6507e6f','ch_08b9d3bd59db','text','{"text": "**********"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3e395c75f35','ch_08b9d3bd59db','heading','{"level": 2, "text": "Act I"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e38b3159ddcd','ch_08b9d3bd59db','text','{"text": "MOTHER. Prakriti! Prakriti! Where has she gone? What ails the girl, I wonder? She’s never to be found in the house."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1a0e1d1460ad','ch_08b9d3bd59db','text','{"text": "PRAKRITI. Here, mother, here I am."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5624fe40cb8','ch_08b9d3bd59db','text','{"text": "MOTHER. Where? PRAKRITI."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_88c8f611ed98','ch_08b9d3bd59db','text','{"text": "Here, by the well."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a7d0c38eae6','ch_08b9d3bd59db','text','{"text": "MOTHER. Whatever will you do next? Past noon, and a blistering sun, and the earth too hot for the feet! The morning’s water was drawn long ago, and the other girls in the village have all taken their pots home. Why, the very crows on the amloki branches are gasping for heat. Yet you sit and roast in the Vaisakh sun for no reason at all! There’s a story in the Purana about how Uma left home and did penance in the burning sun—is that what you are about? PRAKRITI."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_520c86fd3bd5','ch_08b9d3bd59db','text','{"text": "Yes, mother, that’s it—I’m doing penance."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_892fa8eee6b5','ch_08b9d3bd59db','text','{"text": "MOTHER. Good heavens! And for whom?"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_468179a19d2b','ch_08b9d3bd59db','text','{"text": "PRAKRITI. For someone whose call has come to me."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c41927d8bec4','ch_08b9d3bd59db','text','{"text": "MOTHER. What call is that? PRAKRITI."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5661a4ef674','ch_08b9d3bd59db','text','{"text": "‘Give me water.’"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_84e71cf5b619','ch_08b9d3bd59db','text','{"text": "He set the words echoing in my heart."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aed78a0d9493','ch_08b9d3bd59db','text','{"text": "MOTHER. Heaven defend us! He said to you"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b3edaa89f14b','ch_08b9d3bd59db','text','{"text": "‘Give me water’? Who was it? Someone of our own caste? PRAKRITI."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_095e1eb6736e','ch_08b9d3bd59db','text','{"text": "That’s what he said—that he belonged to our kind."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_764f515a8cbf','ch_08b9d3bd59db','text','{"text": "MOTHER. You didn’t hide your caste? Did you tell him that you are a chandalini?"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2241a4fc2f41','ch_08b9d3bd59db','text','{"text": "PRAKRITI. I told him, yes. He said it wasn’t true. If the black clouds of Sravana are dubbed chandal, he said, what of it? It doesn’t change their nature, or destroy the virtue of their water. Don’t humiliate yourself, he said;"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9abe8b155462','ch_08b9d3bd59db','text','{"text": "self-humiliation is a sin, worse than self-murder. MOTHER."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e22a7d9bcf3b','ch_08b9d3bd59db','text','{"text": "What words are these from you? Have you remembered some tale of a former birth?"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c1d618a5c50','ch_08b9d3bd59db','text','{"text": "PRAKRITI. No, this is a tale of my new birth."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e43ae0ca7f78','ch_08b9d3bd59db','text','{"text": "MOTHER. You make me laugh. New birth, indeed! Since when, pray?"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ee71c82a8b5','ch_08b9d3bd59db','text','{"text": "PRAKRITI. It was the other day. The palace gong had just struck noon and it was blazing hot. I was washing that calf at the well—the one whose mother died. Then a Buddhist monk came and stood before me, in his yellow robes, and said, ‘Give me water’. My heart leaped with wonder."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_612434917ecc','ch_08b9d3bd59db','text','{"text": "I started up trembling and bowed before his feet, without touching them. His form was radiant as with the light of dawn. I said, ‘I am a chandalini, and the well-water is unclean’. He said, ‘As I am a human being, so also are you, and all water is clean and holy that cools our heat and satisfies our thirst’. For the first time in my life I heard such words, for the first time I poured water into his cupped hands—the hands of a man the very dust of whose feet I would never have dared to touch."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8785bb706172','ch_08b9d3bd59db','text','{"text": "MOTHER. O, you stupid girl, how could you be so reckless? There will be a price to pay for this madness! Don’t you know what caste you were born in?"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3f31323e7b4','ch_08b9d3bd59db','text','{"text": "PRAKRITI. Only once did he cup his hands, to take the water from mine. Such a little water, yet that water grew to a fathomless, boundless sea. In it flowed all the seven seas in one, and my caste was drowned, and my birth washed clean."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c2ff1eb3f1c4','ch_08b9d3bd59db','text','{"text": "MOTHER. Why, even the way you speak is changed. He has laid your tongue under a spell."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1028a4cc0e81','ch_08b9d3bd59db','text','{"text": "Do you understand yourself what you are saying?"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1646cb2c0296','ch_08b9d3bd59db','text','{"text": "PRAKRITI. Was there no other water, mother, in all Sravasti city? Why did he come to this well of all wells? I may truly call it my new birth! He came to give me the honour of quenching Man’s thirst. That was the mighty act of merit which he sought. Nowhere else could he have found the water which could fulfill his holy vow— no, not in any sacred stream."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d02132a05be0','ch_08b9d3bd59db','text','{"text": "He said that Janaki bathed in such water as this, at the beginning of her forest exile, and that Guhak, the chandal, drew it for her. My heart has been dancing ever since, and night and day I hear those solemn tones—"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_227d445eca96','ch_08b9d3bd59db','text','{"text": "‘Give me water, give me water’."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3a32757c39f','ch_08b9d3bd59db','text','{"text": "MOTHER. I don’t know what to make of it, child;"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5ad1eafdd17','ch_08b9d3bd59db','text','{"text": "I don’t like it. I don’t understand the magic of their spells. Today I don’t recognise your speech;"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_507cdecfc177','ch_08b9d3bd59db','text','{"text": "tomorrow, perhaps, I shall not even recognise your face. Their spells can make a changeling of the very soul itself."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1424001f4c45','ch_08b9d3bd59db','text','{"text": "PRAKRITI. All these days you have never really known me,"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a0ea2af53991','ch_08b9d3bd59db','text','{"text": "MOTHER. He who has recognised me will reveal me. And so I wait and watch."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f73e83d0f2f','ch_08b9d3bd59db','text','{"text": "The midday gong booms from the palace, the girls take up their water-pots and go home, the kite soars alone into the far sky, and I bring my pitcher and sit here at the well by the wayside."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d77f6805b7d','ch_08b9d3bd59db','text','{"text": "MOTHER. For whom do you wait?"}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ca685de87fe','ch_08b9d3bd59db','text','{"text": "PRAKRITI. For the wayfarer."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f1278540da8b','ch_08b9d3bd59db','text','{"text": "MOTHER. What wayfarer will come to you, you crazy girl?"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f29c9c1906d','ch_08b9d3bd59db','text','{"text": "PRAKRITI. That one wayfarer, mother, the one and only. In him are all who fare along the ways of all the world. Day after day goes by, yet he does not come."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f88e353c66e','ch_08b9d3bd59db','text','{"text": "Though he spoke no word, his word was given—why does he not keep his word? For my heart is become like a waterless waste, where the heat-haze quivers all day long. Its water cannot be given, for no one comes to seek it."}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_604a6d6e6fce','ch_08b9d3bd59db','text','{"text": "MOTHER. I can make nothing of your talk today;"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf2f282c0836','ch_08b9d3bd59db','text','{"text": "it’s as though you were intoxicated. Tell me plainly, what do you want?"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_93761527ff57','ch_08b9d3bd59db','text','{"text": "PRAKRITI. I want him. All unlooked for—he came, and taught me this marvellous truth, that even my service will count with the God who guides the world."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_362e835ad4ce','ch_08b9d3bd59db','text','{"text": "O words of great wonder! That I may serve, I, a flower sprung from a poison-plant! Let him raise that truth, that flower from the dust, and take it to his bosom."}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0eedb85df39b','ch_08b9d3bd59db','text','{"text": "MOTHER. Be warned, Prakriti, these men’s words are meant only to be heard, not to be practised. The filth into which an evil fate has cast you is a wall of mud that no spade in the world can break through. You are unclean;"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e53de3a2b641','ch_08b9d3bd59db','text','{"text": "beware of tainting the outside world with your unclean presence."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24fa3e14bd0a','ch_08b9d3bd59db','text','{"text": "See that you keep to your own place, narrow as it is. To stray anywhere beyond its limits is to trespass. PRAKRITI [sings]."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a05112788747','ch_08b9d3bd59db','text','{"text": "Blessed am I, says the flower, who belong to the"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_213c7fa084dc','ch_08b9d3bd59db','text','{"text": "earth."}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a4711f0ba34','ch_08b9d3bd59db','text','{"text": "For I serve you, my God, in this my lowly home."}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8184d6eb34e3','ch_08b9d3bd59db','text','{"text": "Make me forget that I am born of dust,"}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99b4259381d8','ch_08b9d3bd59db','text','{"text": "For my spirit is free from it."}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c6d57df6357','ch_08b9d3bd59db','text','{"text": "When you bend your eyes upon me my petals"}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5a39b6d7f3a6','ch_08b9d3bd59db','text','{"text": "tremble in joy;"}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd2bff64f57c','ch_08b9d3bd59db','text','{"text": "Give me a touch of your feet and make me heavenly,"}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc198ff59e8a','ch_08b9d3bd59db','text','{"text": "For the earth must offer its worship through me."}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ed6a58b88f7','ch_08b9d3bd59db','text','{"text": "MOTHER. Child, I’m beginning to understand something of what you say. You are a woman;"}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_21289103f36e','ch_08b9d3bd59db','text','{"text": "by serving you must worship, and by serving you must rule. Women alone can in a moment overstep the bounds of caste;"}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50c035e35e88','ch_08b9d3bd59db','text','{"text": "when once the curtains of destiny are drawn aside, they all stand revealed in their queenliness."}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ac29966f963','ch_08b9d3bd59db','text','{"text": "You had a good chance, you know, when the king’s son was deer-hunting and came to this very well of yours. You remember, don’t you?"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5083711d808f','ch_08b9d3bd59db','text','{"text": "PRAKRITI. Yes, I remember."}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c4f7071957b5','ch_08b9d3bd59db','text','{"text": "MOTHER. Why didn’t you go to the king’s house? He had forgotten everything in your beauty."}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17d61ed20a52','ch_08b9d3bd59db','text','{"text": "PRAKRITI. Yes, he had forgotten everything—forgotten that I was a human being. He had gone out hunting beasts;"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_518b23b868d7','ch_08b9d3bd59db','text','{"text": "he saw nothing but the beast whom he wanted to bind in chains of gold. MOTHER."}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9738e4c4795c','ch_08b9d3bd59db','text','{"text": "At least he noticed your beauty, if only as game to be hunted. As for the Bhikshu, does he see the woman in you?"}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2cabd191dc8','ch_08b9d3bd59db','text','{"text": "PRAKRITI. You won’t understand, mother, you won’t! I feel that in all these days he is the first who ever really recognised me. That is a marvellous thing. I want him, mother, I want him beyond all measure. I want to take this life of mine and lay it like a basket of flowers at his feet. It will not defile them. Let everyone marvel at my daring! I shall glory in my claim."}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_55d7282b1e26','ch_08b9d3bd59db','text','{"text": "‘I am your handmaid,’ I shall declare—for otherwise I must lie bound for ever at the whole world’s feet, a slave! MOTHER."}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd3d5767dfec','ch_08b9d3bd59db','text','{"text": "Why do you get so excited, child? You were born a slave. It’s the writ of Destiny, who can undo it?"}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f05cb686252','ch_08b9d3bd59db','text','{"text": "PRAKRITI. Fie, fie, Mother, I tell you again, don’t delude yourself with this self-humiliation—it is false, and a sin. Plenty of slaves are born of royal blood, but I am no slave;"}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ffd67531264a','ch_08b9d3bd59db','text','{"text": "plenty of chandals are born of Brahmin families, but I am no chandal."}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d0018b2e19b','ch_08b9d3bd59db','text','{"text": "MOTHER. I don’t know how to answer you, child. Very good. I’ll go to him myself, and cling to his feet."}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b77cfdb716dc','ch_08b9d3bd59db','text','{"text": "‘You accept food from every home’, I’ll say."}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_390163461e21','ch_08b9d3bd59db','text','{"text": "‘Come to our house too, and accept from our hands at least a bowl of water.’"}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_478c5f7bf34e','ch_08b9d3bd59db','text','{"text": "PRAKRITI. No, no, I’ll not call him in that way, from outside. I’ll send my call into his soul, for him to hear. I am longing to give myself;"}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d01a501995b7','ch_08b9d3bd59db','text','{"text": "it is like a pain at my heart. Who is going to accept the gift? Who will join with me in give-and-take? Will he not mingle his longings with mine, as the Ganges mingles with the black waters of the Jumna? For music springs up of itself, and he who came unbidden has left behind him a word of hope."}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44e22b713255','ch_08b9d3bd59db','text','{"text": "What is the use of one pitcher of water when the earth is cracked with drought? Will not the clouds come of themselves to fill the whole sky, the rain seek the soil by its own weight?"}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_72b679ed4064','ch_08b9d3bd59db','text','{"text": "MOTHER. What is the use of such talk? If the clouds come, they come: if they don’t, they don’t;"}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a84b3fadc4f8','ch_08b9d3bd59db','text','{"text": "if the crops wither, it’s no concern of theirs! What more can we do than sit and watch the sky?"}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_19ee1235cc43','ch_08b9d3bd59db','text','{"text": "PRAKRITI. That won’t do for me;"}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0e363e23922','ch_08b9d3bd59db','text','{"text": "I won’t simply sit and watch."}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80e907174d86','ch_08b9d3bd59db','text','{"text": "You know how to work spells;"}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1782590c1e6','ch_08b9d3bd59db','text','{"text": "let those spells be the clasp of my arms, let them drag him here."}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4ee27dc6a52','ch_08b9d3bd59db','text','{"text": "MOTHER. What are you saying, wretched girl? Is there no limit to your recklessness? It would be playing with fire! Are these bhikshus like ordinary folk? How am I to work spells on them? I shudder even to think of it."}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7995cef8b8f6','ch_08b9d3bd59db','text','{"text": "PRAKRITI. You would have worked them boldly enough on the king’s son."}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9d360e90055c','ch_08b9d3bd59db','text','{"text": "MOTHER. I’m not afraid of the king;"}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90328787af45','ch_08b9d3bd59db','text','{"text": "he might have had me impaled, perhaps. But these men—they do nothing. PRAKRITI."}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8514b262c11d','ch_08b9d3bd59db','text','{"text": "I fear nothing any longer, except to sink back again, to forget myself again, to enter again the house of darkness. That would be worse than death! Bring him here you must! I speak so boldly, of such great matters—isn’t that in itself a wonder? Who worked the wonder but he? Shall there not be further wonders? Shall he not come to my side, and sit with me on the corner of my cloth?"}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cff5382ba3dc','ch_08b9d3bd59db','text','{"text": "MOTHER. Suppose I can bring him, are you ready to pay the price? Nothing will be left to you. PRAKRITI."}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_10cc561c267f','ch_08b9d3bd59db','text','{"text": "No, nothing will be left. The burden and heritage of birth after birth—nothing will remain. Only let me bring it all to an end, then I shall live indeed. That’s why I need him. Nothing will be left me. I have waited for age after age, and now in this birth my life shall be fulfilled. My mind is saying it over and over again— fulfilled! It was for this that I heard those wonderful words, ‘Give me water’. Today I know that even I can give. Everyone else had hidden the truth from me."}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d79e511d1908','ch_08b9d3bd59db','text','{"text": "I sit and watch for his coming today to give, to give, to give everything I have."}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9884dd97eacb','ch_08b9d3bd59db','text','{"text": "MOTHER. Have you no respect for religion?"}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_01baf655c6e5','ch_08b9d3bd59db','text','{"text": "PRAKRITI. How can I say? I respect him who respects me. A religion that insults is a false religion. Everyone united to make me conform to a creed that blinds and gags. But since that day something forbids me to conform any longer. I’m afraid of nothing now. Chant your spells, bring the Bhikshu to the side of the chandalini."}',116);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6bcd6cb2a81f','ch_08b9d3bd59db','text','{"text": "I myself shall do him honour—no one else can honour him so well."}',117);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8891770cda58','ch_08b9d3bd59db','text','{"text": "MOTHER. Aren’t you afraid of bringing a curse upon yourself?"}',118);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c57317bba42','ch_08b9d3bd59db','text','{"text": "PRAKRITI. There has been a curse upon me all my life. Poison kills poison, they say—so one curse another. Not another word, mother, not another word. Begin your spells, I cannot bear any more delay."}',119);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_beb2ff313b71','ch_08b9d3bd59db','text','{"text": "MOTHER. Very well, then. What is his name?"}',120);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f123d22e833','ch_08b9d3bd59db','text','{"text": "PRAKRITI. His name is Ananda."}',121);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca4a11caa7b6','ch_08b9d3bd59db','text','{"text": "MOTHER. Ananda? The disciple of the Lord Buddha?"}',122);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d6f6e88986f','ch_08b9d3bd59db','text','{"text": "PRAKRITI. Yes, it is he. MOTHER."}',123);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9321e38b7800','ch_08b9d3bd59db','text','{"text": "O my heart’s treasure, you are the apple of my eye—but it’s a great wrong I’m putting my hand to at your bidding!"}',124);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a64175a64689','ch_08b9d3bd59db','text','{"text": "PRAKRITI. What wrong? I will bring to my side the one who brings all near. What crime is there in that?"}',125);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98091b5aead7','ch_08b9d3bd59db','text','{"text": "MOTHER. They draw men by the strength of their virtue. We drag them with spells, as beasts are dragged in a noose. We only churn up the mud."}',126);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8eec8e3776f0','ch_08b9d3bd59db','text','{"text": "PRAKRITI. So much the better. Without the churning, how can the well be cleansed? MOTHER (apostrophising Ananda]."}',127);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0aa462a7426','ch_08b9d3bd59db','text','{"text": "O thou exalted one, thy power to forgive is greater far than my power to offend. I am about to do thee dishonour, yet I bow before thee: accept my obeisance, Lord."}',128);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_21a9492905c6','ch_08b9d3bd59db','text','{"text": "PRAKRITI. What are you afraid of, mother? Yours are the lips I use, but it’s I who chant the spells. If my longing can draw him here, and if that is a crime, then I will commit the crime. I care nothing for a code which holds only punishment, and no comfort."}',129);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3ed75e4165c','ch_08b9d3bd59db','text','{"text": "MOTHER. You are immensely daring,"}',130);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0289a90507a5','ch_08b9d3bd59db','text','{"text": "PRAKRITI. PRAKRITI."}',131);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd9bde3ef2e0','ch_08b9d3bd59db','text','{"text": "You call me daring? Think of the might of his daring! How simply he spoke the words which no one had ever dared to say to me before!"}',132);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1af75089de8d','ch_08b9d3bd59db','text','{"text": "‘Give me water.’"}',133);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_81ede0fd9cbc','ch_08b9d3bd59db','text','{"text": "Such little words, yet as mighty as flame—they filled all my days with light, they rolled away the black stone whose weight so long had stopped the fountains of my heart, and the joy bubbled forth. Your fear is an illusion, for you did not see him."}',134);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7918482b781c','ch_08b9d3bd59db','text','{"text": "All morning he had begged alms in Sravasti city;"}',135);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_89d0ef51f391','ch_08b9d3bd59db','text','{"text": "when his task was done he came, across the common, past the burning-ground, along the river bank, with the hot sun on his head— and all for what? To say that one word, ‘Give me water’, even to a girl like me. O, it is too wonderful! Whence did such grace, such love, come down—upon a wretch unworthy beyond all others? What can I fear now?"}',136);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50c4f0e1a5b4','ch_08b9d3bd59db','text','{"text": "‘Give me water’—yes, the water which has filled all my days to overflowing, which I must needs give or die!"}',137);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_efacaa6c89b6','ch_08b9d3bd59db','text','{"text": "‘Give me water.’"}',138);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_03321d09121e','ch_08b9d3bd59db','text','{"text": "In a moment I knew that I had water, inexhaustible water;"}',139);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c4dd92b1e24e','ch_08b9d3bd59db','text','{"text": "to whom should I tell my joy? And so I call him night and day. If he does not hear, fear not;"}',140);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09b4a23d0aaf','ch_08b9d3bd59db','text','{"text": "chant your spell, he will be able to bear it."}',141);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd5e5113386f','ch_08b9d3bd59db','text','{"text": "MOTHER. Look, Prakriti, some men in yellow robes are going by the road across the common."}',142);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ec8c8a0b4ac','ch_08b9d3bd59db','text','{"text": "PRAKRITI. So they are;"}',143);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7c1b4968f51','ch_08b9d3bd59db','text','{"text": "all the monks of the sangha, I see. Don’t you hear them chanting? [The chant is heard in the distance.]"}',144);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8ecbf49690e1','ch_08b9d3bd59db','text','{"text": "To the most pure Buddha, mighty ocean of mercy, Seer of knowledge absolute, pure, supreme, Of the world’s sin and suffering the Destroyer— Solemnly to the Buddha I bow in homage."}',145);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1bad95eab9f6','ch_08b9d3bd59db','text','{"text": "PRAKRITI. O Mother, see, he is going, there ahead of them all. He never turned his head or looked towards this well. He could so easily have said"}',146);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_84f528c678f8','ch_08b9d3bd59db','text','{"text": "‘Give me water’ once more before he went."}',147);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2bd4960b6ed5','ch_08b9d3bd59db','text','{"text": "I thought he would never be able to cast me aside—me, his own handiwork, his new creation. [She flings herself down and beats her head on the ground.] This dust, this dust is your place! O wretched woman, who raised you to bloom for a moment in the light? Fallen in the end into this same dust, you must mingle for all time with this same dust, trampled underfoot by all who travel the road."}',148);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b55f42f13df7','ch_08b9d3bd59db','text','{"text": "MOTHER. Child, dear child, forget it, forget it all."}',149);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49942f31e0cd','ch_08b9d3bd59db','text','{"text": "They have broken your momentary dream, and they are going away—let them go, let them go. When a thing is not meant to last, the quicker it goes the better. PRAKRITI."}',150);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6fb18a7cfb6f','ch_08b9d3bd59db','text','{"text": "Day after day this cry of desire, moment by moment this burden of shame;"}',151);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b1128df38a1','ch_08b9d3bd59db','text','{"text": "this prisoned bird in my breast, that beats its wings unto death—do you call it a dream? A dream, is it, that sinks its sharp teeth into the fibres of my heart, and will not loosen its grip? And they, who have no ties, no joy or sorrow, no earthly burden, who float along like the clouds in autumn—are only they awake, are only they real?"}',152);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abf9d1378b87','ch_08b9d3bd59db','text','{"text": "MOTHER. O Prakriti, I cannot bear to see you suffer so."}',153);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0adb9baf38fb','ch_08b9d3bd59db','text','{"text": "Come, get up, I will chant the spells, I will bring him. All along the dusty road I will bring him."}',154);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0afa876c0657','ch_08b9d3bd59db','text','{"text": "‘I want nothing,’ he says in his pride. I’ll break that pride and make him come, running and crying"}',155);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7bf5f72bc326','ch_08b9d3bd59db','text','{"text": "‘I want, I want’."}',156);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e24527de7ff','ch_08b9d3bd59db','text','{"text": "PRAKRITI. Mother, yours is an ancient spell, as old as life itself. Their mantras are raw things of yesterday. These men can never be a match for you—the knot of their mantras will be loosened under the stress of your spells. He is bound to be defeated."}',157);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_304056eb179a','ch_08b9d3bd59db','text','{"text": "MOTHER. Where are they going?"}',158);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_522ef5e7ed4c','ch_08b9d3bd59db','text','{"text": "PRAKRITI. Going? They are going nowhere! During the rains they remain four months in penance and fasting, and then they are off again, how should I know where? That’s what they call being awake! MOTHER."}',159);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c4bd366289a','ch_08b9d3bd59db','text','{"text": "Then why are you talking of spells, you crazy thing? He is going so far—how am I to bring him back?"}',160);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc8af43283d8','ch_08b9d3bd59db','text','{"text": "PRAKRITI. No matter where he goes, you must bring him back. Distance is nothing for your spells. He showed no pity to me, I shall show none to him. Chant your spell, your cruellest spells;"}',161);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71a500a9784c','ch_08b9d3bd59db','text','{"text": "wind them about his mind till every coil bites deep. Wherever he goes, he shall never escape me!"}',162);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32cfbc48dea3','ch_08b9d3bd59db','text','{"text": "MOTHER. You need not fear, it is not beyond our powers."}',163);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da0b80675b31','ch_08b9d3bd59db','text','{"text": "I will give you this magic mirror;"}',164);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02b88ee28bed','ch_08b9d3bd59db','text','{"text": "you shall take it in your hand and dance. His shadow will fall on the glass, and in it you will see what happens to him and how near he has come."}',165);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_12dde22423e3','ch_08b9d3bd59db','text','{"text": "PRAKRITI. See there the clouds, the storm clouds, gathered in the west. The spell will work, mother, it will work. His dry meditations will scatter like withered leaves;"}',166);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a59b5df2659c','ch_08b9d3bd59db','text','{"text": "his lamp will go out, his path will be lost in darkness."}',167);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f94a5ead97ab','ch_08b9d3bd59db','text','{"text": "As a bird at dead of night falls fluttering into the dark courtyard, its nest broken in the storm, even so shall he be whirled helpless to our doors. The thunder throbs in my heart, my mind is filled with the lightning flash, the waves foam high in an ocean whose shore I cannot see."}',168);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_69e761e91378','ch_08b9d3bd59db','text','{"text": "MOTHER. Think well even now, lest sudden terror spring upon you with the work half done. Can you endure to the end? When the spell has reached its height, it would cost me my life to undo it."}',169);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_365df9ec82da','ch_08b9d3bd59db','text','{"text": "Remember that this fire will not die down till all that will burn is burnt to ashes."}',170);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b5298fb4d16c','ch_08b9d3bd59db','text','{"text": "PRAKRITI. For whom are you afraid? Is he a common man? Nothing will hurt him. Let him come, let him tread the path of fire to the very end. Before me I see in vision the night of doom, the storm of union, the bliss of the breaking of worlds."}',171);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_93f7f59728f8','ch_08b9d3bd59db','text','{"text": "*****************"}',172);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6e47dc72a100','ch_08b9d3bd59db','heading','{"level": 2, "text": "Act Ii"}',173);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_83c39f6fff08','ch_08b9d3bd59db','text','{"text": "[Fifteen days have passed.]"}',174);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5273b0ced6f1','ch_08b9d3bd59db','text','{"text": "PRAKRITI. O, my heart will break. I will not look in the mirror, I cannot bear it. Such agony, so furious a storm."}',175);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e9f21d10afab','ch_08b9d3bd59db','text','{"text": "Must the king of the forest crash to the dust at last, his cloud-kissing glory broken?"}',176);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75ac52e23904','ch_08b9d3bd59db','text','{"text": "MOTHER. Even now, child, if you say so, I will try to undo the spell. Let the cords of my life be torn apart and my life-blood spent, if only that great soul can be saved."}',177);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7823968f1707','ch_08b9d3bd59db','text','{"text": "PRAKRITI. That is best,"}',178);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b90bd7f94e4','ch_08b9d3bd59db','text','{"text": "MOTHER. Let the spells stop, I’ll have no more..."}',179);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32a958b6e2ba','ch_08b9d3bd59db','text','{"text": "no, no, don’t! Go on—the end of the path is so near! Make him come to the very end, make him come right to my bosom! After that I will blot out all his suffering, emptying my whole world at his feet. At dead of night the wayfarer will come, and I will kindle the lamps for him in the flames of my burning heart. Deep within are springs of nectar, where he shall bathe and anoint his weary, hot and wounded limbs. Once again he shall say ‘Give me water’—water from the ocean of my heart. Yes, that day will come—go on, go on with the spell."}',180);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53b9364bd88e','ch_08b9d3bd59db','text','{"text": "In my own sorrow"}',181);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_909278b4ebd3','ch_08b9d3bd59db','text','{"text": "Will I quit thy sorrow;"}',182);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00398f478373','ch_08b9d3bd59db','text','{"text": "Thy hurt will I bathe"}',183);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ae66cd32fce0','ch_08b9d3bd59db','text','{"text": "In the deep waters of my pain’s immensity."}',184);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d8a4a21bf8f','ch_08b9d3bd59db','text','{"text": "My world will I give to the flames,"}',185);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f2de11fd4387','ch_08b9d3bd59db','text','{"text": "And my blackened shame shall be cleansed."}',186);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1073a9b3f3a','ch_08b9d3bd59db','text','{"text": "My mortal pain will I offer as gift at thy feet."}',187);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_228c327f417e','ch_08b9d3bd59db','text','{"text": "MOTHER. I never knew it would take so long. My spells have no more power, child;"}',188);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f8f62e400ae9','ch_08b9d3bd59db','text','{"text": "there is no breath left in my body."}',189);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_11eea2521733','ch_08b9d3bd59db','text','{"text": "PRAKRITI. Don’t be afraid, mother;"}',190);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_efade41afe1e','ch_08b9d3bd59db','text','{"text": "hold out a little longer, only a little. It will not be long now."}',191);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_781a99ee664b','ch_08b9d3bd59db','text','{"text": "MOTHER. The month of Ashad is here, and their four months’ fast is at hand. PRAKRITl. They are gone to Vaisali, to the monastery there."}',192);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2f702e6733a','ch_08b9d3bd59db','text','{"text": "MOTHER. How pitiless you are! That is so far away. PRAKRITI."}',193);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc7f9506003b','ch_08b9d3bd59db','text','{"text": "Not very far;"}',194);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b3d178f76fa8','ch_08b9d3bd59db','text','{"text": "seven days’ journey. Fifteen days have already passed. His seat of meditation has been shaken at last. He is coming, he is coming! All that once lay so far away, so many million miles away, beyond the very sun and moon, immeasurably beyond the reach of my arms—it is coming, nearer and nearer! He is coming, and my heart is rocked as by an earthquake."}',195);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d1266ab25b14','ch_08b9d3bd59db','text','{"text": "MOTHER. I have worked the spell through all its stages— such force might have brought down Indra of the thunderbolt himself."}',196);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d794ab5ed94a','ch_08b9d3bd59db','text','{"text": "And yet he does not come. It is a fight to the death indeed. What did you see in the mirror?"}',197);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3365aa52557c','ch_08b9d3bd59db','text','{"text": "PRAKRITI. At first I saw a mist covering the whole sky, deathly pale like the weary gods after their struggle with the demons, Through rifts in the mist there glimmered fire. After that the mist gathered itself up into red and angry clusters, like swollen, festering sores. That day passed. The next day I looked, and all the background was a deep black cloud, with lightning playing across it."}',198);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6aaf956ebf26','ch_08b9d3bd59db','text','{"text": "Before it he was standing, all his limbs fenced with flame. My blood ran cold, and I rushed to tell you to stop your spells at once— but I found you in deep trace, sitting like a log, breathing hardly, and unconscious. It seemed as though a fierce fire burned in you, and your fire was a flaming serpent that hissed and struck in deadly duel at the fire that wrapped him round. I came back and took up the mirror;"}',199);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b19eb4e9d005','ch_08b9d3bd59db','text','{"text": "the light was gone— only torment, unfathomable torment, was in his face. MOTHER."}',200);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f660b1a1d444','ch_08b9d3bd59db','text','{"text": "Yet that did not kill you? The fire of his suffering burnt into my soul, till I thought I could bear no more."}',201);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d5e20c146d8','ch_08b9d3bd59db','text','{"text": "PRAKRITI. It seemed that the tortured form I saw was not his only, but mine too;"}',202);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bcbd3f456818','ch_08b9d3bd59db','text','{"text": "it belonged to us both. In those awful fires the gold and the copper had been melted and fused."}',203);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74422000b7c8','ch_08b9d3bd59db','text','{"text": "MOTHER. And you felt no fear?"}',204);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e0999dbdc79d','ch_08b9d3bd59db','text','{"text": "PRAKRITI. Something far greater than fear."}',205);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_37a6fc8b5a71','ch_08b9d3bd59db','text','{"text": "I beheld the God of Creation, more terrible far than the God of Destruction, lashing the flames to work His purposes, while they writhed and roared in anger. What lay at his feet in the casket of the seven elements—Life or Death? My mind swelled with a joy hard to name— joy in the tremendous detachment of new creation, free of care or fear, of pity or sorrow. Creation breaking, burning and melting among the sparks of the elemental fires. I could not keep still."}',206);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c40cd35dd2a4','ch_08b9d3bd59db','text','{"text": "My whole soul and body danced and danced together, as the pointed flames dance in the fire."}',207);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_088db94b89c7','ch_08b9d3bd59db','text','{"text": "MOTHER. And how did your Bhikshu appear?"}',208);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_36d1f252d111','ch_08b9d3bd59db','text','{"text": "PRAKRITI. His eyes were fixed motionless upon the distance, like stars in the evening twilight. I longed to escape from myself far into boundless space."}',209);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d4b02f3f5b1','ch_08b9d3bd59db','text','{"text": "MOTHER. When you danced before the mirror, he saw you?"}',210);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dfa5a4f86d8b','ch_08b9d3bd59db','text','{"text": "PRAKRITI. Fie upon it, how I am shamed! Again and again his eyes grew red, as though he were about to curse."}',211);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d4cec59cb2de','ch_08b9d3bd59db','text','{"text": "Again and again he trampled down the glowing fires of anger, and at last his anger turned upon himself, quivering, like a spear, and pierced his own breast."}',212);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80b9e3a6dec2','ch_08b9d3bd59db','text','{"text": "MOTHER. And you bore all this?"}',213);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b7f6285b48b','ch_08b9d3bd59db','text','{"text": "PRAKRITI. I was amazed. I, this I, this daughter of yours, this nobody from nowhere—his suffering and mine are one today! What holy fire of creation could have wrought such a union? Who could dream of so great a thing?"}',214);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b5277da7beb0','ch_08b9d3bd59db','text','{"text": "MOTHER. When shall his turmoil be stilled? PRAKRITl. When my suffering is stilled."}',215);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74225f865732','ch_08b9d3bd59db','text','{"text": "How can he attain his mukti until I attain mine?"}',216);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1a4d2fd24a4f','ch_08b9d3bd59db','text','{"text": "MOTHER. When did you last look into your mirror? PRAKRITl. Yesterday evening. He had passed through the lion-gate of Vaisali some days before, at dead of night—seemingly in secret, unknown to the monks. After that I had sometimes seen him ferried across rivers or on difficult mountain passes. I had seen the evening fall, and him alone on the wide commons, or on the dark forest paths at dead of night."}',217);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_afad01c0c773','ch_08b9d3bd59db','text','{"text": "As the days went by, he fell more deeply under the spell and became heedless of everything, all the conflict with his own soul at an end. His face was mazed, his body slack, his eyes fixed in an unseeing stare, as though for him there were neither true nor false, good nor evil—only a blind and thoughtless compulsion, with no meaning in it."}',218);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_251dd32c8121','ch_08b9d3bd59db','text','{"text": "MOTHER. Can you guess how far he has come today?"}',219);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98c9f293a4fa','ch_08b9d3bd59db','text','{"text": "PRAKRITI. I saw him yesterday at Patal village on the river Upali."}',220);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5904a9a364a','ch_08b9d3bd59db','text','{"text": "The river was turbulent with new rains;"}',221);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b3ea80290459','ch_08b9d3bd59db','text','{"text": "there was an old peepul tree by the ghat, fireflies shining in its branches, and under it a lichened altar. As he reached it he gave a sudden start and stood still. It was a place he had known for a long time;"}',222);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_12a50e3b011d','ch_08b9d3bd59db','text','{"text": "I have heard that one day the Lord Buddha preached there to King Suprabhas. He sat down and covered his eyes with his hands—I felt that his dream-spell might break at any moment. I flung away the mirror, for I was afraid of what I might see."}',223);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6390bcc55dfd','ch_08b9d3bd59db','text','{"text": "The whole day has passed since then, and torn between hope and fear I have sat on, not daring to know. Now it is dark again;"}',224);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db70c9edf528','ch_08b9d3bd59db','text','{"text": "on the road goes the watchman calling the hour, it must be an hour past midnight. O mother, the time is short, so short;"}',225);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71117e897f3c','ch_08b9d3bd59db','text','{"text": "don’t let this night be wasted;"}',226);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d4fc7aa6a25a','ch_08b9d3bd59db','text','{"text": "put the whole of your strength into the spell."}',227);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d95b2e979034','ch_08b9d3bd59db','text','{"text": "MOTHER. Child, I can do no more;"}',228);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d6d762f7759','ch_08b9d3bd59db','text','{"text": "the spell is weakening, I am failing body and soul. PRAKRITl."}',229);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7f558458842e','ch_08b9d3bd59db','text','{"text": "It mustn’t weaken now—don’t give up now! Maybe he has turned his face away, maybe the chain we have bound on him is stretched to the uttermost, and will not hold. What if he escapes now, away from this birth of mine, and I can never reach him again? Then it will be my turn to dream, to return to the illusion of a chandal birth. I will never endure that mockery again."}',230);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_81c02b9a2f99','ch_08b9d3bd59db','text','{"text": "I beseech you, mother, put out your whole strength once only;"}',231);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e939b42373f9','ch_08b9d3bd59db','text','{"text": "set in motion your spell of the primeval earth, and shake the complacent heaven of the virtuous."}',232);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7df9b05369c','ch_08b9d3bd59db','text','{"text": "MOTHER. Have you made ready as I told you?"}',233);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04537180c987','ch_08b9d3bd59db','text','{"text": "PRAKRITI. Yes. Yesterday was the second night of the waxing moon. I bathed in the river Gambhira, plunging below the water. Here in the courtyard I drew a circle, with rice and pomegranate blossoms, vermilion and the seven jewels."}',234);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_62ea51cbec10','ch_08b9d3bd59db','text','{"text": "I planted the flags of yellow cloth, I placed sandal-paste and garlands on a brass tray, I lit the lamps. After my bath I put on a cloth, green like the tender rice shoots, and a scarf like the champak flower. I sat with my face to the East. All night long I have contemplated his image. On my left arm I have tied the bracelet of thread—sixteen strands of golden yellow bound in sixteen knots."}',235);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80804581cfed','ch_08b9d3bd59db','text','{"text": "MOTHER. Then dance round the circle in your dance of invocation, while I work my spells before the altar."}',236);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c27fe562874b','ch_08b9d3bd59db','text','{"text": "[Prakriti dances and sings.] Now, Prakriti, take your mirror and look. See, a dark shadow has fallen over the altar. My heart is bursting and I can do no more. Look into the mirror—how long will it be now? PRAKRITl. No, I will not look again, I will listen—listen in my inmost being. If he reveals himself I shall see him before me. Bear up a little longer, mother, he will surely, surely reveal himself."}',237);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1a71975fc97','ch_08b9d3bd59db','text','{"text": "Hark! Hark to the sudden storm, the storm of his coming! The earth quivers beneath his tread, and my heart throbs."}',238);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6da57867ac2e','ch_08b9d3bd59db','text','{"text": "MOTHER. It brings a curse for you, unhappy girl. As for me, it means surely death—the fibres of my being are shattered."}',239);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b27345bc773','ch_08b9d3bd59db','text','{"text": "PRAKRITI. No curse, it brings no curse, it brings the gift of my new birth. The thunderbolt hammers open the Lion-gates of Death;"}',240);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8e46869c168','ch_08b9d3bd59db','text','{"text": "the door breaks, the walls crumble, the falsehood of this birth of mine is shattered."}',241);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbfec1ba4d6a','ch_08b9d3bd59db','text','{"text": "Tremors of fear shake my mind, but rhythms of joy enrapture my soul. My All-destroyer, my All-in-all, you have come! I will enthrone you on the summit of all my dishonour, and build your royal seat of my shame, my fear and my joy."}',242);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0aa0e0d519b','ch_08b9d3bd59db','text','{"text": "MOTHER. My time is near, I can do no more. Look in the mirror at once."}',243);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_13b2139ec8de','ch_08b9d3bd59db','text','{"text": "PRAKRITI. Mother, I’m afraid."}',244);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ffa88fa084e1','ch_08b9d3bd59db','text','{"text": "His journey is almost at an end, and what then? What then for him? Only myself, my wretched self? Nothing else? Only this to repay the long and cruel pain? Nothing but me? Only this at the end of the weary, difficult road?—only me?"}',245);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db6528a64953','ch_08b9d3bd59db','text','{"text": "MOTHER. Have pity, cruel girl, I can bear no more. Look in the mirror, quick! PRAKRITI (looks in the mirror and flings it away)."}',246);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_84d0980db70c','ch_08b9d3bd59db','text','{"text": "O mother, mother, stop! Undo the spell now—at once—undo it! What have you done? What have you done? O wicked, wicked deed!—better have died. What a sight to see! Where is the light and radiance, the shining purity, the heavenly glow? How worn, how faded, has he come to my door! Bearing his self’s defeat as a heavy burden, he comes with drooping head... Away with all this, away with it! [She kicks the paraphernalia of magic to pieces.]"}',247);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8df06a57d624','ch_08b9d3bd59db','text','{"text": "Prakriti, Prakriti, if in truth you are no chandalini, offer no insult to the heroic. Victory, victory to him! [Enter Ananda.] O Lord, you have come to give me deliverance, therefore have you known this torment. Forgive me, forgive me. Let your feet spurn afar the endless reproach of my birth. I have dragged you down to earth, how else could you raise me to your heaven? O pure one, the dust has soiled your feet, but they have not been soiled in vain."}',248);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cacc1c82132b','ch_08b9d3bd59db','text','{"text": "The veil of my illusion shall fall upon them, and wipe away the dust. Victory, victory to thee, O Lord!"}',249);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_883e09a9d498','ch_08b9d3bd59db','text','{"text": "MOTHER. Victory to thee, O Lord. My sins and my life lie together at thy feet, and my days end here, in the haven of thy forgiveness. [She dies.] ANANDA [chanting]."}',250);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a4b60058cd21','ch_08b9d3bd59db','text','{"text": "Buddho Susuddho karuna mahannvo"}',251);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5387c5c3e5a6','ch_08b9d3bd59db','text','{"text": "Yoccanta suddhabbara-gnana locano"}',252);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ae91c948a9b4','ch_08b9d3bd59db','text','{"text": "Lokassa papupakilesa ghatako"}',253);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_57b95844f85b','ch_08b9d3bd59db','text','{"text": "Vandami Buddham ahamadarena tam."}',254);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ec25087be28','ch_08b9d3bd59db','text','{"text": "To the most pure Buddha, mighty ocean of mercy,"}',255);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c80c688eb887','ch_08b9d3bd59db','text','{"text": "Seer of knowledge absolute, pure, supreme,"}',256);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a381e4ac877','ch_08b9d3bd59db','text','{"text": "Of the world’s sin and suffering the Destroyer—"}',257);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d281fabccbe8','ch_08b9d3bd59db','text','{"text": "Solemnly to the Buddha I bow in homage."}',258);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_31140ddd1775','ch_08b9d3bd59db','list','{"ordered": false, "items": ["Rabindranath Tagore"]}',259);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_21557e1d6827','ch_08b9d3bd59db','text','{"text": "About the Author"}',260);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d767c1bb384c','ch_08b9d3bd59db','text','{"text": "Rabindranath Tagore was a poet, novelist, shortstory writer and dramatist. He was awarded the Nobel Prize for Literature in 1913. Tagore’s interest in drama was fostered while he was a boy, for his family enjoyed writing and staging plays."}',261);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_19aaa7ebd104','ch_08b9d3bd59db','text','{"text": "The music in his plays is instrumental in bringing out the delicate display of emotion around an idea. The central interest in his plays is the unfolding of character;"}',262);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b905d756caf','ch_08b9d3bd59db','text','{"text": "of the opening up of the soul to enlightenment of some sort."}',263);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_0c5d4e7ad99e','bk_ncert_english','12-21-broken-images','12.21 Broken Images',NULL,'public',93,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_56db79427cef','ch_0c5d4e7ad99e','text','{"text": "….. for you know only"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_10527438b6fc','ch_0c5d4e7ad99e','text','{"text": "A heap of broken images, where the sun beats,"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0376188750f','ch_0c5d4e7ad99e','text','{"text": "And the dead tree gives no shelter,….."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f75ead953e84','ch_0c5d4e7ad99e','heading','{"level": 2, "text": "T. S. Eliot"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9fe5faac0c62','ch_0c5d4e7ad99e','heading','{"level": 2, "text": "The Waste Land"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_edeff2c7cf00','ch_0c5d4e7ad99e','text','{"text": "The interior of a television studio. A big plasma screen hangs on one side, big enough for a close-up on it to be seen clearly by the audience. On the other side of the stage, a chair and a typically"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6942642ef26a','ch_0c5d4e7ad99e','text','{"text": "‘telly’ table—strong, wide, semi-circular. At the back of the stage are several television sets, with screens of varying sizes. A small red bulb glows above the table, high enough not to appear on the television screen. Manjula Nayak walks in. She is in her mid-thirties/ forties, and has a confident stride. She is wearing a lapel mike. It is immediately evident that she is at home in broadcasting studios. She looks around."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f153a470b55f','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Nice, very nice. Neat! (She goes and sits on the chair."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dcb6f3a3a34b','ch_0c5d4e7ad99e','text','{"text": "Adjusts the earpiece.) But where is the camera? (Listens to the reply.) Ah! I see. New technology. Isn’t it scary? The rate of obsolescence? (Listens.) Of course I have. In London. And in Toronto. But when you think of Indian television studios, you always imagine them cluttered. Lots of men and women scurrying about, shouting orders. Elephantine lights. Headphones. Cameras. You know what I mean. But here... I mean, it’s all so spartan... I know. But a bit lonely too. Like a sound studio..."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_28864fa020b8','ch_0c5d4e7ad99e','text','{"text": "All right. All right... No camera. I just look ahead and speak to an invisible audience in front of me... Direct. Fine. Fine... I can hear you. Clearly. Voice test?..."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c9c2cf6e1ad','ch_0c5d4e7ad99e','text','{"text": "‘Testing, Testing, One, Two, Three, Four, Five, Hello, Hello!’ Shall I tap on the mike? (Laughs.)"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3490f697959f','ch_0c5d4e7ad99e','text','{"text": "My speech will last exactly ten minutes. I have timed it... No, I won’t read."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97412d0912b2','ch_0c5d4e7ad99e','text','{"text": "‘Look ahead and speak!’ Good..."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e2c49b2abf73','ch_0c5d4e7ad99e','text','{"text": "But that may take a little longer. A couple of minutes... if I don’t fumble too much. (Giggles.) The yellow light?... Okay, okay, ready, fine! (She mouths"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e9835fab8d05','ch_0c5d4e7ad99e','text','{"text": "‘Ten’ to ‘Zero’ silently, emphasising each count with her forefinger. At the stroke of ten, the light turns yellow. The Announcer appears on the big plasma screen. The other screens remain blank till the last few minutes of the play.) ANNOUNCER: Good evening. This is a proud evening for the Shree-TV channel. For tonight we bring to you Ms Manjula Nayak. Many of you will know her as a renowned Kannada short-story writer. Until a year ago, she was a lecturer in English in Bangalore."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db2e6c1a4ac8','ch_0c5d4e7ad99e','text','{"text": "But she had been writing in Kannada. Not unusual, as you know. It’s amazing how many of our Kannada writers are lecturers in English: from the earliest days. B. M. Shree, Gokak, Adiga. Even modern ones. Lankesh, Shantinath, Anantha Murthy. And of course there is A. K. Ramanujan, who was equally at home in both languages. But last year Mrs Nayak stunned the world—yes, I mean, the world— by writing a novel. Her first novel. In English! The River Has No Memories."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc0472ea493a','ch_0c5d4e7ad99e','text','{"text": "The advance she received from her British publishers made headlines, here and in the West. And then the novel turned out to be a bestseller all over the world. Our heartiest congratulations to Mrs Nayak. This evening we broadcast a Kannada telefilm based on this remarkable novel. The film will begin in exactly ten minutes. And we have with us in the studio Ms Nayak herself, who has graciously agreed to address our viewers about her work."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20e92f9bb123','ch_0c5d4e7ad99e','text','{"text": "Ladies and gentlemen, welcome the Literary Phenomenon of the Decade, Mrs Manjula Nayak. (Applause on the sound track. The light turns green. The Announcer disappears and Manjula’s image appears in his place. She speaks.)"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c50826d176ca','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Namaskara. I am Manjula Nayak. I must mention that officially I am Mrs Manjula Murty, but my creative self continues to be Manjula Nayak. There are some areas in which we must not let marriage intrude too much. (Laughter.)"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ee488e9d292e','ch_0c5d4e7ad99e','text','{"text": "Talking about one’s work is a very difficult task. So let me find an easy way out. Let me just take up two questions I constantly come across. They seem to bother everyone—here, abroad. I’ll answer them to the best of my ability within the short time at my disposal and shut up. Actually, that’s what a writer should do, shouldn’t she?—Write and shut up! (Laughs.) The first question—you have probably guessed it already."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1c3ef86ddb2e','ch_0c5d4e7ad99e','text','{"text": "After having written in Kannada all your life, why did you choose—suddenly—to write in English? Do you see yourself as a Kannada writer or an English writer? What audience do you write for? And variations on that theme. Actually, let me confess. If I had foreseen how many people I would upset by writing in English—I really would not have committed that folly."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74d1ec482105','ch_0c5d4e7ad99e','text','{"text": "Intellectuals whom I respected, writers who were gurus to me, friends who I thought would pat me on my back and share my delight—they are all suddenly breathing fire. How dare I write in English and betray Kannada! (Laughs.) Betray! The answer is simple;"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_56c705bc38fd','ch_0c5d4e7ad99e','text','{"text": "if there was betrayal, it was not a matter of conscious choice. I wrote the novel in English because it burst out in English. It surprised even me. I couldn’t understand why it was all coming out in English. But it did. That’s all."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_34f7d68ae7fc','ch_0c5d4e7ad99e','text','{"text": "There is no other explanation. What baffles me—actually, let me confess, hurts me— is why our intellectuals can’t grasp this simple fact! I have been accused of writing for foreign readers. Accused! As though I had committed a crime. A writer seeks audiences where she or he can find them! My British publishers said to me:"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_57a3696c4658','ch_0c5d4e7ad99e','text','{"text": "‘We like your book because it’s so Indian."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_47a6c42f9685','ch_0c5d4e7ad99e','text','{"text": "We receive any number of manuscripts from India but they are all written with the western reader in view. Your novel has the genuine Indian feel!’ (Laughs.) But who listens here? A pundit for instance has stated that no Indian writer can express herself—or himself— honestly in English."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5977caa6bb5f','ch_0c5d4e7ad99e','text','{"text": "‘For Indian writers, English is a medium of dishonesty.’"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9091d5f2bee2','ch_0c5d4e7ad99e','text','{"text": "Of course, one could also ask how many Kannada writers are honest in what they write—in Kannada. But if you did that, you would be immediately condemned as a traitor. You can’t win! Recently the President of the Central Sahitya Akademi—the National Academy of the Letters— (who shall remain nameless) declared that Indians who write in English do so in order to make money. That by writing in English they confess their complicity in the global consumer market economy. He of course spoke in English."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f93c172ea16','ch_0c5d4e7ad99e','text','{"text": "Speaking in English, as you know, gives you the authority to make oracular pronouncements on Indian literatures and languages. But my response to the charge that I write in English for money would be: Why not? Isn’t that a good enough reason? Would you like to see what royalties I earned when I wrote in Kannada? (Pause.) Yet the accusation hides—or perhaps reveals—a grim anxiety. As is clear from the dictum of the President of the Akademi, what is at issue is not Creativity but Money."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3094c1d0f7de','ch_0c5d4e7ad99e','text','{"text": "What hits everyone in the eye is the money a writer in English can earn. The advance I received for my novel—the advance only, mind you—helped me resign my job and concentrate on writing. Of course it is a cause for jealousy. Having struggled in Kannada, I can understand that. A Kannada proverb says:"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5ed30b425d8','ch_0c5d4e7ad99e','text','{"text": "‘A response is good. But a meaningful response is better.’"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d9ede7aab2fc','ch_0c5d4e7ad99e','text','{"text": "Meaningful: Arthapoorna. The Kannada word for Meaning is Artha—which also means money! And of course, fame, publicity, glamour...power. (Laughs.) Let me leave it at that."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b21bae6c4fd','ch_0c5d4e7ad99e','text','{"text": "The second question everyone asks is about the book itself: thank God! How could you—you seem so strong and active—I was a long jump athlete in college, though of course no Anju Bobby George—how could you so vividly recreate the inner life of a person confined to bed all her life? How can a healthy, outdoor woman be so empathetic to the emotional world of a disabled person? Well, it is sad, but I owe that to my younger sister, Malini. She was physically challenged."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2a31e9da1ec0','ch_0c5d4e7ad99e','text','{"text": "Suffered from what is technically called, meningomyelocele—the upper part of her body was perfectly normal;"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fae5b98ef318','ch_0c5d4e7ad99e','text','{"text": "below the waist, the nervous system was damaged. Completely dysfunctional. A series of operations, which started soon after her birth, reduced her existence to misery— she spent her entire life confined to the wheel-chair. Six years ago my parents died. She came to stay with us in our house in Jayanagar, and I nursed her."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_66c223f08ac2','ch_0c5d4e7ad99e','text','{"text": "During the last few months it was quite clear she didn’t have much time left. I am childless and she became my child! Truly, the book is about her. I have dedicated it to her memory. She died last year—just a few months before the book came out. I have tried to relive what I learnt about her emotional life as I nursed her—tended to her—watched helplessly as she floated into death. I miss her. I miss my beautiful, gentle sister. (Her eyes moisten.)"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea88c60c3fc4','ch_0c5d4e7ad99e','text','{"text": "She is the only character in the novel drawn from life. The other characters and the plot are entirely fictional. Invented. (Pause.) I must here acknowledge the support I received from one person while I wrote the novel—my husband, Pramod Murty. I was working full time as a lecturer then. College chores. And home was full of her memories. And there was I, suddenly writing in English. Floundering. Sinking. I was utterly clueless. There were moments when I broke down, when I felt I couldn’t go on."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a2c08043166','ch_0c5d4e7ad99e','text','{"text": "But he was always there at my side, encouraging me, prodding me on. Without him, I would never have completed the novel. Thank you, Pramod. (The overhead light turns yellow.) Well, that’s it. I have committed the cardinal sin of writing in English. (Laughs.) There is no prayashchitta for it, no absolution. But fortunately the film you are about to see is in Kannada. That makes me very happy. After all, the family I have written about is Kannada."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f3138dc9430','ch_0c5d4e7ad99e','text','{"text": "I am a Kannada writer myself, born to the language and civilization, and proud of it. The Kannada reality I conceived in English has been translated back into Kannada—to perfection—by the Director. I couldn’t have done it better. My thanks to the cast and the crew and of course, Shree-TV. Well, enjoy the telefilm. Good Night. Namaskara. (The light turns red. She leans back in her chair. Pause. Then into the lapel mike.) I hope that was okay? I didn’t fumble too much, did I? (Listens.)"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_820675d9b38d','ch_0c5d4e7ad99e','text','{"text": "Thank you, Raza. The pleasure’s all mine. See you outside? (The red light switches off. She smiles contentedly.) Whew! That’ll get them. Good. I have taken enough shit from them. (Laughs and gets up. Manjula’s image on the screen should have given way to the film, but hasn’t. Instead, the Image continues as before, watching her calmly. She is of course unaware of it.) (She makes a move to the door.)"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4e333fcdb72','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Where are you going? (Startled, Manjula stops and looks around."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a61d687b0b99','ch_0c5d4e7ad99e','text','{"text": "Touches her earpiece to check if the sound came from there and moves on.) You can’t go yet. —Manjula! (Manjula looks around baffled and sees that her image continues on the screen. She does a double take. From now on, throughout the play, Manjula and her image react to each other exactly as though they were both live characters.)"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e14a5ce42c0a','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Oh God! Am I still on? (Confused, she rushes back to the chair and stops.)"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4dd1ef99a0f9','ch_0c5d4e7ad99e','text','{"text": "IMAGE: You are not. The camera is off."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e98e48130a0','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Is it?.. Then..."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d60114a7579f','ch_0c5d4e7ad99e','text','{"text": "how?"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50bb067088e5','ch_0c5d4e7ad99e','text','{"text": "IMAGE: You are standing up. If the camera were on, I would be standing up too. I’m not."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c74d54a94de3','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Is this some kind of a trick? (Into her lapel mike.) Hello! Hello! Can you hear me? How come I’m still on the screen? Raza, hello... (Taps her mike. No response.) Is there a technical hitch?"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_29abf247800f','ch_0c5d4e7ad99e','text','{"text": "IMAGE: No hitch. MANJULA (to the Image): But how... Who are you... How... Has the tape got stuck? (Calls out into the mike.) Raza, Raza."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b6187b48573','ch_0c5d4e7ad99e','text','{"text": "Help! Help!"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b264dd3f396','ch_0c5d4e7ad99e','text','{"text": "IMAGE: What are you screaming for? What are you afraid of? It’s only me."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_41147cebc17d','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Who are you?"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5f1e70a73a36','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Me? You. MANJULA (to herself): This is absurd."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abb70e9187a1','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Quite. (A long pause while Manjula refuses to acknowledge the presence of the Image. Then she slowly looks up. The Image smiles.)"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71aa1866b114','ch_0c5d4e7ad99e','text','{"text": "IMAGE: A good speech, I must say. My compliments. An excellent performance. The viewers loved it. All two million of them."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76e5a9e7bdda','ch_0c5d4e7ad99e','text','{"text": "MANJULA: But the film? Hasn’t it started?"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e781186c261','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Aw, screw the film..."}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_097bf1a9dc35','ch_0c5d4e7ad99e','text','{"text": "It’s awful anyway."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cfe570c7ec1a','ch_0c5d4e7ad99e','text','{"text": "MANJULA: I told them it won’t work. A telefilm needs lots of movement. Different locations. Pace. Action. Drama."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_28243e9317a0','ch_0c5d4e7ad99e','text','{"text": "‘A good novel does not necessarily make a good film,’ I argued."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abed10857737','ch_0c5d4e7ad99e','text','{"text": "But they were persistent. Sponsors were easy to find. (Pause.) They paid well."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_580888af3573','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Your performance now... this introduction... it will be the best thing this evening. You’ll be all over the papers. You have managed to upset a lot of people."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53b7798f95ff','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Thanks. I meant to. (Pause.)"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_42111f64b1e1','ch_0c5d4e7ad99e','text','{"text": "IMAGE: If one had to comment... in the extreme case that one had to...that bit about your sister Malini...the tears...that could have been played down."}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d9e92eea2620','ch_0c5d4e7ad99e','text','{"text": "MANJULA: I wasn’t pretending. I loved her. (Pause.) I love her."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6eb938fe9c9c','ch_0c5d4e7ad99e','text','{"text": "Still. I don’t think I have ever been as close to anyone else."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44ce7dca5622','ch_0c5d4e7ad99e','text','{"text": "IMAGE: It was a close bond?"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43e176c7c7cf','ch_0c5d4e7ad99e','text','{"text": "MANJULA: The novel doesn’t really do her justice. She was attractive—more attractive than me. Intelligent—more intelligent than me. And vivacious, which I never was. I accepted that. She radiated life from the wheelchair to which she was confined. I have always been reconciled to being the second best."}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_60ce40749403','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Her illness was unfortunate. But because of it, she got the best of everything."}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c0c61263450','ch_0c5d4e7ad99e','text','{"text": "MANJULA (defensive): She never asked for anything. Soon after her birth, the moment the gravity of her situation was realised, my parents moved to Bangalore. Took a house in the Koramangala Extension. She became the...the (searches for a phrase and then settles for)... the apple of their eye. When she was old enough to go to school, a teacher came home to teach her English and Mathematics. Everything else, she read up for herself. History, Philosophy, Anatomy. She was hungry—hungry for life."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db45f9dfc1ab','ch_0c5d4e7ad99e','text','{"text": "Gobbled it all up."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8b29b1935a8','ch_0c5d4e7ad99e','text','{"text": "IMAGE: And you?"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_237546517a46','ch_0c5d4e7ad99e','text','{"text": "MANJULA: I have often wondered whether I would have been as bright if I’d received all that love and attention."}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_151829c89c13','ch_0c5d4e7ad99e','text','{"text": "IMAGE: No, you wouldn’t. Let’s face it. MANJULA (defensively): I did write a bestseller."}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e085f18444e5','ch_0c5d4e7ad99e','text','{"text": "IMAGE: That’s true."}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d4c5d3e20766','ch_0c5d4e7ad99e','text','{"text": "MANJULA: But you are right. I wouldn’t. They left me with grandparents in Dharwad. An affectionate couple. They fussed over me. But no substitute for parents. When vacations approached I could barely wait to get to Bangalore."}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e886ba8261cb','ch_0c5d4e7ad99e','text','{"text": "And once I finished college, I found a job in Bangalore and came and lived with them. Those were the happiest days of my life! Halcyon! But then I met Pramod. We got married and settled down in Jayanagar. Father helped with the house but he left most of his money in her name—for her care. She was always the focus. Naturally."}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a51304cd6cf','ch_0c5d4e7ad99e','text','{"text": "IMAGE: But when your parents died, why didn’t you move into the Koramangala house? Such a nice, big house. The garden. The sense of space."}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b174d2fb5ec','ch_0c5d4e7ad99e','text','{"text": "MANJULA: The Jayanagar house was my house. I was used to it. My college was in Jayanagar. We had selected a house which was within walking distance. Koramangala would have meant a long haul every morning. And then such a huge house! Not easy to look after. I would have had to stay home all day like mother. Give up my job probably. No, as I said, she was one of the most sensitive people I have known. She realised moving to Koramangala would turn my life upside down."}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24aa4d9851c3','ch_0c5d4e7ad99e','text','{"text": "She insisted that we sell the Koramangala house. I was reluctant but she wouldn’t listen. She wanted no sacrifices on her account, no compromises. And she adjusted beautifully to the smaller house. (Pause.) Actually I couldn’t take Koramangala! Non-Kannadigas, most of them. And of course all those empty houses bought as investments by Non-Resident Indians. I fancied myself a Kannada writer in those days. Wanted to breathe the language. Live in the heart of Kannada culture."}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_175dcf0b7663','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Now that you are a success in English, have you bought a big bungalow in Koramangala?"}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e9b10b1ca3a','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Aw, shut up!"}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_045107e96a4c','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Was Malini at home with Kannada?"}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0b8bf5f5163','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Of course, it is our mother-tongue. But she rarely used it. Her Kannada was limited to the cook and the maid."}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7f399844bbfd','ch_0c5d4e7ad99e','text','{"text": "IMAGE: So Kannada was the one area that became yours?"}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c48997017a6a','ch_0c5d4e7ad99e','text','{"text": "MANJULA: You could say that. I tried to occupy it and make it mine. (Laughs.)"}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76450a8134fd','ch_0c5d4e7ad99e','text','{"text": "Actually, I have never said it publicly, but if you argue that a novel written in English cannot express truth about India because we do not express ourselves in English— (Takes a breath. Laughs.) God, what a sentence! But if you believe that, then let me say I could not have written about my sister in Kannada. She breathed, laughed, dreamt in English. Her friends spoke only English. Having her in my house for six years helped improve my English. (Pause.)"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bb2e373bb6bb','ch_0c5d4e7ad99e','text','{"text": "IMAGE: So when are you going to write your next novel? Will it also be in English?"}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92fb0fecebcc','ch_0c5d4e7ad99e','text','{"text": "MANJULA: I think I have already answered that question. Why need I write another novel? Surely one is more than enough?"}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_690de0584bcc','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Critically and financially. But then what are you going to do? You have resigned your job. You are rich—"}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c49f7c26149d','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Well-to-do."}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b0b69176642','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Well-to-do. You have no sister to look after. An empty house. Nothing you can use."}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a46d8fdb2cc','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Are you trying to make me feel guilty? Are you implying I"}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_988e94fdc666','ch_0c5d4e7ad99e','text','{"text": "‘used’ her? It was my life as well you know. I am in the back too, though I would never admit to it publicly. Most readers find the girl’s"}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b63842caab3f','ch_0c5d4e7ad99e','text','{"text": "‘first cousin’ quite unattractive."}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20fcc3d4bc2d','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Eek! That odious character! Is that you?"}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a7ecf1e0a208','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Well! There you are!"}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e0ff08981e1','ch_0c5d4e7ad99e','text','{"text": "IMAGE: A triumph of objective self-analysis, shall we say?"}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_454c6e7e5fd1','ch_0c5d4e7ad99e','text','{"text": "MANJULA: If you must. But I am not that wicked really. It was a narrative necessity to have a negative character. A matter of technique. The sympathetic heroine. A villain as a counterpoint. You see?"}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d623af60a49f','ch_0c5d4e7ad99e','text','{"text": "IMAGE: But Pramod must be pleased by your treatment of his character. He comes across as not very good-looking or striking..."}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27881b7003f7','ch_0c5d4e7ad99e','text','{"text": "MANJULA: But not bad-looking, either."}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_454f54460b04','ch_0c5d4e7ad99e','text','{"text": "Good enough for me."}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0d2ed28e991','ch_0c5d4e7ad99e','text','{"text": "IMAGE: ...but an intelligent, warm and lovable person. Fun-loving. Fond of practical jokes. Noble and simple. Almost simple-minded."}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af31a24d5e92','ch_0c5d4e7ad99e','text','{"text": "MANJULA: You can say that again! You know, we met soon after I moved to Bangalore. He felt attracted to me. Didn’t know how to convey it. So do you know what he did? I had a friend called Lucy. A close friend. He wrote a letter to her about me. And wrote me a letter about Lucy."}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fca0df18ea8c','ch_0c5d4e7ad99e','text','{"text": "Then he mailed her letter in an envelope addressed to me and vice versa. So I received this letter addressed to Lucy—moaning and groaning about how I tortured him. And I didn’t even know he was interested in me. And of course Lucy received the other letter. He thought he was being absolutely clever— original. We went and confronted him. Lucy tore her letter to shreds and flung the pieces on him and stormed off. Melodramatically."}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b22a05583298','ch_0c5d4e7ad99e','text','{"text": "I felt sorry for him and said, ‘Idiot, every fifteen-year old tries that trick, convinced it’s never been done before.’"}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5bd5640f5624','ch_0c5d4e7ad99e','text','{"text": "He blushed to the roots of his hair."}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_06f9245b8443','ch_0c5d4e7ad99e','text','{"text": "IMAGE: But you got married. So the ruse worked."}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c68a18606b31','ch_0c5d4e7ad99e','text','{"text": "MANJULA: No ruse. He had made such a fool of himself, he did the only thing he could to save his self-respect. He married me. I didn’t mind."}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_54f7d2d8e21f','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Mind? You would never have got another man of his calibre."}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97e9e8c681f5','ch_0c5d4e7ad99e','text','{"text": "MANJULA: I suppose so."}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_584489bab92c','ch_0c5d4e7ad99e','text','{"text": "IMAGE: And what happened to Lucy?"}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1da7f0e91f2','ch_0c5d4e7ad99e','text','{"text": "MANJULA: She stopped talking to me. (They both laugh.) Women found him attractive."}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_73a21dd2275b','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Malini too?"}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b66f0a98b63','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Of course. She was a woman, after all."}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_83383b42ef98','ch_0c5d4e7ad99e','text','{"text": "IMAGE: They were close to each other?"}',116);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be3432739786','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Very."}',117);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bf6a94b7c1d1','ch_0c5d4e7ad99e','text','{"text": "IMAGE: And you didn’t mind?"}',118);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ee157fbea66d','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Mind? Thank God for it. You see, he is in software development. Works from home. She was confined to her chair. Can you imagine what would have happened if they hadn’t got on?"}',119);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2dd1c8e6a8c','ch_0c5d4e7ad99e','text','{"text": "IMAGE: He must be proud of you. That flattering portrayal of him in the novel. The moving acknowledgment in your speech today..."}',120);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1a6de0e61489','ch_0c5d4e7ad99e','text','{"text": "MANJULA: I doubt if he will even hear of my speech. Ever. He is in the US."}',121);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_296fd8ee2dae','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Oh! When did he go?"}',122);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c11b6fc0a971','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Last year. He lives in Los Angeles now. He is in demand as a software wizard."}',123);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d4b1d980ce28','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Last year! So has he even read the novel?"}',124);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a0b6e7d7da6f','ch_0c5d4e7ad99e','text','{"text": "MANJULA: The launching of the novel was a major media event in the US. After all, you must remember it had already proved a super hit in Britain. They invited me to New York for the release. There was much fanfare. He sent me an email of congratulations. From Los Angeles. Apologised that he couldn’t get leave to attend."}',125);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_31d53cf49ab4','ch_0c5d4e7ad99e','text','{"text": "IMAGE: And you didn’t go to LA?"}',126);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_077b8730117f','ch_0c5d4e7ad99e','text','{"text": "MANJULA: He didn’t even hint at it."}',127);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22916d13e182','ch_0c5d4e7ad99e','text','{"text": "IMAGE: I’m sorry. But the chronology is beginning to confuse me. When did he decide to go to the States? Was it after Malini’s death?"}',128);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1c86b5eb87af','ch_0c5d4e7ad99e','text','{"text": "MANJULA: Yes."}',129);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0afd5936939c','ch_0c5d4e7ad99e','text','{"text": "IMAGE: Immediately after?"}',130);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c6cc1b46748','ch_0c5d4e7ad99e','text','{"text": "MANJULA: No. But soon after."}',131);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac3a4feb3d60','ch_0c5d4e7ad99e','text','{"text": "IMAGE: How long after? MANJULA (explodes): Who are you, for God’s sake? What gives you the right to interrogate me like this—about my private life? Either you are me in which case you know everything."}',132);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4133d2d2266e','ch_0c5d4e7ad99e','text','{"text": "Or you are an electronic image, externally prying. In which case, you can just... just... switch off. (The Image smiles. Suddenly Manjula becomes calm.)"}',133);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9d6ca973c82','ch_0c5d4e7ad99e','list','{"ordered": false, "items": ["Girish Karnad"]}',134);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d29727e0294','ch_0c5d4e7ad99e','text','{"text": "About the Author"}',135);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f553a4b6cd22','ch_0c5d4e7ad99e','text','{"text": "Girish Karnad is a contemporary writer, playwright, actor and movie director. He is a recipient of the Padma Shri (1974), Padma Bhushan (1992) and the Jnanpith Award (1998). He writes in both Kannada and English. His plays generally use history and mythology to focus on contemporary issues."}',136);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e8e89a567fe','ch_0c5d4e7ad99e','text','{"text": "He is also active in the world of Indian cinema. This play, too, can be looked at from multiple levels—the focus on values, both personal and academic, and the issue of bilingualism in today’s world."}',137);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_1b0fc01df267','bk_ncert_english','12-22-the-last-lesson','12.22 The Last Lesson',NULL,'public',94,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_65add5fb3cf3','ch_1b0fc01df267','text','{"text": "I started for school very late that morning and was in great dread of a scolding, especially because M. Hamel had said that he would question us on participles, and I did not know the first word about them. For a moment I thought of running away and spending the day out of doors."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_999e024d7d3c','ch_1b0fc01df267','text','{"text": "It was so warm, so bright! The birds were chirping at the edge of the woods;"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e44fd34d836','ch_1b0fc01df267','text','{"text": "and in the open field back of the sawmill the Prussian soldiers were drilling. It was all much more tempting than the rule for participles, but I had the strength to resist, and hurried off to school. When I passed the town hall there was a crowd in front of the bulletin-board."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bbffc5f8bf37','ch_1b0fc01df267','text','{"text": "For the last two years all our bad news had come from there — the lost battles, the draft, the orders of the commanding officer — and I thought to myself, without stopping, ‘What can be the matter now?’ Then, as I hurried by as fast as I could go, the blacksmith, Wachter, who was there, with his apprentice, reading the bulletin, called after me, ‘Don’t go so fast, bub;"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e2b2f7118b92','ch_1b0fc01df267','text','{"text": "you’ll get to your school in plenty of time!’ I thought he was making fun of me, and reached M."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46b82faa4856','ch_1b0fc01df267','text','{"text": "Hamel’s little garden all out of breath. Usually, when school began, there was a great bustle, which could be heard out in the street, the opening and closing of desks, lessons repeated in unison, very loud, with our hands over our ears to understand better, and the teacher’s great ruler rapping on the table. But now it was all so still! I had counted on the commotion to get to my desk without being seen;"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6cc87bfa8436','ch_1b0fc01df267','text','{"text": "but, of course, that day everything had to be as quiet as Sunday morning."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0196cd1174bf','ch_1b0fc01df267','text','{"text": "Through the window I saw my classmates, already in their places, and M. Hamel walking up and down with his terrible iron ruler under his arm. I had to open the door and go in before everybody. You can imagine how I blushed and how frightened I was. But nothing happened. M. Hamel saw me and said very kindly, ‘Go to your place quickly, little Franz. We were beginning without you.’"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e593027995f8','ch_1b0fc01df267','text','{"text": "I jumped over the bench and sat down at my desk. Not till then, when I had got a little over my fright, did I see that our teacher had on his beautiful green coat, his frilled shirt, and the little black silk cap, all embroidered, that he never wore except on inspection and prize days. Besides, the whole school seemed so strange and solemn."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e2f7afac0189','ch_1b0fc01df267','text','{"text": "But the thing that surprised me most was to see, on the back benches that were always empty, the village people sitting quietly like ourselves;"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97b0e07c3c94','ch_1b0fc01df267','text','{"text": "old Hauser, with his three-cornered hat, the former mayor, the former postmaster, and several others besides. Everybody looked sad;"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a50f6075c23a','ch_1b0fc01df267','text','{"text": "and Hauser had brought an old primer, thumbed at the edges, and he held it open on his knees with his great spectacles lying across the pages. While I was wondering about it all, M."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d81434d28a1','ch_1b0fc01df267','text','{"text": "Hamel mounted his chair, and, in the same grave and gentle tone which he had used to me, said, ‘My children, this is the last lesson I shall give you. The order has come from Berlin to teach only German in the schools of Alsace and Lorraine. The new master comes tomorrow. This is your last French lesson. I want you to be very attentive.’"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59534c50b0ee','ch_1b0fc01df267','text','{"text": "What a thunderclap these words were to me! Oh, the wretches;"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5ed71157c5c','ch_1b0fc01df267','text','{"text": "that was what they had put up at the town-hall! My last French lesson! Why, I hardly knew how to write! I should never learn any more! I must stop there, then! Oh, how sorry I was for not learning my lessons, for seeking birds’ eggs, or going sliding on the Saar! My books, that had seemed such a nuisance a while ago, so heavy to carry, my grammar, and my history of the saints, were old friends now that I couldn’t give up. And M."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf92453ae85c','ch_1b0fc01df267','text','{"text": "Hamel, too;"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_21ef71ded92a','ch_1b0fc01df267','text','{"text": "the idea that he was going away, that I should never see him again, made me forget all about his ruler and how cranky he was. Poor man! It was in honour of this last lesson that he had put on his fine Sunday clothes, and now I understood why the old men of the village were sitting there in the back of the room. It was because they were sorry, too, that they had not gone to school more."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac8bf289d028','ch_1b0fc01df267','text','{"text": "It was their way of thanking our master for his forty years of faithful service and of showing their respect for the country that was theirs no more. While I was thinking of all this, I heard my name called. It was my turn to recite. What would I not have given to be able to say that dreadful rule for the participle all through, very loud and clear, and without one mistake? But I got mixed up on the first words and stood there, holding on to my desk, my heart beating, and not daring to look up."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cdff0d52059f','ch_1b0fc01df267','text','{"text": "I heard M. Hamel say to me, ‘I won’t scold you, little Franz;"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1b9d45ee5aa','ch_1b0fc01df267','text','{"text": "you must feel bad enough. See how it is! Every day we have said to ourselves, ‘Bah! I’ve plenty of time. I’ll learn it tomorrow.’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_87b2676bbda5','ch_1b0fc01df267','text','{"text": "And now you see where we’ve come out. Ah, that’s the great trouble with Alsace;"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_276df6c03666','ch_1b0fc01df267','text','{"text": "she puts off learning till tomorrow. Now those fellows out there will have the right to say to you, ‘How is it;"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_01b0cdb364cc','ch_1b0fc01df267','text','{"text": "you pretend to be Frenchmen, and yet you can neither speak nor write your own language?’ But you are not the worst, poor little Franz. We’ve all a great deal to reproach ourselves with.’"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_beee2265ba02','ch_1b0fc01df267','text','{"text": "‘Your parents were not anxious enough to have you learn. They preferred to put you to work on a farm or at the mills, so as to have a little more money. And I? I’ve been to blame also. Have I not often sent you to water my flowers instead of learning your lessons? And when I wanted to go fishing, did I not just give you a holiday?’ Then, from one thing to another, M."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9d97e039160','ch_1b0fc01df267','text','{"text": "Hamel went on to talk of the French language, saying that it was the most beautiful language in the world — the clearest, the most logical;"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b8ac3b2f3a2d','ch_1b0fc01df267','text','{"text": "that we must guard it among us and never forget it, because when a people are enslaved, as long as they hold fast to their language it is as if they had the key to their prison. Then he opened a grammar and read us our lesson. I was amazed to see how well I understood it."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d62d90a681a0','ch_1b0fc01df267','text','{"text": "All he said seemed so easy, so easy! I think, too, that I had never listened so carefully, and that he had never explained everything with so much patience. It seemed almost as if the poor man wanted to give us all he knew before going away, and to put it all into our heads at one stroke. After the grammar, we had a lesson in writing. That day M. Hamel had new copies for us, written in a beautiful round hand — France, Alsace, France, Alsace."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_52d345e82542','ch_1b0fc01df267','text','{"text": "They looked like little flags floating everywhere in the school-room, hung from the rod at the top of our desks. You ought to have seen how every one set to work, and how quiet it was! The only sound was the scratching of the pens over the paper. Once some beetles flew in;"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80acda0de53c','ch_1b0fc01df267','text','{"text": "but nobody paid any attention to them, not even the littlest ones, who worked right on tracing their fish-hooks, as if that was French, too."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67dd4f98f3a8','ch_1b0fc01df267','text','{"text": "On the roof the pigeons cooed very low, and I thought to myself, ‘Will they make them sing in German, even the pigeons?’ Whenever I looked up from my writing I saw M. Hamel sitting motionless in his chair and gazing first at one thing, then at another, as if he wanted to fix in his mind just how everything looked in that little school-room. Fancy! For forty years he had been there in the same place, with his garden outside the window and his class in front of him, just like that."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0565399f9964','ch_1b0fc01df267','text','{"text": "Only the desks and benches had been worn smooth;"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e58022a03e55','ch_1b0fc01df267','text','{"text": "the walnut-trees in the garden were taller, and the hopvine that he had planted himself twined about the windows to the roof. How it must have broken his heart to leave it all, poor man;"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3c2d548e6b55','ch_1b0fc01df267','text','{"text": "to hear his sister moving about in the room above, packing their trunks! For they must leave the country next day. But he had the courage to hear every lesson to the very last."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b228d7bde2a1','ch_1b0fc01df267','text','{"text": "After the writing, we had a lesson in history, and then the babies chanted their ba, be bi, bo, bu. Down there at the back of the room old Hauser had put on his spectacles and, holding his primer in both hands, spelled the letters with them. You could see that he, too, was crying;"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f422a2c45590','ch_1b0fc01df267','text','{"text": "his voice trembled with emotion, and it was so funny to hear him that we all wanted to laugh and cry. Ah, how well I remember it, that last lesson! All at once the church-clock struck twelve. Then the Angelus."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a250dcd2dafe','ch_1b0fc01df267','text','{"text": "At the same moment the trumpets of the Prussians, returning from drill, sounded under our windows. M. Hamel stood up, very pale, in his chair. I never saw him look so tall."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e9222e58c56f','ch_1b0fc01df267','text','{"text": "‘My friends,’ said he, ‘I—I—’ But something choked him."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b27ef4bb31e8','ch_1b0fc01df267','text','{"text": "He could not go on. Then he turned to the blackboard, took a piece of chalk, and, bearing on with all his might, he wrote as large as he could —"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e7b37ddf729','ch_1b0fc01df267','text','{"text": "‘Vive La France!’ Then he stopped and leaned his head against the wall, and, without a word, he made a gesture to us with his hand —"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_26e1231898bf','ch_1b0fc01df267','text','{"text": "‘School is dismissed — you may go.’"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_15f79dceb6a4','ch_1b0fc01df267','list','{"ordered": false, "items": ["Alphonse Daudet"]}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a94e8f6c1201','ch_1b0fc01df267','text','{"text": "About the author"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_29128a5ae5ef','ch_1b0fc01df267','text','{"text": "Alphonse Daudet (1840-1897) was a French novelist and short-story writer. The Last Lesson is set in the days of the Franco-Prussian War (1870-1871) in which France was defeated by Prussia led by Bismarck. Prussia then consisted of what now are the nations of Germany, Poland and parts of Austria. In this story the French districts of Alsace and Lorraine have passed into Prussian hands."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc2b5a00f29c','ch_1b0fc01df267','text','{"text": "Read the story to find out what effect this had on life at school."}',44);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_4bc72362dbac','bk_ncert_english','12-23-lost-spring','12.23 Lost Spring',NULL,'public',95,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa881517deca','ch_4bc72362dbac','text','{"text": "Stories of Stolen Childhood"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_410c84cb11ff','ch_4bc72362dbac','text','{"text": "‘Sometimes I find a Rupee in the garbage’"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0095a06b71b5','ch_4bc72362dbac','text','{"text": "‘Why do you do this?’ I ask Saheb whom I encounter every morning scrounging for gold in the garbage dumps of my neighbourhood."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9fe49518af04','ch_4bc72362dbac','text','{"text": "Saheb left his home long ago. Set amidst the green fields of Dhaka, his home is not even a distant memory. There were many storms that swept away their fields and homes, his mother tells him. That’s why they left, looking for gold in the big city where he now lives."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bff5fa73d986','ch_4bc72362dbac','text','{"text": "‘I have nothing else to do,’ he mutters, looking away."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_384a1801ad68','ch_4bc72362dbac','text','{"text": "‘Go to school,’ I say glibly, realising immediately how hollow the advice must sound."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2d1d242d77ed','ch_4bc72362dbac','text','{"text": "‘There is no school in my neighbourhood. When they build one, I will go.’"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9087e2d6ff23','ch_4bc72362dbac','text','{"text": "‘If I start a school, will you come?’ I ask, half-joking."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90293d2dd15a','ch_4bc72362dbac','text','{"text": "‘Yes,’ he says, smiling broadly. A few days later I see him running up to me."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f8ff7ee6e751','ch_4bc72362dbac','text','{"text": "‘Is your school ready?’"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ae44aa2c638b','ch_4bc72362dbac','text','{"text": "‘It takes longer to build a school,’ I say, embarrassed at having made a promise that was not meant."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b99decada02d','ch_4bc72362dbac','text','{"text": "But promises like mine abound in every corner of his bleak world. After months of knowing him, I ask him his name."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2996f9a81a18','ch_4bc72362dbac','text','{"text": "‘Saheb-e-Alam,’ he announces. He does not know what it means. If he knew its meaning — lord of the universe — he would have a hard time believing it. Unaware of what his name represents, he roams the streets with his friends, an army of barefoot boys who appear like the morning birds and disappear at noon. Over the months, I have come to recognise each of them."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2e55f46d841','ch_4bc72362dbac','text','{"text": "‘Why aren’t you wearing chappals?’ I ask one."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1524199c5a01','ch_4bc72362dbac','text','{"text": "‘My mother did not bring them down from the shelf,’ he answers simply."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b40ebaae443f','ch_4bc72362dbac','text','{"text": "‘Even if she did he will throw them off,’ adds another who is wearing shoes that do not match."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_360536ea1f0d','ch_4bc72362dbac','text','{"text": "When I comment on it, he shuffles his feet and says nothing."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_72ab6b4d0277','ch_4bc72362dbac','text','{"text": "‘I want shoes,’ says a third boy who has never owned a pair all his life."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8558518a24a','ch_4bc72362dbac','text','{"text": "Travelling across the country I have seen children walking barefoot, in cities, on village roads. It is not lack of money but a tradition to stay barefoot, is one explanation. I wonder if this is only an excuse to explain away a perpetual state of poverty. I remember a story a man from Udipi once told me. As a young boy he would go to school past an old temple, where his father was a priest. He would stop briefly at the temple and pray for a pair of shoes."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e77edf0a77fd','ch_4bc72362dbac','text','{"text": "Thirty years later I visited his town and the temple, which was now drowned in an air of desolation. In the backyard, where lived the new priest, there were red and white plastic chairs. A young boy dressed in a grey uniform, wearing socks and shoes, arrived panting and threw his school bag on a folding bed. Looking at the boy, I remembered the prayer another boy had made to the goddess when he had finally got a pair of shoes, ‘Let me never lose them.’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c7ec4a7061a','ch_4bc72362dbac','text','{"text": "The goddess had granted his prayer. Young boys like the son of the priest now wore shoes. But many others like the ragpickers in my neighbourhood remain shoeless. My acquaintance with the barefoot ragpickers leads me to Seemapuri, a place on the periphery of Delhi yet miles away from it, metaphorically. Those who live here are squatters who came from Bangladesh back in 1971. Saheb’s family is among them. Seemapuri was then a wilderness. It still is, but it is no longer empty."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d24a1068d1bc','ch_4bc72362dbac','text','{"text": "In structures of mud, with roofs of tin and tarpaulin, devoid of sewage, drainage or running water, live 10,000 ragpickers. They have lived here for more than thirty years without an identity, without permits but with ration cards that get their names on voters’ lists and enable them to buy grain. Food is more important for survival than an identity."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17c0daa8ef72','ch_4bc72362dbac','text','{"text": "‘If at the end of the day we can feed our families and go to bed without an aching stomach, we would rather live here than in the fields that gave us no grain,’ say a group of women in tattered saris when I ask them why they left their beautiful land of green fields and rivers."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bbcd9fd168fa','ch_4bc72362dbac','text','{"text": "Wherever they find food, they pitch their tents that become transit homes. Children grow up in them, becoming partners in survival. And survival in Seemapuri means rag-picking. Through the years, it has acquired the proportions of a fine art. Garbage to them is gold. It is their daily bread, a roof over their heads, even if it is a leaking roof. But for a child it is even more."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ec9975abe14','ch_4bc72362dbac','text','{"text": "‘I sometimes find a rupee, even a ten-rupee note,’ Saheb says, his eyes lighting up."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_840b3c9f9496','ch_4bc72362dbac','text','{"text": "When you can find a silver coin in a heap of garbage, you don’t stop scrounging, for there is hope of finding more. It seems that for children, garbage has a meaning different from what it means to their parents. For the children it is wrapped in wonder, for the elders it is a means of survival. One winter morning I see Saheb standing by the fenced gate of the neighbourhood club, watching two young men dressed in white, playing tennis."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2df1ee949676','ch_4bc72362dbac','text','{"text": "‘I like the game,’ he hums, content to watch it standing behind the fence."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_126065db80cd','ch_4bc72362dbac','text','{"text": "‘I go inside when no one is around,’ he admits."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a286b87ba9bc','ch_4bc72362dbac','text','{"text": "‘The gatekeeper lets me use the swing.’"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bb0b8345de8e','ch_4bc72362dbac','text','{"text": "Saheb too is wearing tennis shoes that look strange over his discoloured shirt and shorts."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b042b7d5a0c','ch_4bc72362dbac','text','{"text": "‘Someone gave them to me,’ he says in the manner of an explanation."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3babb9084151','ch_4bc72362dbac','text','{"text": "The fact that they are discarded shoes of some rich boy, who perhaps refused to wear them because of a hole in one of them, does not bother him. For one who has walked barefoot, even shoes with a hole is a dream come true. But the game he is watching so intently is out of his reach. This morning, Saheb is on his way to the milk booth. In his hand is a steel canister."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_63acec0cb847','ch_4bc72362dbac','text','{"text": "‘I now work in a tea stall down the road,’ he says, pointing in the distance."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_793d05bb8c0b','ch_4bc72362dbac','text','{"text": "‘I am paid 800 rupees and all my meals.’"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4107c0ef8244','ch_4bc72362dbac','text','{"text": "Does he like the job? I ask. His face, I see, has lost the carefree look. The steel canister seems heavier than the plastic bag he would carry so lightly over his shoulder. The bag was his. The canister belongs to the man who owns the tea shop. Saheb is no longer his own master!"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a2efaf69aa87','ch_4bc72362dbac','text','{"text": "‘I want to drive a car’ Mukesh insists on being his own master."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9d25d9dbbdb4','ch_4bc72362dbac','text','{"text": "‘I will be a motor mechanic,’ he announces."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c079f6f3c6bd','ch_4bc72362dbac','text','{"text": "‘Do you know anything about cars?’ I ask."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb7def8a02ad','ch_4bc72362dbac','text','{"text": "‘I will learn to drive a car,’ he answers, looking straight into my eyes."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8229bf704ce7','ch_4bc72362dbac','text','{"text": "His dream looms like a mirage amidst the dust of streets that fill his town Firozabad, famous for its bangles. Every other family in Firozabad is engaged in making bangles. It is the centre of India’s glass-blowing industry where families have spent generations working around furnaces, welding glass, making bangles for all the women in the land it seems. Mukesh’s family is among them."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c8e8f150c1b','ch_4bc72362dbac','text','{"text": "None of them know that it is illegal for children like him to work in the glass furnaces with high temperatures, in dingy cells without air and light;"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b19f7b24ba2','ch_4bc72362dbac','text','{"text": "that the law, if enforced, could get him and all those 20,000 children out of the hot furnaces where they slog their daylight hours, often losing the brightness of their eyes. Mukesh’s eyes beam as he volunteers to take me home, which he proudly says is being rebuilt."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad965dcf610f','ch_4bc72362dbac','text','{"text": "We walk down stinking lanes choked with garbage, past homes that remain hovels with crumbling walls, wobbly doors, no windows, crowded with families of humans and animals coexisting in a primeval state. He stops at the door of one such house, bangs a wobbly iron door with his foot, and pushes it open. We enter a half-built shack. In one part of it, thatched with dead grass, is a firewood stove over which sits a large vessel of sizzling spinach leaves."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fcb1095f558d','ch_4bc72362dbac','text','{"text": "On the ground, in large aluminium platters, are more chopped vegetables. A frail young woman is cooking the evening meal for the whole family. Through eyes filled with smoke she smiles. She is the wife of Mukesh’s elder brother. Not much older in years, she has begun to command respect as the bahu, the daughter-in-law of the house, already in charge of three men — her husband, Mukesh and their father."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d58ded964f58','ch_4bc72362dbac','text','{"text": "When the older man enters, she gently withdraws behind the broken wall and brings her veil closer to her face. As custom demands, daughters-inlaw must veil their faces before male elders. In this case the elder is an impoverished bangle maker. Despite long years of hard labour, first as a tailor, then a bangle maker, he has failed to renovate a house, send his two sons to school. All he has managed to do is teach them what he knows — the art of making bangles."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_655826b06cd8','ch_4bc72362dbac','text','{"text": "‘It is his karam, his destiny,’ says Mukesh’s grandmother, who has watched her own husband go blind with the dust from polishing the glass of bangles."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_346629163a9f','ch_4bc72362dbac','text','{"text": "‘Can a god-given lineage ever be broken?’ she implies."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e2614c7308ce','ch_4bc72362dbac','text','{"text": "Born in the caste of bangle makers, they have seen nothing but bangles — in the house, in the yard, in every other house, every other yard, every street in Firozabad. Spirals of bangles — sunny gold, paddy green, royal blue, pink, purple, every colour born out of the seven colours of the rainbow — lie in mounds in unkempt yards, are piled on four-wheeled handcarts, pushed by young men along the narrow lanes of the shanty town."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4840c8dcacf2','ch_4bc72362dbac','text','{"text": "And in dark hutments, next to lines of flames of flickering oil lamps, sit boys and girls with their fathers and mothers, welding pieces of coloured glass into circles of bangles. Their eyes are more adjusted to the dark than to the light outside. That is why they often end up losing their eyesight before they become adults. Savita, a young girl in a drab pink dress, sits alongside an elderly woman, soldering pieces of glass."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79b656baede6','ch_4bc72362dbac','text','{"text": "As her hands move mechanically like the tongs of a machine, I wonder if she knows the sanctity of the bangles she helps make. It symbolises an Indian woman’s suhaag, auspiciousness in marriage. It will dawn on her suddenly one day when her head is draped with a red veil, her hands dyed red with henna, and red bangles rolled onto her wrists. She will then become a bride. Like the old woman beside her who became one many years ago. She still has bangles on her wrist, but no light in her eyes."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca82c50c6c6e','ch_4bc72362dbac','text','{"text": "‘Ek waqt ser bhar khana bhi nahin khaya,’ she says, in a voice drained of joy."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d93c4ae9622','ch_4bc72362dbac','text','{"text": "She has not enjoyed even one full meal in her entire lifetime — that’s what she has reaped! Her husband, an old man with a flowing beard, says, ‘I know nothing except bangles. All I have done is make a house for the family to live in.’"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_15089765675c','ch_4bc72362dbac','text','{"text": "Hearing him, one wonders if he has achieved what many have failed in their lifetime. He has a roof over his head! The cry of not having money to do anything except carry on the business of making bangles, not even enough to eat, rings in every home. The young men echo the lament of their elders. Little has moved with time, it seems, in Firozabad. Years of mind-numbing toil have killed all initiative and the ability to dream."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce702c94e90c','ch_4bc72362dbac','text','{"text": "‘Why not organise yourselves into a cooperative?’ I ask a group of young men who have fallen into the vicious circle of middlemen who trapped their fathers and forefathers."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_618119d5c061','ch_4bc72362dbac','text','{"text": "‘Even if we get organised, we are the ones who will be hauled up by the police, beaten and dragged to jail for doing something illegal,’ they say."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7579950270ba','ch_4bc72362dbac','text','{"text": "There is no leader among them, no one who could help them see things differently. Their fathers are as tired as they are. They talk endlessly in a spiral that moves from poverty to apathy to greed and to injustice. Listening to them, I see two distinct worlds— one of the family, caught in a web of poverty, burdened by the stigma of caste in which they are born;"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53acc6656b07','ch_4bc72362dbac','text','{"text": "the other a vicious circle of the sahukars, the middlemen, the policemen, the keepers of law, the bureaucrats and the politicians."}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_318d48ef25c6','ch_4bc72362dbac','text','{"text": "Together they have imposed the baggage on the child that he cannot put down. Before he is aware, he accepts it as naturally as his father. To do anything else would mean to dare. And daring is not part of his growing up. When I sense a flash of it in Mukesh I am cheered."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_87a26571693e','ch_4bc72362dbac','text','{"text": "‘I want to be a motor mechanic,’ he repeats."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c834a387d738','ch_4bc72362dbac','text','{"text": "He will go to a garage and learn. But the garage is a long way from his home."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3fec98d46d3f','ch_4bc72362dbac','text','{"text": "‘I will walk,’ he insists."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53a46c3ac2ac','ch_4bc72362dbac','text','{"text": "‘Do you also dream of flying a plane?’ He is suddenly silent."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea8e00715d71','ch_4bc72362dbac','text','{"text": "‘No,’ he says, staring at the ground. In his small murmur there is an embarrassment that has not yet turned into regret. He is content to dream of cars that he sees hurtling down the streets of his town. Few airplanes fly over Firozabad."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4019fdfd3e65','ch_4bc72362dbac','list','{"ordered": false, "items": ["Anees Jung"]}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4a9ce5e0c71','ch_4bc72362dbac','text','{"text": "About the author Anees Jung (1964) was born in Rourkela and spent her childhood and adolescence in Hyderabad. She received her education in Hyderabad and in the United States of America. Her parents were both writers. Anees Jung began her career as a writer in India. She has been an editor and columnist for major newspapers in India and abroad, and has authored several books."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_78f59d9e89c5','ch_4bc72362dbac','text','{"text": "The following is an excerpt from her book titled Lost Spring, Stories of Stolen Childhood. Here she analyses the grinding poverty and traditions which condemn these children to a life of exploitation."}',66);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_574314f1608f','bk_ncert_english','12-24-deep-water','12.24 Deep Water',NULL,'public',96,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71942ebccf77','ch_574314f1608f','text','{"text": "It had happened when I was ten or eleven years old. I had decided to learn to swim. There was a pool at the Y.M.C.A. in Yakima that offered exactly the opportunity. The Yakima River was treacherous."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75a8a3ef0b18','ch_574314f1608f','text','{"text": "Mother continually warned against it, and kept fresh in my mind the details of each drowning in the river. But the Y.M.C.A. pool was safe. It was only two or three feet deep at the shallow end;"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d630f0110f61','ch_574314f1608f','text','{"text": "and while it was nine feet deep at the other, the drop was gradual. I got a pair of water wings and went to the pool. I hated to walk naked into it and show my skinny legs. But I subdued my pride and did it. From the beginning, however, I had an aversion to the water when I was in it."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5cc3569e8efa','ch_574314f1608f','text','{"text": "This started when I was three or four years old and father took me to the beach in California. He and I stood together in the surf. I hung on to him, yet the waves knocked me down and swept over me. I was buried in water. My breath was gone. I was frightened. Father laughed, but there was terror in my heart at the overpowering force of the waves. My introduction to the Y.M.CA. swimming pool revived unpleasant memories and stirred childish fears. But in a little while I gathered confidence."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_527df5f1cd61','ch_574314f1608f','text','{"text": "I paddled with my new water wings, watching the other boys and trying to learn by aping them. I did this two or three times on different days and was just beginning to feel at ease in the water when the misadventure happened. I went to the pool when no one else was there. The place was quiet. The water was still, and the tiled bottom was as white and clean as a bathtub. I was timid about going in alone, so I sat on the side of the pool to wait for others."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4202ed06f61e','ch_574314f1608f','text','{"text": "I had not been there long when in came a big bruiser of a boy, probably eighteen years old. He had thick hair on his chest. He was a beautiful physical specimen, with legs and arms that showed rippling muscles. He yelled, ‘Hi, Skinny! How’d you like to be ducked?’ With that he picked me up and tossed me into the deep end. I landed in a sitting position, swallowed water, and went at once to the bottom. I was frightened, but not yet frightened out of my wits."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7241ffb8d5f9','ch_574314f1608f','text','{"text": "On the way down I planned: When my feet hit the bottom, I would make a big jump, come to the surface, lie flat on it, and paddle to the edge of the pool. It seemed a long way down. Those nine feet were more like ninety, and before I touched bottom my lungs were ready to burst. But when my feet hit bottom I summoned all my strength and made what I thought was a great spring upwards. I imagined I would bob to the surface like a cork. Instead, I came up slowly."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b4d47b16722','ch_574314f1608f','text','{"text": "I opened my eyes and saw nothing but water — water that had a dirty yellow tinge to it. I grew panicky. I reached up as if to grab a rope and my hands clutched only at water. I was suffocating. I tried to yell but no sound came out. Then my eyes and nose came out of the water — but not my mouth. I flailed at the surface of the water, swallowed and choked. I tried to bring my legs up, but they hung as dead weights, paralysed and rigid. A great force was pulling me under."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9dc8eef11ee6','ch_574314f1608f','text','{"text": "I screamed, but only the water heard me. I had started on the long journey back to the bottom of the pool. I struck at the water as I went down, expending my strength as one in a nightmare fights an irresistible force. I had lost all my breath. My lungs ached, my head throbbed. I was getting dizzy. But I remembered the strategy — I would spring from the bottom of the pool and come like a cork to the surface. I would lie flat on the water, strike out with my arms, and thrash with my legs."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c458ef87f6d','ch_574314f1608f','text','{"text": "Then I would get to the edge of the pool and be safe. I went down, down, endlessly. I opened my eyes. Nothing but water with a yellow glow — dark water that one could not see through. And then sheer, stark terror seized me, terror that knows no understanding, terror that knows no control, terror that no one can understand who has not experienced it. I was shrieking under water. I was paralysed under water — stiff, rigid with fear. Even the screams in my throat were frozen."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8109b97ccb15','ch_574314f1608f','text','{"text": "Only my heart, and the pounding in my head, said that I was still alive. And then in the midst of the terror came a touch of reason. I must remember to jump when I hit the bottom. At last I felt the tiles under me. My toes reached out as if to grab them. I jumped with everything I had. But the jump made no difference. The water was still around me. I looked for ropes, ladders, water wings. Nothing but water. A mass of yellow water held me."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_415347b664bd','ch_574314f1608f','text','{"text": "Stark terror took an even deeper hold on me, like a great charge of electricity. I shook and trembled with fright. My arms wouldn’t move. My legs wouldn’t move. I tried to call for help, to call for mother. Nothing happened. And then, strangely, there was light. I was coming out of the awful yellow water. At least my eyes were. My nose was almost out too. Then I started down a third time. I sucked for air and got water. The yellowish light was going out. Then all effort ceased. I relaxed."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc6ff02ee334','ch_574314f1608f','text','{"text": "Even my legs felt limp;"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f9405a99b7c','ch_574314f1608f','text','{"text": "and a blackness swept over my brain. It wiped out fear;"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_544e722d317d','ch_574314f1608f','text','{"text": "it wiped out terror. There was no more panic. It was quiet and peaceful. Nothing to be afraid of. This is nice... to be drowsy... to go to sleep... no need to jump... too tired to jump... it’s nice to be carried gently... to float along in space... tender arms around me... tender arms like Mother’s... now I must go to sleep... I crossed to oblivion, and the curtain of life fell."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22c255479c01','ch_574314f1608f','text','{"text": "The next I remember I was lying on my stomach beside the pool, vomiting. The chap that threw me in was saying, ‘But I was only fooling.’"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_545b40f37a06','ch_574314f1608f','text','{"text": "Someone said, ‘The kid nearly died. Be all right now. Let’s carry him to the locker room.’"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3c2ef9e42fae','ch_574314f1608f','text','{"text": "Several hours later, I walked home. I was weak and trembling. I shook and cried when I lay on my bed. I couldn’t eat that night. For days a haunting fear was in my heart. The slightest exertion upset me, making me wobbly in the knees and sick to my stomach. I never went back to the pool. I feared water. I avoided it whenever I could. A few years later when I came to know the waters of the Cascades, I wanted to get into them."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e21eec726e8','ch_574314f1608f','text','{"text": "And whenever I did — whether I was wading the Tieton or Bumping River or bathing in Warm Lake of the Goat Rocks — the terror that had seized me in the pool would come back. It would take possession of me completely. My legs would become paralysed. Icy horror would grab my heart. This handicap stayed with me as the years rolled by."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb8defc50967','ch_574314f1608f','text','{"text": "In canoes on Maine lakes fishing for landlocked salmon, bass fishing in New Hampshire, trout fishing on the Deschutes and Metolius in Oregon, fishing for salmon on the Columbia, at Bumping Lake in the Cascades — wherever I went, the haunting fear of the water followed me. It ruined my fishing trips;"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0447b9bbddaf','ch_574314f1608f','text','{"text": "deprived me of the joy of canoeing, boating, and swimming. I used every way I knew to overcome this fear, but it held me firmly in its grip."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0fc540d96dc','ch_574314f1608f','text','{"text": "Finally, one October, I decided to get an instructor and learn to swim. I went to a pool and practiced five days a week, an hour each day. The instructor put a belt around me. A rope attached to the belt went through a pulley that ran on an overhead cable. He held on to the end of the rope, and we went back and forth, back and forth across the pool, hour after hour, day after day, week after week. On each trip across the pool a bit of the panic seized me."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_593c94d8242b','ch_574314f1608f','text','{"text": "Each time the instructor relaxed his hold on the rope and I went under, some of the old terror returned and my legs froze. It was three months before the tension began to slack. Then he taught me to put my face under water and exhale, and to raise my nose and inhale. I repeated the exercise hundreds of times. Bit by bit I shed part of the panic that seized me when my head went under water. Next he held me at the side of the pool and had me kick with my legs. For weeks I did just that."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4520e7f3d0ba','ch_574314f1608f','text','{"text": "At first my legs refused to work. But they gradually relaxed;"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35f9ccb9d0e3','ch_574314f1608f','text','{"text": "and finally I could command them. Thus, piece by piece, he built a swimmer. And when he had perfected each piece, he put them together into an integrated whole. In April he said, ‘Now you can swim. Dive off and swim the length of the pool, crawl stroke.’"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1bedd959fa6d','ch_574314f1608f','text','{"text": "I did. The instructor was finished. But I was not finished. I still wondered if I would be terror-stricken when I was alone in the pool. I tried it. I swam the length up and down. Tiny vestiges of the old terror would return. But now I could frown and say to that terror, ‘Trying to scare me, eh? Well, here’s to you! Look!’ And off I’d go for another length of the pool. This went on until July. But I was still not satisfied. I was not sure that all the terror had left."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_675612bde471','ch_574314f1608f','text','{"text": "So I went to Lake Wentworth in New Hampshire, dived off a dock at Triggs Island, and swam two miles across the lake to Stamp Act Island. I swam the crawl, breast stroke, side stroke, and back stroke. Only once did the terror return. When I was in the middle of the lake, I put my face under and saw nothing but bottomless water. The old sensation returned in miniature. I laughed and said, ‘Well, Mr Terror, what do you think you can do to me?’ It fled and I swam on. Yet I had residual doubts."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c548d8d300f','ch_574314f1608f','text','{"text": "At my first opportunity I hurried west, went up the Tieton to Conrad Meadows, up the Conrad Creek Trail to Meade Glacier, and camped in the high meadow by the side of Warm Lake. The next morning I stripped, dived into the lake, and swam across to the other shore and back — just as Doug Corpron used to do. I shouted with joy, and Gilbert Peak returned the echo. I had conquered my fear of water."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e27781b7a6c6','ch_574314f1608f','text','{"text": "The experience had a deep meaning for me, as only those who have known stark terror and conquered it can appreciate. In death there is peace. There is terror only in the fear of death, as Roosevelt knew when he said, ‘All we have to fear is fear itself.’"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d8a0ef680c18','ch_574314f1608f','text','{"text": "Because I had experienced both the sensation of dying and the terror that fear of it can produce, the will to live somehow grew in intensity. At last I felt released — free to walk the trails and climb the peaks and to brush aside fear."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f409d9e204c','ch_574314f1608f','list','{"ordered": false, "items": ["William Douglas"]}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a5cf65aaaf5','ch_574314f1608f','text','{"text": "About the author"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_850640f242dc','ch_574314f1608f','text','{"text": "William Douglas (1898-1980) was born in Maine, Minnesota. After graduating with a Bachelors of Arts in English and Economics, he spent two years teaching high school in Yakima."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_743a76e3ecd5','ch_574314f1608f','text','{"text": "However, he got tired of this and decided to pursue a legal career. He met Franklin D. Roosevelt at Yale and became an adviser and friend to the President. Douglas was a leading advocate of individual rights. He retired in 1975 with a term lasting thirty-six years and remains the longest-serving Justice in the history of the court. The following excerpt is taken from Of Men and Mountains by William O. Douglas. It reveals how as a young boy William Douglas nearly drowned in a swimming pool."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dcabfacec0f3','ch_574314f1608f','text','{"text": "In this essay he talks about his fear of water and thereafter, how he finally overcame it. Notice how the autobiographical part of the selection is used to support his discussion of fear."}',35);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_2f831f024227','bk_ncert_english','12-25-the-rattrap','12.25 The Rattrap',NULL,'public',97,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e434f81825b0','ch_2f831f024227','text','{"text": "Once upon a time there was a man who went around selling small rattraps of wire."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd9a74bc2fce','ch_2f831f024227','text','{"text": "He made them himself at odd moments, from the material he got by begging in the stores or at the big farms. But even so, the business was not especially profitable, so he had to resort to both begging and petty thievery to keep body and soul together. Even so, his clothes were in rags, his cheeks were sunken, and hunger gleamed in his eyes. No one can imagine how sad and monotonous life can appear to such a vagabond, who plods along the road, left to his own meditations."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3fa59a40585','ch_2f831f024227','text','{"text": "But one day this man had fallen into a line of thought, which really seemed to him entertaining. He had naturally been thinking of his rattraps when suddenly he was struck by the idea that the whole world about him — the whole world with its lands and seas, its cities and villages — was nothing but a big rattrap. It had never existed for any other purpose than to set baits for people."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3861923df5a','ch_2f831f024227','text','{"text": "It offered riches and joys, shelter and food, heat and clothing, exactly as the rattrap offered cheese and pork, and as soon as anyone let himself be tempted to touch the bait, it closed in on him, and then everything came to an end. The world had, of course, never been very kind to him, so it gave him unwonted joy to think ill of it in this way."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_684984edb6bb','ch_2f831f024227','text','{"text": "It became a cherished pastime of his, during many dreary ploddings, to think of people he knew who had let themselves be caught in the dangerous snare, and of others who were still circling around the bait. One dark evening as he was trudging along the road he caught sight of a little gray cottage by the roadside, and he knocked on the door to ask shelter for the night. Nor was he refused."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db0ab1e71cd5','ch_2f831f024227','text','{"text": "Instead of the sour faces which ordinarily met him, the owner, who was an old man without wife or child, was happy to get someone to talk to in his loneliness. Immediately he put the porridge pot on the fire and gave him supper;"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b02b04acaf2','ch_2f831f024227','text','{"text": "then he carved off such a big slice from his tobacco roll that it was enough both for the stranger’s pipe and his own. Finally he got out an old pack of cards and played"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dedf2bfe3a34','ch_2f831f024227','text','{"text": "‘mjolis’ with his guest until bedtime. The old man was just as generous with his confidences as with his porridge and tobacco. The guest was informed at once that in his days of prosperity his host had been a crofter at Ramsjo Ironworks and had worked on the land. Now that he was no longer able to do day labour, it was his cow which supported him. Yes, that bossy was extraordinary. She could give milk for the creamery every day, and last month he had received all of thirty kronor in payment."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_011302dacdb4','ch_2f831f024227','text','{"text": "The stranger must have seemed incredulous, for the old man got up and went to the window, took down a leather pouch which hung on a nail in the very window frame, and picked out three wrinkled ten-kronor bills. These he held up before the eyes of his guest, nodding knowingly, and then stuffed them back into the pouch. The next day both men got up in good season."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_23ebe837d194','ch_2f831f024227','text','{"text": "The crofter was in a hurry to milk his cow, and the other man probably thought he should not stay in bed when the head of the house had gotten up. They left the cottage at the same time. The crofter locked the door and put the key in his pocket. The man with the rattraps said good bye and thank you, and thereupon each went his own way. But half an hour later the rattrap peddler stood again before the door. He did not try to get in, however."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_516941be940b','ch_2f831f024227','text','{"text": "He only went up to the window, smashed a pane, stuck in his hand, and got hold of the pouch with the thirty kronor. He took the money and thrust it into his own pocket. Then he hung the leather pouch very carefully back in its place and went away. As he walked along with the money in his pocket he felt quite pleased with his smartness. He realised, of course, that at first he dared not continue on the public highway, but must turn off the road, into the woods."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fea4dc4ad80f','ch_2f831f024227','text','{"text": "During the first hours this caused him no difficulty. Later in the day it became worse, for it was a big and confusing forest which he had gotten into. He tried, to be sure, to walk in a definite direction, but the paths twisted back and forth so strangely! He walked and walked without coming to the end of the wood, and finally he realised that he had only been walking around in the same part of the forest. All at once he recalled his thoughts about the world and the rattrap."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa248821ed1b','ch_2f831f024227','text','{"text": "Now his own turn had come. He had let himself be fooled by a bait and had been caught. The whole forest, with its trunks and branches, its thickets and fallen logs, closed in upon him like an impenetrable prison from which he could never escape. It was late in December. Darkness was already descending over the forest. This increased the danger, and increased also his gloom and despair."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f20fe4b90686','ch_2f831f024227','text','{"text": "Finally he saw no way out, and he sank down on the ground, tired to death, thinking that his last moment had come. But just as he laid his head on the ground, he heard a sound—a hard regular thumping. There was no doubt as to what that was. He raised himself."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8122dfefa13f','ch_2f831f024227','text','{"text": "‘‘Those are the hammer strokes from an iron mill’"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_066a808a6235','ch_2f831f024227','text','{"text": "’, he thought."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bddc03afbb3f','ch_2f831f024227','text','{"text": "‘‘There must be people near by’"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5753f088b546','ch_2f831f024227','text','{"text": "’. He summoned all his strength, got up, and staggered in the direction of the sound. The Ramsjo Ironworks, which are now closed down, were, not so long ago, a large plant, with smelter, rolling mill, and forge. In the summertime long lines of heavily loaded barges and scows slid down the canal, which led to a large inland lake, and in the wintertime the roads near the mill were black from all the coal dust which sifted down from the big charcoal crates."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91141dd9d2aa','ch_2f831f024227','text','{"text": "During one of the long dark evenings just before Christmas, the master smith and his helper sat in the dark forge near the furnace waiting for the pig iron, which had been put in the fire, to be ready to put on the anvil. Every now and then one of them got up to stir the glowing mass with a long iron bar, returning in a few moments, dripping with perspiration, though, as was the custom, he wore nothing but a long shirt and a pair of wooden shoes."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0e67f0d1b9f','ch_2f831f024227','text','{"text": "All the time there were many sounds to be heard in the forge. The big bellows groaned and the burning coal cracked. The fire boy shovelled charcoal into the maw of the furnace with a great deal of clatter. Outside roared the waterfall, and a sharp north wind whipped the rain against the brick-tiled roof. It was probably on account of all this noise that the blacksmith did not notice that a man had opened the gate and entered the forge, until he stood close up to the furnace."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d4dd12f9ae92','ch_2f831f024227','text','{"text": "Surely it was nothing unusual for poor vagabonds without any better shelter for the night to be attracted to the forge by the glow of light which escaped through the sooty panes, and to come in to warm themselves in front of the fire. The blacksmiths glanced only casually and indifferently at the intruder. He looked the way people of his type usually did, with a long beard, dirty, ragged, and with a bunch of rattraps dangling on his chest."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00ca419478df','ch_2f831f024227','text','{"text": "He asked permission to stay, and the master blacksmith nodded a haughty consent without honouring him with a single word. The tramp did not say anything, either. He had not come there to talk but only to warm himself and sleep. In those days the Ramsjo iron mill was owned by a very prominent ironmaster, whose greatest ambition was to ship out good iron to the market."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_365a61ff4092','ch_2f831f024227','text','{"text": "He watched both night and day to see that the work was done as well as possible, and at this very moment he came into the forge on one of his nightly rounds of inspection. Naturally the first thing he saw was the tall ragamuffin who had eased his way so close to the furnace that steam rose from his wet rags. The ironmaster did not follow the example of the blacksmiths, who had hardly deigned to look at the stranger."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba9522169284','ch_2f831f024227','text','{"text": "He walked close up to him, looked him over very carefully, then tore off his slouch hat to get a better view of his face."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b94f3cc4667','ch_2f831f024227','text','{"text": "‘‘But of course it is you, Nils Olof!’"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7560a865c956','ch_2f831f024227','text','{"text": "’ he said."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d5bd7ca44c5','ch_2f831f024227','text','{"text": "‘How you do look!’ The man with the rattraps had never before seen the ironmaster at Ramsjo and did not even know what his name was."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7537c8877303','ch_2f831f024227','text','{"text": "But it occurred to him that if the fine gentleman thought he was an old acquaintance, he might perhaps throw him a couple of kronor. Therefore he did not want to undeceive him all at once."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75a058c57819','ch_2f831f024227','text','{"text": "‘‘Yes, God knows things have gone downhill with me’"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b4815dbacab','ch_2f831f024227','text','{"text": "’, he said."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fc32b5d8243b','ch_2f831f024227','text','{"text": "‘‘You should not have resigned from the regiment’"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3fe03e1627b','ch_2f831f024227','text','{"text": "’, said the ironmaster."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c25de886ef61','ch_2f831f024227','text','{"text": "‘‘That was the mistake. If only I had still been in the service at the time, it never would have happened. Well, now of course you will come home with me.’"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e39fa51328e6','ch_2f831f024227','text','{"text": "’ To go along up to the manor house and be received by the owner like an old regimental comrade — that, however, did not please the tramp."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f8ebb5e7990d','ch_2f831f024227','text','{"text": "‘‘No, I couldn’"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2d3b8719f106','ch_2f831f024227','text','{"text": "t think of it!’’ he said, looking quite alarmed. He thought of the thirty kronor. To go up to the manor house would be like throwing himself voluntarily into the lion’s den. He only wanted a chance to sleep here in the forge and then sneak away as inconspicuously as possible. The ironmaster assumed that he felt embarrassed because of his miserable clothing."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04880ef449b0','ch_2f831f024227','text','{"text": "‘‘Please don’"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43ce4e6fd927','ch_2f831f024227','text','{"text": "t think that I have such a fine home that you cannot show yourself there’’, He said..."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ae3f89b505c','ch_2f831f024227','text','{"text": "‘‘Elizabeth is dead, as you may already have heard. My boys are abroad, and there is no one at home except my oldest daughter and myself. We were just saying that it was too bad we didn’"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dcd583e953a5','ch_2f831f024227','text','{"text": "t have any company for Christmas. Now come along with me and help us make the Christmas food disappear a little faster.’"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc98a39a7950','ch_2f831f024227','text','{"text": "But the stranger said no, and no, and again no, and the ironmaster saw that he must give in."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac1892c1d31a','ch_2f831f024227','text','{"text": "‘‘It looks as though Captain von Stahle preferred to stay with you tonight, Stjernstrom’"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f64d0a85963a','ch_2f831f024227','text','{"text": "’, he said to the master blacksmith, and turned on his heel. But he laughed to himself as he went away, and the blacksmith, who knew him, understood very well that he had not said his last word. It was not more than half an hour before they heard the sound of carriage wheels outside the forge, and a new guest came in, but this time it was not the ironmaster. He had sent his daughter, apparently hoping that she would have better powers of persuasion than he himself."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6af6ff94025b','ch_2f831f024227','text','{"text": "She entered, followed by a valet, carrying on his arm a big fur coat. She was not at all pretty, but seemed modest and quite shy. In the forge everything was just as it had been earlier in the evening. The master blacksmith and his apprentice still sat on their bench, and iron and charcoal still glowed in the furnace. The stranger had stretched himself out on the floor and lay with a piece of pig iron under his head and his hat pulled down over his eyes."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_13b98c4ff4cf','ch_2f831f024227','text','{"text": "As soon as the young girl caught sight of him, she went up and lifted his hat. The man was evidently used to sleeping with one eye open. He jumped up abruptly and seemed to be quite frightened."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0b1291158e8','ch_2f831f024227','text','{"text": "‘‘My name is Edla Willmansson,’"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71d8ccdc6294','ch_2f831f024227','text','{"text": "’ said the young girl."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f609fb954381','ch_2f831f024227','text','{"text": "‘‘My father came home and said that you wanted to sleep here in the forge tonight, and then I asked permission to come and bring you home to us. I am so sorry, Captain, that you are having such a hard time.’"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d1b8683a9309','ch_2f831f024227','text','{"text": "’ She looked at him compassionately, with her heavy eyes, and then she noticed that the man was afraid."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3cff8afcb98','ch_2f831f024227','text','{"text": "‘‘Either he has stolen something or else he has escaped from, jail’"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_454694a8e2c9','ch_2f831f024227','text','{"text": "’, she thought, and added quickly, ‘You may be sure, Captain, that you will be allowed to leave us just as freely as you came. Only please stay with us over Christmas Eve.’"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3148d9c4ff2b','ch_2f831f024227','text','{"text": "’ She said this in such a friendly manner that the rattrap peddler must have felt confidence in her."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a5e53e62212','ch_2f831f024227','text','{"text": "‘‘It would never have occurred to me that you would bother with me yourself, miss,’"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1bca116e6107','ch_2f831f024227','text','{"text": "’ he said."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fc6693a0c5f6','ch_2f831f024227','text','{"text": "‘’I will come at once.’"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_627aeff2269f','ch_2f831f024227','text','{"text": "’ He accepted the fur coat, which the valet handed him with a deep bow, threw it over his rags, and followed the young lady out to the carriage, without granting the astonished blacksmiths so much as a glance. But while he was riding up to the manor house he had evil forebodings."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c15bf7902645','ch_2f831f024227','text','{"text": "‘‘Why the devil did I take that fellow’"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4acb00fa07c5','ch_2f831f024227','text','{"text": "s money?’’ he thought."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b264c8d61479','ch_2f831f024227','text','{"text": "‘‘Now I am sitting in the trap and will never get out of it.’"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3345adf82382','ch_2f831f024227','text','{"text": "’ The next day was Christmas Eve, and when the ironmaster came into the dining room for breakfast he probably thought with satisfaction of his old regimental comrade whom he had run across so unexpectedly."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96c77963d6d2','ch_2f831f024227','text','{"text": "‘First of all we must see to it that he gets a little flesh on his bones,’ he said to his daughter, who was busy at the table."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_36f65aa98025','ch_2f831f024227','text','{"text": "‘And then we must see that he gets something else to do than to run around the country selling rattraps.’"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d537c9c6b4c','ch_2f831f024227','text','{"text": "‘It is queer that things have gone downhill with him as badly as that,’ said the daughter."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e445a9775497','ch_2f831f024227','text','{"text": "‘Last night I did not think there was anything about him to show that he had once been an educated man.’"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_efef150df581','ch_2f831f024227','text','{"text": "‘You must have patience, my little girl,’ said the father."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05990ea43211','ch_2f831f024227','text','{"text": "‘As soon as he gets clean and dressed up, you will see something different. Last night he was naturally embarrassed. The tramp manners will fall away from him with the tramp clothes.’"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f90a026243f5','ch_2f831f024227','text','{"text": "Just as he said this the door opened and the stranger entered. Yes, now he was truly clean and well dressed. The valet had bathed him, cut his hair, and shaved him. Moreover he was dressed in a good-looking suit of clothes which belonged to the ironmaster. He wore a white shirt and a starched collar and whole shoes. But although his guest was now so well groomed, the ironmaster did not seem pleased."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_48eaa2bda105','ch_2f831f024227','text','{"text": "He looked at him with puckered brow, and it was easy to understand that when he had seen the strange fellow in the uncertain reflection from the furnace he might have made a mistake, but that now, when he stood there in broad daylight, it was impossible to mistake him for an old acquaintance."}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22b673f29175','ch_2f831f024227','text','{"text": "‘What does this mean?’ he thundered."}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_19d7fe849aed','ch_2f831f024227','text','{"text": "The stranger made no attempt to dissimulate. He saw at once that the splendour had come to an end."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e2683ebbb25','ch_2f831f024227','text','{"text": "‘It is not my fault, sir,’ he said."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b57180b985a','ch_2f831f024227','text','{"text": "‘I never pretended to be anything but a poor trader, and I pleaded and begged to be allowed to stay in the forge. But no harm has been done. At worst I can put on my rags again and go away’."}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_786790691a17','ch_2f831f024227','text','{"text": "‘Well,’ said the ironmaster, hesitating a little, ‘it was not quite honest, either. You must admit that, and I should not be surprised if the sheriff would like to have something to say in the matter.’"}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_260e9fa938f8','ch_2f831f024227','text','{"text": "The tramp took a step forward and struck the table with his fist."}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22b020f1c3ec','ch_2f831f024227','text','{"text": "‘Now I am going to tell you, Mr Ironmaster, how things are,’ he said."}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cafdbd5a48b7','ch_2f831f024227','text','{"text": "‘This whole world is nothing but a big rattrap. All the good things that are offered to you are nothing but cheese rinds and bits of pork, set out to drag a poor fellow into trouble. And if the sheriff comes now and locks me up for this, then you, Mr Ironmaster, must remember that a day may come when you yourself may want to get a big piece of pork, and then you will get caught in the trap.’"}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7731aa035c23','ch_2f831f024227','text','{"text": "The ironmaster began to laugh."}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_23c1e626910b','ch_2f831f024227','text','{"text": "‘That was not so badly said, my good fellow. Perhaps we should let the sheriff alone on Christmas Eve. But now get out of here as fast as you can.’"}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f4e61a28531','ch_2f831f024227','text','{"text": "But just as the man was opening the door, the daughter said, ‘I think he ought to stay with us today. I don’t want him to go.’"}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02a1fee4ccd5','ch_2f831f024227','text','{"text": "And with that she went and closed the door."}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_36e66362c729','ch_2f831f024227','text','{"text": "‘What in the world are you doing?’ said the father."}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d9d81c4e75e','ch_2f831f024227','text','{"text": "The daughter stood there quite embarrassed and hardly knew what to answer. That morning she had felt so happy when she thought how homelike and Christmassy she was going to make things for the poor hungry wretch. She could not get away from the idea all at once, and that was why she had interceded for the vagabond."}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7810c1078b9a','ch_2f831f024227','text','{"text": "‘I am thinking of this stranger here,’ said the young girl."}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b9a16b91d406','ch_2f831f024227','text','{"text": "‘He walks and walks the whole year long, and there is probably not a single place in the whole country where he is welcome and can feel at home. Wherever he turns he is chased away. Always he is afraid of being arrested and cross-examined. I should like to have him enjoy a day of peace with us here — just one in the whole year.’"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_610aab9bc0c2','ch_2f831f024227','text','{"text": "The ironmaster mumbled something in his beard. He could not bring himself to oppose her."}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0efd01ee4ad2','ch_2f831f024227','text','{"text": "‘It was all a mistake, of course,’ she continued."}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f02af67b9c2d','ch_2f831f024227','text','{"text": "‘But anyway I don’t think we ought to chase away a human being whom we have asked to come here, and to whom we have promised Christmas cheer.’"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c145336c51dd','ch_2f831f024227','text','{"text": "‘You do preach worse than a parson,’ said the ironmaster."}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3f1083ece94','ch_2f831f024227','text','{"text": "‘I only hope you won’t have to regret this.’"}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8fdddee96726','ch_2f831f024227','text','{"text": "The young girl took the stranger by the hand and led him up to the table."}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91bab54b9370','ch_2f831f024227','text','{"text": "‘Now sit down and eat,’ she said, for she could see that her father had given in."}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1aaef89f7eda','ch_2f831f024227','text','{"text": "The man with the rattraps said not a word;"}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_091ce5ea43e5','ch_2f831f024227','text','{"text": "he only sat down and helped himself to the food. Time after time he looked at the young girl who had interceded for him. Why had she done it? What could the crazy idea be? After that, Christmas Eve at Ramsjo passed just as it always had. The stranger did not cause any trouble because he did nothing but sleep. The whole forenoon he lay on the sofa in one of the guest rooms and slept at one stretch."}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aee424687265','ch_2f831f024227','text','{"text": "At noon they woke him up so that he could have his share of the good Christmas fare, but after that he slept again. It seemed as though for many years he had not been able to sleep as quietly and safely as here at Ramsjo. In the evening, when the Christmas tree was lighted, they woke him up again, and he stood for a while in the drawing room, blinking as though the candlelight hurt him, but after that he disappeared again. Two hours later he was aroused once more."}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_666e8db45e31','ch_2f831f024227','text','{"text": "He then had to go down into the dining room and eat the Christmas fish and porridge."}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fe5efc8e4531','ch_2f831f024227','text','{"text": "As soon as they got up from the table he went around to each one present and said thank you and good night, but when he came to the young girl she gave him to understand that it was her father’s intention that the suit which he wore was to be a Christmas present — he did not have to return it;"}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e51a25f1c8e','ch_2f831f024227','text','{"text": "and if he wanted to spend next Christmas Eve in a place where he could rest in peace, and be sure that no evil would befall him, he would be welcomed back again."}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bee923ee96c3','ch_2f831f024227','text','{"text": "The man with the rattraps did not answer anything to this. He only stared at the young girl in boundless amazement. The next morning the ironmaster and his daughter got up in good season to go to the early Christmas service. Their guest was still asleep, and they did not disturb him. When, at about ten o’clock, they drove back from the church, the young girl sat and hung her head even more dejectedly than usual."}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4a218fb8c6bd','ch_2f831f024227','text','{"text": "At church she had learned that one of the old crofters of the ironworks had been robbed by a man who went around selling rattraps."}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c3b6ae274498','ch_2f831f024227','text','{"text": "‘Yes, that was a fine fellow you let into the house,’ said her father."}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_33bd42ffe80c','ch_2f831f024227','text','{"text": "‘I only wonder how many silver spoons are left in the cupboard by this time.’"}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d9ea0913669e','ch_2f831f024227','text','{"text": "The wagon had hardly stopped at the front steps when the ironmaster asked the valet whether the stranger was still there. He added that he had heard at church that the man was a thief. The valet answered that the fellow had gone and that he had not taken anything with him at all. On the contrary, he had left behind a little package which Miss Willmansson was to be kind enough to accept as a Christmas present."}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6e7a7356cee2','ch_2f831f024227','text','{"text": "The young girl opened the package, which was so badly done up that the contents came into view at once. She gave a little cry of joy. She found a small rattrap, and in it lay three wrinkled ten kronor notes. But that was not all. In the rattrap lay also a letter written in large, jagged characters —"}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f1e07ae48d1','ch_2f831f024227','text','{"text": "‘Honoured and noble Miss, ‘Since you have been so nice to me all day long, as if I was a captain, I want to be nice to you, in return, as if I was a real captain — for I do not want you to be embarrassed at this Christmas season by a thief;"}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3324cb91e825','ch_2f831f024227','text','{"text": "but you can give back the money to the old man on the roadside, who has the money pouch hanging on the window frame as a bait for poor wanderers."}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f11c9b0186d','ch_2f831f024227','text','{"text": "‘The rattrap is a Christmas present from a rat who would have been caught in this world’s rattrap if he had not been raised to captain, because in that way he got power to clear himself."}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_73c13a40d6e6','ch_2f831f024227','text','{"text": "‘Written with friendship and high regard, ‘Captain von Stahle.’"}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a2bcd4f232c8','ch_2f831f024227','list','{"ordered": false, "items": ["Selma Lagerlof"]}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90dd1c1a477a','ch_2f831f024227','text','{"text": "About the author"}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1c5948611d1f','ch_2f831f024227','text','{"text": "Selma Lagerlof (1858-1940) was a Swedish writer whose stories have been translated into many languages."}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_12d958979cba','ch_2f831f024227','text','{"text": "A universal theme runs through all of them — a belief that the essential goodness in a human being can be awakened through understanding and love. This story is set amidst the mines of Sweden, rich in iron ore, which figure large in the history and legends of that country. The story is told somewhat in the manner of a fairy tale."}',111);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_20580fff771a','bk_ncert_english','12-26-indigo','12.26 Indigo',NULL,'public',98,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a354492debf5','ch_20580fff771a','text','{"text": "When I first visited Gandhi in 1942 at his ashram in Sevagram, in central India, he said, ‘I will tell you how it happened that I decided to urge the departure of the British. It was in 1917.’"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e6ff4af0c88','ch_20580fff771a','text','{"text": "He had gone to the December 1916 annual convention of the Indian National Congress party in Lucknow. There were 2,301 delegates and many visitors. During the proceedings, Gandhi recounted, ‘a peasant came up to me looking like any other peasant in India, poor and emaciated, and said, ‘I am Rajkumar Shukla. I am from Champaran, and I want you to come to my district’!’’ Gandhi had never heard of the place. It was in the foothills of the towering Himalayas, near the kingdom of Nepal."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_adb4c8ed3394','ch_20580fff771a','text','{"text": "Under an ancient arrangement, the Champaran peasants were sharecroppers. Rajkumar Shukla was one of them. He was illiterate but resolute. He had come to the Congress session to complain about the injustice of the landlord system in Bihar, and somebody had probably said, ‘Speak to Gandhi.’"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_385e3ba6d364','ch_20580fff771a','text','{"text": "Gandhi told Shukla he had an appointment in Cawnpore and was also committed to go to other parts of India. Shukla accompanied him everywhere. Then Gandhi returned to his ashram near Ahmedabad. Shukla followed him to the ashram. For weeks he never left Gandhi’s side."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f56628d1eca1','ch_20580fff771a','text','{"text": "‘Fix a date,’ he begged."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b6e60a9616e2','ch_20580fff771a','text','{"text": "Impressed by the sharecropper’s tenacity and story Gandhi said, ‘‘I have to be in Calcutta on such-and-such a date. Come and meet me and take me from there.’"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a9654bf3145','ch_20580fff771a','text','{"text": "Months passed. Shukla was sitting on his haunches at the appointed spot in Calcutta when Gandhi arrived;"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a4bebd9573a6','ch_20580fff771a','text','{"text": "he waited till Gandhi was free. Then the two of them boarded a train for the city of Patna in Bihar. There Shukla led him to the house of a lawyer named Rajendra Prasad who later became President of the Congress party and of India. Rajendra Prasad was out of town, but the servants knew Shukla as a poor yeoman who pestered their master to help the indigo sharecroppers."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75a7e2d76b4f','ch_20580fff771a','text','{"text": "So they let him stay on the grounds with his companion, Gandhi, whom they took to be another peasant. But Gandhi was not permitted to draw water from the well lest some drops from his bucket pollute the entire source;"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4265943d8481','ch_20580fff771a','text','{"text": "how did they know that he was not an untouchable? Gandhi decided to go first to Muzzafarpur, which was en route to Champaran, to obtain more complete information about conditions than Shukla was capable of imparting. He accordingly sent a telegram to Professor J.B."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_14f4c2ca0be0','ch_20580fff771a','text','{"text": "Kripalani, of the Arts College in Muzzafarpur, whom he had seen at Tagore’s Shantiniketan school. The train arrived at midnight, 15 April 1917. Kripalani was waiting at the station with a large body of students. Gandhi stayed there for two days in the home of Professor Malkani, a teacher in a government school."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5d02f81b971','ch_20580fff771a','text','{"text": "‘‘It was an extraordinary thing ‘in those days,’"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1ac3703ecd8','ch_20580fff771a','text','{"text": "’ Gandhi commented, ‘for a government professor to harbour a man like me’. In smaller localities, the Indians were afraid to show sympathy for advocates of home-rule. The news of Gandhi’s advent and of the nature of his mission spread quickly through Muzzafarpur and to Champaran. Sharecroppers from Champaran began arriving on foot and by conveyance to see their champion."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59740c83bc9f','ch_20580fff771a','text','{"text": "Muzzafarpur lawyers called on Gandhi to brief him;"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b584d4a6b35f','ch_20580fff771a','text','{"text": "they frequently represented peasant groups in court;"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abc60dfa6132','ch_20580fff771a','text','{"text": "they told him about their cases and reported the size of their fee. Gandhi chided the lawyers for collecting big fee from the sharecroppers. He said, ‘‘I have come to the conclusion that we should stop going to law courts. Taking such cases to the courts does litte good. Where the peasants are so crushed and fear-stricken, law courts are useless."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d57e5f1af44','ch_20580fff771a','text','{"text": "The real relief for them is to be free from fear.’"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_55c49abb3dda','ch_20580fff771a','text','{"text": "’ Most of the arable land in the Champaran district was divided into large estates owned by Englishmen and worked by Indian tenants. The chief commercial crop was indigo. The landlords compelled all tenants to plant three twentieths or 15 per cent of their holdings with indigo and surrender the entire indigo harvest as rent. This was done by long-term contract. Presently, the landlords learned that Germany had developed synthetic indigo."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a1d1ed3ac10','ch_20580fff771a','text','{"text": "They, thereupon, obtained agreements from the sharecroppers to pay them compensation for being released from the 15 per cent arrangement. The sharecropping arrangement was irksome to the peasants, and many signed willingly. Those who resisted, engaged lawyers;"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_15b9e2c508c7','ch_20580fff771a','text','{"text": "the landlords hired thugs. Meanwhile, the information about synthetic indigo reached the illiterate peasants who had signed, and they wanted their money back. At this point Gandhi arrived in Champaran. He began by trying to get the facts."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_881b78231636','ch_20580fff771a','text','{"text": "First he visited the secretary of the British landlord’s association. The secretary told him that they could give no information to an outsider. Gandhi answered that he was no outsider. Next, Gandhi called on the British official commissioner of the Tirhut division in which the Champaran district lay."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b272de41d36b','ch_20580fff771a','text','{"text": "‘‘The commissioner,’"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_adda146d73e7','ch_20580fff771a','text','{"text": "’ Gandhi reports, ‘‘proceeded to bully me and advised me forthwith to leave Tirhut.’"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3bd369f492f4','ch_20580fff771a','text','{"text": "’ Gandhi did not leave. Instead he proceeded to Motihari, the capital of Champaran. Several lawyers accompanied him. At the railway station, a vast multitude greeted Gandhi. He went to a house and, using it as headquarters, continued his investigations. A report came in that a peasant had been maltreated in a nearby village. Gandhi decided to go and see;"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb90a388f17c','ch_20580fff771a','text','{"text": "the next morning he started out on the back of an elephant."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c651e87be4b6','ch_20580fff771a','text','{"text": "He had not proceeded far when the police superintendent’s messenger overtook him and ordered him to return to town in his carriage. Gandhi complied. The messenger drove Gandhi home where he served him with an official notice to quit Champaran immediately. Gandhi signed a receipt for the notice and wrote on it that he would disobey the order. In consequence, Gandhi received a summons to appear in court the next day. All night Gandhi remained awake."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a9af9abc32b','ch_20580fff771a','text','{"text": "He telegraphed Rajendra Prasad to come from Bihar with influential friends. He sent instructions to the ashram. He wired a full report to the Viceroy. Morning found the town of Motihari black with peasants. They did not know Gandhi’s record in South Africa. They had merely heard that a Mahatma who wanted to help them was in trouble with the authorities. Their spontaneous demonstration, in thousands, around the courthouse was the beginning of their liberation from fear of the British."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8001098c3e9','ch_20580fff771a','text','{"text": "The officials felt powerless without Gandhi’s cooperation. He helped them regulate the crowd. He was polite and friendly. He was giving them concrete proof that their might, hitherto dreaded and unquestioned, could be challenged by Indians. The government was baffled. The prosecutor requested the judge to postpone the trial. Apparently, the authorities wished to consult their superiors. Gandhi protested against the delay. He read a statement pleading guilty."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_172122f13f33','ch_20580fff771a','text','{"text": "He was involved, he told the court, in a"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_163b528b28ef','ch_20580fff771a','text','{"text": "‘conflict of duties’— on the one hand, not to set a bad example as a lawbreaker;"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58ac454406b0','ch_20580fff771a','text','{"text": "on the other hand, to render the"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_874a50ddeb42','ch_20580fff771a','text','{"text": "‘humanitarian and national service’ for which he had come."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dee9d7b64566','ch_20580fff771a','text','{"text": "He disregarded the order to leave, ‘not for want of respect for lawful authority, but in obedience to the higher law of our being, the voice of conscience’. He asked the penalty due. The magistrate announced that he would pronounce sentence after a two-hour recess and asked Gandhi to furnish bail for those 120 minutes. Gandhi refused. The judge released him without bail. When the court reconvened, the judge said he would not deliver the judgment for several days."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b767ffa5f19','ch_20580fff771a','text','{"text": "Meanwhile he allowed Gandhi to remain at liberty. Rajendra Prasad, Brij Kishor Babu, Maulana Mazharul Huq and several other prominent lawyers had arrived from Bihar. They conferred with Gandhi. What would they do if he was sentenced to prison, Gandhi asked. Why, the senior lawyer replied, they had come to advise and help him;"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_317696166466','ch_20580fff771a','text','{"text": "if he went to jail there would be nobody to advise and they would go home. What about the injustice to the sharecroppers, Gandhi demanded. The lawyers withdrew to consult."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_764abf5976de','ch_20580fff771a','text','{"text": "Rajendra Prasad has recorded the upshot of their consultations —"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b7d1cb0c02c','ch_20580fff771a','text','{"text": "‘They thought, amongst themselves, that Gandhi was totally a stranger, and yet he was prepared to go to prison for the sake of the peasants;"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb28fae52878','ch_20580fff771a','text','{"text": "if they, on the other hand, being not only residents of the adjoining districts but also those who claimed to have served these peasants, should go home, it would be shameful desertion.’"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3eb3f6c78f7d','ch_20580fff771a','text','{"text": "They accordingly went back to Gandhi and told him they were ready to follow him into jail."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b7f032e5117a','ch_20580fff771a','text','{"text": "‘‘The battle of Champaran is won,’"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f6763a0287b7','ch_20580fff771a','text','{"text": "’ he exclaimed. Then he took a piece of paper and divided the group into pairs and put down the order in which each pair was to court arrest. Several days later, Gandhi received a written communication from the magistrate informing him that the Lieutenant-Governor of the province had ordered the case to be dropped. Civil disobedience had triumphed, the first time in modern India. Gandhi and the lawyers now proceeded to conduct a far -flung inquiry into the grievances of the farmers."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58afa8e8d6e8','ch_20580fff771a','text','{"text": "Depositions by about ten thousand peasants were written down, and notes made on other evidence. Documents were collected. The whole area throbbed with the activity of the investigators and the vehement protests of the landlords. In June, Gandhi was summoned to Sir Edward Gait, the Lieutenant-Governor. Before he went he met leading associates and again laid detailed plans for civil disobedience if he should not return."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_29804a1a5f6c','ch_20580fff771a','text','{"text": "Gandhi had four protracted interviews with the Lieutenant- Governor who, as a result, appointed an official commission of inquiry into the indigo sharecroppers’ situation. The commission consisted of landlords, government officials, and Gandhi as the sole representative of the peasants. Gandhi remained in Champaran for an initial uninterrupted period of seven months and then again for several shorter visits."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8218d3d8bc0c','ch_20580fff771a','text','{"text": "The visit, undertaken casually on the entreaty of an unlettered peasant in the expectation that it would last a few days, occupied almost a year of Gandhi’s life. The official inquiry assembled a crushing mountain of evidence against the big planters, and when they saw this they agreed, in principle, to make refunds to the peasants."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_816cd3a3d675','ch_20580fff771a','text','{"text": "‘But how much must we pay?’ they asked Gandhi."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e258355ca18','ch_20580fff771a','text','{"text": "They thought he would demand repayment in full of the money which they had illegally and deceitfully extorted from the sharecroppers. He asked only 50 per cent."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac7d35504e2f','ch_20580fff771a','text','{"text": "‘There he seemed adamant,’ writes Reverend J."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf0981932607','ch_20580fff771a','text','{"text": "Z. Hodge, a British missionary in Champaran who observed the entire episode at close range."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00bce7569ff4','ch_20580fff771a','text','{"text": "‘Thinking probably that he would not give way, the representative of the planters offered to refund to the extent of 25 per cent, and to his amazement Mr. Gandhi took him at his word, thus breaking the deadlock.’"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_13ce9b972e81','ch_20580fff771a','text','{"text": "This settlement was adopted unanimously by the commission. Gandhi explained that the amount of the refund was less important than the fact that the landlords had been obliged to surrender part of the money and, with it, part of their prestige. Therefore, as far as the peasants were concerned, the planters had behaved as lords above the law. Now the peasant saw that he had rights and defenders. He learned courage. Events justified Gandhi’s position."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_48cb2bd211ba','ch_20580fff771a','text','{"text": "Within a few years the British planters abandoned their estates, which reverted to the peasants. Indigo sharecropping disappeared. Gandhi never contented himself with large political or economic solutions. He saw the cultural and social backwardness in the Champaran villages and wanted to do something about it immediately. He appealed for teachers. Mahadev Desai and Narhari Parikh, two young men who had just joined Gandhi as disciples, and their wives, volunteered for the work."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ff8c7a1ac35','ch_20580fff771a','text','{"text": "Several more came from Bombay, Poona and other distant parts of the land. Devadas, Gandhi’s youngest son, arrived from the ashram and so did Mrs. Gandhi. Primary schools were opened in six villages. Kasturbai taught the ashram rules on personal cleanliness and community sanitation. Health conditions were miserable. Gandhi got a doctor to volunteer his services for six months. Three medicines were available — castor oil, quinine and sulphur ointment."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec017d4bcd5a','ch_20580fff771a','text','{"text": "Anybody who showed a coated tongue was given a dose of castor oil;"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa0e468ec0b4','ch_20580fff771a','text','{"text": "anybody with malaria fever received quinine plus castor oil;"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_640c52393b3b','ch_20580fff771a','text','{"text": "anybody with skin eruptions received ointment plus castor oil. Gandhi noticed the filthy state of women’s clothes. He asked Kasturbai to talk to them about it. One woman took Kasturbai into her hut and said, ‘‘Look, there is no box or cupboard here for clothes. The sari I am wearing is the only one I have.’"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1fab1a706c02','ch_20580fff771a','text','{"text": "During his long stay in Champaran, Gandhi kept a long distance watch on the ashram. He sent regular instructions by mail and asked for financial accounts. Once he wrote to the residents that it was time to fill in the old latrine trenches and dig new ones otherwise the old ones would begin to smell bad. The Champaran episode was a turning-point in Gandhi’s life."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8f53b771d24','ch_20580fff771a','text','{"text": "‘‘What I did,’"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e58048326f7a','ch_20580fff771a','text','{"text": "he explained, ‘was a very ordinary thing. I declared that the British could not order me about in my own country.’"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ccb37f6d8d2c','ch_20580fff771a','text','{"text": "But Champaran did not begin as an act of defiance. It grew out of an attempt to alleviate the distress of large numbers of poor peasants. This was the typical Gandhi pattern — his politics were intertwined with the practical, day-to-day problems of the millions. His was not a loyalty to abstractions;"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c9a1237122d','ch_20580fff771a','text','{"text": "it was a loyalty to living, human beings. In everything Gandhi did, moreover, he tried to mould a new free Indian who could stand on his own feet and thus make India free."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d5011d39d33','ch_20580fff771a','text','{"text": "Early in the Champaran action, Charles Freer Andrews, the English pacifist who had become a devoted follower of the Mahatma, came to bid Gandhi farewell before going on a tour of duty to the Fiji Islands. Gandhi’s lawyer friends thought it would be a good idea for Andrews to stay in Champaran and help them. Andrews was willing if Gandhi agreed. But Gandhi was vehemently opposed. He said, ‘‘You think that in this unequal fight it would be helpful if we have an Englishman on our side."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a43fa84959a8','ch_20580fff771a','text','{"text": "This shows the weakness of your heart. The cause is just and you must rely upon yourselves to win the battle. You should not seek a prop in Mr. Andrews because he happens to be an Englishman’’."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c3f83491b528','ch_20580fff771a','text','{"text": "‘‘He had read our minds correctly,’ ’ Rajendra Prasad comments, ‘and we had no reply… Gandhi in this way taught us a lesson in self-reliance’’. Self-reliance, Indian independence and help to sharecroppers were all bound together."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6da4cfcd8d4b','ch_20580fff771a','list','{"ordered": false, "items": ["Louis Fischer"]}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_72ab35da6189','ch_20580fff771a','text','{"text": "About the author"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a43e9bc37259','ch_20580fff771a','text','{"text": "Louis Fischer (1896-1970) was born in Philadelphia. He served as a volunteer in the British Army between 1918 and 1920. Fischer made a career as a journalist and wrote for The New York Times, The Saturday Review and for European and Asian publications. He was also a member of the faculty at Princeton University. The following is an excerpt from his book- The Life of Mahatma Gandhi."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76c51c52dc19','ch_20580fff771a','text','{"text": "The book has been reviewed as one of the best books ever written on Gandhi by Times Educational Supplement."}',67);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_be990a008551','bk_ncert_english','12-27-poets-and-pancakes','12.27 Poets and Pancakes',NULL,'public',99,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7d93813b10e','ch_be990a008551','text','{"text": "Pancake was the brand name of the make-up material that Gemini Studios bought in truck-loads. Greta Garbo1 must have used it, Miss Gohar must have used it, Vyjayantimala2 must also have used it but Rati Agnihotri may not have even heard of it. The make-up department of the Gemini Studios was in the upstairs of a building that was believed to have been Robert Clive’s stables."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6eb4bbc5cb18','ch_be990a008551','text','{"text": "A dozen other buildings in the city are said to have been his residence. For his brief life and an even briefer stay in Madras, Robert Clive seems to have done a lot of moving, besides fighting some impossible battles in remote corners of India and marrying a maiden in St. Mary’s Church in Fort St. George in Madras. The make-up room had the look of a hair-cutting salon with lights at all angles around half a dozen large mirrors."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18d39efef388','ch_be990a008551','text','{"text": "They were all incandescent lights, so you can imagine the fiery misery of those subjected to make-up. The make-up department was first headed by a Bengali who became too big for a studio and left. He was succeeded by a Maharashtrian who was assisted by a Dharwar Kannadiga, an Andhra, a Madras Indian Christian, an Anglo-Burmese and the usual local Tamils. All this shows that there was a great deal of national integration long before A.I.R."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_048eb3a4ad09','ch_be990a008551','text','{"text": "and Doordarshan began broadcasting programmes on national integration. This gang of nationally integrated make-up men could turn any decent-looking person into a hideous crimson hued monster with the help of truck-loads of pancake and a number of other locally made potions and lotions. Those were the days of mainly indoor shooting, and only five per cent of the film was shot outdoors."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_23b62318797d','ch_be990a008551','text','{"text": "I suppose the sets and studio lights needed the girls and boys to be made to look ugly in order to look presentable in the movie. A strict hierarchy was maintained in the make-up department. The chief make-up man made the chief actors and actresses ugly, his senior assistant the"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf5105f40948','ch_be990a008551','text','{"text": "‘second’ hero and heroine, the junior assistant the main comedian, and so forth. The players who played the crowd were the responsibility of the office boy. (Even the make-up department of the Gemini Studio had an"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_167170bf5778','ch_be990a008551','text','{"text": "‘office boy’!) On the days when there was a crowdshooting, you could see him mixing his paint in a giant vessel and slapping it on the crowd players."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d51b40ce1de','ch_be990a008551','text','{"text": "The idea was to close every pore on the surface of the face in the process of applying make-up. He wasn’t exactly a"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7578bc28b2c3','ch_be990a008551','text','{"text": "‘boy’;"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b2da7bf144e','ch_be990a008551','text','{"text": "he was in his early forties, having entered the studios years ago in the hope of becoming a star actor or a top screen writer, director or lyrics writer. He was a bit of a poet. In those days I worked in a cubicle, two whole sides of which were French windows. (I didn’t know at that time they were called French windows.) Seeing me sitting at my desk tearing up newspapers day in and day out, most people thought I was doing next to nothing. It is likely that the Boss thought likewise too."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1c29b140301','ch_be990a008551','text','{"text": "So anyone who felt I should be given some occupation would barge into my cubicle and deliver an extended lecture. The"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f94a6f1f5ad','ch_be990a008551','text','{"text": "‘boy’ in the make-up department had decided I should be enlightened on how great literary talent was being allowed to go waste in a department fit only for barbers and perverts. Soon I was praying for crowd-shooting all the time. Nothing short of it could save me from his epics."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a8799c3a6fc','ch_be990a008551','text','{"text": "In all instances of frustration, you will always find the anger directed towards a single person openly or covertly and this man of the make-up department was convinced that all his woes, ignominy and neglect were due to Kothamangalam Subbu. Subbu was the No. 2 at Gemini Studios. He couldn’t have had a more encouraging opening in films than our grown-up make-up boy had."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f286d229497a','ch_be990a008551','text','{"text": "On the contrary he must have had to face more uncertain and difficult times, for when he began his career, there were no firmly established film producing companies or studios. Even in the matter of education, specially formal education, Subbu couldn’t have had an appreciable lead over our boy. But by virtue of being born a Brahmin — a virtue, indeed! — he must have had exposure to more affluent situations and people."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8f9791d7f3d','ch_be990a008551','text','{"text": "He had the ability to look cheerful at all times even after having had a hand in a flop film. He always had work for somebody — he could never do things on his own — but his sense of loyalty made him identify himself with his principal completely and turn his entire creativity to his principal’s advantage. He was tailor-made for films. Here was a man who could be inspired when commanded."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7744f4ba9241','ch_be990a008551','text','{"text": "‘The rat fights the tigress underwater and kills her but takes pity on the cubs and tends them lovingly — I don’t know how to do the scene,’ the producer would say and Subbu would come out with four ways of the rat pouring affection on its victim’s offspring."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d080fbfa007d','ch_be990a008551','text','{"text": "‘Good, but I am not sure it is effective enough,’ the producer would say and in a minute Subbu would come out with fourteen more alternatives."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd9bf0aac4aa','ch_be990a008551','text','{"text": "Film-making must have been and was so easy with a man like Subbu around and if ever there was a man who gave direction and definition to Gemini Studios during its golden years, it was Subbu. Subbu had a separate identity as a poet and though he was certainly capable of more complex and higher forms, he deliberately chose to address his poetry to the masses. His success in films overshadowed and dwarfed his literary achievements — or so his critics felt. He composed several truly original"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e11b38c59b8','ch_be990a008551','text','{"text": "‘story poems’ in folk refrain and diction and also wrote a sprawling novel Thillana Mohanambal with dozens of very deftly etched characters."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea5aa9e929e7','ch_be990a008551','text','{"text": "He quite successfully recreated the mood and manner of the Devadasis of the early 20th century. He was an amazing actor — he never aspired to the lead roles — but whatever subsidiary role he played in any of the films, he performed better than the supposed main players. He had a genuine love for anyone he came across and his house was a permanent residence for dozens of near and far relations and acquaintances."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_16cee77bb978','ch_be990a008551','text','{"text": "It seemed against Subbu’s nature to be even conscious that he was feeding and supporting so many of them. Such a charitable and improvident man, and yet he had enemies! Was it because he seemed so close and intimate with The Boss? Or was it his general demeanour that resembled a sycophant’s? Or his readiness to say nice things about everything? In any case, there was this man in the make-up department who would wish the direst things for Subbu."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ecdee653bd20','ch_be990a008551','text','{"text": "You saw Subbu always with The Boss but in the attendance rolls, he was grouped under a department called the Story Department comprising a lawyer and an assembly of writers and poets. The lawyer was also officially known as the legal adviser, but everybody referred to him as the opposite. An extremely talented actress, who was also extremely temperamental, once blew over on the sets. While everyone stood stunned, the lawyer quietly switched on the recording equipment."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7244e0115ae4','ch_be990a008551','text','{"text": "When the actress paused for breath, the lawyer said to her, ‘One minute, please,’ and played back the recording. There was nothing incriminating or unmentionably foul about the actress’s tirade against the producer. But when she heard her voice again through the sound equipment, she was struck dumb."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5a0a5adb1301','ch_be990a008551','text','{"text": "A girl from the countryside, she hadn’t gone through all the stages of worldly experience that generally precede a position of importance and sophistication that she had found herself catapulted into. She never quite recovered from the terror she felt that day. That was the end of a brief and brilliant acting career — the legal adviser, who was also a member of the Story Department, had unwittingly brought about that sad end."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0985bcadf7c3','ch_be990a008551','text','{"text": "While every other member of the Department wore a kind of uniform — khadi dhoti with a slightly oversized and clumsily tailored white khadi shirt — the legal adviser wore pants and a tie and sometimes a coat that looked like a coat of mail. Often he looked alone and helpless — a man of cold logic in a crowd of dreamers — a neutral man in an assembly of Gandhiites and khadiites."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a97d44016162','ch_be990a008551','text','{"text": "Like so many of those who were close to The Boss, he was allowed to produce a film and though a lot of raw stock and pancake were used on it, not much came of the film. Then one day The Boss closed down the Story Department and this was perhaps the only instance in all human history where a lawyer lost his job because the poets were asked to go home. Gemini Studios was the favourite haunt of poets like S.D.S.Yogiar3, Sangu Subramanyam, Krishna Sastry and Harindranath Chattopadhyaya4."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_419e96e4023f','ch_be990a008551','text','{"text": "It had an excellent mess which supplied good coffee at all times of the day and for most part of the night. Those were the days when Congress rule meant Prohibition and meeting over a cup of coffee was rather satisfying entertainment. Barring the office boys and a couple of clerks, everybody else at the Studios radiated leisure, a pre-requisite for poetry. Most of them wore khadi and worshipped Gandhiji but beyond that they had not the faintest appreciation for political thought of any kind."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_56cedd39fda5','ch_be990a008551','text','{"text": "Naturally, they were all averse to the term"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a93d2ebc7402','ch_be990a008551','text','{"text": "‘Communism’. A Communist was a godless man — he had no filial or conjugal love;"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e50618188b14','ch_be990a008551','text','{"text": "he had no compunction about killing his own parents or his children;"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4df197c87c34','ch_be990a008551','text','{"text": "he was always out to cause and spread unrest and violence among innocent and ignorant people. Such notions which prevailed everywhere else in South India at that time also, naturally, floated about vaguely among the khadi-clad poets of Gemini Studios. Evidence of it was soon forthcoming."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7c2c4e54341','ch_be990a008551','text','{"text": "When Frank Buchman’s Moral Re-Armament army, some two hundred strong, visited Madras sometime in 1952, they could not have found a warmer host in India than the Gemini Studios. Someone called the group an international circus. They weren’t very good on the trapeze and their acquaintance with animals was only at the dinner table, but they presented two plays in a most professional manner. Their"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b43324a4297','ch_be990a008551','text','{"text": "‘Jotham Valley’ and"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6aa20ecf589b','ch_be990a008551','text','{"text": "‘The Forgotten Factor’ ran several shows in Madras and along with the other citizens of the city, the Gemini family of six hundred saw the plays over and over again."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_516e3f9dea31','ch_be990a008551','text','{"text": "The message of the plays were usually plain and simple homilies, but the sets and costumes were first-rate. Madras and the Tamil drama community were terribly impressed and for some years almost all Tamil plays had a scene of sunrise and sunset in the manner of"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04ba2c29d2f5','ch_be990a008551','text','{"text": "‘Jotham Valley’ with a bare stage, a white background curtain and a tune played on the flute."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18ec8ddf82c0','ch_be990a008551','text','{"text": "It was some years later that I learnt that the MRA was a kind of countermovement to international Communism and the big bosses of Madras like Mr. Vasan simply played into their hands. I am not sure however, that this was indeed the case, for the unchangeable aspects of these big bosses and their enterprises remained the same, MRA or no MRA, international Communism or no international Communism."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8528848ff4d1','ch_be990a008551','text','{"text": "The staff of Gemini Studios had a nice time hosting two hundred people of all hues and sizes of at least twenty nationalities. It was such a change from the usual collection of crowd players waiting to be slapped with thick layers of make-up by the office-boy in the make-up department. A few months later, the telephone lines of the big bosses of Madras buzzed and once again we at Gemini Studios cleared a whole shooting stage to welcome another visitor."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2bd5e3a79d3f','ch_be990a008551','text','{"text": "All they said was that he was a poet from England. The only poets from England the simple Gemini staff knew or heard of were Wordsworth and Tennyson;"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f37f8bf7c901','ch_be990a008551','text','{"text": "the more literate ones knew of Keats, Shelley and Byron;"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d9fad010d4e','ch_be990a008551','text','{"text": "and one or two might have faintly come to know of someone by the name Eliot. Who was the poet visiting the Gemini Studios now?"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a70fb8da565','ch_be990a008551','text','{"text": "‘He is not a poet. He is an editor. That’s why The Boss is giving him a big reception.’"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7178f70b4aa','ch_be990a008551','text','{"text": "Vasan was also the editor of the popular Tamil weekly Ananda Vikatan. He wasn’t the editor of any of the known names of British publications in Madras, that is, those known at the Gemini Studios. Since the top men of The Hindu were taking the initiative, the surmise was that the poet was the editor of a daily — but not from The Manchester Guardian or the London Times. That was all that even the most wellinformed among us knew."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0472703cd2cc','ch_be990a008551','text','{"text": "At last, around four in the afternoon, the poet (or the editor) arrived. He was a tall man, very English, very serious and of course very unknown to all of us. Battling with half a dozen pedestal fans on the shooting stage, The Boss read out a long speech. It was obvious that he too knew precious little about the poet (or the editor). The speech was all in the most general terms but here and there it was peppered with words like"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_234c3303ecfd','ch_be990a008551','text','{"text": "‘freedom’ and"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c79b006dc5cd','ch_be990a008551','text','{"text": "‘democracy’. Then the poet spoke. He couldn’t have addressed a more dazed and silent audience — no one knew what he was talking about and his accent defeated any attempt to understand what he was saying."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b7d79c7cb63e','ch_be990a008551','text','{"text": "The whole thing lasted about an hour;"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68d0086f7a0f','ch_be990a008551','text','{"text": "then the poet left and we all dispersed in utter bafflement — what are we doing? What is an English poet doing in a film studio which makes Tamil films for the simplest sort of people? People whose lives least afforded them the possibility of cultivating a taste for English poetry? The poet looked pretty baffled too, for he too must have felt the sheer incongruity of his talk about the thrills and travails of an English poet."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3d5e3925149','ch_be990a008551','text','{"text": "His visit remained an unexplained mystery. The great prose-writers of the world may not admit it, but my conviction grows stronger day after day that prosewriting is not and cannot be the true pursuit of a genius."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_464abe9db5d4','ch_be990a008551','text','{"text": "It is for the patient, persistent, persevering drudge with a heart so shrunken that nothing can break it;"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70f08b08ce7a','ch_be990a008551','text','{"text": "rejection slips don’t mean a thing to him;"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1517bab7c35a','ch_be990a008551','text','{"text": "he at once sets about making a fresh copy of the long prose piece and sends it on to another editor enclosing postage for the return of the manuscript."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3d7bb9cc353','ch_be990a008551','text','{"text": "It was for such people that The Hindu had published a tiny announcement in an insignificant corner of an unimportant page — a short story contest organised by a British periodical by the name The Encounter. Of course, The Encounter wasn’t a known commodity among the Gemini literati. I wanted to get an idea of the periodical before I spent a considerable sum in postage sending a manuscript to England."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a0012f074b2','ch_be990a008551','text','{"text": "In those days, the British Council Library had an entrance with no long winded signboards and notices to make you feel you were sneaking into a forbidden area. And there were copies of The Encounter lying about in various degrees of freshness, almost untouched by readers. When I read the editor’s name, I heard a bell ringing in my shrunken heart."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70fbe7f1261a','ch_be990a008551','text','{"text": "It was the poet who had visited the Gemini Studios — I felt like I had found a long lost brother and I sang as I sealed the envelope and wrote out his address. I felt that he too would be singing the same song at the same time — long lost brothers of Indian films discover each other by singing the same song in the first reel and in the final reel of the film. Stephen Spender5. Stephen — that was his name."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c8ace45c059','ch_be990a008551','text','{"text": "And years later, when I was out of Gemini Studios and I had much time but not much money, anything at a reduced price attracted my attention. On the footpath in front of the Madras Mount Road Post Office, there was a pile of brand new books for fifty paise each. Actually they were copies of the same book, an elegant paperback of American origin."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_461fc8aba82e','ch_be990a008551','text','{"text": "‘Special low-priced student edition, in connection with the 50th Anniversary of the Russian Revolution’, I paid fifty paise and picked up a copy of the book, The God That Failed. Six eminent men of letters in six separate essays described"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_055c9fd89901','ch_be990a008551','text','{"text": "‘their journeys into Communism and their disillusioned return’;"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ac995306f09','ch_be990a008551','text','{"text": "Andre Gide6, Richard Wright7, Ignazio Silone8, Arthur Koestler9, Louis Fischer10 and Stephen Spender."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8077174b76d1','ch_be990a008551','text','{"text": "Stephen Spender! Suddenly the book assumed tremendous significance. Stephen Spender, the poet who had visited Gemini Studios! In a moment I felt a dark chamber of my mind lit up by a hazy illumination. The reaction to Stephen Spender at Gemini Studios was no longer a mystery. The Boss of the Gemini Studios may not have much to do with Spender’s poetry. But not with his god that failed."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2471faeda69c','ch_be990a008551','list','{"ordered": false, "items": ["Asokamitran"]}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd7afabfcab8','ch_be990a008551','text','{"text": "About the author"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea7197c6ccaf','ch_be990a008551','text','{"text": "Asokamitran (1931), a Tamil writer, recounts his years at Gemini Studios in his book My Years with Boss which talks of the influence of movies on every aspect of life in India."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f3ea480050e','ch_be990a008551','text','{"text": "The Gemini Studios, located in Chennai, was set up in 1940. It was one of the most influential filmproducing organisations of India in the early days of Indian film-making. Its founder was S.S. Vasan. The duty of Asokamitran in Gemini Studios was to cut out newspaper clippings on a wide variety of subjects and store them in files. Many of these had to be written out by hand. Although he performed an insignificant function he was the most well-informed of all the members of the Gemini family."}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3dd52370c6b1','ch_be990a008551','text','{"text": "The following is an excerpt from his book My Years with Boss."}',65);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_419ba0d00046','bk_ncert_english','12-28-the-interview','12.28 The Interview',NULL,'public',100,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_500dda5e2798','ch_419ba0d00046','text','{"text": "Part I"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2da54a8728c0','ch_419ba0d00046','text','{"text": "Since its invention a little over 130 years ago, the interview has become a commonplace of journalism. Today, almost everybody who is literate will have read an interview at some point in their lives, while from the other point of view, several thousand celebrities have been interviewed over the years, some of them repeatedly. So it is hardly surprising that opinions of the interview — of its functions, methods and merits — vary considerably."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e613bde3cfee','ch_419ba0d00046','text','{"text": "Some might make quite extravagant claims for it as being, in its highest form, a source of truth, and, in its practice, an art. Others, usually celebrities who see themselves as its victims, might despise the interview as an unwarranted intrusion into their lives, or feel that it somehow diminishes them, just as in some primitive cultures it is believed that if one takes a photographic portrait of somebody then one is stealing that person’s soul. V. S. Naipaul1"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_89252b065ad6','ch_419ba0d00046','text','{"text": "‘feels that some people are wounded by interviews and lose a part of themselves,’ Lewis Carroll, the creator of Alice in Wonderland, was said to have had"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d2b291ed970','ch_419ba0d00046','text','{"text": "‘a just horror of the interviewer’ and he never consented to be interviewed — It was his horror of being lionized which made him thus repel would be acquaintances, interviewers, and the persistent petitioners for his autograph and he would afterwards relate the stories of his success in silencing all such people with much satisfaction and amusement."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27fc333afe67','ch_419ba0d00046','text','{"text": "Rudyard Kipling2 expressed an even more condemnatory attitude towards the interviewer. His wife, Caroline, writes in her diary for 14 October 1892 that their day was"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9706ce00f060','ch_419ba0d00046','text','{"text": "‘wrecked by two reporters from Boston’."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca7be3ea9979','ch_419ba0d00046','text','{"text": "She reports her husband as saying to the reporters, ‘Why do I refuse to be interviewed? Because it is immoral! It is a crime, just as much of a crime as an offence against my person, as an assault, and just as much merits punishment. It is cowardly and vile. No respectable man would ask it, much less give it,’ Yet Kipling had himself perpetrated such an"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e628e3986a95','ch_419ba0d00046','text','{"text": "‘assault’ on Mark Twain only a few years before. H. G. Wells3 in an interview in 1894 referred to"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_340f4a7b6078','ch_419ba0d00046','text','{"text": "‘the interviewing ordeal’, but was a fairly frequent interviewee and forty years later found himself interviewing Joseph Stalin4."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_afbeb11bf146','ch_419ba0d00046','text','{"text": "Saul Bellow5, who has consented to be interviewed on several occasions, nevertheless once described interviews as being like thumbprints on his windpipe. Yet despite the drawbacks of the interview, it is a supremely serviceable medium of communication."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e2db97e4ad45','ch_419ba0d00046','text','{"text": "‘These days, more than at any other time, our most vivid impressions of our contemporaries are through interviews,’ Denis Brian has written."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96cd87eb1720','ch_419ba0d00046','text','{"text": "‘Almost everything of moment reaches us through one man asking questions of another. Because of this, the interviewer holds a position of unprecedented power and influence.’"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b0741120402','ch_419ba0d00046','text','{"text": "Part II"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abf3e60e122a','ch_419ba0d00046','text','{"text": "\"I am a professor who writes novels on Sundays\""}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92d4361cac0d','ch_419ba0d00046','list','{"ordered": false, "items": ["Umberto Eco"]}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e157039a39c1','ch_419ba0d00046','text','{"text": "The following is an extract from an interview of Umberto Eco. The interviewer is Mukund Padmanabhan from The Hindu. Umberto Eco, a professor at the University of Bologna in Italy had already acquired a formidable reputation as a scholar for his ideas on semiotics (the study of signs), literary interpretation, and medieval aesthetics before he turned to writing fiction."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_371dea7aa4f8','ch_419ba0d00046','text','{"text": "Literary fiction, academic texts, essays, children’s books, newspaper articles—his written output is staggeringly large and wide-ranging, In 1980, he acquired the equivalent of intellectual superstardom with the publication of The Name of the Rose, which sold more than 10 million copies."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18bc954a9c21','ch_419ba0d00046','text','{"text": "Mukund: The English novelist and academic David Lodge once remarked, ‘I can’t understand how one man can do all the things he [Eco] does.’"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f1d108218233','ch_419ba0d00046','text','{"text": "Umberto Eco: Maybe I give the impression of doing many things. But in the end, I am convinced I am always doing the same thing."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e005ad4636bf','ch_419ba0d00046','text','{"text": "Mukund: Which is?"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_11899dc08be9','ch_419ba0d00046','text','{"text": "Umberto Eco: Aah, now that is more difficult to explain. I have some philosophical interests and I pursue them through my academic work and my novels. Even my books for children are about non-violence and peace...you see, the same bunch of ethical, philosophical interests. And then I have a secret."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09cb5779e208','ch_419ba0d00046','text','{"text": "Did you know what will happen if you eliminate the empty spaces from the universe, eliminate the empty spaces in all the atoms? The universe will become as big as my fist. Similarly, we have a lot of empty spaces in our lives. I call them interstices. Say you are coming over to my place. You are in an elevator and while you are coming up, I am waiting for you. This is an interstice, an empty space. I work in empty spaces."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ea833a2f43e','ch_419ba0d00046','text','{"text": "While waiting for your elevator to come up from the first to the third floor, I have already written an article! (Laughs)."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c309843ccdbb','ch_419ba0d00046','text','{"text": "Mukund: Not everyone can do that of course. Your non-fictional writing, your scholarly work has a certain playful and personal quality about it. It is a marked departure from a regular academic style — which is invariably depersonalised and often dry and boring."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_160d330b7667','ch_419ba0d00046','text','{"text": "Have you consciously adopted an informal approach or is it something that just came naturally to you?"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da5bd59d3e4b','ch_419ba0d00046','text','{"text": "Umberto Eco: When I presented my first Doctoral dissertation in Italy, one of the Professors said, ‘Scholars learn a lot of a certain subject, then they make a lot of false hypotheses, then they correct them and at the end, they put the conclusions. You, on the contrary, told the story of your research. Even including your trials and errors.’"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_404e5db7f8ce','ch_419ba0d00046','text','{"text": "At the same time, he recognised I was right and went on to publish my dissertation as a book, which meant he appreciated it. At that point, at the age of 22, I understood scholarly books should be written the way I had done — by telling the story of the research. This is why my essays always have a narrative aspect. And this is why probably I started writing narratives [novels] so late — at the age of 50, more or less."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_728e3217e4dd','ch_419ba0d00046','text','{"text": "I remember that my dear friend Roland Barthes was always frustrated that he was an essayist and not a novelist. He wanted to do creative writing one day or another but he died before he could do so. I never felt this kind of frustration. I started writing novels by accident. I had nothing to do one day and so I started. Novels probably satisfied my taste for narration."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a6b29461cb1','ch_419ba0d00046','text','{"text": "Mukund: Talking about novels, from being a famous academic you went on to becoming spectacularly famous after the publication of The Name of the Rose. You’ve written five novels against many more scholarly works of non-fiction, at least more than 20 of them..."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98773ae1a3dc','ch_419ba0d00046','text','{"text": "Umberto Eco: Over 40."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5869e78c688c','ch_419ba0d00046','text','{"text": "Mukund: Over 40! Among them a seminal piece of work on semiotics. But ask most people about Umberto Eco and they will say, ‘Oh, he’s the novelist.’"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_860f9d454a2a','ch_419ba0d00046','text','{"text": "Does that bother you?"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e9622cd50d7','ch_419ba0d00046','text','{"text": "Umberto Eco: Yes. Because I consider myself a university professor who writes novels on Sundays. It’s not a joke. I participate in academic conferences and not meetings of Pen Clubs and writers. I identify myself with the academic community. But okay, if they [most people] have read only the novels... (laughs and shrugs). I know that by writing novels, I reach a larger audience. I cannot expect to have one million readers with stuff on semiotics."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40f1bede98dc','ch_419ba0d00046','text','{"text": "Mukund: Which brings me to my next question. The Name of the Rose is a very serious novel. It’s a detective yarn at one level but it also delves into metaphysics, theology, and medieval history. Yet it enjoyed a huge mass audience. Were you puzzled at all by this?"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7b6ffa5c1a9','ch_419ba0d00046','text','{"text": "Umberto Eco: No. Journalists are puzzled. And sometimes publishers. And this is because journalists and publishers believe that people like trash and don’t like difficult reading experiences."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75addd013464','ch_419ba0d00046','text','{"text": "Consider there are six billion people on this planet. The Name of the Rose sold between 10 and 15 million copies. So in a way I reached only a small percentage of readers. But it is exactly these kinds of readers who don’t want easy experiences. Or at least don’t always want this. I myself, at 9 pm after dinner, watch television and want to see either"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c0fa27f42b8','ch_419ba0d00046','text','{"text": "‘Miami Vice’ or"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1357a85f9e6c','ch_419ba0d00046','text','{"text": "‘Emergency Room’."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5e63a4d5b124','ch_419ba0d00046','text','{"text": "I enjoy it and I need it. But not all day."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff85152642fd','ch_419ba0d00046','text','{"text": "Mukund: Could the huge success of the novel have anything to do with the fact that it dealt with a period of medieval history that..."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2616da9c8567','ch_419ba0d00046','text','{"text": "Umberto Eco: That’s possible. But let me tell you another story, because I often tell stories like a Chinese wise man. My American publisher said while she loved my book, she didn’t expect to sell more than 3,000 copies in a country where nobody has seen a cathedral or studies Latin."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f6632b47ced','ch_419ba0d00046','text','{"text": "So I was given an advance for 3,000 copies, but in the end it sold two or three million in the U.S. A lot of books have been written about the medieval past far before mine. I think the success of the book is a mystery. Nobody can predict it. I think if I had written The Name of the Rose ten years earlier or ten years later, it wouldn’t have been the same. Why it worked at that time is a mystery."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50819d32c1f9','ch_419ba0d00046','list','{"ordered": false, "items": ["Christopher Silvester"]}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0781a0dfc5f7','ch_419ba0d00046','text','{"text": "From the Introduction to The Penguin Book of Interviews edited by Christopher Silvester."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4269f9d2115c','ch_419ba0d00046','text','{"text": "About the Author"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_618981b51b52','ch_419ba0d00046','text','{"text": "Christopher Silvester (1959) was a student of history at Peterhouse, Cambridge. He was a reporter for Private Eye for ten years and has written features for Vanity Fair. Following is an excerpt taken from his introduction to the Penguin Book of Interviews, An Anthology from 1859 to the Present Day."}',47);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_30803b78d369','bk_ncert_english','12-29-going-places','12.29 Going Places',NULL,'public',101,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46ef0717c6d6','ch_30803b78d369','text','{"text": "‘When I leave,’ Sophie said, coming home from school, ‘I’m going to have a boutique.’"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d4e032b3ba1','ch_30803b78d369','text','{"text": "Jansie, linking arms with her along the street;"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3baf2e275bbb','ch_30803b78d369','text','{"text": "looked doubtful."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ce80b0eaeda','ch_30803b78d369','text','{"text": "‘Takes money, Soaf, something like that.’"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c48bab668d4a','ch_30803b78d369','text','{"text": "‘I’ll find it,’ Sophie said, staring far down the street."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8e62a03034ab','ch_30803b78d369','text','{"text": "‘Take you a long time to save that much.’"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8925364594bb','ch_30803b78d369','text','{"text": "‘Well I’ll be a manager then — yes, of course — to begin with."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b5826f1a8040','ch_30803b78d369','text','{"text": "Till I’ve got enough. But anyway, I know just how it’s all going to look.’"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_760d05857e86','ch_30803b78d369','text','{"text": "‘They wouldn’t make you manager straight off, Soaf.’"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_004c3a33af26','ch_30803b78d369','text','{"text": "‘I’ll be like Mary Quant,’ Sophie said."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2a173387655','ch_30803b78d369','text','{"text": "‘I’ll be a natural. They’ll see it from the start. I’ll have the most amazing shop this city’s ever seen.’"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a473f8155752','ch_30803b78d369','text','{"text": "’ Jansie, knowing they were both earmarked for the biscuit factory, became melancholy. She wished Sophie wouldn’t say these things. When they reached Sophie’s street Jansie said, ‘It’s only a few months away now, Soaf, you really should be sensible. They don’t pay well for shop work, you know that, your dad would never allow it.’"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_72d91331fc50','ch_30803b78d369','text','{"text": "‘Or an actress. Now there’s real money in that. Yes, and I could maybe have the boutique on the side. Actresses don’t work full time, do they? Anyway, that or a fashion designer, you know — something a bit sophisticated’. And she turned in through the open street door leaving Jansie standing in the rain."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bdaedf177717','ch_30803b78d369','text','{"text": "‘If ever I come into money I’ll buy a boutique.’"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ed618cecd15','ch_30803b78d369','text','{"text": "‘Huh - if you ever come into money... if you ever come into money you’ll buy us a blessed decent house to live in, thank you very much.’"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7ce05410a7f','ch_30803b78d369','text','{"text": "Sophie’s father was scooping shepherd’s pie into his mouth as hard as he could go, his plump face still grimy and sweat — marked from the day."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ad7575ccb44','ch_30803b78d369','text','{"text": "‘She thinks money grows on trees, don’t she, Dad?’ said little Derek, hanging on the back of his father’s chair."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_761eeef46869','ch_30803b78d369','text','{"text": "Their mother sighed. Sophie watched her back stooped over the sink and wondered at the incongruity of the delicate bow which fastened her apron strings. The delicate-seeming bow and the crooked back. The evening had already blacked in the windows and the small room was steamy from the stove and cluttered with the heavy-breathing man in his vest at the table and the dirty washing piled up in the corner. Sophie felt a tightening in her throat. She went to look for her brother Geoff."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46924b7bf9f5','ch_30803b78d369','text','{"text": "He was kneeling on the floor in the next room tinkering with a part of his motorcycle over some newspaper spread on the carpet. He was three years out of school, an apprentice mechanic, travelling to his work each day to the far side of the city. He was almost grown up now, and she suspected areas of his life about which she knew nothing, about which he never spoke. He said little at all, ever, voluntarily. Words had to be prized out of him like stones out of the ground."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_427b05cbcf43','ch_30803b78d369','text','{"text": "And she was jealous of his silence. When he wasn’t speaking it was as though he was away somewhere, out there in the world in those places she had never been. Whether they were only the outlying districts of the city, or places beyond in the surrounding country — who knew? — they attained a special fascination simply because they were unknown to her and remained out of her reach."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51f900ae07dd','ch_30803b78d369','text','{"text": "Perhaps there were also people, exotic, interesting people of whom he never spoke — it was possible, though he was quiet and didn’t make new friends easily. She longed to know them. She wished she could be admitted more deeply into her brother’s affections and that someday he might take her with him. Though their father forbade it and Geoff had never expressed an opinion, she knew he thought her too young. And she was impatient."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_94fad2c77f33','ch_30803b78d369','text','{"text": "She was conscious of a vast world out there waiting for her and she knew instinctively that she would feel as at home there as in the city which had always been her home. It expectantly awaited her arrival. She saw herself riding there behind Geoff. He wore new, shining black leathers and she a yellow dress with a kind of cape that flew out behind. There was the sound of applause as the world rose to greet them."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_491f2fb791e1','ch_30803b78d369','text','{"text": "He sat frowning at the oily component he cradled in his hands, as though it were a small dumb animal and he was willing it to speak."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f106d235ec4','ch_30803b78d369','text','{"text": "‘I met Danny Casey,’ Sophie said."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09f9cb4554f5','ch_30803b78d369','text','{"text": "He looked around abruptly."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9659d3aa0d66','ch_30803b78d369','text','{"text": "‘Where?’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ff64a2270b7','ch_30803b78d369','text','{"text": "‘In the arcade — funnily enough.’"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cde4183c9828','ch_30803b78d369','text','{"text": "‘It’s never true.’"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_923e631f1741','ch_30803b78d369','text','{"text": "‘I did too.’"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0d40ec78d9c','ch_30803b78d369','text','{"text": "‘You told Dad?’ She shook her head, chastened at his unawareness that he was always the first to share her secrets."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_15344d97a0cd','ch_30803b78d369','text','{"text": "‘I don’t believe it.’"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fbdac5c7557c','ch_30803b78d369','text','{"text": "‘There I was looking at the clothes in Royce’s window when someone came and stood beside me, and I looked around and who should it be but Danny Casey.’"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22316f4b4a6f','ch_30803b78d369','text','{"text": "‘All right, what does he look like?’"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5a4c1a8b2eba','ch_30803b78d369','text','{"text": "‘Oh come on, you know what he looks like.’"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c38704950f98','ch_30803b78d369','text','{"text": "‘Close to, I mean.’"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6918c8158cb0','ch_30803b78d369','text','{"text": "‘Well — he has green eyes. Gentle eyes. And he’s not so tall as you’d think...’"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f9a1b340e07','ch_30803b78d369','text','{"text": "She wondered if she should say about his teeth, but decided against it. Their father had washed when he came in and his face and arms were shiny and pink and he smelled of soap. He switched on the television, tossed one of little Derek’s shoes from his chair onto the sofa, and sat down with a grunt."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_292035e169e0','ch_30803b78d369','text','{"text": "‘Sophie met Danny Casey,’ Geoff said."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5c73c45e505','ch_30803b78d369','text','{"text": "Sophie wriggled where she was sitting at the table. Her father turned his head on his thick neck to look at her. His expression was one of disdain."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67f81103bbac','ch_30803b78d369','text','{"text": "‘It’s true,’ Geoff said."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bdbfe82ca055','ch_30803b78d369','text','{"text": "‘I once knew a man who had known Tom Finney,’ his father said reverently to the television."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49dac8e8098b','ch_30803b78d369','text','{"text": "‘But that was a long time ago.’"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ace330d4ccf9','ch_30803b78d369','text','{"text": "‘You told us,’ Geoff said."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_78529bc9fc4f','ch_30803b78d369','text','{"text": "‘Casey might be that good some day.’"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5feb94e32e8a','ch_30803b78d369','text','{"text": "‘Better than that even. He’s the best.’"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7088641afc91','ch_30803b78d369','text','{"text": "‘If he keeps his head on his shoulders. If they look after him properly. A lot of distractions for a youngster in the game these days.’"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ef78ac17422','ch_30803b78d369','text','{"text": "‘He’ll be all right. He’s with the best team in the country.’"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7640da577f6','ch_30803b78d369','text','{"text": "‘He’s very young yet.’"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e60d9d29bdf','ch_30803b78d369','text','{"text": "‘He’s older than I am.’"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_961f8499add1','ch_30803b78d369','text','{"text": "‘Too young really for the first team.’"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f4a41270c87f','ch_30803b78d369','text','{"text": "‘You can’t argue with that sort of ability.’"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_66888d7b0883','ch_30803b78d369','text','{"text": "‘He’s going to buy a shop,’ Sophie said from the table. Her father grimaced."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da810732ce68','ch_30803b78d369','text','{"text": "‘Where’d you hear that?’"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_762ee22366ca','ch_30803b78d369','text','{"text": "‘He told me so.’"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b6e3b175455','ch_30803b78d369','text','{"text": "He muttered something inaudible and dragged himself round in his chair."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d79403e212ad','ch_30803b78d369','text','{"text": "‘This another of your wild stories?’"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4a700b340259','ch_30803b78d369','text','{"text": "‘She met him in the arcade,’ Geoff said, and told him how it had been."}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_28ab07a99636','ch_30803b78d369','text','{"text": "‘One of these days you’re going to talk yourself into a load of trouble,’ her father said aggressively."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_57a18a37de36','ch_30803b78d369','text','{"text": "‘Geoff knows it’s true, don’t you Geoff?’"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eba5b6ad8efe','ch_30803b78d369','text','{"text": "‘He don’t believe you-though he’d like to.’"}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1a158a58ae4c','ch_30803b78d369','text','{"text": "* * * The table lamp cast an amber glow across her brother’s bedroom wall, and across the large poster of United’s first team squad and the row of coloured photographs beneath, three of them of the young Irish prodigy, Casey."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d96cef8efac8','ch_30803b78d369','text','{"text": "‘Promise you’ll tell no-one?’ Sophie said."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1bd504a38781','ch_30803b78d369','text','{"text": "‘Nothing to tell is there?’"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6dfa774944e1','ch_30803b78d369','text','{"text": "‘Promise, Geoff — Dad’d murder me.’"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba6db1ce6ce7','ch_30803b78d369','text','{"text": "‘Only if he thought it was true.’"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43b85c8df6d0','ch_30803b78d369','text','{"text": "‘Please, Geoff.’"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0c1cef9fdcf','ch_30803b78d369','text','{"text": "‘Christ, Sophie, you’re still at school."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79a38d5bb8f6','ch_30803b78d369','text','{"text": "Casey must have strings of girls.’"}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_944fd98609e1','ch_30803b78d369','text','{"text": "‘No he doesn’t.’"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_30af2f180183','ch_30803b78d369','text','{"text": "‘How could you know that?’ he jeered."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_87ac0c8b8a70','ch_30803b78d369','text','{"text": "‘He told me, that’s how.’"}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e726fca22c16','ch_30803b78d369','text','{"text": "‘As if anyone would tell a girl something like that.’"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0cd8520dc026','ch_30803b78d369','text','{"text": "‘Yes he did. He isn’t like that. He’s... quiet.’"}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8868e74f3fca','ch_30803b78d369','text','{"text": "‘Not as quiet as all that — apparently.’"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f2b642374753','ch_30803b78d369','text','{"text": "‘It was nothing like that, Geoff — it was me spoke first. When I saw who it was, I said, ‘Excuse me, but aren’t you Danny Casey?’ And he looked sort of surprised. And he said, ‘Yes, that’s right.’"}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3c7f9165bdf','ch_30803b78d369','text','{"text": "And I knew it must be him because he had the accent, you know, like when they interviewed him on the television. So I asked him for an autograph for little Derek, but neither of us had any paper or a pen. So then we just talked a bit. About the clothes in Royce’s window. He seemed lonely. After all, it’s a long way from the west of Ireland. And then, just as he was going, he said, if I would care to meet him next week he would give me an autograph then. Of course, I said I would.’"}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a21fea9b2b53','ch_30803b78d369','text','{"text": "‘As if he’d ever show up.’"}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e332d3cfed33','ch_30803b78d369','text','{"text": "‘You do believe me now, don’t you?’ He dragged his jacket, which was shiny and shapeless, from the back of the chair and pushed his arms into it."}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5378cc831d70','ch_30803b78d369','text','{"text": "She wished he paid more attention to his appearance. Wished he cared more about clothes. He was tall with a strong dark face. Handsome, she thought."}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0015dddd9df6','ch_30803b78d369','text','{"text": "‘It’s the unlikeliest thing I ever heard,’ he said. * * * On Saturday they made their weekly pilgrimage to watch United. Sophie and her father and little Derek went down near the goal — Geoff, as always, went with his mates higher up. United won two-nil and Casey drove in the second goal, a blend of innocence and Irish genius, going round the two big defenders on the edge of the penalty area, with her father screaming for him to pass, and beating the hesitant goalkeeper from a dozen yards."}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09657ca50fa0','ch_30803b78d369','text','{"text": "Sophie glowed with pride. Afterwards Geoff was ecstatic."}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1fea4c063661','ch_30803b78d369','text','{"text": "‘I wish he was an Englishman,’ someone said on the bus."}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_473441bffa2d','ch_30803b78d369','text','{"text": "‘Ireland’ll win the World Cup,’ little Derek told his mother when Sophie brought him home. Her father was gone to the pub to celebrate."}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4441a53ebe0f','ch_30803b78d369','text','{"text": "‘What’s this you’ve been telling?’ Jansie said, next week."}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_93f40aa55bd5','ch_30803b78d369','text','{"text": "‘About what?’"}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f8e033055b5','ch_30803b78d369','text','{"text": "‘Your Geoff told our Frank you met Danny Casey.’"}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ff623e3980e','ch_30803b78d369','text','{"text": "This wasn’t an inquisition, just Jansie being nosey. But Sophie was startled."}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3be92b3fdf44','ch_30803b78d369','text','{"text": "‘Oh, that.’"}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a09029920902','ch_30803b78d369','text','{"text": "Jansie frowned, sensing she was covering."}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d11407c1bcfa','ch_30803b78d369','text','{"text": "‘Yes — that.’"}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a3414611cf1','ch_30803b78d369','text','{"text": "‘Well-yes, I did.’"}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_87dc44dddf57','ch_30803b78d369','text','{"text": "‘You never did?’ Jansie exclaimed."}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cfd331249cfb','ch_30803b78d369','text','{"text": "Sophie glared at the ground. Damn that Geoff, this was a Geoff thing not a Jansie thing. It was meant to be something special just between them. Something secret. It wasn’t a Jansie kind of thing at all. Tell gawky Jansie something like that and the whole neighbourhood would get to know it. Damn that Geoff, was nothing sacred?"}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7fec58a8d974','ch_30803b78d369','text','{"text": "‘It’s a secret — meant to be.’"}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_37d6042a8f8e','ch_30803b78d369','text','{"text": "‘I’ll keep a secret, Soaf, you know that.’"}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f588e964528e','ch_30803b78d369','text','{"text": "‘I wasn’t going to tell anyone."}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_869333d199b2','ch_30803b78d369','text','{"text": "There’ll be a right old row if my dad gets to hear about it.’"}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4603ecd42c8','ch_30803b78d369','text','{"text": "Jansie blinked."}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9065f8e2b5b0','ch_30803b78d369','text','{"text": "‘A row? I’d have thought he’d be chuffed as anything.’"}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e60d7e7b3c1','ch_30803b78d369','text','{"text": "She realised then that Jansie didn’t know about the date bit — Geoff hadn’t told about that. She breathed more easily. So Geoff hadn’t let her down after all. He believed in her after all. After all some things might be sacred."}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_01650ee04a16','ch_30803b78d369','text','{"text": "‘It was just a little thing really. I asked him for an autograph, but we hadn’t any paper or a pen so it was no good.’"}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_986486630d6f','ch_30803b78d369','text','{"text": "How much had Geoff said?"}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_42ac2001d2d2','ch_30803b78d369','text','{"text": "‘Jesus, I wish I’d have been there.’"}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_14177a735052','ch_30803b78d369','text','{"text": "‘Of course, my dad didn’t want to believe it."}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e5d4138cef2','ch_30803b78d369','text','{"text": "You know what a misery he is. But the last thing I need is queues of people round our house asking him, ‘What’s all this about Danny Casey?’ He’d murder me. And you know how my mum gets when there’s a row.’"}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e651ef656f75','ch_30803b78d369','text','{"text": "Jansie said, hushed, ‘You can trust me, Soaf, you know that.’"}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43a6b42b5008','ch_30803b78d369','text','{"text": "************************"}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1c29f49a932','ch_30803b78d369','text','{"text": "After dark she walked by the canal, along a sheltered path lighted only by the glare of the lamps from the wharf across the water, and the unceasing drone of the city was muffled and distant. It was a place she had often played in when she was a child. There was a wooden bench beneath a solitary elm where lovers sometimes came. She sat down to wait. It was the perfect place, she had always thought so, for a meeting of this kind. For those who wished not to be observed."}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d117b09586d','ch_30803b78d369','text','{"text": "She knew he would approve. For some while, waiting, she imagined his coming. She watched along the canal, seeing him come out of the shadows, imagining her own consequent excitement. Not until some time had elapsed did she begin balancing against this the idea of his not coming. Here I sit, she said to herself, wishing Danny would come, wishing he would come and sensing the time passing. I feel the pangs of doubt stirring inside me. I watch for him but still there is no sign of him."}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1d61e021a16','ch_30803b78d369','text','{"text": "I remember Geoff saying he would never come, and how none of them believed me when I told them. I wonder what will I do, what can I tell them now if he doesn’t come? But we know how it was, Danny and me — that’s the main thing. How can you help what people choose to believe? But all the same, it makes me despondent, this knowing I’ll never be able to show them they’re wrong to doubt me. She waited, measuring in this way the changes taking place in her. Resignation was no sudden thing."}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_235a96212c42','ch_30803b78d369','text','{"text": "Now I have become sad, she thought. And it is a hard burden to carry, this sadness. Sitting here waiting and knowing he will not come I can see the future and how I will have to live with this burden. They of course will doubt me, as they always doubted me, but I will have to hold up my head remembering how it was. Already I envisage the slow walk home, and Geoff’s disappointed face when I tell him, ‘He didn’t come, that Danny.’"}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9d615f2cfe6b','ch_30803b78d369','text','{"text": "And then he’ll fly out and slam the door."}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c20fe7f27ab','ch_30803b78d369','text','{"text": "‘But we know how it was,’ I shall tell myself, ‘Danny and me.’"}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd40b25ac1d1','ch_30803b78d369','text','{"text": "It is a hard thing, this sadness. She climbed the crumbling steps to the street. Outside the pub she passed her father’s bicycle propped against the wall, and was glad. He would not be there when she got home."}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_881f33daeb8d','ch_30803b78d369','text','{"text": "‘Excuse me, but aren’t you Danny Casey?’ Coming through the arcade she pictured him again outside Royce’s."}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4da066f4adaa','ch_30803b78d369','text','{"text": "He turns, reddening slightly."}',116);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bdef2436ef4c','ch_30803b78d369','text','{"text": "‘Yes, that’s right.’"}',117);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e9097325505','ch_30803b78d369','text','{"text": "‘I watch you every week, with my dad and my brothers. We think you’re great.’"}',118);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_48b2e38b4088','ch_30803b78d369','text','{"text": "‘Oh, well now — that’s very nice.’"}',119);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53e932127a1f','ch_30803b78d369','text','{"text": "‘I wonder — would you mind signing an autograph?’ His eyes are on the same level as your own."}',120);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b3229ab2797','ch_30803b78d369','text','{"text": "His nose is freckled and turns upwards slightly, and when he smiles he does so shyly, exposing teeth with gaps between. His eyes are green, and when he looks straight at you they seem to shimmer. They seem gentle, almost afraid. Like a gazelle’s. And you look away. You let his eyes run over you a little. And then you come back to find them, slightly breathless. And he says, ‘I don’t seem to have a pen at all.’"}',121);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bcfbf917cf46','ch_30803b78d369','text','{"text": "You realise you haven’t either."}',122);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c2d9e70e2226','ch_30803b78d369','text','{"text": "‘My brothers will be very sorry,’ you say."}',123);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40ae2b0b2743','ch_30803b78d369','text','{"text": "And afterwards you wait there alone in the arcade for a long while, standing where he stood, remembering the soft melodious voice, the shimmer of green eyes. No taller than you. No bolder than you. The prodigy. The innocent genius. The great Danny Casey."}',124);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b7e8ea6ed01','ch_30803b78d369','text','{"text": "And she saw it all again, last Saturday — saw him ghost past the lumbering defenders, heard the fifty thousand catch their breath as he hovered momentarily over the ball, and then the explosion of sound as he struck it crisply into the goal, the sudden thunderous eruption of exultant approbation."}',125);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_69d2dc2a50ce','ch_30803b78d369','list','{"ordered": false, "items": ["A. R. Barton"]}',126);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_42535b64422f','ch_30803b78d369','text','{"text": "About the Author"}',127);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da477fdb3165','ch_30803b78d369','text','{"text": "A. R. Barton is a modern writer, who lives in Zurich and writes in English. In the story Going Places, Barton explores the theme of adolescent fantasising and hero worship."}',128);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_be1c88a44822','bk_ncert_english','12-30-my-mother-at-sixty-six','12.30 My Mother at Sixty-six',NULL,'public',102,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f5a4a6c9661','ch_be1c88a44822','text','{"text": "Driving from my parent’s"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_498bb6bf3d55','ch_be1c88a44822','text','{"text": "home to Cochin last Friday"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2dea5ec6b536','ch_be1c88a44822','text','{"text": "morning, I saw my mother,"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba93950289d8','ch_be1c88a44822','text','{"text": "beside me,"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a11143f01d2','ch_be1c88a44822','text','{"text": "doze, open mouthed, her face ashen like that"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_840b9c1cf5a0','ch_be1c88a44822','text','{"text": "of a corpse and realised with pain"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_557dfba8fde8','ch_be1c88a44822','text','{"text": "that she was as old as she"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1e677bb4e30','ch_be1c88a44822','text','{"text": "looked but soon"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5e1cda79b2c','ch_be1c88a44822','text','{"text": "put that thought away, and"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5e502fb378bd','ch_be1c88a44822','text','{"text": "looked out at Young"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1be0eb165ede','ch_be1c88a44822','text','{"text": "Trees sprinting, the merry children spilling"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3107cf97060','ch_be1c88a44822','text','{"text": "out of their homes, but after the airport’s"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1fa4d0d549a5','ch_be1c88a44822','text','{"text": "security check, standing a few yards"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_203fb0f72e9a','ch_be1c88a44822','text','{"text": "away, I looked again at her, wan,"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8ef068b11f9','ch_be1c88a44822','text','{"text": "pale"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_26a3b22e004a','ch_be1c88a44822','text','{"text": "as a late winter’s moon and felt that"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_193d5c560bac','ch_be1c88a44822','text','{"text": "old"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76715cbf2951','ch_be1c88a44822','text','{"text": "familiar ache, my childhood’s fear,"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b914582a797a','ch_be1c88a44822','text','{"text": "but all I said was, see you soon,"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c5ad6b1e0d6','ch_be1c88a44822','text','{"text": "Amma,"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b3a238311656','ch_be1c88a44822','text','{"text": "all I did was smile and smile and"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_407ce1851fc3','ch_be1c88a44822','text','{"text": "smile......"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_03615207427c','ch_be1c88a44822','list','{"ordered": false, "items": ["Kamala Das"]}',23);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_ac1f1d7d0c49','bk_ncert_english','12-31-an-elementary-school-classroom-in-a-slum','12.31 An Elementary School Classroom in a Slum',NULL,'public',103,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8995879222b2','ch_ac1f1d7d0c49','text','{"text": "Far far from gusty waves these children’s faces."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_78fc0a48c16c','ch_ac1f1d7d0c49','text','{"text": "Like rootless weeds, the hair torn round their pallor:"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_345c97502119','ch_ac1f1d7d0c49','text','{"text": "The tall girl with her weighed-down head. The paperseeming"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbcbe8d32feb','ch_ac1f1d7d0c49','text','{"text": "boy, with rat’s eyes. The stunted, unlucky heir"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c832ac106898','ch_ac1f1d7d0c49','text','{"text": "Of twisted bones, reciting a father’s gnarled disease,"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b0398ec15050','ch_ac1f1d7d0c49','text','{"text": "His lesson, from his desk. At back of the dim class"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_231ed67459fd','ch_ac1f1d7d0c49','text','{"text": "One unnoted, sweet and young. His eyes live in a dream,"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d60602980aa','ch_ac1f1d7d0c49','text','{"text": "Of squirrel’s game, in tree room, other than this."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a1b5c921123','ch_ac1f1d7d0c49','text','{"text": "On sour cream walls, donations. Shakespeare’s head,"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d1ba49aecc8c','ch_ac1f1d7d0c49','text','{"text": "Cloudless at dawn, civilized dome riding all cities."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4894e6b7b2ba','ch_ac1f1d7d0c49','text','{"text": "Belled, flowery, Tyrolese valley. Open-handed map"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6dac08d4b799','ch_ac1f1d7d0c49','text','{"text": "Awarding the world its world. And yet, for these"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a879d5280a37','ch_ac1f1d7d0c49','text','{"text": "Children, these windows, not this map, their world,"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_83d48cbdd221','ch_ac1f1d7d0c49','text','{"text": "Where all their future’s painted with a fog,"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_170cc7cb8108','ch_ac1f1d7d0c49','text','{"text": "A narrow street sealed in with a lead sky"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1bc7cc7e8830','ch_ac1f1d7d0c49','text','{"text": "Far far from rivers, capes, and stars of words."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_146892aea442','ch_ac1f1d7d0c49','text','{"text": "Surely, Shakespeare is wicked, the map a bad example,"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f1811a0b7e60','ch_ac1f1d7d0c49','text','{"text": "With ships and sun and love tempting them to steal—"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_edb4c9d06364','ch_ac1f1d7d0c49','text','{"text": "For lives that slyly turn in their cramped holes"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_65d27b483f55','ch_ac1f1d7d0c49','text','{"text": "From fog to endless night? On their slag heap, these children"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71e7eded4660','ch_ac1f1d7d0c49','text','{"text": "Wear skins peeped through by bones and spectacles of steel"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_12e7184de354','ch_ac1f1d7d0c49','text','{"text": "With mended glass, like bottle bits on stones."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_15d4c62c4d25','ch_ac1f1d7d0c49','text','{"text": "All of their time and space are foggy slum."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79412799ab2f','ch_ac1f1d7d0c49','text','{"text": "So blot their maps with slums as big as doom."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_95bab39087b0','ch_ac1f1d7d0c49','text','{"text": "Unless, governor, inspector, visitor,"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4daf2d84a910','ch_ac1f1d7d0c49','text','{"text": "This map becomes their window and these windows"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_628cbb51d720','ch_ac1f1d7d0c49','text','{"text": "That shut upon their lives like catacombs,"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a23e4f21b5ab','ch_ac1f1d7d0c49','text','{"text": "Break O break open till they break the town"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_218255798a1f','ch_ac1f1d7d0c49','text','{"text": "And show the children to green fields, and make their world"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b785a63a79b','ch_ac1f1d7d0c49','text','{"text": "Run azure on gold sands, and let their tongues"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db48ef465e00','ch_ac1f1d7d0c49','text','{"text": "Run naked into books the white and green leaves open"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cca8ac6e0996','ch_ac1f1d7d0c49','text','{"text": "History theirs whose language is the sun."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c798148e2790','ch_ac1f1d7d0c49','list','{"ordered": false, "items": ["Stephen Spender"]}',33);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_62af9da2350b','bk_ncert_english','12-32-keeping-quiet','12.32 Keeping Quiet',NULL,'public',104,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e0acd8fb84db','ch_62af9da2350b','text','{"text": "Now we will count to twelve"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc84c47bb915','ch_62af9da2350b','text','{"text": "and we will all keep still."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_197dd33f8748','ch_62af9da2350b','text','{"text": "For once on the face of the Earth"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b9ee4a931af','ch_62af9da2350b','text','{"text": "let’s not speak in any language,"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97c900cffc8a','ch_62af9da2350b','text','{"text": "let’s stop for one second,"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d86356903f8','ch_62af9da2350b','text','{"text": "and not move our arms so much."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_247025a2f0af','ch_62af9da2350b','text','{"text": "It would be an exotic moment"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ef4237c0d0e','ch_62af9da2350b','text','{"text": "without rush, without engines,"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f95af9298118','ch_62af9da2350b','text','{"text": "we would all be together"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db6bfff60db3','ch_62af9da2350b','text','{"text": "in a sudden strangeness."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f2daa3bebde6','ch_62af9da2350b','text','{"text": "Fishermen in the cold sea"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6553557f3869','ch_62af9da2350b','text','{"text": "would not harm whales"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8ec49b527cba','ch_62af9da2350b','text','{"text": "and the man gathering salt"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b7e5b3dcf9d5','ch_62af9da2350b','text','{"text": "would look at his hurt hands."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ed4f14de68a5','ch_62af9da2350b','text','{"text": "Those who prepare green wars,"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68ce906f89f7','ch_62af9da2350b','text','{"text": "wars with gas, wars with fire,"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9716c596d5ea','ch_62af9da2350b','text','{"text": "victory with no survivors,"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_28e9dff07768','ch_62af9da2350b','text','{"text": "would put on clean clothes"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74c456222fb6','ch_62af9da2350b','text','{"text": "and walk about with their"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_45ce879c7b70','ch_62af9da2350b','text','{"text": "brothers"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82d37d6e720a','ch_62af9da2350b','text','{"text": "in the shade, doing nothing."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_230011c42d4d','ch_62af9da2350b','text','{"text": "What I want should not be"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4151caead3e3','ch_62af9da2350b','text','{"text": "confused"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98d476e9aefc','ch_62af9da2350b','text','{"text": "with total inactivity."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2a7e6e87c182','ch_62af9da2350b','text','{"text": "Life is what it is about;"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3385a9731754','ch_62af9da2350b','text','{"text": "I want no truck with death."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5c5d10c660d','ch_62af9da2350b','text','{"text": "If we were not so single-minded"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97189f105dc6','ch_62af9da2350b','text','{"text": "about keeping our lives moving,"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1f616f9b98b','ch_62af9da2350b','text','{"text": "and for once could do nothing,"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_614f3b0f0b79','ch_62af9da2350b','text','{"text": "perhaps a huge silence"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_89faee490eda','ch_62af9da2350b','text','{"text": "might interrupt this sadness"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fcb52f547370','ch_62af9da2350b','text','{"text": "of never understanding ourselves"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a106d9617cbb','ch_62af9da2350b','text','{"text": "and of threatening ourselves with"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef3c97b2d87c','ch_62af9da2350b','text','{"text": "death."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f529f5db45e','ch_62af9da2350b','text','{"text": "Perhaps the Earth can teach us"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99130ab03c16','ch_62af9da2350b','text','{"text": "as when everything seems dead"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c7ace5dfaea','ch_62af9da2350b','text','{"text": "and later proves to be alive."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7acf2b562ad1','ch_62af9da2350b','text','{"text": "Now I’ll count up to twelve"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a88b16aea352','ch_62af9da2350b','text','{"text": "and you keep quiet and I will go."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_935a84866bbc','ch_62af9da2350b','list','{"ordered": false, "items": ["Pablo Neruda"]}',40);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_93825f5f8479','bk_ncert_english','12-33-a-thing-of-beauty','12.33 A thing of Beauty',NULL,'public',105,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b54af8ecebf','ch_93825f5f8479','text','{"text": "A thing of beauty is a joy forever"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa244142f3f6','ch_93825f5f8479','text','{"text": "Its loveliness increases, it will never"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_efb051849a04','ch_93825f5f8479','text','{"text": "Pass into nothingness; but will keep"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9de8ad48a61c','ch_93825f5f8479','text','{"text": "A bower quiet for us, and a sleep"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d1da4e4aa224','ch_93825f5f8479','text','{"text": "Full of sweet dreams, and health, and quiet breathing."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_95a4ef9890e0','ch_93825f5f8479','text','{"text": "Therefore, on every morrow, are we wreathing"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3dfbd899f1cf','ch_93825f5f8479','text','{"text": "A flowery band to bind us to the earth,"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d05c9945393b','ch_93825f5f8479','text','{"text": "Spite of despondence, of the inhuman dearth"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a7439b66500c','ch_93825f5f8479','text','{"text": "Of noble natures, of the gloomy days,"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51abbfcefbd5','ch_93825f5f8479','text','{"text": "Of all the unhealthy and o’er-darkened ways"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a24b7753aa2','ch_93825f5f8479','text','{"text": "Made for our searching: yes, in spite of all,"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35fe4f1d18f6','ch_93825f5f8479','text','{"text": "Some shape of beauty moves away the pall"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_487e551c5638','ch_93825f5f8479','text','{"text": "From our dark spirits. Such the sun, the moon,"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d221805ee71','ch_93825f5f8479','text','{"text": "Trees old, and young, sprouting a shady boon"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b7c00c486afa','ch_93825f5f8479','text','{"text": "For simple sheep; and such are daffodils"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_61869c92d685','ch_93825f5f8479','text','{"text": "With the green world they live in; and clear rills"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3df72b8182ec','ch_93825f5f8479','text','{"text": "That for themselves a cooling covert make"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e3b11d2d784','ch_93825f5f8479','text','{"text": "‘Gainst the hot season; the mid forest brake,"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f1c14abefb86','ch_93825f5f8479','text','{"text": "Rich with a sprinkling of fair musk-rose blooms;"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa9275ea4bd0','ch_93825f5f8479','text','{"text": "And such too is the grandeur of the dooms"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74321aebd835','ch_93825f5f8479','text','{"text": "We have imagined for the mighty dead;"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_332935e525d6','ch_93825f5f8479','text','{"text": "All lovely tales that we have heard or read;"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc1b0eb90931','ch_93825f5f8479','text','{"text": "An endless fountain of immortal drink,"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bbf8faa89d4d','ch_93825f5f8479','text','{"text": "Pouring unto us from the heaven’s brink."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9888c12511cc','ch_93825f5f8479','list','{"ordered": false, "items": ["John Keats"]}',25);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_24484e3ebdf1','bk_ncert_english','12-34-a-roadside-stand','12.34 A Roadside Stand',NULL,'public',106,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_54e23b8d4512','ch_24484e3ebdf1','text','{"text": "The little old house was out with a little new shed"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c24a709636e','ch_24484e3ebdf1','text','{"text": "In front at the edge of the road where the traffic sped,"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bf21e56ab6e6','ch_24484e3ebdf1','text','{"text": "A roadside stand that too pathetically pled,"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d6836b18883b','ch_24484e3ebdf1','text','{"text": "It would not be fair to say for a dole of bread,"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_777ce5007557','ch_24484e3ebdf1','text','{"text": "But for some of the money, the cash, whose flow supports"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_26d482673109','ch_24484e3ebdf1','text','{"text": "The flower of cities from sinking and withering faint."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8393ecb0538','ch_24484e3ebdf1','text','{"text": "The polished traffic passed with a mind ahead,"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c4da0147f65','ch_24484e3ebdf1','text','{"text": "Or if ever aside a moment, then out of sorts"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1deb6ef5d921','ch_24484e3ebdf1','text','{"text": "At having the landscape marred with the artless paint"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e39016e3efc3','ch_24484e3ebdf1','text','{"text": "Of signs that with N turned wrong and S turned wrong"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f054252dde03','ch_24484e3ebdf1','text','{"text": "Offered for sale wild berries in wooden quarts,"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_267889a3c1f8','ch_24484e3ebdf1','text','{"text": "Or crook-necked golden squash with silver warts,"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de7cb9046dc3','ch_24484e3ebdf1','text','{"text": "Or beauty rest in a beautiful mountain scene,"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f2e990bd863','ch_24484e3ebdf1','text','{"text": "You have the money, but if you want to be mean,"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e0e6212526a','ch_24484e3ebdf1','text','{"text": "Why keep your money (this crossly) and go along."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1a13e4c2915','ch_24484e3ebdf1','text','{"text": "The hurt to the scenery wouldn’t be my complaint"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ee95f26e9612','ch_24484e3ebdf1','text','{"text": "So much as the trusting sorrow of what is unsaid:"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d395868a406','ch_24484e3ebdf1','text','{"text": "Here far from the city we make our roadside stand"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_746fd38a40a0','ch_24484e3ebdf1','text','{"text": "And ask for some city money to feel in hand"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0191016cc8f1','ch_24484e3ebdf1','text','{"text": "To try if it will not make our being expand,"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ac41048d3bd','ch_24484e3ebdf1','text','{"text": "And give us the life of the moving-pictures’ promise"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a843869221ef','ch_24484e3ebdf1','text','{"text": "That the party in power is said to be keeping from us."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2301c500c774','ch_24484e3ebdf1','text','{"text": "It is in the news that all these pitiful kin"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_036c25f9fefc','ch_24484e3ebdf1','text','{"text": "Are to be bought out and mercifully gathered in"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab45730f243d','ch_24484e3ebdf1','text','{"text": "To live in villages, next to the theatre and the store,"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2a89bca292e2','ch_24484e3ebdf1','text','{"text": "Where they won’t have to think for themselves anymore,"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fcc13f288168','ch_24484e3ebdf1','text','{"text": "While greedy good-doers, beneficent beasts of prey,"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c12da19c968','ch_24484e3ebdf1','text','{"text": "Swarm over their lives enforcing benefits"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_65c9f45a5e6c','ch_24484e3ebdf1','text','{"text": "That are calculated to soothe them out of their wits,"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a135c1a4aef8','ch_24484e3ebdf1','text','{"text": "And by teaching them how to sleep they sleep all day,"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3394b31ed64e','ch_24484e3ebdf1','text','{"text": "Destroy their sleeping at night the ancient way."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b1e6bc4d3ff','ch_24484e3ebdf1','text','{"text": "Sometimes I feel myself I can hardly bear"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8dbcf878f5dc','ch_24484e3ebdf1','text','{"text": "The thought of so much childish longing in vain,"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82e0a73fb75b','ch_24484e3ebdf1','text','{"text": "The sadness that lurks near the open window there,"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_adec6d189ed6','ch_24484e3ebdf1','text','{"text": "That waits all day in almost open prayer"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b763ff30c098','ch_24484e3ebdf1','text','{"text": "For the squeal of brakes, the sound of a stopping car,"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d96f09489903','ch_24484e3ebdf1','text','{"text": "Of all the thousand selfish cars that pass,"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2de4c9d78453','ch_24484e3ebdf1','text','{"text": "Just one to inquire what a farmer’s prices are."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_190f73351d1c','ch_24484e3ebdf1','text','{"text": "And one did stop, but only to plow up grass"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_94ca86f8976a','ch_24484e3ebdf1','text','{"text": "In using the yard to back and turn around;"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_69863c6c48ab','ch_24484e3ebdf1','text','{"text": "And another to ask the way to where it was bound;"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0fed54b3ae7b','ch_24484e3ebdf1','text','{"text": "And another to ask could they sell it a gallon of gas"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_100cc8181069','ch_24484e3ebdf1','text','{"text": "They couldn’t (this crossly); they had none, didn’t it see?"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_716f68169afa','ch_24484e3ebdf1','text','{"text": "No, in country money, the country scale of gain,"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_215602b999d6','ch_24484e3ebdf1','text','{"text": "The requisite lift of spirit has never been found,"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_226f58888c88','ch_24484e3ebdf1','text','{"text": "Or so the voice of the country seems to complain,"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_794e67b8445b','ch_24484e3ebdf1','text','{"text": "I can’t help owning the great relief it would be"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a99e2136d1ee','ch_24484e3ebdf1','text','{"text": "To put these people at one stroke out of their pain."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a556f0f94689','ch_24484e3ebdf1','text','{"text": "And then next day as I come back into the sane,"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3fe65201e95f','ch_24484e3ebdf1','text','{"text": "I wonder how I should like you to come to me"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c405fb4f146','ch_24484e3ebdf1','text','{"text": "And offer to put me gently out of my pain."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75c8db5da0e8','ch_24484e3ebdf1','list','{"ordered": false, "items": ["Robert Frost"]}',52);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_6e1430efb5b9','bk_ncert_english','12-35-aunt-jennifer-s-tigers','12.35 Aunt Jennifer’s Tigers',NULL,'public',107,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_39741d082707','ch_6e1430efb5b9','text','{"text": "Aunt Jennifer’s tigers prance across a screen,"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bbb501a78fd0','ch_6e1430efb5b9','text','{"text": "Bright topaz denizens of a world of green."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6393814a85d7','ch_6e1430efb5b9','text','{"text": "They do not fear the men beneath the tree;"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_237429d0c223','ch_6e1430efb5b9','text','{"text": "They pace in sleek chivalric certainty."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ff0ea0210d3','ch_6e1430efb5b9','text','{"text": "Aunt Jennifer’s fingers fluttering through her wool"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_852d42e2a613','ch_6e1430efb5b9','text','{"text": "Find even the ivory needle hard to pull."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac36d0d1147a','ch_6e1430efb5b9','text','{"text": "The massive weight of Uncle’s wedding band"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_039e9ca86fd4','ch_6e1430efb5b9','text','{"text": "Sits heavily upon Aunt Jennifer’s hand."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d4e8270027d6','ch_6e1430efb5b9','text','{"text": "When Aunt is dead, her terrified hands will lie"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05dac4fc53d3','ch_6e1430efb5b9','text','{"text": "Still ringed with ordeals she was mastered by."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1316b55fa6f7','ch_6e1430efb5b9','text','{"text": "The tigers in the panel that she made"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6842ee8eea0e','ch_6e1430efb5b9','text','{"text": "Will go on prancing, proud and unafraid."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51817a106843','ch_6e1430efb5b9','list','{"ordered": false, "items": ["Adrienne Rich"]}',13);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_17e7c9058a63','bk_ncert_english','12-36-the-third-level','12.36 The Third Level',NULL,'public',108,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cda5ac8894af','ch_17e7c9058a63','text','{"text": "THE presidents of the New York Central and the New York, New Haven and Hartford railroads will swear on a stack of timetables that there are only two. But I say there are three, because I’ve been on the third level of the Grand Central Station. Yes, I’ve taken the obvious step: I talked to a psychiatrist friend of mine, among others."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_83573ab57c3c','ch_17e7c9058a63','text','{"text": "I told him about the third level at Grand Central Station, and he said it was a wakingdream wish fulfillment. He said I was unhappy. That made my wife kind of mad, but he explained that he meant the modern world is full of insecurity, fear, war, worry and all the rest of it, and that I just want to escape. Well, who doesn’t? Everybody I know wants to escape, but they don’t wander down into any third level at Grand Central Station. But that’s the reason, he said, and my friends all agreed."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e0df74c7dcc3','ch_17e7c9058a63','text','{"text": "Everything points to it, they claimed. My stamp collecting, for example;"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_393e83ae6a1e','ch_17e7c9058a63','text','{"text": "that’s a"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f526e274c8e','ch_17e7c9058a63','text','{"text": "‘temporary refuge from reality.’"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d890e21a55e8','ch_17e7c9058a63','text','{"text": "Well, maybe, but my grandfather didn’t need any refuge from reality;"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5e00c9c12b4b','ch_17e7c9058a63','text','{"text": "things were pretty nice and peaceful in his day, from all I hear, and he started my collection. It’s a nice collection too, blocks of four of practically every U.S. issue, first-day covers, and so on. President Roosevelt collected stamps too, you know. Anyway, here’s what happened at Grand Central. One night last summer I worked late at the office."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1bcdd07beb57','ch_17e7c9058a63','text','{"text": "I was in a hurry to get uptown to my apartment so I decided to take the subway from Grand Central because it’s faster than the bus. Now, I don’t know why this should have happened to me. I’m just an ordinary guy named Charley, thirty-one years old, and I was wearing a tan gabardine suit and a straw hat with a fancy band;"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2be1c708cda1','ch_17e7c9058a63','text','{"text": "I passed a dozen men who looked just like me. And I wasn’t trying to escape from anything;"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ea174273860','ch_17e7c9058a63','text','{"text": "I just wanted to get home to Louisa, my wife."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa0124586cbc','ch_17e7c9058a63','text','{"text": "I turned into Grand Central from Vanderbilt Avenue, and went down the steps to the first level, where you take trains like the Twentieth Century. Then I walked down another flight to the second level, where the suburban trains leave from, ducked into an arched doorway heading for the subway — and got lost. That’s easy to do. I’ve been in and out of Grand Central hundreds of times, but I’m always bumping into new doorways and stairs and corridors."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4061bd4659a1','ch_17e7c9058a63','text','{"text": "Once I got into a tunnel about a mile long and came out in the lobby of the Roosevelt Hotel. Another time I came up in an office building on Forty-sixth Street, three blocks away. Sometimes I think Grand Central is growing like a tree, pushing out new corridors and staircases like roots. There’s probably a long tunnel that nobody knows about feeling its way under the city right now, on its way to Times Square, and maybe another to Central Park."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b50e2b58391','ch_17e7c9058a63','text','{"text": "And maybe — because for so many people through the years Grand Central has been an exit, a way of escape — maybe that’s how the tunnel I got into... But I never told my psychiatrist friend about that idea. The corridor I was in began angling left and slanting downward and I thought that was wrong, but I kept on walking. All I could hear was the empty sound of my own footsteps and I didn’t pass a soul. Then I heard that sort of hollow roar ahead that means open space and people talking."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a1968d05556','ch_17e7c9058a63','text','{"text": "The tunnel turned sharp left;"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20f368ec9be8','ch_17e7c9058a63','text','{"text": "I went down a short flight of stairs and came out on the third level at Grand Central Station. For just a moment I thought I was back on the second level, but I saw the room was smaller, there were fewer ticket windows and train gates, and the information booth in the centre was wood and oldlooking. And the man in the booth wore a green eyeshade and long black sleeve protectors. The lights were dim and sort of flickering."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8d9ea29185c','ch_17e7c9058a63','text','{"text": "Then I saw why;"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9da6aa4d243d','ch_17e7c9058a63','text','{"text": "they were open-flame gaslights. There were brass spittoons on the floor, and across the station a glint of light caught my eye;"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d76c391addae','ch_17e7c9058a63','text','{"text": "a man was pulling a gold watch from his vest pocket. He snapped open the cover, glanced at his watch and frowned. He wore a derby hat, a black four-button suit with tiny lapels, and he had a big, black, handlebar mustache."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa93ceb5b28a','ch_17e7c9058a63','text','{"text": "Then I looked around and saw that everyone in the station was dressed like eighteen-ninety-something;"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9158e9e78dce','ch_17e7c9058a63','text','{"text": "I never saw so many beards, sideburns and fancy mustaches in my life. A woman walked in through the train gate;"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_52417a090544','ch_17e7c9058a63','text','{"text": "she wore a dress with leg-ofmutton sleeves and skirts to the top of her high-buttoned shoes. Back of her, out on the tracks, I caught a glimpse of a locomotive, a very small Currier & Ives locomotive with a funnel-shaped stack. And then I knew."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9cf2c0b7ae53','ch_17e7c9058a63','text','{"text": "To make sure, I walked over to a newsboy and glanced at the stack of papers at his feet. It was The World;"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_356eea4f3ab9','ch_17e7c9058a63','text','{"text": "and The World hasn’t been published for years. The lead story said something about President Cleveland. I’ve found that front page since, in the Public Library files, and it was printed June 11, 1894. I turned toward the ticket windows knowing that here — on the third level at Grand Central — I could buy tickets that would take Louisa and me anywhere in the United States we wanted to go."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d8bb4236afb8','ch_17e7c9058a63','text','{"text": "In the year 1894. And I wanted two tickets to Galesburg, Illinois. Have you ever been there? It’s a wonderful town still, with big old frame houses, huge lawns, and tremendous trees whose branches meet overhead and roof the streets. And in 1894, summer evenings were twice as long, and people sat out on their lawns, the men smoking cigars and talking quietly, the women waving palm-leaf fans, with the fire-flies all around, in a peaceful world."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_183102067e90','ch_17e7c9058a63','text','{"text": "To be back there with the First World War still twenty years off, and World War II over forty years in the future... I wanted two tickets for that. The clerk figured the fare — he glanced at my fancy hatband, but he figured the fare — and I had enough for two coach tickets, one way. But when I counted out the money and looked up, the clerk was staring at me. He nodded at the bills."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ed0b25bb3244','ch_17e7c9058a63','text','{"text": "‘‘That ain’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b45f2ddc35a','ch_17e7c9058a63','text','{"text": "t money, mister,’’ he said, ‘‘and if you’"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_88df69406658','ch_17e7c9058a63','text','{"text": "re trying to skin me, you won’t get very far,’’ and he glanced at the cash drawer beside him. Of course the money was old-style bills, half again as big as the money we use nowadays, and different-looking. I turned away and got out fast. There’s nothing nice about jail, even in 1894. And that was that. I left the same way I came, I suppose."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_681867e6ae5a','ch_17e7c9058a63','text','{"text": "Next day, during lunch hour, I drew three hundred dollars out of the bank, nearly all we had, and bought old-style currency (that really worried my psychiatrist friend). You can buy old money at almost any coin dealer’s, but you have to pay a premium. My three hundred dollars bought less than two hundred in old-style bills, but I didn’t care;"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1daf43261e22','ch_17e7c9058a63','text','{"text": "eggs were thirteen cents a dozen in 1894."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abb35110be65','ch_17e7c9058a63','text','{"text": "But I’ve never again found the corridor that leads to the third level at Grand Central Station, although I’ve tried often enough. Louisa was pretty worried when I told her all this, and didn’t want me to look for the third level any more, and after a while I stopped;"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82492e95785a','ch_17e7c9058a63','text','{"text": "I went back to my stamps. But now we’re both looking, every weekend, because now we have proof that the third level is still there."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43530963b414','ch_17e7c9058a63','text','{"text": "My friend Sam Weiner disappeared! Nobody knew where, but I sort of suspected because Sam’s a city boy, and I used to tell him about Galesburg — I went to school there — and he always said he liked the sound of the place. And that’s where he is, all right. In 1894."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db41f7ffb5cd','ch_17e7c9058a63','text','{"text": "Because one night, fussing with my stamp collection, I found — Well, do you know what a first-day cover is? When a new stamp is issued, stamp collectors buy some and use them to mail envelopes to themselves on the very first day of sale;"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d539eed3736','ch_17e7c9058a63','text','{"text": "and the postmark proves the date. The envelope is called a first-day cover. They’re never opened;"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0181c2ee14e1','ch_17e7c9058a63','text','{"text": "you just put blank paper in the envelope. That night, among my oldest first-day covers, I found one that shouldn’t have been there. But there it was."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f8224542455','ch_17e7c9058a63','text','{"text": "It was there because someone had mailed it to my grandfather at his home in Galesburg;"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_acb2258cb1af','ch_17e7c9058a63','text','{"text": "that’s what the address on the envelope said. And it had been there since July 18, 1894 — the postmark showed that — yet I didn’t remember it at all. The stamp was a six-cent, dull brown, with a picture of President Garfield. Naturally, when the envelope came to Granddad in the mail, it went right into his collection and stayed there — till I took it out and opened it. The paper inside wasn’t blank."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a711ef5a285','ch_17e7c9058a63','text','{"text": "It read:"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e6fa8a394338','ch_17e7c9058a63','text','{"text": "941 Willard Street"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_563143870130','ch_17e7c9058a63','text','{"text": "Galesburg, Illinois"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1780f7412c8b','ch_17e7c9058a63','text','{"text": "July 18, 1894"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d41fb256c398','ch_17e7c9058a63','text','{"text": "Charley"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2410f41d0bd5','ch_17e7c9058a63','text','{"text": "I got to wishing that you were right. Then I got to believing"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ed7ca096105','ch_17e7c9058a63','text','{"text": "you were right. And, Charley, it’s true; I found the third level!"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_831453322c00','ch_17e7c9058a63','text','{"text": "I’ve been here two weeks, and right now, down the street at the"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1dafb86a0d03','ch_17e7c9058a63','text','{"text": "Daly’s, someone is playing a piano, and they’re all out on the front"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_326968967c93','ch_17e7c9058a63','text','{"text": "porch singing ‘Seeing Nelly Home.’ And I’m invited over for"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e86cd736703','ch_17e7c9058a63','text','{"text": "lemonade. Come on back, Charley and Louisa. Keep looking till you"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4fd21e44d685','ch_17e7c9058a63','text','{"text": "find the third level! It’s worth it, believe me!"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ed107dab410','ch_17e7c9058a63','text','{"text": "The note is signed Sam. At the stamp and coin store I go to, I found out that Sam bought eight hundred dollars’ worth of old-style currency. That ought to set him up in a nice little hay, feed and grain business;"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3868c8cb6c2a','ch_17e7c9058a63','text','{"text": "he always said that’s what he really wished he could do, and he certainly can’t go back to his old business. Not in Galesburg, Illinois, in 1894. His old business? Why, Sam was my psychiatrist."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53116ac429d7','ch_17e7c9058a63','list','{"ordered": false, "items": ["Jack Finney"]}',53);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_a37e720d6a35','bk_ncert_english','12-37-the-tiger-king','12.37 The Tiger King',NULL,'public',109,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0569976c147f','ch_a37e720d6a35','heading','{"level": 2, "text": "I"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3bd647618de7','ch_a37e720d6a35','text','{"text": "THE Maharaja of Pratibandapuram is the hero of this story. He may be identified as His Highness Jamedar-General, Khiledar-Major, Sata Vyaghra Samhari, Maharajadhiraja Visva Bhuvana Samrat, Sir Jilani Jung Jung Bahadur, M.A.D., A.C.T.C., or C.R.C.K. But this name is often shortened to the Tiger King. I have come forward to tell you why he came to be known as Tiger King."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bfb4956895d8','ch_a37e720d6a35','text','{"text": "I have no intention of pretending to advance only to end in a strategic withdrawal. Even the threat of a Stuka bomber will not throw me off track. The Stuka, if it likes, can beat a hasty retreat from my story. Right at the start, it is imperative to disclose a matter of vital importance about the Tiger King. Everyone who reads of him will experience the natural desire to meet a man of his indomitable courage face-to-face. But there is no chance of its fulfilment."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec4df228cef0','ch_a37e720d6a35','text','{"text": "As Bharata said to Rama about Dasaratha, the Tiger King has reached that final abode of all living creatures. In other words, the Tiger King is dead. The manner of his death is a matter of extraordinary interest. It can be revealed only at the end of the tale. The most fantastic aspect of his demise was that as soon as he was born, astrologers had foretold that one day the Tiger King would actually have to die."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_084f3df07f12','ch_a37e720d6a35','text','{"text": "‘The child will grow up to become the warrior of warriors, hero of heroes, champion of champions. But...’"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_794e02951e17','ch_a37e720d6a35','text','{"text": "they bit their lips and swallowed hard. When compelled to continue, the astrologers came out with it."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_39bb7e3c18ef','ch_a37e720d6a35','text','{"text": "‘This is a secret which should not be revealed at all. And yet we are forced to speak out. The child born under this star will one day have to meet its death.’"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d83eb032de9','ch_a37e720d6a35','text','{"text": "At that very moment a great miracle took place. An astonishing phrase emerged from the lips of the ten-dayold Jilani Jung Jung Bahadur, ‘O wise prophets!’’ Everyone stood transfixed in stupefaction. They looked wildly at each other and blinked."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6244589e476f','ch_a37e720d6a35','text','{"text": "‘‘O wise prophets! It was I who spoke.’"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef92d41a906f','ch_a37e720d6a35','text','{"text": "’ This time there were no grounds for doubt. It was the infant born just ten days ago who had enunciated the words so clearly. The chief astrologer took off his spectacles and gazed intently at the baby."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_281983821b21','ch_a37e720d6a35','text','{"text": "‘‘All those who are born will one day have to die. We don’t need your predictions to know that. There would be some sense in it if you could tell us the manner of that death,’’ the royal infant uttered these words in his little squeaky voice. The chief astrologer placed his finger on his nose in wonder. A baby barely ten days old opens its lips in speech! Not only that, it also raises intelligent questions! Incredible! Rather like the bulletins issued by the war office, than facts."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e0fc4be9a3d9','ch_a37e720d6a35','text','{"text": "The chief astrologer took his finger off his nose and fixed his eyes upon the little prince."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac513369a520','ch_a37e720d6a35','text','{"text": "‘‘The prince was born in the hour of the Bull. The Bull and the Tiger are enemies, therefore, death comes from the Tiger,’’ he explained. You may think that crown prince Jung Jung Bahadur was thrown into a quake when he heard the word ‘Tiger’. That was exactly what did not happen. As soon as he heard it pronounced, the crown prince gave a deep growl. Terrifying words emerged from his lips."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9faddf6595bb','ch_a37e720d6a35','text','{"text": "‘‘Let tigers beware!’’ This account is only a rumour rife in Pratibandapuram. But with hindsight we may conclude it was based on some truth."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_851848042112','ch_a37e720d6a35','heading','{"level": 2, "text": "Ii"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f9ff0ad1553c','ch_a37e720d6a35','text','{"text": "Crown prince Jung Jung Bahadur grew taller and stronger day by day. No other miracle marked his childhood days apart from the event already described."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_367063287f1d','ch_a37e720d6a35','text','{"text": "The boy drank the milk of an English cow, was brought up by an English nanny, tutored in English by an Englishman, saw nothing but English films — exactly as the crown princes of all the other Indian states did. When he came of age at twenty, the State, which had been with the Court of Wards until then, came into his hands. But everyone in the kingdom remembered the astrologer’s prediction. Many continued to discuss the matter. Slowly it came to the Maharaja’s ears."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d192f4dfbb1','ch_a37e720d6a35','text','{"text": "There were innumerable forests in the Pratibandapuram State. They had tigers in them. The Maharaja knew the old saying, ‘You may kill even a cow in self-defence’. There could certainly be no objection to killing tigers in self-defence. The Maharaja started out on a tiger hunt. The Maharaja was thrilled beyond measure when he killed his first tiger. He sent for the State astrologer and showed him the dead beast."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c2b9f2b31e5','ch_a37e720d6a35','text','{"text": "‘‘What do you say now?’’ he demanded. ‘‘Your majesty may kill ninety-nine tigers in exactly the same manner. But...’’ the astrologer drawled. ‘‘But what? Speak without fear.’’"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb6e89ce2c14','ch_a37e720d6a35','text','{"text": "‘But you must be very careful with the hundredth tiger.’’‘‘What if the hundredth tiger were also killed?’’ ‘‘Then I will tear up all my books on astrology, set fire to them, and…’’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_457c69240360','ch_a37e720d6a35','text','{"text": "‘‘And…’’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4fc64d8b3495','ch_a37e720d6a35','text','{"text": "‘‘I shall cut off my tuft, crop my hair short and become an insurance agent,’’ the astrologer finished on an incoherent note."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff66e9a00c7d','ch_a37e720d6a35','heading','{"level": 2, "text": "Iii"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb1b0c24db98','ch_a37e720d6a35','text','{"text": "From that day onwards it was celebration time for all the tigers inhabiting Pratibandapuram. The State banned tiger hunting by anyone except the Maharaja. A proclamation was issued to the effect that if anyone dared to fling so much as a stone at a tiger, all his wealth and property would be confiscated. The Maharaja vowed he would attend to all other matters only after killing the hundred tigers."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_262393999071','ch_a37e720d6a35','text','{"text": "Initially the king seemed well set to realise his ambition. Not that he faced no dangers. There were times when the bullet missed its mark, the tiger leapt upon him and he fought the beast with his bare hands. Each time it was the Maharaja who won. At another time he was in danger of losing his throne. A high-ranking British officer visited Pratibandapuram. He was very fond of hunting tigers. And fonder of being photographed with the tigers he had shot."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b44fe68a4637','ch_a37e720d6a35','text','{"text": "As usual, he wished to hunt tigers in Pratibandapuram. But the Maharaja was firm in his resolve. He refused permission."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7de72d960662','ch_a37e720d6a35','text','{"text": "‘‘I can organise any other hunt. You may go on a boar hunt. You may conduct a mouse hunt. We are ready for a mosquito hunt. But tiger hunt! That’"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a6271a164ec9','ch_a37e720d6a35','text','{"text": "s impossible!’’ The British officer’s secretary sent word to the Maharaja through the dewan that the durai himself did not have to kill the tiger. The Maharaja could do the actual killing. What was important to the durai was a photograph of himself holding the gun and standing over the tiger’s carcass. But the Maharaja would not agree even to this proposal."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c6ab67054e61','ch_a37e720d6a35','text','{"text": "If he relented now, what would he do if other British officers turned up for tiger hunts? Because he prevented a British officer from fulfilling his desire, the Maharaja stood in danger of losing his kingdom itself. The Maharaja and the dewan held deliberations over this issue. As a result, a telegram was despatched forthwith to a famous British company of jewellers in Calcutta."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0fb9b902a6dd','ch_a37e720d6a35','text','{"text": "‘Send samples of expensive diamond rings of different designs.’"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cfa85b7d3a3c','ch_a37e720d6a35','text','{"text": "Some fifty rings arrived. The Maharaja sent the whole lot to the British officer’s good lady. The king and the minister expected the duraisani to choose one or two rings and send the rest back. Within no time at all the duraisani sent her reply:"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aba2245c0459','ch_a37e720d6a35','text','{"text": "‘Thank you very much for your gifts.’"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c4f2ee054b04','ch_a37e720d6a35','text','{"text": "In two days a bill for three lakh of rupees came from the British jewellers. The Maharaja was happy that though he had lost three lakh of rupees, he had managed to retain his kingdom."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_023c7301ad72','ch_a37e720d6a35','heading','{"level": 2, "text": "Iv"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d6257922d57','ch_a37e720d6a35','text','{"text": "The Maharaja’s tiger hunts continued to be highly successful. Within ten years he was able to kill seventy tigers. And then, an unforeseen hurdle brought his mission to a standstill. The tiger population became extinct in the forests of Pratibandapuram."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bf690254fcb6','ch_a37e720d6a35','text','{"text": "Who knows whether the tigers practised birth control or committed harakiri? Or simply ran away from the State because they desired to be shot by British hands alone? One day the Maharaja sent for the dewan."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd88f1fb445b','ch_a37e720d6a35','text','{"text": "‘‘Dewan saheb, aren’"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b4bff661703a','ch_a37e720d6a35','text','{"text": "t you aware of the fact that thirty tigers still remain to be shot down by this gun of mine?’’ he asked brandishing his gun. Shuddering at the sight of the gun, the dewan cried out, ‘‘Your Majesty! I am not a tiger!’’"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_89676edc11e6','ch_a37e720d6a35','text','{"text": "‘‘Which idiot would call you a tiger?’’"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6cf02c627237','ch_a37e720d6a35','text','{"text": "‘No, and I’m not a gun!’’"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2b8117c7f58','ch_a37e720d6a35','text','{"text": "‘You are neither tiger nor gun. Dewan saheb, I summoned you here for a different purpose. I have decided to get married.’’ The dewan began to babble even more."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_63201f5c544d','ch_a37e720d6a35','text','{"text": "‘‘Your Majesty, I have two wives already. If I marry you ...’’"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58d84ecbc562','ch_a37e720d6a35','text','{"text": "‘‘Don’t talk nonsense! Why should I marry you? What I want is a tiger...’’"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef94a73e16b1','ch_a37e720d6a35','text','{"text": "‘‘Your Majesty! Please think it over. Your ancestors were married to the sword. If you like, marry the gun. A Tiger King is more than enough for this state. It doesn’t need a Tiger Queen as well!’’ The Maharaja gave a loud crack of laughter."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35a02a646a71','ch_a37e720d6a35','text','{"text": "‘‘I’m not thinking of marrying either a tiger or a gun, but a girl from the ranks of human beings. First you may draw up statistics of tiger populations in the different native states. Next you may investigate if there is a girl I can marry in the royal family of a state with a large tiger population.’"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e03e4fe5f1c','ch_a37e720d6a35','text','{"text": "’ The dewan followed his orders. He found the right girl from a state which possessed a large number of tigers. Maharaja Jung Jung Bahadur killed five or six tigers each time he visited his father-in-law. In this manner, ninety-nine tiger skins adorned the walls of the reception hall in the Pratibandapuram palace."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea8ce68e3c68','ch_a37e720d6a35','heading','{"level": 2, "text": "V"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_56a50fed601b','ch_a37e720d6a35','text','{"text": "The Maharaja’s anxiety reached a fever pitch when there remained just one tiger to achieve his tally of a hundred."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3695dafa283','ch_a37e720d6a35','text','{"text": "He had this one thought during the day and the same dream at night. By this time the tiger farms had run dry even in his father-in-Iaw’s kingdom. It became impossible to locate tigers anywhere. Yet only one more was needed. If he could kill just that one single beast, the Maharaja would have no fears left. He could give up tiger hunting altogether. But he had to be extremely careful with that last tiger. What had the late chief astrologer said?"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df7aa54ecc77','ch_a37e720d6a35','text','{"text": "‘Even after killing ninety-nine tigers the Maharaja should beware of the hundredth...’"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_757aa5189b44','ch_a37e720d6a35','text','{"text": "’ True enough. The tiger was a savage beast after all. One had to be wary of it. But where was that hundredth tiger to be found? It seemed easier to find tiger’s milk than a live tiger. Thus the Maharaja was sunk in gloom. But soon came the happy news which dispelled that gloom. In his own state sheep began to disappear frequently from a hillside village."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a4466db3690','ch_a37e720d6a35','text','{"text": "It was first ascertained that this was not the work of Khader Mian Saheb or Virasami Naicker, both famed for their ability to swallow sheep whole. Surely, a tiger was at work. The villagers ran to inform the Maharaja. The Maharaja announced a three-year exemption from all taxes for that village and set out on the hunt at once. The tiger was not easily found. It seemed as if it had wantonly hid itself in order to flout the Maharaja’s will. The Maharaja was equally determined."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_08c701b04f9a','ch_a37e720d6a35','text','{"text": "He refused to leave the forest until the tiger was found. As the days passed, the Maharaja’s fury and obstinacy mounted alarmingly. Many officers lost their jobs. One day when his rage was at its height, the Maharaja called the dewan and ordered him to double the land tax forthwith."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_733e1cc23ccf','ch_a37e720d6a35','text','{"text": "‘‘The people will become discontented. Then our state too will fall a prey to the Indian National Congress.’’"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_15691cc56810','ch_a37e720d6a35','text','{"text": "‘‘In that case you may resign from your post,’’ said the king. The dewan went home convinced that if the Maharaja did not find the tiger soon, the results could be catastrophic. He felt life returning to him only when he saw the tiger which had been brought from the People’s Park in Madras and kept hidden in his house. At midnight when the town slept in peace, the dewan and his aged wife dragged the tiger to the car and shoved it into the seat. The dewan himself drove the car straight to the forest where the Maharaja was hunting."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4d9a473b00b','ch_a37e720d6a35','text','{"text": "When they reached the forest the tiger launched its satyagraha and refused to get out of the car. The dewan was thoroughly exhausted in his efforts to haul the beast out of the car and push it down to the ground. On the following day, the same old tiger wandered into the Maharaja’s presence and stood as if in humble supplication, ‘Master, what do you command of me?’’ It was with boundless joy that the Maharaja took careful aim at the beast. The tiger fell in a crumpled heap."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50576c3d271d','ch_a37e720d6a35','text','{"text": "‘‘I have killed the hundredth tiger. My vow has been fulfilled,’’ the Maharaja was overcome with elation. Ordering the tiger to be brought to the capital in grand procession, the Maharaja hastened away in his car. After the Maharaja left, the hunters went to take a closer look at the tiger. The tiger looked back at them rolling its eyes in bafflement. The men realised that the tiger was not dead;"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_946e684eb2ca','ch_a37e720d6a35','text','{"text": "the bullet had missed it. It had fainted from the shock of the bullet whizzing past. The hunters wondered what they should do."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18d6d5b99442','ch_a37e720d6a35','text','{"text": "They decided that the Maharaja must not come to know that he had missed his target. If he did, they could lose their jobs. One of the hunters took aim from a distance of one foot and shot the tiger. This time he killed it without missing his mark. Then, as commanded by the king, the dead tiger was taken in procession through the town and buried. A tomb was erected over it. A few days later the Maharaja’s son’s third birthday was celebrated."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58df5d145450','ch_a37e720d6a35','text','{"text": "Until then the Maharaja had given his entire mind over to tiger hunting. He had had no time to spare for the crown prince. But now the king turned his attention to the child. He wished to give him some special gift on his birthday. He went to the shopping centre in Pratibandapuram and searched every shop, but couldn’t find anything suitable. Finally he spotted a wooden tiger in a toyshop and decided it was the perfect gift. The wooden tiger cost only two annas and a quarter."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_356df43107a7','ch_a37e720d6a35','text','{"text": "But the shopkeeper knew that if he quoted such a low price to the Maharaja, he would be punished under the rules of the Emergency. So, he said, ‘‘Your Majesty, this is an extremely rare example of craftsmanship. A bargain at three hundred rupees!’’"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f4f7dd69a813','ch_a37e720d6a35','text','{"text": "‘‘Very good. Let this be your offering to the crown prince on his birthday,’’ said the king and took it away with him. On that day father and son played with that tiny little wooden tiger. It had been carved by an unskilled carpenter. Its surface was rough;"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c2e0280b0a7','ch_a37e720d6a35','text','{"text": "tiny slivers of wood stood up like quills all over it. One of those slivers pierced the Maharaja’s right hand. He pulled it out with his left hand and continued to play with the prince. The next day, infection flared in the Maharaja’s right hand."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d1d2ed7128e','ch_a37e720d6a35','text','{"text": "In four days, it developed into a suppurating sore which spread all over the arm. Three famous surgeons were brought in from Madras. After holding a consultation they decided to operate. The operation took place. The three surgeons who performed it came out of the theatre and announced, ‘The operation was successful. The Maharaja is dead.’"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3dbd4a5282c5','ch_a37e720d6a35','text','{"text": "In this manner the hundredth tiger took its final revenge upon the Tiger King."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74c0b52932e5','ch_a37e720d6a35','list','{"ordered": false, "items": ["Kalki"]}',66);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_6f97dbc83e28','bk_ncert_english','12-38-journey-to-the-end-of-the-earth','12.38 Journey to the end of the Earth',NULL,'public',110,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ed5ac8e40758','ch_6f97dbc83e28','text','{"text": "EARLY this year, I found myself aboard a Russian research vessel — the Akademik Shokalskiy — heading towards the coldest, driest, windiest continent in the world: Antarctica. My journey began 13.09 degrees north of the Equator in Madras, and involved crossing nine time zones, six checkpoints, three bodies of water, and at least as many ecospheres."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67072522ab71','ch_6f97dbc83e28','text','{"text": "By the time I actually set foot on the Antarctic continent I had been travelling over 100 hours in combination of a car, an aeroplane and a ship;"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_11e7fe883757','ch_6f97dbc83e28','text','{"text": "so, my first emotion on facing Antarctica’s expansive white landscape and uninterrupted blue horizon was relief, followed up with an immediate and profound wonder. Wonder at its immensity, its isolation, but mainly at how there could ever have been a time when India and Antarctica were part of the same landmass."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8833db7d4ad9','ch_6f97dbc83e28','text','{"text": "Part of History"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b7d439d89853','ch_6f97dbc83e28','text','{"text": "Six hundred and fifty million years ago, a giant amalgamated southern supercontinent — Gondwana — did indeed exist, centred roughly around the present-day Antarctica. Things were quite different then: humans hadn’t arrived on the global scene, and the climate was much warmer, hosting a huge variety of flora and fauna."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18b4db7ce978','ch_6f97dbc83e28','text','{"text": "For 500 million years Gondwana thrived, but around the time when the dinosaurs were wiped out and the age of the mammals got under way, the landmass was forced to separate into countries, shaping the globe much as we know it today. To visit Antarctica now is to be a part of that history;"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fdea2942b571','ch_6f97dbc83e28','text','{"text": "to get a grasp of where we’ve come from and where we could possibly be heading."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_19dffed6f2b3','ch_6f97dbc83e28','text','{"text": "It’s to understand the significance of Cordilleran folds and pre-Cambrian granite shields;"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9eb2331710f0','ch_6f97dbc83e28','text','{"text": "ozone and carbon;"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_47a7dbc0a4b1','ch_6f97dbc83e28','text','{"text": "evolution and extinction. When you think about all that can happen in a million years, it can get pretty mind-boggling."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f526f98fccd','ch_6f97dbc83e28','text','{"text": "Imagine: India pushing northwards, jamming against Asia to buckle its crust and form the Himalayas;"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_310a3a34f9d8','ch_6f97dbc83e28','text','{"text": "South America drifting off to join North America, opening up the Drake Passage to create a cold circumpolar current, keeping Antarctica frigid, desolate, and at the bottom of the world."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27ee0ffe7d60','ch_6f97dbc83e28','text','{"text": "For a sun-worshipping South Indian like myself, two weeks in a place where 90 per cent of the Earth’s total ice volumes are stored is a chilling prospect (not just for circulatory and metabolic functions, but also for the imagination). It’s like walking into a giant ping-pong ball devoid of any human markers — no trees, billboards, buildings. You lose all earthly sense of perspective and time here."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7d0508e82b5b','ch_6f97dbc83e28','text','{"text": "The visual scale ranges from the microscopic to the mighty: midges and mites to blue whales and icebergs as big as countries (the largest recorded was the size of Belgium). Days go on and on and on in surreal 24-hour austral summer light, and a ubiquitous silence, interrupted only by the occasional avalanche or calving ice sheet, consecrates the place. It’s an immersion that will force you to place yourself in the context of the earth’s geological history."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4db8a4d3d41a','ch_6f97dbc83e28','text','{"text": "And for humans, the prognosis isn’t good."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24dd5a9d4402','ch_6f97dbc83e28','text','{"text": "Human Impact"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2755b9ea4b5f','ch_6f97dbc83e28','text','{"text": "Human civilisations have been around for a paltry 12,000 years — barely a few seconds on the geological clock. In that short amount of time, we’ve managed to create quite a ruckus, etching our dominance over Nature with our villages, towns, cities, megacities."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51a799632318','ch_6f97dbc83e28','text','{"text": "The rapid increase of human populations has left us battling with other species for limited resources, and the unmitigated burning of fossil fuels has now created a blanket of carbon dioxide around the world, which is slowly but surely increasing the average global temperature. Climate change is one of the most hotly contested environmental debates of our time."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_77eb77dff678','ch_6f97dbc83e28','text','{"text": "Will the West Antarctic ice sheet melt entirely? Will the Gulf Stream ocean current be disrupted? Will it be the end of the world as we know it? Maybe. Maybe not."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_055a8ae930c7','ch_6f97dbc83e28','text','{"text": "Either way, Antarctica is a crucial element in this debate — not just because it’s the only place in the world, which has never sustained a human population and therefore remains relatively ‘pristine’ in this respect;"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b88422eef09b','ch_6f97dbc83e28','text','{"text": "but more importantly, because it holds in its ice-cores half-million-year-old carbon records trapped in its layers of ice. If we want to study and examine the Earth’s past, present and future, Antarctica is the place to go."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cfba59c4d18f','ch_6f97dbc83e28','text','{"text": "Students on Ice, the programme I was working with on the Shokaskiy, aims to do exactly this by taking high school students to the ends of the world and providing them with inspiring educational opportunities which will help them foster a new understanding and respect for our planet. It’s been in operation for six years now, headed by Canadian Geoff Green, who got tired of carting celebrities and retired, rich, curiosity-seekers who could only ‘give’ back in a limited way."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_acf3dedb3cb5','ch_6f97dbc83e28','text','{"text": "With Students on Ice, he offers the future generation of policy-makers a life-changing experience at an age when they’re ready to absorb, learn, and most importantly, act. The reason the programme has been so successful is because it’s impossible to go anywhere near the South Pole and not be affected by it."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eafc260846e9','ch_6f97dbc83e28','text','{"text": "It’s easy to be blasé about polar ice-caps melting while sitting in the comfort zone of our respective latitude and longitude, but when you can visibly see glaciers retreating and ice shelves collapsing, you begin to realise that the threat of global warming is very real. Antarctica, because of her simple ecosystem and lack of biodiversity, is the perfect place to study how little changes in the environment can have big repercussions."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70582d16bc23','ch_6f97dbc83e28','text','{"text": "Take the microscopic phytoplankton — those grasses of the sea that nourish and sustain the entire Southern Ocean’s food chain. These single-celled plants use the sun’s energy to assimilate carbon and synthesise organic compounds in that wondrous and most important of processes called photosynthesis."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ec0d0aa4c5d','ch_6f97dbc83e28','text','{"text": "Scientists warn that a further depletion in the ozone layer will affect the activities of phytoplankton, which in turn will affect the lives of all the marine animals and birds of the region, and the global carbon cycle. In the parable of the phytoplankton, there is a great metaphor for existence: take care of the small things and the big things will fall into place."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f63e9cc42d7','ch_6f97dbc83e28','text','{"text": "Walk on the Ocean"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6fbd01c31ae5','ch_6f97dbc83e28','text','{"text": "My Antarctic experience was full of such epiphanies, but the best occurred just short of the Antarctic Circle at 65.55 degrees south. The Shokalskiy had managed to wedge herself into a thick white stretch of ice between the peninsula and Tadpole Island which was preventing us from going any further."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_29323ce04039','ch_6f97dbc83e28','text','{"text": "The Captain decided we were going to turn around and head back north, but before we did, we were all instructed to climb down the gangplank and walk on the ocean. So there we were, all 52 of us, kitted out in Gore-Tex and glares, walking on a stark whiteness that seemed to spread out forever. Underneath our feet was a metre-thick ice pack, and underneath that, 180 metres of living, breathing, salt water."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_72b48ccfb8fd','ch_6f97dbc83e28','text','{"text": "In the periphery Crabeater seals were stretching and sunning themselves on ice floes much like stray dogs will do under the shade of a banyan tree. It was nothing short of a revelation: everything does indeed connect. Nine time zones, six checkpoints, three bodies of water and many ecospheres later, I was still wondering about the beauty of balance in play on our planet."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ef8bb667860','ch_6f97dbc83e28','text','{"text": "How would it be if Antarctica were to become the warm place that it once used to be? Will we be around to see it, or would we have gone the way of the dinosaurs, mammoths and woolly rhinos? Who’s to say? But after spending two weeks with a bunch of teenagers who still have the idealism to save the world, all I can say is that a lot can happen in a million years, but what a difference a day makes!"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d90e5287dfff','ch_6f97dbc83e28','list','{"ordered": false, "items": ["Tishani Doshi"]}',32);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_eb687440e711','bk_ncert_english','12-39-the-enemy','12.39 The Enemy',NULL,'public',111,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02cdd1c5b606','ch_eb687440e711','text','{"text": "Dr Sadao Hoki''s house was built on a spot of the Japanese coast where as a little boy he had often played. The low, square stone house was set upon rocks well above a narrow beach that was outlined with bent pines. As a boy Sadao had climbed the pines, supporting himself on his bare feet, as he had seen men do in the South Seas when they climbed for coconuts. His father had taken him often to"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ef32709811c','ch_eb687440e711','text','{"text": "the islands of those seas, and never had he failed to say to the little brave boy at his side, ''Those islands yonder, they are the stepping stones to the future for Japan.'' ''Where shall we step from them?'' Sadao had asked seriously."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e3578201596','ch_eb687440e711','text','{"text": "''Who knows?'' his father had answered."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cdc354a8e6d6','ch_eb687440e711','text','{"text": "''Who can limit our future? It depends on what we make it.'' Sadao had taken this into his mind as he did everything his father said, his father who never joked or played with him but who spent infinite pains upon him who was his only son."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8bd3114e8720','ch_eb687440e711','text','{"text": "Sadao knew that his education was his father''s chief concern. For this reason he had been sent at twenty-two to America to learn all that could be learned of surgery and medicine. He had come back at thirty, and before his father died he had seen Sadao become famous not only as a surgeon but as a scientist. Because he was perfecting a discovery which would render wounds entirely clean, he had not been sent abroad with the troops. Also, he knew, there was some slight danger that the old General"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bdcc1464de02','ch_eb687440e711','text','{"text": "might need an operation for a condition for which he was now being treated medically, and for this possibility Sadao was being kept in Japan. Clouds were rising from the ocean now. The unexpected warmth of the past few days had at night drawn heavy fog from the cold waves. Sadao watched mists hide outlines of a little island near the shore and then come creeping up the beach below the house, wreathing around the pines. In a few minutes fog would be wrapped about the house too. Then he would go"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c08346e3f67','ch_eb687440e711','text','{"text": "into the room where Hana, his wife, would be waiting for him with the two children. But at this moment the door opened and she looked out, a dark-blue woollen haori1 over her kimono. She came to him affectionately and put her arm through his as he stood, smiled and said nothing. He had met Hana in America, but he had waited to fall in love with her until he was sure she was Japanese. His father would never have received her unless she had been pure in her race. He wondered often whom he would"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b51499c9037f','ch_eb687440e711','text','{"text": "have married if he had not met Hana, and by what luck he had found her in the most casual way, by chance literally, at an American professor''s house. The professor and his wife had been kind people anxious to do something for their few foreign students, and the students, though bored, had accepted this kindness. Sadao had often told Hana how nearly he had not gone to Professor Harley''s house that night — the rooms were so small, the food so bad, the professor''s wife so voluble. But he had gone"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46ac5c06d371','ch_eb687440e711','text','{"text": "and there he had found Hana, a new student, and had felt he would love her if it were at all possible. Now he felt her hand on his arm and was aware of the pleasure it gave him, even though they had been married years enough to have the two children. For they had not married heedlessly in America. They had finished their work at school and had come home to Japan, and when his father had seen her the marriage had been arranged in the old Japanese way, although Sadao and Hana had talked everything"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bfee1dcffc5f','ch_eb687440e711','text','{"text": "over beforehand. They were perfectly happy. She laid her cheek against his arm. It was at this moment that both of them saw something black come out of the mists. It was a man. He was flung up out of the ocean — flung, it seemed, to his feet by a breaker. He staggered a few steps, his body outlined against the mist, his arms above his head. Then the curled mists hid him again."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb9e8eb4a6e6','ch_eb687440e711','text','{"text": "''Who is that?'' Hana cried."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c7d09859a7cd','ch_eb687440e711','text','{"text": "She dropped Sadao''s arm and they both leaned over the railing of the veranda. Now they saw him again. The man was on his hands and knees crawling. Then they saw him fall on his face and lie there. ''A fisherman perhaps,'' Sadao said, ''washed from his boat.'' He ran quickly down the steps and behind him Hana came, her wide sleeves flying. A mile or two away on either side there were fishing villages, but here was only the bare and lonely coast, dangerous with rocks. The surf beyond the beach was"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4abbd568cb8e','ch_eb687440e711','text','{"text": "spiked with rocks. Somehow the man had managed to come through them — he must be badly torn. They saw when they came toward him that indeed it was so. The sand on one side of him had already a stain of red soaking through."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53aed122ae83','ch_eb687440e711','text','{"text": "''He is wounded,'' Sadao exclaimed."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_252e14558cf2','ch_eb687440e711','text','{"text": "He made haste to the man, who lay motionless, his face in the sand. An old cap stuck to his head soaked with sea water. He was in wet rags of garments. Sadao stopped, Hana at his side, and turned the man''s head. They saw the face. ''A white man!'' Hana whispered. Yes, it was a white man. The wet cap fell away and there was his wet yellow hair, long, as though for many weeks it had not been cut, and upon his young and tortured face was a rough yellow beard. He was unconscious and knew nothing that"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a57426394c7','ch_eb687440e711','text','{"text": "they did for him. Now Sadao remembered the wound, and with his expert fingers he began to search for it. Blood flowed freshly at his touch. On the right side of his lower back Sadao saw that a gun wound had been reopened. The flesh was blackened with powder. Sometime, not many days ago, the man had been shot and had not been tended. It was bad chance that the rock had struck the wound."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c60d7eb00a97','ch_eb687440e711','text','{"text": "''Oh, how he is bleeding!'' Hana whispered again in a solemn voice."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_100b6671eff9','ch_eb687440e711','text','{"text": "The mists screened them now completely, and at this time of day no one came by. The fishermen had gone home and even the chance beachcombers would have considered the day at an end."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d227a4c121f','ch_eb687440e711','text','{"text": "''What shall we do with this man?'' Sadao muttered."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_16a6f5f71f3e','ch_eb687440e711','text','{"text": "But his trained hands seemed of their own will to be doing what they could to stanch the fearful bleeding. He packed the wound with the sea moss that strewed the beach. The man moaned with pain in his stupor but he did not awaken."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_112db6a98342','ch_eb687440e711','text','{"text": "''The best thing that we could do would be to put him back in the sea,'' Sadao said, answering himself."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_acb37f496019','ch_eb687440e711','text','{"text": "Now that the bleeding was stopped for the moment he stood up and dusted the sand from his hands."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_005d41af5119','ch_eb687440e711','text','{"text": "''Yes, undoubtedly that would be best,'' Hana said steadily."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_592af3b46322','ch_eb687440e711','text','{"text": "But she continued to stare down at the motionless man."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_21c680b57158','ch_eb687440e711','text','{"text": "''If we sheltered a white man in our house we should be arrested and if we turned him over as a prisoner, he would certainly die,'' Sadao said."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d8b350cf9ebb','ch_eb687440e711','text','{"text": "''The kindest thing would be to put him back into the sea,'' Hana said."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f2b68380378c','ch_eb687440e711','text','{"text": "But neither of them moved. They were staring with a curious repulsion upon the inert figure."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74783cc45935','ch_eb687440e711','text','{"text": "''What is he?'' Hana whispered."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_08d83bce69ed','ch_eb687440e711','text','{"text": "''There is something about him that looks American,'' Sadao said."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8f38ab76e99','ch_eb687440e711','text','{"text": "He took up the battered cap. Yes, there, almost gone, was the faint lettering."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c3ece4e8e14d','ch_eb687440e711','text','{"text": "''A sailor,'' he said, ''from an American warship.'' He spelled it out: ''U.S. Navy.'' The man was a prisoner of war!"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0935ee4b2e89','ch_eb687440e711','text','{"text": "''He has escaped.'' Hana cried softly, ''and that is why he is wounded.'' ''In the back,'' Sadao agreed."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5319e4d8ad72','ch_eb687440e711','text','{"text": "They hesitated, looking at each other. Then Hana said with resolution: ''Come, are we able to put him back into the sea?'' ''If I am able, are you?'' Sadao asked."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46b45efb14ba','ch_eb687440e711','text','{"text": "''No,'' Hana said, ''But if you can do it alone...'' Sadao hesitated again."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c18a26a6919','ch_eb687440e711','text','{"text": "''The strange thing is,'' he said, ''that if the man were whole I could turn him over to the police without difficulty. I care nothing for him. He is my enemy. All Americans are my enemy. And he is only a common fellow. You see how foolish his face is. But since he is wounded...'' ''You also cannot throw him back to the sea,'' Hana said."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_06f08628e463','ch_eb687440e711','text','{"text": "''Then there is only one thing to do. We must carry him into the house.'' ''But the servants?'' Sadao inquired."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d2fe9225ea80','ch_eb687440e711','text','{"text": "''We must simply tell them that we intend to give him to the police — as indeed we must, Sadao. We must think of the children and your position. It would endanger all of us if we did not give this man over as a prisoner of war.'' ''Certainly,'' Sadao agreed."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dfaadabfc30a','ch_eb687440e711','text','{"text": "''I would not think of doing anything else.'' Thus agreed, together they lifted the man."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a8fe68cf9b2','ch_eb687440e711','text','{"text": "He was very light, like a fowl that had been half-starved for a long time until it is only feathers and skeleton. So, his arms hanging, they carried him up the steps and into the side door of the house. This door opened into a passage, and down the passage they carried the man towards an empty bedroom. It had been the bedroom of Sadao''s father, and since his death it had not been used. They laid the man on the deeply matted floor. Everything here had been Japanese to please the old man, who"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_895d4adbbbab','ch_eb687440e711','text','{"text": "would never in his own home sit on a chair or sleep in a foreign bed. Hana went to the wall cupboards and slid back a door and took out a soft quilt. She hesitated. The quilt was covered with flowered silk and the lining was pure white silk. ''He is so dirty,'' she murmured in distress. ''Yes, he had better be washed,'' Sadao agreed. ''If you will fetch hot water I will wash him.'' ''I cannot bear for you to touch him,'' she said."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb4a92996402','ch_eb687440e711','text','{"text": "''We shall have to tell the servants he is here. I will tell Yumi now. She can leave the children for a few minutes and she can wash him.'' Sadao considered a moment."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f032c372c677','ch_eb687440e711','text','{"text": "''Let it be so,'' he agreed."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c775ec77f04','ch_eb687440e711','text','{"text": "''You tell Yumi and I will tell the others.'' But the utter pallor of the man''s unconscious face moved him first to stoop and feel his pulse. It was faint but it was there. He put his hand against the man''s cold breast."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82ca2d5af12a','ch_eb687440e711','text','{"text": "The heart too was yet alive."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c75a8134c7f','ch_eb687440e711','text','{"text": "''He will die unless he is operated on,'' Sadao said, considering."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fdaf16f921bf','ch_eb687440e711','text','{"text": "''The question is whether he will not die anyway.'' Hana cried out in fear."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b693275cef2d','ch_eb687440e711','text','{"text": "''Don''t try to save him!"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd8de52e6447','ch_eb687440e711','text','{"text": "What if he should live?'' ''What if he should die?'' Sadao replied. He stood gazing down on the motionless man. This man must have extraordinary vitality or he would have been dead by now. But then he was very young — perhaps not yet twentyfive."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_124a77194df4','ch_eb687440e711','text','{"text": "''You mean die from the operation?'' Hana asked."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_150041733de3','ch_eb687440e711','text','{"text": "''Yes,'' Sadao said."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96ffe4f63cc5','ch_eb687440e711','text','{"text": "Hana considered this doubtfully, and when she did not answer Sadao turned away."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f77e72f5bb9b','ch_eb687440e711','text','{"text": "''At any rate something must be done with him,'' he said, ''and first he must be washed.'' He went quickly out of the room and Hana came behind him."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9ce282ac2e9c','ch_eb687440e711','text','{"text": "She did not wish to be left alone with the white man. He was the first she had seen since she left America and now he seemed to have nothing to do with those whom she had known there. Here he was her enemy, a menace, living or dead. She turned to the nursery and called, ''Yumi!'' But the children heard her voice and she had to go in for a moment and smile at them and play with the baby boy, now nearly three months old. Over the baby''s soft black hair she motioned with her mouth, ''Yumi — come with"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_87d26753f6c0','ch_eb687440e711','text','{"text": "me!'' ''I will put the baby to bed,'' Yumi replied."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07870cc259b6','ch_eb687440e711','text','{"text": "''He is ready.'' She went with Yumi into the bedroom next to the nursery and stood with the boy in her arms while Yumi spread the sleeping quilts on the floor and laid the baby between them."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d156d1d96e01','ch_eb687440e711','text','{"text": "Then Hana led the way quickly and softly to the kitchen. The two servants were frightened at what their master had just told them. The old gardener, who was also a house servant, pulled the few hairs on his upper lip."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aabcf95ac3e9','ch_eb687440e711','text','{"text": "''The master ought not to heal the wound of this white man,'' he said bluntly to Hana."}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b1627684986','ch_eb687440e711','text','{"text": "''The white man ought to die. First he was shot. Then the sea caught him and wounded him with her rocks. If the master heals what the gun did and what the sea did they will take revenge on us.'' ''I will tell him what you say,'' Hana replied courteously."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4da2921ace44','ch_eb687440e711','text','{"text": "But she herself was also frightened, although she was not superstitious as the old man was. Could it ever be well to help an enemy? Nevertheless she told Yumi to fetch the hot water and bring it to the room where the white man was. She went ahead and slid back the partitions. Sadao was not yet there. Yumi, following, put down her wooden bucket. Then she went over to the white man. When she saw him her thick lips folded themselves into stubbornness."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_33f0f88474fb','ch_eb687440e711','text','{"text": "''I have never washed a white man,'' she said, ''and I will not wash so dirty a one now.'' Hana cried at her severely."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_306e26db2642','ch_eb687440e711','text','{"text": "''You will do what your master commands you!'' There was so fierce a look of resistance upon Yumi''s round dull face that Hana felt unreasonably afraid. After all, if the servants should report something that was not as it happened? ''Very well,'' she said with dignity. ''You understand we only want to bring him to his senses so that we can turn him over as a prisoner?'' ''I will have nothing to do with it,'' Yumi said, ''I am a poor person and it is not my business.'' ''Then please,'' Hana said gently, ''return to your own work.'' At once Yumi left the room."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5008e82a04d7','ch_eb687440e711','text','{"text": "But this left Hana with the white man alone. She might have been too afraid to stay had not her anger at Yumi''s stubbornness now sustained her. ''Stupid Yumi,'' she muttered fiercely. ''Is this anything but a man? And a wounded helpless man!'' In the conviction of her own superiority she bent impulsively and untied the knotted rugs that kept the white man covered. When she had his breast bare she dipped the small clean towel that Yumi had brought into the steaming hot water and washed his face"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d70c98a341d','ch_eb687440e711','text','{"text": "carefully. The man''s skin, though rough with exposure, was of a fine texture and must have been very blond when he was a child. While she was thinking these thoughts, though not really liking the man better now that he was no longer a child, she kept on washing him until his upper body was quite clean. But she dared not turn him over. Where was Sadao? Now her anger was ebbing, and she was anxious again and she rose, wiping her hands on the wrong towel. Then lest the man be chilled, she put the"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ee9001899b4e','ch_eb687440e711','text','{"text": "quilt over him. ''Sadao!'' she called softly. He had been about to come in when she called. His hand had been on the door and now he opened it. She saw that he had brought his surgeon''s emergency bag and that he wore his surgeon''s coat."}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f11787dafdfe','ch_eb687440e711','text','{"text": "''You have decided to operate!'' she cried."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_346b5cc89dfe','ch_eb687440e711','text','{"text": "''Yes,'' he said shortly."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c78b79e0e89','ch_eb687440e711','text','{"text": "He turned his back to her and unfolded a sterilized towel upon the floor of the tokonoma2 alcove, and put his instruments out upon it."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6fb277112ba6','ch_eb687440e711','text','{"text": "''Fetch towels,'' he said."}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6e034cfd4850','ch_eb687440e711','text','{"text": "She went obediently, but how anxious now, to the linen shelves and took out the towels. There ought also to be old pieces of matting so that the blood would not ruin the fine floor covering. She went out to the back veranda where the gardener kept strips of matting with which to protect delicate shrubs on cold nights and took an armful of them. But when she went back into the room, she saw this was useless. The blood had already soaked through the packing in the man''s wound and had ruined the"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4400b7bee2f4','ch_eb687440e711','text','{"text": "mat under him. ''Oh, the mat!'' she cried."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e2e041247684','ch_eb687440e711','text','{"text": "''Yes, it is ruined,'' Sadao replied, as though he did not care."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce84613433e2','ch_eb687440e711','text','{"text": "''Help me to turn him,'' he commanded her."}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43dc2ff73629','ch_eb687440e711','text','{"text": "She obeyed him without a word, and he began to wash the man''s back carefully. ''Yumi would not wash him,'' she said. ''Did you wash him then?'' Sadao asked, not stopping for a moment his swift concise movements."}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8217d2d55ee1','ch_eb687440e711','text','{"text": "''Yes,'' she said."}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d65d3fe7c72','ch_eb687440e711','text','{"text": "He did not seem to hear her. But she was used to his absorption when he was at work. She wondered for a moment if it mattered to him what was the body upon which he worked so long as it was for the work he did so excellently."}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e1da8c6ec19','ch_eb687440e711','text','{"text": "''You will have to give the anesthetic if he needs it,'' he said."}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c9bc2a250ad','ch_eb687440e711','text','{"text": "''I?'' she repeated blankly."}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eee7af087abc','ch_eb687440e711','text','{"text": "''But never have I!'' ''It is easy enough,'' he said impatiently."}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea418b93e743','ch_eb687440e711','text','{"text": "He was taking out the packing now, and the blood began to flow more quickly. He peered into the wound with the bright surgeon''s light fastened on his forehead. ''The bullet is still there,'' he said with cool interest. ''Now I wonder how deep this rock wound is. If it is not too deep it may be that I can get the bullet. But the bleeding is not superficial. He has lost much blood.'' At this moment Hana choked. He looked up and saw her face the colour of sulphur."}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96ed5d381b2c','ch_eb687440e711','text','{"text": "''Don''t faint,'' he said sharply. He did not put down his exploring instrument. ''If I stop now the man will surely die.'' She clapped her hands to her mouth and leaped up and ran out of the room."}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fafb1ed26c5b','ch_eb687440e711','text','{"text": "Outside in the garden he heard her retching. But he went on with his work."}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_78e6363a50af','ch_eb687440e711','text','{"text": "''It will be better for her to empty her stomach,'' he thought."}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a12b71c899db','ch_eb687440e711','text','{"text": "He had forgotten that of course she had never seen an operation. But her distress and his inability to go to her at once made him impatient and irritable with this man who lay like dead under his knife."}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ef1b4553bf6','ch_eb687440e711','text','{"text": "''This man.'' he thought, ''there is no reason under heaven why he should live.'' Unconsciously this thought made him ruthless and he proceeded swiftly."}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c466b44b5f93','ch_eb687440e711','text','{"text": "In his dream the man moaned but Sadao paid no heed except to mutter at him."}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da2eda73a23f','ch_eb687440e711','text','{"text": "''Groan,'' he muttered, ''groan if you like. I am not doing this for my own pleasure. In fact, I do not know why I am doing it.'' The door opened and there was Hana again."}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70cdcbdc837e','ch_eb687440e711','text','{"text": "''Where is the anesthetic?'' she asked in a clear voice."}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ae322e245fb','ch_eb687440e711','text','{"text": "Sadao motioned with his chin."}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_77e4893d8125','ch_eb687440e711','text','{"text": "''It is as well that you came back,'' he said."}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_706b019e11c7','ch_eb687440e711','text','{"text": "''This fellow is beginning to stir.'' She had the bottle and some cotton in her hand."}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_739a3935d426','ch_eb687440e711','text','{"text": "''But how shall I do it?'' she asked."}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b9557460b9e7','ch_eb687440e711','text','{"text": "''Simply saturate the cotton and hold it near his nostrils,'' Sadao replied without delaying for one moment the intricate detail of his work."}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4a7cb6a7b544','ch_eb687440e711','text','{"text": "''When he breathes badly move it away a little.'' She crouched close to the sleeping face of the young American."}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7f655daea790','ch_eb687440e711','text','{"text": "It was a piteously thin face, she thought, and the lips were twisted. The man was suffering whether he knew it or not. Watching him, she wondered if the stories they heard sometimes of the sufferings of prisoners were true. They came like flickers of rumour, told by word of mouth and always contradicted. In the newspapers the reports were always that wherever the Japanese armies went the people received them gladly, with cries of joy at their liberation. But sometimes she remembered such men as"}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c818efeac388','ch_eb687440e711','text','{"text": "General Takima, who at home beat his wife cruelly, though no one mentioned it now that he had fought so victorious a battle in Manchuria. If a man like that could be so cruel to a woman in his power, would he not be cruel to one like this for instance? She hoped anxiously that this young man had not been tortured. It was at this moment that she observed deep red scars on his neck, just under the ear."}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af9e287ee60d','ch_eb687440e711','text','{"text": "''Those scars,'' she murmured, lifting her eyes to Sadao."}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7f4a127e2cb3','ch_eb687440e711','text','{"text": "But he did not answer. At this moment he felt the tip of his instrument strike against something hard, dangerously near the kidney. All thought left him. He felt only the purest pleasure. He probed with his fingers, delicately, familiar with every atom of this human body. His old American professor of anatomy had seen to that knowledge."}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_107e8e35de7b','ch_eb687440e711','text','{"text": "''Ignorance of the human body is the surgeon''s cardinal sin, sirs!'' he had thundered at his classes year after year."}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a2491972b7f2','ch_eb687440e711','text','{"text": "''To operate without as complete knowledge of the body as if you had made it — anything less than that is murder.'' ''It is not quite at the kidney, my friend,'' Sadao murmured."}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68d1ee7d2163','ch_eb687440e711','text','{"text": "It was his habit to murmur to the patient when he forgot himself in an operation."}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_182f753081f1','ch_eb687440e711','text','{"text": "''My friend,'' he always called his patients and so now he did, forgetting that this was his enemy."}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e249a98c7b8','ch_eb687440e711','text','{"text": "Then quickly, with the cleanest and most precise of incisions, the bullet was out. The man quivered but he was still unconscious. Nevertheless he muttered a few English words."}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abfe947166f8','ch_eb687440e711','text','{"text": "''Guts,'' he muttered, choking."}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f46403a0cdb','ch_eb687440e711','text','{"text": "''They got...my guts...'' ''Sadao!'' Hana cried sharply."}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_01689fef2ec8','ch_eb687440e711','text','{"text": "''Hush,'' Sadao said."}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f341fa327338','ch_eb687440e711','text','{"text": "The man sank again into silence so profound that Sadao took up his wrist, hating the touch of it. Yes, there was still a pulse so faint, so feeble, but enough, if he wanted the man to live, to give hope."}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7d53a497e78','ch_eb687440e711','text','{"text": "''But certainly I do not want this man to live,'' he thought."}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c01a76529bdc','ch_eb687440e711','text','{"text": "''No more anesthetic,'' he told Hana."}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7f3b0e20f538','ch_eb687440e711','text','{"text": "He turned as swiftly as though he had never paused and from his medicines he chose a small vial and from it filled a hypodermic and thrust it into the patient''s left arm. Then putting down the needle, he took the man''s wrist again. The pulse under his fingers fluttered once or twice and then grew stronger."}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cac5d1c18951','ch_eb687440e711','text','{"text": "''This man will live in spite of all,'' he said to Hana and sighed."}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_65c26eacd04a','ch_eb687440e711','text','{"text": "The young man woke, so weak, his blue eyes so terrified when he perceived where he was, that Hana felt compelled to apologise. She herself served him, for none of the servants would enter the room. When she came in the first time, she saw him summon his small strength to be prepared for some fearful thing."}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_795c0cd263f9','ch_eb687440e711','text','{"text": "''Don''t be afraid,'' she begged him softly. ''How come."}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7592070bc4a','ch_eb687440e711','text','{"text": ". . you speak English. . .'' he gasped."}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_632f5ebdabf7','ch_eb687440e711','text','{"text": "''I was a long time in America,'' she replied."}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5e83a3b4565','ch_eb687440e711','text','{"text": "She saw that he wanted to reply to that but he could not, and so she knelt and fed him gently from the porcelain spoon. He ate unwillingly, but still he ate."}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be523ff80749','ch_eb687440e711','text','{"text": "''Now you will soon be strong,'' she said, not liking him and yet moved to comfort him."}',116);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_781932beda4a','ch_eb687440e711','text','{"text": "He did not answer. When Sadao came in the third day after the operation, he found the young man sitting up, his face bloodless with the effort."}',117);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b3068b799cee','ch_eb687440e711','text','{"text": "''Lie down,'' Sadao cried."}',118);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dfbbff687f94','ch_eb687440e711','text','{"text": "''Do you want to die?'' He forced the man down gently and strongly and examined the wound."}',119);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b88fc5d7675a','ch_eb687440e711','text','{"text": "''You may kill yourself if you do this sort of thing,'' he scolded."}',120);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44df47100762','ch_eb687440e711','text','{"text": "''What are you going to do with me?'' the boy muttered."}',121);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f78258fa5ff','ch_eb687440e711','text','{"text": "He looked just now barely seventeen."}',122);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_590ec28c3cd2','ch_eb687440e711','text','{"text": "''Are you going to hand me over?'' For a moment Sadao did not answer."}',123);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ceef263e5ad','ch_eb687440e711','text','{"text": "He finished his examination and then pulled the silk quilt over the man."}',124);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_220e27dbdd3a','ch_eb687440e711','text','{"text": "''I do not know myself what I shall do with you,'' he said."}',125);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c45c3d8bc18c','ch_eb687440e711','text','{"text": "''I ought of course to give you to the police. You are a prisoner of war — no, do not tell me anything.'' He put up his hand as he saw the young man was about to speak."}',126);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c58ac122577c','ch_eb687440e711','text','{"text": "''Do not even tell me your name unless I ask it.'' They looked at each other for a moment, and then the young man closed his eyes and turned his face to the wall."}',127);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f435d9037ad0','ch_eb687440e711','text','{"text": "''Okay,'' he whispered, his mouth a bitter line."}',128);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aae64ec0a42b','ch_eb687440e711','text','{"text": "Outside the door Hana was waiting for Sadao. He saw at once that she was in trouble."}',129);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_85ad92cd1229','ch_eb687440e711','text','{"text": "''Sadao, Yumi tells me the servants feel they cannot stay if we hide this man here any more,'' she said."}',130);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_545672b87ec6','ch_eb687440e711','text','{"text": "''She tells me that they are saying that you and I were so long in America that we have forgotten to think of our own country first. They think we like Americans.'' ''It is not true,'' Sadao said harshly''Americans are our enemies. But I have been trained not to let a man die if I can help it.'' ''The servants cannot understand that,'' she said anxiously."}',131);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7b0207f0ad95','ch_eb687440e711','text','{"text": "''No,'' he agreed."}',132);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b731c497c768','ch_eb687440e711','text','{"text": "Neither seemed able to say more, and somehow the household dragged on. The servants grew more watchful. Their courtesy was as careful as ever, but their eyes were cold upon the pair to whom they were hired."}',133);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_10763ad329fe','ch_eb687440e711','text','{"text": "''It is clear what our master ought to do,'' the old gardener said one morning."}',134);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_15e07d139ff1','ch_eb687440e711','text','{"text": "He had worked with flowers all his life, and had been a specialist too in moss. For Sadao''s father he had made one of the finest moss gardens in Japan, sweeping the bright green carpet constantly so that not a leaf or a pine needle marred the velvet of its surface. ''My old master''s son knows very well what he ought to do,'' he now said, pinching a bud from a bush as he spoke."}',135);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0097dbb846fc','ch_eb687440e711','text','{"text": "''When the man was so near death why did he not let him bleed?'' ''That young master is so proud of his skill to save life that he saves any life,'' the cook said contemptuously."}',136);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_72c7a8846302','ch_eb687440e711','text','{"text": "She split a fowl''s neck skillfully and held the fluttering bird and let its blood flow into the roots of a wistaria vine. Blood is the best of fertilisers, and the old gardener would not let her waste a drop of it. ''It is the children of whom we must think,'' Yumi said sadly. ''What will be their fate if their father is condemned as a traitor?'' They did not try to hide what they said from the ears of Hana as she stood arranging the day''s flowers in the veranda near by, and she knew they spoke on"}',137);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1322e896a303','ch_eb687440e711','text','{"text": "purpose that she might hear. That they were right she knew too in most of her being. But there was another part of her which she herself could not understand. It was not sentimental liking of the prisoner. She had come to think of him as a prisoner. She had not liked him even yesterday when he had said in his impulsive way, ''Anyway, let me tell you that my name is Tom.'' She had only bowed her little distant bow. She saw hurt in his eyes but she did not wish to assuage it. Indeed, he was a great"}',138);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_564f6fb0dd9e','ch_eb687440e711','text','{"text": "trouble in this house. As for Sadao, every day he examined the wound carefully. The last stitches had been pulled out this morning, and the young man would, in a fortnight be nearly as well as ever. Sadao went back to his office and carefully typed a letter to the Chief of police reporting the whole matter."}',139);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ea65546f2e0','ch_eb687440e711','text','{"text": "''On the twenty-first day of February an escaped prisoner was washed up on the shore in front of my house.'' So far he typed and then he opened a secret drawer of his desk and put the unfinished report into it."}',140);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e2d41290dd12','ch_eb687440e711','text','{"text": "On the seventh day after that, two things happened. In the morning the servants left together, their belongings tied in large square cotton kerchiefs. When Hana got up in the morning nothing was done, the house not cleaned and the food not prepared, and she knew what it meant. She was dismayed and even terrified, but her pride as a mistress would not allow her to show it. Instead, she inclined her head gracefully when they appeared before her in the kitchen, and she paid them off and thanked"}',141);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_374be5e08c87','ch_eb687440e711','text','{"text": "them for all that they had done for her. They were crying, but she did not cry. The cook and the gardener had served Sadao since he was a little boy in his father''s house, and Yumi cried because of the children. She was so grieving that after she had gone she ran back to Hana. ''If the baby misses me too much tonight, send for me. I am going to my own house and you know where it is.'' ''Thank you,'' Hana said smiling. But she told herself she would not send for Yumi however the baby cried. She made"}',142);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_706d4e8e2d17','ch_eb687440e711','text','{"text": "the breakfast and Sadao helped with the children. Neither of them spoke of the servants beyond the fact that they were gone. But after Hana had taken morning food to the prisoner, she came back to Sadao."}',143);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c840a18b291a','ch_eb687440e711','text','{"text": "''Why is it we cannot see clearly what we ought to do?'' she asked him."}',144);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec4c1b9d69a3','ch_eb687440e711','text','{"text": "''Even the servants see more clearly than we do. Why are we different from other Japanese?'' Sadao did not answer."}',145);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71ed794dd290','ch_eb687440e711','text','{"text": "But a little later he went into the room where the prisoner was and said brusquely, ''Today you may get up on your feet. I want you to stay up only five minutes at a time. Tomorrow you may try it twice as long. It would be well that you get back your strength as quickly as possible.'' He saw the flicker of terror on the young face that was still very pale."}',146);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_083b822ce3be','ch_eb687440e711','text','{"text": "''Okay,'' the boy murmured."}',147);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53b7cc4d1cb3','ch_eb687440e711','text','{"text": "Evidently he was determined to say more."}',148);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b2055a750d8','ch_eb687440e711','text','{"text": "''I feel I ought to thank you, Doctor, for having saved my life.'' ''Don''t thank me too early,'' Sadao said coldly. He saw the flicker of terror again in the boy''s eyes — terror as unmistakable as an animal''s. The scars on his neck were crimson for a moment. Those scars! What were they? Sadao did not ask. In the afternoon the second thing happened. Hana, working hard on unaccustomed labour, saw a messenger come to the door in official uniform. Her hands went weak and she could not draw her breath. The servants must have told already. She ran to Sadao, gasping, unable to utter a word. But by then the messenger had simply followed her through the garden and there he stood. She pointed at him helplessly. Sadao looked up from his book. He was in his office, the other partition of which was thrown open to the garden for the southern sunshine. ''What is it?'' he asked the messenger and then he rose, seeing the man''s uniform. ''You are to come to the palace,'' the man said. ''The old General is in pain again.'' ''Oh,'' Hana breathed, ''is that all?'' ''All?'' the messenger exclaimed."}',149);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_34a09ab54b9f','ch_eb687440e711','text','{"text": "''Is it not enough?'' ''Indeed it is,'' she replied."}',150);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc76e71dd82b','ch_eb687440e711','text','{"text": "''I am very sorry.'' When Sadao came to say goodbye, she was in the kitchen, but doing nothing."}',151);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97541c2f64ea','ch_eb687440e711','text','{"text": "The children were asleep and she sat merely resting for a moment, more exhausted from her fright than from work."}',152);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ef1f0470096','ch_eb687440e711','text','{"text": "''I thought they had come to arrest you'', she said."}',153);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_11afc2d48b2f','ch_eb687440e711','text','{"text": "He gazed down into her anxious eyes."}',154);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17e4d2c4c9c9','ch_eb687440e711','text','{"text": "''I must get rid of this man for your sake,'' he said in distress."}',155);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3594d45636b1','ch_eb687440e711','text','{"text": "''Somehow I must get rid of him.'' (Sadao goes to see the General) ''Of course,'' the General said weakly, ''I understand fully. But that is because, I once took a degree in Princeton. So few Japanese have.'' ''I care nothing for the man, Excellency,'' Sadao said, ''but having operated on him with such success...'' ''Yes, yes'' the General said."}',156);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9dd769baae5','ch_eb687440e711','text','{"text": "''It only makes me feel you more indispensable to me. Evidently you can save anyone — you are so skilled. You say you think I can stand one more such attack as I have had today?'' ''Not more than one,'' Sadao said."}',157);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_811296ee23c6','ch_eb687440e711','text','{"text": "''Then certainly I can allow nothing to happen to you,'' the General said with anxiety."}',158);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f2160c0af14a','ch_eb687440e711','text','{"text": "His long pale Japanese face became expressionless, which meant that he was in deep thought."}',159);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2a18d211e411','ch_eb687440e711','text','{"text": "''You cannot be arrested,'' the General said, closing his eyes."}',160);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_57c5b3add78f','ch_eb687440e711','text','{"text": "''Suppose you were condemned to death and the next day I had to have my operation?'' ''There are other surgeons, Excellency,'' Sadao suggested."}',161);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c499b93beff','ch_eb687440e711','text','{"text": "''None I trust,'' the General replied."}',162);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8fa1aa428438','ch_eb687440e711','text','{"text": "''The best ones have been trained by Germans and would consider the operation successful even if I died. I do not care for their point of view.'' He sighed."}',163);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d74d0324892','ch_eb687440e711','text','{"text": "''It seems a pity that we cannot better combine the German ruthlessness with the American sentimentality. Then you could turn your prisoner over to execution and yet I could be sure you would not murder me while I was unconscious.'' The General laughed."}',164);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f70ab500a80e','ch_eb687440e711','text','{"text": "He had an unusual sense of humour."}',165);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_421f7d3599da','ch_eb687440e711','text','{"text": "''As a Japanese, could you not combine these two foreign elements?'' he asked."}',166);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6facabb1fd3d','ch_eb687440e711','text','{"text": "Sadao smiled."}',167);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d58a629b1fe','ch_eb687440e711','text','{"text": "''I am not quite sure,'' he said, ''but for your sake I would be willing to try, Excellency.'' The General shook his head."}',168);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96fbcf832269','ch_eb687440e711','text','{"text": "''I had rather not be the test case,'' he said."}',169);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a58fd7063831','ch_eb687440e711','text','{"text": "He felt suddenly weak and overwhelmed with the cares of his life as an official in times such as these when repeated victory brought great responsibilities all over the south Pacific."}',170);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_138d7a7885e6','ch_eb687440e711','text','{"text": "''It is very unfortunate that this man should have washed up on your doorstep,'' he said irritably."}',171);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_408f9dd6c920','ch_eb687440e711','text','{"text": "''I feel it so myself,'' Sadao said gently."}',172);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40158c4a31de','ch_eb687440e711','text','{"text": "''It would be best if he could be quietly killed,'' the General said."}',173);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ab1c59d4706','ch_eb687440e711','text','{"text": "''Not by you, but by someone who does not know him. I have my own private assassins. Suppose I send two of them to your house tonight or better, any night. You need know nothing about it. It is now warm — what would be more natural than that you should leave the outer partition of the white man''s room open to the garden while he sleeps?'' ''Certainly it would be very natural,'' Sadao agreed."}',174);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c98a571b1090','ch_eb687440e711','text','{"text": "''In fact, it is so left open every night.'' ''Good,'' the General said, yawning."}',175);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f6151dd39937','ch_eb687440e711','text','{"text": "''They are very capable assassins — they make no noise and they know the trick of inward bleeding. If you like I can even have them remove the body.'' Sadao considered."}',176);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cab973d3323e','ch_eb687440e711','text','{"text": "''That perhaps would be best, Excellency,'' he agreed, thinking of Hana."}',177);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a95cc6b1be7d','ch_eb687440e711','text','{"text": "He left the General''s presence then and went home, thinking over the plan. In this way the whole thing would be taken out of his hands. He would tell Hana nothing, since she would be timid at the idea of assassins in the house, and yet certainly such persons were essential in an absolute state such as Japan was. How else could rulers deal with those who opposed them? He refused to allow anything but reason to be the atmosphere of his mind as he went into the room where the American was in bed."}',178);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc0ff652d0c2','ch_eb687440e711','text','{"text": "But as he opened the door, to his surprise he found the young man out of bed, and preparing to go into the garden. ''What is this!'' he exclaimed."}',179);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_038b010337ff','ch_eb687440e711','text','{"text": "''Who gave you permission to leave your room?'' ''I''m not used to waiting for permission,'' Tom said gaily. ''Gosh, I feel pretty good again!"}',180);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27e215099207','ch_eb687440e711','text','{"text": "But will the muscles on this side always feel stiff?'' ''Is it so?'' Sadao inquired, surprised. He forgot all else."}',181);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fcb506c1914d','ch_eb687440e711','text','{"text": "''Now I thought I had provided against that,'' he murmured."}',182);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c92ba8195aa4','ch_eb687440e711','text','{"text": "He lifted the edge of the man''s shirt and gazed at the healing scar. ''Massage may do it,'' he said, ''if exercise does not.'' ''It won''t bother me much,'' the young man said. His young face was gaunt under the stubbly blond beard. ''Say, Doctor, I''ve got something I want to say to you. If I hadn''t met a Jap like you — well, I wouldn''t be alive today. I know that.'' Sadao bowed but he could not speak."}',183);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ff635ad89ac','ch_eb687440e711','text','{"text": "''Sure, I know that,'' Tom went on warmly."}',184);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f7d6b933d45','ch_eb687440e711','text','{"text": "His big thin hands gripping a chair were white at the knuckles."}',185);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50920092b69b','ch_eb687440e711','text','{"text": "''I guess if all the Japs were like you there wouldn''t have been a war.'' ''Perhaps,'' Sadao said with difficulty."}',186);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3fe347ab61b0','ch_eb687440e711','text','{"text": "''And now I think you had better go back to bed.'' He helped the boy back into bed and then bowed."}',187);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_872106c04977','ch_eb687440e711','text','{"text": "''Good night,'' he said."}',188);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e89a0d53cc72','ch_eb687440e711','text','{"text": "Sadao slept badly that night. Time and time again he woke, thinking he heard the rustling of footsteps, the sound of a twig broken or a stone displaced in the garden — a noise such as men might make who carried a burden. The next morning he made the excuse to go first into the guest room. If the American were gone he then could simply tell Hana that so the General had directed. But when he opened the door he saw at once that there on the pillow was the shaggy blond head. He could hear the"}',189);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_86f2e0d7adcc','ch_eb687440e711','text','{"text": "peaceful breathing of sleep and he closed the door again quietly."}',190);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_37835b47a8d8','ch_eb687440e711','text','{"text": "''He is asleep,'' he told Hana."}',191);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7504dcf80e29','ch_eb687440e711','text','{"text": "''He is almost well to sleep like that.'' ''What shall we do with him?'' Hana whispered her old refrain."}',192);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_730686ff5c64','ch_eb687440e711','text','{"text": "Sadao shook his head."}',193);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_86494142f4a5','ch_eb687440e711','text','{"text": "''I must decide in a day or two,'' he promised."}',194);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_146082c103aa','ch_eb687440e711','text','{"text": "But certainly, he thought, the second night must be the night. There rose a wind that night, and he listened to the sounds of bending boughs and whistling partitions. Hana woke too."}',195);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_622b869b3b72','ch_eb687440e711','text','{"text": "''Ought we not to go and close the sick man''s partition?'' she asked."}',196);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad36c93f23ed','ch_eb687440e711','text','{"text": "''No,'' Sadao said."}',197);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb825d19d8de','ch_eb687440e711','text','{"text": "''He is able now to do it for himself.'' But the next morning the American was still there."}',198);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1f972592642','ch_eb687440e711','text','{"text": "Then the third night of course must be the night. The wind changed to quiet rain and the garden was full of the sound of dripping eaves and running springs. Sadao slept a little better, but he woke at the sound of a crash and leaped to his feet."}',199);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_090cae7a12a4','ch_eb687440e711','text','{"text": "''What was that?'' Hana cried."}',200);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_19807265c46b','ch_eb687440e711','text','{"text": "The baby woke at her voice and began to wail."}',201);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_caa74fc7dfd3','ch_eb687440e711','text','{"text": "''I must go and see,'' But he held her and would not let her move."}',202);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d0487ab1742','ch_eb687440e711','text','{"text": "''Sadao,'' she cried, ''what is the matter with you?'' ''Don''t go,'' he muttered, ''don''t go!'' His terror infected her and she stood breathless, waiting."}',203);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba0fb192b883','ch_eb687440e711','text','{"text": "There was only silence. Together they crept back into the bed, the baby between them. Yet when he opened the door of the guest room in the morning there was the young man. He was very gay and had already washed and was now on his feet. He had asked for a razor yesterday and had shaved himself and today there was a faint colour in his cheeks."}',204);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_755b012054ca','ch_eb687440e711','text','{"text": "''I am well,'' he said joyously."}',205);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f1a9afe346f4','ch_eb687440e711','text','{"text": "Sadao drew his kimono round his weary body. He could not, he decided suddenly, go through another night. It was not that he cared for this young man''s life. No, simply it was not worth the strain. ''You are well,'' Sadao agreed. He lowered his voice. ''You are so well that I think if I put my boat on the shore tonight, with food and extra clothing in it, you might be able to row to that little island not far from the coast. It is so near the coast that it has not been worth fortifying. Nobody lives"}',206);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e62fdd325c77','ch_eb687440e711','text','{"text": "on it because in storm it is submerged. But this is not the season of storm. You could live there until you saw a Korean fishing boat pass by. They pass quite near the island because the water is many fathoms deep there.'' The young man stared at him, slowly comprehending."}',207);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20afcdfb3627','ch_eb687440e711','text','{"text": "''Do I have to?'' he asked."}',208);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_646d5d3fe9b3','ch_eb687440e711','text','{"text": "''I think so,'' Sadao said gently."}',209);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd1d1e6444c4','ch_eb687440e711','text','{"text": "''You understand — it is not hidden that you are here.'' The young man nodded in perfect comprehension."}',210);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fcb4b9c7ce76','ch_eb687440e711','text','{"text": "''Okay,'' he said simply."}',211);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b81c795911a4','ch_eb687440e711','text','{"text": "Sadao did not see him again until evening. As soon as it was dark he had dragged the stout boat down to the shore and in it he put food and bottled water that he had bought secretly during the day, as well as two quilts he had bought at a pawnshop. The boat he tied to a post in the water, for the tide was high. There was no moon and he worked without a flashlight. When he came to the house he entered as though he were just back from his work, and so Hana knew nothing."}',212);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4bc24a79c74a','ch_eb687440e711','text','{"text": "''Yumi was here today,'' she said as she served his supper."}',213);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d82e20cd1fe0','ch_eb687440e711','text','{"text": "Though she was so modern, still she did not eat with him."}',214);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f648f6c1aa7','ch_eb687440e711','text','{"text": "''Yumi cried over the baby,'' she went on with a sigh."}',215);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_866a22368e0b','ch_eb687440e711','text','{"text": "''She misses him so.'' ''The servants will come back as soon as the foreigner is gone,'' Sadao said."}',216);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b080f619b957','ch_eb687440e711','text','{"text": "He went into the guest room that night before he went to bed himself and checked carefully the American''s temperature, the state of the wound, and his heart and pulse. The pulse was irregular but that was perhaps because of excitement. The young man''s pale lips were pressed together and his eyes burned. Only the scars on his neck were red."}',217);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e847f1af953','ch_eb687440e711','text','{"text": "''I realise you are saving my life again,'' he told Sadao."}',218);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1307b6fff46a','ch_eb687440e711','text','{"text": "''Not at all,'' Sadao said."}',219);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e13b62bd9d4a','ch_eb687440e711','text','{"text": "''It is only inconvenient to have you here any longer.'' He had hesitated a good deal about giving the man a flashlight."}',220);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_845f26137380','ch_eb687440e711','text','{"text": "But he had decided to give it to him after all. It was a small one, his own, which he used at night when he was called."}',221);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ee61edbb881a','ch_eb687440e711','text','{"text": "''If your food runs out before you catch a boat,'' he said, ''signal me two flashes at the same instant the sun drops over the horizon. Do not signal in darkness, for it will be seen. If you are all right but still there, signal me once. You will find fresh fish easy to catch but you must eat them raw. A fire would be seen.'' ''Okay,'' the young man breathed."}',222);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff39594e541a','ch_eb687440e711','text','{"text": "He was dressed now in the Japanese clothes which Sadao had given him, and at the last moment Sadao wrapped a black cloth about his blond head."}',223);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_08ee9aeae96e','ch_eb687440e711','text','{"text": "''Now,'' Sadao said."}',224);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f4b928caa579','ch_eb687440e711','text','{"text": "The young American, without a word, shook Sadao''s hand warmly, and then walked quite well across the floor and down the step into the darkness of the garden. Once — twice... Sadao saw his light flash to find his way. But that would not be suspected. He waited until from the shore there was one more flash. Then he closed the partition. That night he slept. ''You say the man escaped?'' the General asked faintly. He had been operated upon a week before, an emergency operation to which Sadao had been"}',225);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d2ad8133b7c1','ch_eb687440e711','text','{"text": "called in the night. For twelve hours Sadao had not been sure the General would live. The gall bladder was much involved. Then the old man had begun to breathe deeply again and to demand food. Sadao had not been able to ask about the assassins. So far as he knew they had never come. The servants had returned and Yumi had cleaned the guest room thoroughly and had burned sulphur in it to get the white man''s smell out of it. Nobody said anything. Only the gardener was cross because he had got"}',226);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_facc325320e7','ch_eb687440e711','text','{"text": "behind with his chrysanthemums. But after a week Sadao felt the General was well enough to be spoken to about the prisoner. ''Yes, Excellency, he escaped,'' Sadao now said. He coughed, signifying that he had not said all he might have said, but was unwilling to disturb the General further. But the old man opened his eyes suddenly. ''That prisoner,'' he said with some energy, ''did I not promise you I would kill him for you?'' ''You did, Excellency,'' Sadao said."}',227);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5705b330a758','ch_eb687440e711','text','{"text": "''Well, well!'' the old man said in a tone of amazement, ''so I did! But you see, I was suffering a good deal. The truth is, I thought of nothing but myself. In short, I forgot my promise to you.'' ''I wondered, Your Excellency,'' Sadao murmured."}',228);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e777b6f6ecc','ch_eb687440e711','text','{"text": "''It was certainly very careless of me,'' the General said."}',229);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f7f980af2ab','ch_eb687440e711','text','{"text": "''But you understand it was not lack of patriotism or dereliction of duty.'' He looked anxiously at his doctor."}',230);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1ab1110e77a7','ch_eb687440e711','text','{"text": "''If the matter should come out you would understand that, wouldn''t you?'' ''Certainly, Your Excellency,'' Sadao said."}',231);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9fe964ec95b5','ch_eb687440e711','text','{"text": "He suddenly comprehended that the General was in the palm of his hand and that as a consequence he himself was perfectly safe."}',232);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5f512aab70ef','ch_eb687440e711','text','{"text": "''I can swear to your loyalty, Excellency,'' he said to the old General, ''and to your zeal against the enemy.'' ''You are a good man,'' the General murmured and closed his eyes.'' ''You will be rewarded.'' But Sadao, searching the spot of black in the twilighted sea that night, had his reward."}',233);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cdfe20ce656b','ch_eb687440e711','text','{"text": "There was no prick of light in the dusk. No one was on the island. His prisoner was gone — safe, doubtless, for he had warned him to wait only for a Korean fishing boat. He stood for a moment on the veranda, gazing out to the sea from whence the young man had come that other night. And into his mind, although without reason, there came other white faces he had known — the professor at whose house he had met Hana, a dull man, and his wife had been a silly talkative woman, in spite of her wish to"}',234);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a4c54b07818','ch_eb687440e711','text','{"text": "be kind. He remembered his old teacher of anatomy, who had been so insistent on mercy with the knife, and then he remembered the face of his fat and slatternly landlady. He had had great difficulty in finding a place to live in America because he was a Japanese. The Americans were full of prejudice and it had been bitter to live in it, knowing himself their superior. How he had despised the ignorant and dirty old woman who had at last consented to house him in her miserable home! He had once"}',235);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2a0d6c3aaa32','ch_eb687440e711','text','{"text": "tried to be grateful to her because she had in his last year nursed him through influenza, but it was difficult, for she was no less repulsive to him in her kindness. Now he remembered the youthful, haggard face of his prisoner — white and repulsive."}',236);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_29b4530add8e','ch_eb687440e711','text','{"text": "''Strange,'' he thought."}',237);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3210d53868e','ch_eb687440e711','text','{"text": "''I wonder why I could not kill him?''"}',238);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_29354c1e8f90','ch_eb687440e711','list','{"ordered": false, "items": ["Pearl S. Buck"]}',239);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_8cfeaeb16280','bk_ncert_english','12-40-should-wizard-hit-mommy','12.40 Should Wizard Hit Mommy?',NULL,'public',112,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ff480939faa','ch_8cfeaeb16280','text','{"text": "In the evenings and for Saturday naps like today''s, Jack told his daughter Jo a story out of his head. This custom, begun when she was two, was itself now nearly two years old, and his head felt empty. Each new story was a slight variation of a basic tale: a small creature, usually named Roger (Roger Fish, Roger Squirrel, Roger Chipmunk), had some problem and went with it to the wise old owl. The owl told him to go to the wizard, and the wizard performed a magic spell that solved the problem, demanding in payment a number of pennies greater than the number that Roger Creature had, but in the same breath directing the animal to a place where the extra pennies could be found. Then Roger was so happy he played many games with other creatures, and went home to his mother just in time to hear the train whistle that brought his daddy home from Boston. Jack described their supper, and the story was over. Working"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a73d447ef5eb','ch_8cfeaeb16280','text','{"text": "his way through this scheme was especially fatiguing on Saturday, because Jo never fell asleep in naps any more, and knowing this made the rite seem futile. The little girl (not so little any more;"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3fb02cb52bc','ch_8cfeaeb16280','text','{"text": "the bumps her feet made under the covers were halfway down the bed, their big double bed that they let her be in for naps and when she was sick) had at last arranged herself, and from the way her fat face deep in the pillow shone in the sunlight sifting through the drawn shades, it did not seem"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a4071736805','ch_8cfeaeb16280','text','{"text": "fantastic that some magic would occur, and she would take her nap like an infant of two. Her brother, Bobby, was two, and already asleep with his bottle. Jack asked, ''Who shall the story be about today?'' ''Roger...'' Jo squeezed her eyes shut and smiled to be thinking she was thinking. Her eyes opened, her mother''s blue. ''Skunk,'' she said firmly. A new animal;"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d2679b221796','ch_8cfeaeb16280','text','{"text": "they must talk about skunks at nursery school. Having a fresh hero momentarily stirred Jack to creative enthusiasm. ''All right,'' he said."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_babbb22d7356','ch_8cfeaeb16280','text','{"text": "''Once upon a time, in the deep dark woods, there was a tiny little creature by the name of Roger Skunk. And he smelled very bad.'' ''Yes,'' Jo said."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f15fe74842d','ch_8cfeaeb16280','text','{"text": "''He smelled so bad that none of the other little woodland creatures would play with him.'' Jo looked at him solemnly;"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a7f180a7608','ch_8cfeaeb16280','text','{"text": "she hadn''t foreseen this. ''Whenever he would go out to play,'' Jack continued with zest, remembering certain humiliations of his own childhood, ''all of the other tiny animals would cry, ''Uh-oh, here comes Roger Stinky Skunk,'' and they would run away, and Roger Skunk would stand there all alone, and two little round tears would fall from his eyes.'' The corners of Jo''s mouth drooped down and her lower lip bent forward as he traced with a forefinger along the side of her nose the course of one of Roger Skunk''s tears."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ffc9065bf4a0','ch_8cfeaeb16280','text','{"text": "''Won''t he see the owl?'' she asked in a high and faintly roughened voice."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1ea984186527','ch_8cfeaeb16280','text','{"text": "Sitting on the bed beside her, Jack felt the covers tug as her legs switched tensely. He was pleased with this moment — he was telling her something true, something she must know — and had no wish to hurry on. But downstairs a chair scraped, and he realised he must get down to help Clare paint the living-room woodwork."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a89dead6bbe9','ch_8cfeaeb16280','text','{"text": "''Well, he walked along very sadly and came to a very big tree, and in the tiptop of the tree was an enormous wise old owl.'' ''Good.'' ''Mr Owl,'' Roger Skunk said, ''all the other little animals run away from me because I smell so bad.'' ''So you do,'' the owl said."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d9de13fa6d2','ch_8cfeaeb16280','text','{"text": "''Very, very bad.'' ''What can I do?'' Roger Skunk said, and he cried very hard."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e832aba97860','ch_8cfeaeb16280','text','{"text": "''The wizard, the wizard,'' Jo shouted, and sat right up, and a Little Golden Book spilled from the bed."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1edfb54add5f','ch_8cfeaeb16280','text','{"text": "''Now, Jo. Daddy''s telling the story."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f56fcb9a2cf5','ch_8cfeaeb16280','text','{"text": "Do you want to tell Daddy the story?'' ''No. You me.'' ''Then lie down and be sleepy.'' Her head relapsed onto the pillow and she said, ''Out of your head.'' ''Well. The owl thought and thought. At last he said, ''Why don''t you go see the wizard?'' ''Daddy?'' ''What?'' ''Are magic spells real?'' This was a new phase, just this last month, a reality phase. When he told her spiders eat bugs, she turned to her mother and asked, ''Do they really?'' and when Clare told her God was in the sky and all around them, she"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3c7f0e96c7ca','ch_8cfeaeb16280','text','{"text": "turned to her father and insisted, with a sly yet eager smile, ''Is He really?'' ''They''re real in stories,'' Jack answered curtly. She had made him miss a beat in the narrative. ''The owl said, ''Go through the dark woods, under the apple trees, into the swamp, over the crick —'' ''What''s a crick?'' A little river."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b8acf8fc84ca','ch_8cfeaeb16280','text','{"text": "''Over the crick, and there will be the wizard''s house.'' And that''s the way Roger Skunk went, and pretty soon he came to a little white house, and he rapped on the door.'' Jack rapped on the window sill, and under the covers Jo''s tall figure clenched in an infantile thrill. ''And then a tiny little old man came out, with a long white beard and a pointed blue hat, and said, ''Eh? Whatzis? Whatcher want? You smell awful.'' The wizard''s voice was one of Jack''s own favourite effects;"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07ee21cc9516','ch_8cfeaeb16280','text','{"text": "he did it by scrunching up his face and somehow whining through his eyes, which felt for the interval rheumy."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bed7c16f5904','ch_8cfeaeb16280','text','{"text": "He felt being an old man suited him."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5a1f95b443ed','ch_8cfeaeb16280','text','{"text": "''I know it,'' Roger Skunk said, ''and all the little animals run away from me. The enormous wise owl said you could help me.'' ''Eh? Well, maybe. Come on in. Don''t get too close.'' Now, inside, Jo, there were all these magic things, all jumbled together in a big dusty heap, because the wizard did not have any cleaning lady.'' ''Why?'' ''Why? Because he was a wizard, and a very old man.'' ''Will he die?'' ''No. Wizards don''t die."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1ebc61df0b08','ch_8cfeaeb16280','text','{"text": "Well, he rummaged around and found an old stick called a magic wand and asked Roger Skunk what he wanted to smell like. Roger thought and thought and said, ''Roses.'' ''Yes. Good,'' Jo said smugly. Jack fixed her with a trance like gaze and chanted in the wizard''s elderly irritable voice: ''Abracadabry, hocus-poo, Roger Skunk, how do you do, Roses, boses, pull an ear, Roger Skunk, you never fear: Bingo!'' He paused as a rapt expression widened out from his daughter''s nostrils, forcing her eyebrows up"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8162f8dd37c0','ch_8cfeaeb16280','text','{"text": "and her lower lip down in a wide noiseless grin, an expression in which Jack was startled to recognise his wife feigning pleasure at cocktail parties. ''And all of a sudden,'' he whispered, ''the whole inside of the wizard''s house was full of the smell of — roses! ''Roses!'' Roger Fish cried. And the wizard said, very cranky, ''That''ll be seven pennies.'' ''Daddy.'' ''What?'' ''Roger Skunk. You said Roger Fish.'' ''Yes. Skunk.'' ''You said Roger Fish. Wasn''t that silly?'' ''Very silly of your stupid old daddy."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24bc1f29dd84','ch_8cfeaeb16280','text','{"text": "Where was I? Well, you know about the pennies.'' ''Say it.'' ''O.K. Roger Skunk said, ''But all I have is four pennies,'' and he began to cry.'' Jo made the crying face again, but this time without a trace of sincerity. This annoyed Jack. Downstairs some more furniture rumbled. Clare shouldn''t move heavy things;"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd3e6b4a4294','ch_8cfeaeb16280','text','{"text": "she was six months pregnant. It would be their third. ''So the wizard said, ''Oh, very well. Go to the end of the lane and turn around three times and look down the magic well and there you will"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e601668ef48','ch_8cfeaeb16280','text','{"text": "find three pennies. Hurry up.'' So Roger Skunk went to the end of the lane and turned around three times and there in the magic well were three pennies! So he took them back to the wizard and was very happy and ran out into the woods and all the other little animals gathered around him because he smelled so good. And they played tag, baseball, football, basketball, lacrosse, hockey, soccer, and pick-up-sticks.'' ''What''s pick-up-sticks?'' ''It''s a game you play with sticks.'' ''Like the wizard''s magic"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3ed0052e6ca','ch_8cfeaeb16280','text','{"text": "wand?'' ''Kind of. And they played games and laughed all afternoon and then it began to get dark and they all ran home to their mommies.'' Jo was starting to fuss with her hands and look out of the window, at the crack of day that showed under the shade. She thought the story was all over. Jack didn''t like women when they took anything for granted;"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f4a0fbac0530','ch_8cfeaeb16280','text','{"text": "he liked them apprehensive, hanging on his words. ''Now, Jo, are you listening?'' ''Yes.'' ''Because this is very interesting. Roger Skunk''s mommy said,"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bf5fcee70d96','ch_8cfeaeb16280','text','{"text": "''What''s that awful smell?'' ''Wha-at?'' ''And, Roger Skunk said, ''It''s me, Mommy. I smell like roses.'' And she said, ''Who made you smell like that?'' And he said, ''The wizard,'' and she said, ''Well, of all the nerve. You come with me and we''re going right back to that very awful wizard.'' Jo sat up, her hands dabbling in the air with genuine fright."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6cb30757cdd3','ch_8cfeaeb16280','text','{"text": "''But Daddy, then he said about the other little animals run away!'' Her hands skittered off, into the underbrush."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_741338f610a3','ch_8cfeaeb16280','text','{"text": "''All right. He said, ''But Mommy, all the other little animals run away,'' and she said, ''I don''t care. You smelled the way a little skunk should have and I''m going to take you right back to that wizard,'' and she took an umbrella and went back with Roger Skunk and hit that wizard right over the head.'' ''No,'' Jo said, and put her hand out to touch his lips, yet even in her agitation did not quite dare to stop the source of truth."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_031c8c9f52b9','ch_8cfeaeb16280','text','{"text": "Inspiration came to her."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e76e39934dab','ch_8cfeaeb16280','text','{"text": "''Then the wizard hit her on the head and did not change that little skunk back.'' ''No,'' he said."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74d3557db375','ch_8cfeaeb16280','text','{"text": "''The wizard said''O.K.'' and Roger Skunk did not smell of roses any more. He smelled very bad again.'' ''But the other little amum — oh! — amum — '' ''Joanne. It''s Daddy''s story. Shall Daddy not tell you any more stories?'' Her broad face looked at him through sifted light, astounded."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1dd1f1029d08','ch_8cfeaeb16280','text','{"text": "''This is what happened, then. Roger Skunk and his mommy went home and they heard Woo-oo, woooo-oo and it was the choo-choo train bringing Daddy Skunk home from Boston. And they had lima beans, celery, liver, mashed potatoes, and Pie-Oh-My for dessert. And when Roger Skunk was in bed Mommy Skunk came up and hugged him and said he smelled like her little baby skunk again and she loved him very much. And that''s the end of the story.'' ''But Daddy.'' ''What?'' ''Then did the other little animals run away?'' ''No, because eventually they got used to the way he was and did not mind it at all.'' ''What''s evenshiladee?'' ''In a little while.'' ''That was a stupid mommy.'' ''It was not,'' he said with rare emphasis, and believed, from her expression, that she realised he was defending his own mother to her, or something as odd."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_626d654cd488','ch_8cfeaeb16280','text','{"text": "''Now I want you to put your big heavy head in the pillow and have a good long nap.'' He adjusted the shade so not even a crack of day showed, and tiptoed to the door, in the pretense that she was already asleep."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2df4e9dc4e4b','ch_8cfeaeb16280','text','{"text": "But when he turned, she was crouching on top of the covers and staring at him."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8e9f60becb67','ch_8cfeaeb16280','text','{"text": "''Hey. Get under the covers and fall faaast asleep. Bobby''s asleep.'' She stood up and bounced gingerly on the springs."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82a7167622f2','ch_8cfeaeb16280','text','{"text": "''Daddy.'' ''What?'' ''Tomorrow, I want you to tell me the story that that wizard took that magic wand and hit that mommy'' — her plump arms chopped forcefully — ''right over the head.'' ''No. That''s not the story."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4a25731c0074','ch_8cfeaeb16280','text','{"text": "The point is that the little skunk loved his mommy more than he loved all the other little animals and she knew what was right.'' ''No. Tomorrow you say he hit that mommy. Do it.'' She kicked her legs up and sat down on the bed with a great heave and complaint of springs, as she had done hundreds of times before, except that this time she did not laugh."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_396dd6067a00','ch_8cfeaeb16280','text','{"text": "''Say it, Daddy.'' ''Well, we''ll see."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_812724e113b3','ch_8cfeaeb16280','text','{"text": "Now at least have a rest. Stay on the bed. You''re a good girl.'' He closed the door and went downstairs. Clare had spread the newspapers and opened the paint can and, wearing an old shirt of his on top of her maternity smock, was stroking the chair rail with a dipped brush. Above him footsteps vibrated and he called, ''Joanne! Shall I come up there and spank you?'' The footsteps hesitated."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da891d7e98cc','ch_8cfeaeb16280','text','{"text": "''That was a long story,'' Clare said."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1805c70559ef','ch_8cfeaeb16280','text','{"text": "''The poor kid,'' he answered, and with utter weariness watched his wife labour."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1f4f8b3de5e','ch_8cfeaeb16280','text','{"text": "The woodwork, a cage of moldings and rails and baseboards all around them, was half old tan and half new ivory and he felt caught in an ugly middle position, and though he as well felt his wife''s presence in the cage with him, he did not want to speak with her, work with her, touch her, anything."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_975ade3cbb5b','ch_8cfeaeb16280','list','{"ordered": false, "items": ["John Updike"]}',45);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_a8c30604eb65','bk_ncert_english','12-41-on-the-face-of-it','12.41 On the Face of it',NULL,'public',113,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eac2e4e3516d','ch_a8c30604eb65','heading','{"level": 2, "text": "Scene One"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bab11bcc8119','ch_a8c30604eb65','text','{"text": "Mr Lamb''s garden [There is the occasional sound of birdsong and of tree leaves rustling. Derry''s"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f87d2423f66','ch_a8c30604eb65','text','{"text": "footsteps are heard as he walks slowly and tentatively through the long grass. He pauses, then walks on again. He comes round a screen of bushes, so that when Mr Lamb speaks to him he is close at hand and Derry is startled]"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_63198f2d4839','ch_a8c30604eb65','text','{"text": "MR LAMB: Mind the apples!"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8e38ae15719','ch_a8c30604eb65','text','{"text": "DERRY: What? Who''s that? Who''s there?"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4aed926a7410','ch_a8c30604eb65','text','{"text": "MR LAMB: Lamb''s my name. Mind the apples. Crab apples those are. Windfalls in the long grass. You could trip."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd3270f51883','ch_a8c30604eb65','text','{"text": "DERRY: I. . . . there. . . . I thought this was an empty place. I didn''t know there was anybody"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab5eba0831ae','ch_a8c30604eb65','text','{"text": "here...."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2a075737a24','ch_a8c30604eb65','text','{"text": "MR LAMB: That''s all right. I''m here. What are you afraid of, boy? That''s all right."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_88367066dbf7','ch_a8c30604eb65','text','{"text": "DERRY: I thought it was empty. . . . an empty house."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_062735d5c801','ch_a8c30604eb65','text','{"text": "MR LAMB: So it is. Since I''m out here in the garden. It is empty. Until I go back inside. In the meantime, I''m out here and likely to stop. A day like this. Beautiful day. Not a day to be indoors."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b27588b4c5cc','ch_a8c30604eb65','text','{"text": "DERRY: [Panic] I''ve got to go."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fbf7222c02bd','ch_a8c30604eb65','text','{"text": "MR LAMB: Not on my account. I don''t mind who comes into the garden. The gate''s always open. Only you climbed the garden wall."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c26bb358efb','ch_a8c30604eb65','text','{"text": "DERRY: [Angry] You were watching me."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fc63cb995bb0','ch_a8c30604eb65','text','{"text": "MR LAMB: I saw you. But the gate''s open. All welcome. You''re welcome. I sit here. I like sitting."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d1fe0cd52aac','ch_a8c30604eb65','text','{"text": "DERRY: I''d not come to steal anything."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd5dbe125907','ch_a8c30604eb65','text','{"text": "MR LAMB: No, no. The young lads steal. . . . scrump the apples. You''re not so young."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5bc25c82f0f1','ch_a8c30604eb65','text','{"text": "DERRY: I just....wanted to come in. Into the garden."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7f899317bc50','ch_a8c30604eb65','text','{"text": "MR LAMB: So you did. Here we are, then."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_406300f2a0ce','ch_a8c30604eb65','text','{"text": "DERRY: You don''t know who I am."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5348c230306','ch_a8c30604eb65','text','{"text": "MR LAMB: A boy. Thirteen or so."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_222af6d346b9','ch_a8c30604eb65','text','{"text": "DERRY: Fourteen. [Pause] But I''ve got to go now. Good-bye."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f6698cad741a','ch_a8c30604eb65','text','{"text": "MR LAMB: Nothing to be"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbe41fd77fb4','ch_a8c30604eb65','text','{"text": "afraid of. Just a garden. Just me."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b217d28f2836','ch_a8c30604eb65','text','{"text": "DERRY: But I''m not. . . . I''m not afraid. [Pause] People are afraid of me."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1c0265982190','ch_a8c30604eb65','text','{"text": "MR LAMB: Why should that be?"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43a3acb42bd1','ch_a8c30604eb65','text','{"text": "DERRY: Everyone is. It doesn''t matter who they are, or what they say, or how they look. How they pretend. I know. I can see."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b4addfc20363','ch_a8c30604eb65','text','{"text": "MR LAMB: See what?"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75a3d7aa76c9','ch_a8c30604eb65','text','{"text": "DERRY: What they think."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_08d5e6140306','ch_a8c30604eb65','text','{"text": "MR LAMB: What do they think, then?"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ee2811b02b04','ch_a8c30604eb65','text','{"text": "DERRY: You think. . . ."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b1238c4e293','ch_a8c30604eb65','text','{"text": "''Here''s a boy.'' You look at me."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e60c554558d5','ch_a8c30604eb65','text','{"text": ". . and then you see my face and you think."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4968d4cef984','ch_a8c30604eb65','text','{"text": "''That''s bad."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2cdd91e314a3','ch_a8c30604eb65','text','{"text": "That''s a terrible thing. That''s the ugliest thing I ever saw.'' You think, ''Poor boy.'' But I''m not. Not poor. Underneath, you are afraid. Anybody would be. I am. When I look in the mirror, and see it, I''m afraid of me."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c2702188fc3','ch_a8c30604eb65','text','{"text": "MR LAMB: No, Not the whole of you. Not of you."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ca700180902','ch_a8c30604eb65','text','{"text": "DERRY: Yes! [Pause]"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2685915d400','ch_a8c30604eb65','text','{"text": "MR LAMB: Later on, when it''s a bit cooler, I''ll get the ladder and a stick, and pull down those crab apples. They''re ripe for it. I make jelly. It''s a good time of year, September. Look at them. . . . orange and"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32c925f7101a','ch_a8c30604eb65','text','{"text": "golden. That''s magic fruit. I often say. But it''s best picked and made into jelly. You could give me a hand."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e3e119e98f1','ch_a8c30604eb65','text','{"text": "DERRY: What have you changed the subject for? People always do that. Why don''t you ask me? Why do you do what they all do and pretend it isn''t true and isn''t there? In case I see you looking and mind and get upset? I''ll tell. . . . you don''t ask me because you''re afraid to."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_867e7276061e','ch_a8c30604eb65','text','{"text": "MR LAMB: You want me to ask. . . . say so, then."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b3d3f721267d','ch_a8c30604eb65','text','{"text": "DERRY: I don''t like being with people. Any people."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4cac2ea63915','ch_a8c30604eb65','heading','{"level": 2, "text": "Mr Lamb: I"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_950091ce0f75','ch_a8c30604eb65','text','{"text": "should say....to look at it.... I should say, you got burned in a fire."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3cf57723027b','ch_a8c30604eb65','text','{"text": "DERRY: Not in a fire. I got acid all down that side of my face and it burned it all away. It ate my face up. It ate me up. And now it''s like this and it won''t ever be any different."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_203b94ed45b3','ch_a8c30604eb65','text','{"text": "MR LAMB: No."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d369df84e04','ch_a8c30604eb65','text','{"text": "DERRY: Aren''t you interested?"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5e7a15dd43a','ch_a8c30604eb65','text','{"text": "MR LAMB: You''re a boy who came into the garden. Plenty do. I''m interested in anybody. Anything. There''s nothing God made that doesn''t interest me. Look over there. . . . over beside the far wall. What"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76174e8972a8','ch_a8c30604eb65','text','{"text": "can you see?"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5edef3fdc79f','ch_a8c30604eb65','text','{"text": "DERRY: Rubbish."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_87d3a815dac8','ch_a8c30604eb65','text','{"text": "MR LAMB: Rubbish? Look, boy, look. . . . what do you see?"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d05481ccec69','ch_a8c30604eb65','text','{"text": "DERRY: Just. . . . grass and stuff. Weeds."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1df4eb38289d','ch_a8c30604eb65','text','{"text": "MR LAMB: Some call them weeds. If you like, then. . . . a weed garden, that. There''s fruit and there are flowers, and trees and herbs. All sorts. But over there....weeds. I grow weeds there. Why is one green, growing plant called a weed and another''flower''? Where''s the difference. It''s all life.... growing. Same as you and me."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c05a8feeff6c','ch_a8c30604eb65','text','{"text": "DERRY: We''re not the same."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e482189fc811','ch_a8c30604eb65','text','{"text": "MR LAMB: I''m"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ecef1a0abe6d','ch_a8c30604eb65','text','{"text": "old. You''re young. You''ve got a burned face, I''ve got a tin leg. Not important. You''re standing there.... I''m sitting here. Where''s the difference?"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_13c85b00d327','ch_a8c30604eb65','text','{"text": "DERRY: Why have you got a tin leg?"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_57b0ba1311d4','ch_a8c30604eb65','text','{"text": "MR LAMB: Real one got blown off, years back. Lamey-Lamb, some kids say. Haven''t you heard them? You will. Lamey-Lamb. It fits. Doesn''t trouble me."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abc213a8c2b8','ch_a8c30604eb65','text','{"text": "DERRY: But you can put on trousers and cover it up and no one sees, they don''t have to notice and stare."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0910998a2d2a','ch_a8c30604eb65','text','{"text": "MR LAMB: Some do. Some don''t. They get tired of it, in the end."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6e4c9ff03c78','ch_a8c30604eb65','text','{"text": "There''s plenty of other things to stare at."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f8b5c7ce368e','ch_a8c30604eb65','text','{"text": "DERRY: Like my face."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80cb0f43fd07','ch_a8c30604eb65','text','{"text": "MR LAMB: Like crab apples or the weeds or a spider climbing up a silken ladder, or my tall sun-flowers."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e156182bb032','ch_a8c30604eb65','text','{"text": "DERRY: Things."}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cbaa96194712','ch_a8c30604eb65','text','{"text": "MR LAMB: It''s all relative. Beauty and the beast."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d671afff1248','ch_a8c30604eb65','text','{"text": "DERRY: What''s that supposed to mean?"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74e10dd834c2','ch_a8c30604eb65','text','{"text": "MR LAMB: You tell me."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5e6a4fbc448c','ch_a8c30604eb65','text','{"text": "DERRY: You needn''t think they haven''t all told me that fairy story before."}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5831eb74c20b','ch_a8c30604eb65','text','{"text": "''It''s not what you look like, it''s what you are inside. Handsome is as handsome does. Beauty loved the monstrous beast for himself and when she kissed him he changed into a handsome prince.'' Only he wouldn''t, he''d have stayed a monstrous beast."}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_acd2d6b4cc53','ch_a8c30604eb65','text','{"text": "I won''t change."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b8b224acac0','ch_a8c30604eb65','text','{"text": "MR LAMB: In that way? No, you won''t."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f756669a8143','ch_a8c30604eb65','text','{"text": "DERRY: And no one''ll kiss me, ever. Only my mother, and she kisses me on the other side of my face, and I don''t like my mother to kiss me, she does it because she has to. Why should I like that? I don''t care if nobody ever kisses me."}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be33b770f60c','ch_a8c30604eb65','text','{"text": "MR LAMB: Ah, but do you care if you never kiss them."}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ea04384688d','ch_a8c30604eb65','text','{"text": "DERRY: What?"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9cc9f6b52f26','ch_a8c30604eb65','text','{"text": "MR LAMB: Girls. Pretty girls. Long hair and large eyes. People you love."}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43537eb17571','ch_a8c30604eb65','text','{"text": "DERRY: Who''d let me? Not one."}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_161a5503fdda','ch_a8c30604eb65','text','{"text": "MR LAMB: Who can tell?"}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_390ccfcbf7de','ch_a8c30604eb65','text','{"text": "DERRY: I won''t ever"}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2964811c56f0','ch_a8c30604eb65','text','{"text": "look different. When I''m as old as you, I''ll look the same. I''ll still only have half a face."}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_54e0ba5f2143','ch_a8c30604eb65','text','{"text": "MR LAMB: So you will. But the world won''t. The world''s got a whole face, and the world''s there to be looked at."}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bf9795dd325d','ch_a8c30604eb65','text','{"text": "DERRY: Do you think this is the world? This old garden?"}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5735d6d62510','ch_a8c30604eb65','text','{"text": "MR LAMB: When I''m here. Not the only one. But the world, as much as anywhere."}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53f105134f67','ch_a8c30604eb65','text','{"text": "DERRY: Does your leg hurt you?"}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b15c45b8b913','ch_a8c30604eb65','text','{"text": "MR LAMB: Tin doesn''t hurt, boy!"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6239efb9870d','ch_a8c30604eb65','text','{"text": "DERRY: When it came off, did it?"}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8cb183a6032f','ch_a8c30604eb65','text','{"text": "MR LAMB: Certainly."}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1c5c95d863c8','ch_a8c30604eb65','text','{"text": "DERRY: And now? I mean, where the tin stops,"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be2bbbbd3099','ch_a8c30604eb65','text','{"text": "at the top?"}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e335d1946cd','ch_a8c30604eb65','text','{"text": "MR LAMB: Now and then. In wet weather. It doesn''t signify."}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_54ac55b1af57','ch_a8c30604eb65','text','{"text": "DERRY: Oh, that''s something else they all say. ''Look at all those people who are in pain and brave and never cry and never complain and don''t feel sorry for themselves.''"}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68f8ed997f9b','ch_a8c30604eb65','text','{"text": "MR LAMB: I haven''t said it."}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_47f488612631','ch_a8c30604eb65','text','{"text": "DERRY: And think of all those people worse off than you. Think, you might have been blinded, or born deaf, or have to live in a wheelchair, or be daft in your head and dribble."}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44450a020e26','ch_a8c30604eb65','text','{"text": "MR LAMB: And that''s all true, and you know it. DERRY:"}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0b7c475d70a','ch_a8c30604eb65','text','{"text": "It won''t make my face change. Do you know, one day, a woman went by me in the street — I was at a bus-stop — and she was with another woman, and she looked at me, and she said.... whispered....only I heard her.... she said, ''Look at that, that''s a terrible thing. That''s a face only a mother could love.''"}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa96ddcbd0b3','ch_a8c30604eb65','text','{"text": "MR LAMB: So you believe everything you hear, then?"}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f22a9a2be4f','ch_a8c30604eb65','text','{"text": "DERRY: It was cruel."}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_955fb8e22ae0','ch_a8c30604eb65','text','{"text": "MR LAMB: Maybe not meant as such. Just something said between them."}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_850c31fe3049','ch_a8c30604eb65','text','{"text": "DERRY: Only I heard it. I heard."}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71fa0e0cc8a7','ch_a8c30604eb65','text','{"text": "MR LAMB: And is that"}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f4efb7e10eac','ch_a8c30604eb65','text','{"text": "the only thing you ever heard anyone say, in your life?"}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9fdf10d4aec5','ch_a8c30604eb65','text','{"text": "DERRY: Oh no! I''ve heard a lot of things."}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1305d8a60404','ch_a8c30604eb65','text','{"text": "MR LAMB: So now you keep your ears shut."}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b43462836807','ch_a8c30604eb65','text','{"text": "DERRY: You''re. . . . peculiar. You say peculiar things. You ask questions I don''t understand."}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_035116372217','ch_a8c30604eb65','text','{"text": "MR LAMB: I like to talk. Have company. You don''t have to answer questions. You don''t have to stop here at all. The gate''s open."}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7cf1a60d01c','ch_a8c30604eb65','text','{"text": "DERRY: Yes, but. . ."}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a0310b8c759','ch_a8c30604eb65','text','{"text": "MR LAMB: I''ve a hive of bees behind those trees over there. Some hear bees and they say, bees buzz. But when you"}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4a6a77622c44','ch_a8c30604eb65','text','{"text": "listen to bees for a long while, they humm....and hum means''sing''. I hear them singing, my bees."}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0dadfeae1e3b','ch_a8c30604eb65','text','{"text": "DERRY: But....I like it here. I came in because I liked it....when I looked over the wall."}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9ca965d157b','ch_a8c30604eb65','text','{"text": "MR LAMB: If you''d seen me, you''d not have come in."}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_83b1f0a4169c','ch_a8c30604eb65','text','{"text": "DERRY: No."}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c4dac3a3a66','ch_a8c30604eb65','text','{"text": "MR LAMB: No."}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5788522f7349','ch_a8c30604eb65','text','{"text": "DERRY: It''d have been trespassing."}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e39c290b384a','ch_a8c30604eb65','text','{"text": "MR LAMB: Ah. That''s not why."}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9d681c3842c','ch_a8c30604eb65','text','{"text": "DERRY: I don''t like being near people. When they stare. . . . when I see them being afraid of me."}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68981cf0ef2d','ch_a8c30604eb65','text','{"text": "MR LAMB: You could lock yourself up in a room and never leave it. There was"}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbae72dded2e','ch_a8c30604eb65','text','{"text": "a man who did that. He was afraid, you see. Of everything. Everything in this world. A bus might run him over, or a man might breathe deadly germs onto him, or a donkey might kick him to death, or lightning might strike him down, or he might love a girl and the girl would leave him, and he might slip on a banana skin and fall and people who saw him would laugh their heads off. So he went into this room, and locked the door, and got into his bed, and stayed there."}',116);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1b230c6494e','ch_a8c30604eb65','text','{"text": "DERRY: For ever?"}',117);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_812ea8ecc4b4','ch_a8c30604eb65','text','{"text": "MR LAMB: For a"}',118);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c3f00e6a472','ch_a8c30604eb65','text','{"text": "while."}',119);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b4bf87e5bdb2','ch_a8c30604eb65','text','{"text": "DERRY: Then what?"}',120);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9449561e2482','ch_a8c30604eb65','text','{"text": "MR LAMB: A picture fell off the wall on to his head and killed him. [Derry laughs a lot]"}',121);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a341fc18729c','ch_a8c30604eb65','text','{"text": "MR LAMB: You see?"}',122);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7b742d893765','ch_a8c30604eb65','text','{"text": "DERRY: But. . . . you still say peculiar things."}',123);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_10d1d0a4aab9','ch_a8c30604eb65','text','{"text": "MR LAMB: Peculiar to some."}',124);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9c3f2171a07','ch_a8c30604eb65','text','{"text": "DERRY: What do you do all day?"}',125);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b6f7086ca7c8','ch_a8c30604eb65','text','{"text": "MR LAMB: Sit in the sun. Read books. Ah, you thought it was an empty house, but inside, it''s full. Books and other things. Full."}',126);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_077905b00ac3','ch_a8c30604eb65','text','{"text": "DERRY: But there aren''t any curtains at the windows."}',127);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_349705beded4','ch_a8c30604eb65','text','{"text": "MR LAMB: I''m not fond of curtains. Shutting things out, shutting things in. I"}',128);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bb7d6d0bd7f9','ch_a8c30604eb65','text','{"text": "like the light and the darkness, and the windows open, to hear the wind."}',129);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d28934189bd','ch_a8c30604eb65','text','{"text": "DERRY: Yes. I like that. When it''s raining, I like to hear it on the roof."}',130);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_03026921daa9','ch_a8c30604eb65','text','{"text": "MR LAMB: So you''re not lost, are you? Not altogether? You do hear things. You listen."}',131);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_131c522bf179','ch_a8c30604eb65','text','{"text": "DERRY: They talk about me. Downstairs, When I''m not there."}',132);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_86b9af9c3bb4','ch_a8c30604eb65','text','{"text": "''What''ll he ever do?"}',133);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f7d188968c0','ch_a8c30604eb65','text','{"text": "What''s going to happen to him when we''ve gone? How ever will he get on in this world? Looking like that? With that on his face?'' That''s what they say."}',134);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c20190c3e53','ch_a8c30604eb65','text','{"text": "MR LAMB: Lord, boy, you''ve got two arms, two legs and eyes and ears, you''ve got a tongue and a brain. You''ll get on the way you want, like all the rest. And if you chose, and set your mind to it, you could get on better than all the rest."}',135);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79ad711f9e06','ch_a8c30604eb65','text','{"text": "DERRY: How?"}',136);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07639d4f6377','ch_a8c30604eb65','text','{"text": "MR LAMB: Same way as I do."}',137);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f03543a7f4d3','ch_a8c30604eb65','text','{"text": "DERRY: Do you have any friends?"}',138);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c21845b375b','ch_a8c30604eb65','text','{"text": "MR LAMB: Hundreds."}',139);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ddf8b1c5f81','ch_a8c30604eb65','text','{"text": "DERRY: But you live"}',140);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abf541c98387','ch_a8c30604eb65','text','{"text": "by yourself in that house. It''s a big house, too."}',141);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_47df2ff9552b','ch_a8c30604eb65','text','{"text": "MR LAMB: Friends everywhere. People come in.... everybody knows me. The gate''s always open. They come and sit here. And in front of the fire in winter. Kids come for the apples and pears. And for toffee. I make toffee with honey. Anybody comes. So have you."}',142);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c6cf6c7aa799','ch_a8c30604eb65','text','{"text": "DERRY: But I''m not a friend."}',143);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3dcbfe6a1eec','ch_a8c30604eb65','text','{"text": "MR LAMB: Certainly you are. So far as I''m concerned. What have you done to make me think you''re not?"}',144);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c64f1578ae98','ch_a8c30604eb65','text','{"text": "DERRY: You don''t know me. You don''t know where I come from or"}',145);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b9d2038b058','ch_a8c30604eb65','text','{"text": "even what my name is."}',146);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b0f4dd458bf1','ch_a8c30604eb65','text','{"text": "MR LAMB: Why should that signify? Do I have to write all your particulars down and put them in a filing box, before you can be a friend?"}',147);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e0796bce568','ch_a8c30604eb65','text','{"text": "DERRY: I suppose...not. No."}',148);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1196278dc8a9','ch_a8c30604eb65','text','{"text": "MR LAMB: You could tell me your name. If you chose. And not, if you didn''t."}',149);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7f992f892280','ch_a8c30604eb65','text','{"text": "DERRY: Derry. Only it''s Derek....but I hate that. Derry. If I''m your friend, you don''t have to be mine. I choose that."}',150);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f167c00aa1b3','ch_a8c30604eb65','text','{"text": "MR LAMB: Certainly."}',151);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4187901b8c46','ch_a8c30604eb65','text','{"text": "DERRY: I might never come here again, you might never see me again and then I couldn''t still be a"}',152);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7569add6dcc1','ch_a8c30604eb65','text','{"text": "friend."}',153);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_65dc208377dc','ch_a8c30604eb65','text','{"text": "MR LAMB: Why not?"}',154);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b87b53788702','ch_a8c30604eb65','text','{"text": "DERRY: How could I? You pass people in the street and you might even speak to them, but you never see them again. It doesn''t mean they''re friends."}',155);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5336f121754e','ch_a8c30604eb65','text','{"text": "MR LAMB: Doesn''t mean they''re enemies, either, does it?"}',156);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4857ff3b73f7','ch_a8c30604eb65','text','{"text": "DERRY: No they''re just....nothing. People. That''s all."}',157);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ee1b8a08de8b','ch_a8c30604eb65','text','{"text": "MR LAMB: People are never just nothing. Never."}',158);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_66bfe3210d15','ch_a8c30604eb65','text','{"text": "DERRY: There are some people I hate."}',159);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6bd129fd1ca2','ch_a8c30604eb65','text','{"text": "MR LAMB: That''d do you more harm than any bottle of acid. Acid only burns your face."}',160);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d19546b4c02f','ch_a8c30604eb65','text','{"text": "DERRY: Only...."}',161);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_504b4052344f','ch_a8c30604eb65','text','{"text": "MR LAMB: Like a bomb only blew"}',162);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_398c8e841e8e','ch_a8c30604eb65','text','{"text": "up my leg. There''s worse things can happen. You can burn yourself away inside."}',163);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e3f1ab8167a','ch_a8c30604eb65','text','{"text": "DERRY: After I''d come home, one person said, ''He''d have been better off stopping in there. In the hospital. He''d be better off with others like himself.'' She thinks blind people only ought to be with other blind people and idiot boys with idiot boys."}',164);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c940768fb4e','ch_a8c30604eb65','text','{"text": "MR LAMB: And people with no legs altogether?"}',165);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9feebc7f3524','ch_a8c30604eb65','text','{"text": "DERRY: That''s right."}',166);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3257dd2b12b3','ch_a8c30604eb65','text','{"text": "MR LAMB: What kind of a world would that be?"}',167);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4af18b4eca3','ch_a8c30604eb65','text','{"text": "DERRY: At least there''d be nobody to stare at you because"}',168);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e046084d6b4f','ch_a8c30604eb65','text','{"text": "you weren''t like them."}',169);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a13d1c13bfb8','ch_a8c30604eb65','text','{"text": "MR LAMB: So you think you''re just the same as all the other people with burned faces? Just by what you look like? Ah. . . . everything''s different. Everything''s the same, but everything is different. Itself."}',170);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_750d39424831','ch_a8c30604eb65','text','{"text": "DERRY: How do you make all that out?"}',171);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25ee26121d9f','ch_a8c30604eb65','text','{"text": "MR LAMB: Watching. Listening. Thinking."}',172);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b660f8b30c6f','ch_a8c30604eb65','text','{"text": "DERRY: I''d like a place like this. A garden. I''d like a house with no curtains."}',173);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb9b9f407f26','ch_a8c30604eb65','text','{"text": "MR LAMB: The gate''s always open."}',174);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b9d2f84504df','ch_a8c30604eb65','text','{"text": "DERRY: But this isn''t mine."}',175);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f96be55d108','ch_a8c30604eb65','text','{"text": "MR LAMB: Everything''s yours if you want it. What''s"}',176);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96e7bb505515','ch_a8c30604eb65','text','{"text": "mine is anybody''s."}',177);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4adef658ef90','ch_a8c30604eb65','text','{"text": "DERRY: So I could come here again? Even if you were out....I could come here."}',178);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f931e14b764','ch_a8c30604eb65','text','{"text": "MR LAMB: Certainly. You might find others here, of course."}',179);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_629eab456ed9','ch_a8c30604eb65','text','{"text": "DERRY: Oh...."}',180);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_229cb57e724c','ch_a8c30604eb65','text','{"text": "MR LAMB: Well, that needn''t stop you, you needn''t mind."}',181);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ffc40677d31b','ch_a8c30604eb65','text','{"text": "DERRY: It''d stop them. They''d mind me. When they saw me here. They look at my face and run."}',182);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3467f23c09bc','ch_a8c30604eb65','text','{"text": "MR LAMB: They might. They might not. You''d have to take the risk. So would they."}',183);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1d9215ef540','ch_a8c30604eb65','text','{"text": "DERRY: No, you would. You might have me and lose all your other friends, because nobody wants to stay"}',184);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5243526a6097','ch_a8c30604eb65','text','{"text": "near me if they can help it."}',185);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8844d9dcaec','ch_a8c30604eb65','text','{"text": "MR LAMB: I''ve not moved."}',186);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_865ef6fa81a9','ch_a8c30604eb65','text','{"text": "DERRY: No...."}',187);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_423e9f0c3515','ch_a8c30604eb65','text','{"text": "MR LAMB: When I go down the street, the kids shout''Lamey-Lamb.'' But they still come into the garden, into my house;"}',188);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff4181fc5b10','ch_a8c30604eb65','text','{"text": "it''s a game. They''re not afraid of me. Why should they be? Because I''m not afraid of them, that''s why not."}',189);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b8044e27068a','ch_a8c30604eb65','text','{"text": "DERRY: Did you get your leg blown off in the war?"}',190);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4d72e3f8524','ch_a8c30604eb65','text','{"text": "MR LAMB: Certainly."}',191);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_55497dcefcc9','ch_a8c30604eb65','text','{"text": "DERRY: How will you climb on a ladder and get the crab apples down, then?"}',192);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f66b63a2156','ch_a8c30604eb65','text','{"text": "MR LAMB: Oh, there''s a lot of things I''ve learned to do, and"}',193);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40782f33198e','ch_a8c30604eb65','text','{"text": "plenty of time for it. Years. I take it steady."}',194);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d335b8cf12f0','ch_a8c30604eb65','text','{"text": "DERRY: If you fell and broke your neck, you could lie on the grass and die. If you were on your own."}',195);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d84103b46a4','ch_a8c30604eb65','text','{"text": "MR LAMB: I could."}',196);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_136dc0f0760b','ch_a8c30604eb65','text','{"text": "DERRY: You said I could help you."}',197);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20059171b66e','ch_a8c30604eb65','text','{"text": "MR LAMB: If you want to."}',198);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00aea4f1d045','ch_a8c30604eb65','text','{"text": "DERRY: But my mother''ll want to know where I am. It''s three miles home, across the fields. I''m fourteen. but they still want to know where I am."}',199);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_817b6d7a866d','ch_a8c30604eb65','text','{"text": "MR LAMB: People worry."}',200);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d1ce554bf95','ch_a8c30604eb65','text','{"text": "DERRY: People fuss."}',201);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d987db2e5364','ch_a8c30604eb65','text','{"text": "MR LAMB: Go back and tell them."}',202);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c66cc0d45558','ch_a8c30604eb65','text','{"text": "DERRY: It''s three miles."}',203);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3c48a0e9ec4','ch_a8c30604eb65','text','{"text": "MR LAMB: It''s a fine evening."}',204);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6bdd26121a28','ch_a8c30604eb65','text','{"text": "You''ve got legs."}',205);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bbd8e8166891','ch_a8c30604eb65','text','{"text": "DERRY: Once I got home, they''d never let me come back."}',206);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_31cf4f008f7d','ch_a8c30604eb65','text','{"text": "MR LAMB: Once you got home, you''d never let yourself come back."}',207);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_061c1077e687','ch_a8c30604eb65','text','{"text": "DERRY: You don''t know....you don''t know what I could do."}',208);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_86a5c59819b6','ch_a8c30604eb65','text','{"text": "MR LAMB: No. Only you know that."}',209);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_33e42298751b','ch_a8c30604eb65','text','{"text": "DERRY: If I chose. . . ."}',210);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3230473cb8f1','ch_a8c30604eb65','text','{"text": "MR LAMB: Ah. . . . if you chose. I don''t know everything, boy. I can''t tell you what to do."}',211);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a21ae52dedf2','ch_a8c30604eb65','text','{"text": "DERRY: They tell me."}',212);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d8fe01b42736','ch_a8c30604eb65','text','{"text": "MR LAMB: Do you have to agree?"}',213);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ca6f46ea250','ch_a8c30604eb65','text','{"text": "DERRY: I don''t know what I want. I want....something no one else has got or ever will have. Something"}',214);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f4526d1d4447','ch_a8c30604eb65','text','{"text": "just mine. Like this garden. I don''t know what it is."}',215);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_394e35375444','ch_a8c30604eb65','text','{"text": "MR LAMB: You could find out."}',216);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9270dc92990','ch_a8c30604eb65','text','{"text": "DERRY: How?"}',217);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0f845c6298c','ch_a8c30604eb65','text','{"text": "MR LAMB: Waiting. Watching. Listening. Sitting here or going there. I''ll have to see to the bees."}',218);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f31b3252a3c','ch_a8c30604eb65','text','{"text": "DERRY: Those other people who come here....do they talk to you? Ask you things?"}',219);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e29e63736ed','ch_a8c30604eb65','text','{"text": "MR LAMB: Some do, some don''t. I ask them. I like to learn."}',220);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_faf37d6a8a76','ch_a8c30604eb65','text','{"text": "DERRY: I don''t believe in them. I don''t think anybody ever comes. You''re here all by yourself and miserable and no one would know if you were alive or dead and nobody"}',221);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0ec9a225309','ch_a8c30604eb65','text','{"text": "cares."}',222);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_167ef548afff','ch_a8c30604eb65','text','{"text": "MR LAMB: You think what you please."}',223);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8982f52bce9','ch_a8c30604eb65','text','{"text": "DERRY: All right then, tell me some of their names."}',224);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b91367e425d0','ch_a8c30604eb65','text','{"text": "MR LAMB: What are names? Tom, Dick or Harry. [Getting up] I''m off down to the bees."}',225);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_119a471325ee','ch_a8c30604eb65','text','{"text": "DERRY: I think you''re daft....crazy...."}',226);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7f852a6355a4','ch_a8c30604eb65','text','{"text": "MR LAMB: That''s a good excuse."}',227);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d4c812d9bbf','ch_a8c30604eb65','text','{"text": "DERRY: What for? You don''t talk sense."}',228);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a7066ee30e4','ch_a8c30604eb65','text','{"text": "MR LAMB: Good excuse not to come back. And you''ve got a burned-up face, and that''s other people''s excuse."}',229);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c5a6708624c','ch_a8c30604eb65','text','{"text": "DERRY: You''re like the others, you like to say things like that. If you don''t feel sorry for my face,"}',230);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cadab940e2c8','ch_a8c30604eb65','text','{"text": "you''re frightened of it, and if you''re not frightened, you think I''m ugly as a devil. I am a devil. Don''t you? [Shouts] [Mr Lamb does not reply. He has gone to his bees. ]"}',231);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0df67623475e','ch_a8c30604eb65','text','{"text": "DERRY: [Quietly] No. You don''t. I like it here. [Pause. Derry gets up and shouts.] I''m going. But I''ll come back. You see. You wait. I can run. I haven''t got a tin leg. I''ll be back. [Derry runs off. Silence. The sounds of the garden again.]"}',232);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97220c62e3cf','ch_a8c30604eb65','text','{"text": "MR LAMB: [To himself] There my dears. That''s you seen to. Ah. . . . you know. We all"}',233);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d5b25e6a64da','ch_a8c30604eb65','text','{"text": "know. I''ll come back. They never do, though. Not them. Never do come back. [The garden noises fade.]"}',234);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_77fe8135a000','ch_a8c30604eb65','heading','{"level": 2, "text": "Scene Two"}',235);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0479c1e22337','ch_a8c30604eb65','text','{"text": "Derry''s house. MOTHER: You think I don''t know about him, you think. I haven''t heard things?"}',236);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ba190e38906','ch_a8c30604eb65','text','{"text": "DERRY: You shouldn''t believe all you hear. MOTHER: Been told. Warned. We''ve not lived here three months, but I know what there is to know and you''re not to go back there."}',237);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d33e2908ad74','ch_a8c30604eb65','text','{"text": "DERRY: What are you afraid of? What do you think he is? An old man with a tin leg and he lives in a huge"}',238);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_57fe17cbb4bd','ch_a8c30604eb65','text','{"text": "house without curtains and has a garden. And I want to be there, and sit and....listen to things. Listen and look. MOTHER: Listen to what?"}',239);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_862575810b05','ch_a8c30604eb65','text','{"text": "DERRY: Bees singing. Him talking. MOTHER: And what''s he got to say to you?"}',240);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_727b57390190','ch_a8c30604eb65','text','{"text": "DERRY: Things that matter. Things nobody else has ever said. Things I want to think about. MOTHER: Then you stay here and do your thinking. You''re best off here."}',241);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_08cd0b3e1f53','ch_a8c30604eb65','text','{"text": "DERRY: I hate it here. MOTHER: You can''t help the things you say. I forgive you. It''s bound to make you feel bad"}',242);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f34fcbc5a7aa','ch_a8c30604eb65','text','{"text": "things....and say them. I don''t blame you."}',243);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ef595b12b38','ch_a8c30604eb65','text','{"text": "DERRY: It''s got nothing to do with my face and what I look like. I don''t care about that and it isn''t important. It''s what I think and feel and what I want to see and find out and hear. And I''m going back there. Only to help him with the crab apples. Only to look at things and listen. But I''m going. MOTHER: You''ll stop here."}',244);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc3abe4041cf','ch_a8c30604eb65','text','{"text": "DERRY: Oh no, oh no. Because if I don''t go back there, I''ll never go anywhere in this world again. [The door slams. Derry runs,"}',245);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b4bcd23e58f5','ch_a8c30604eb65','text','{"text": "panting.] And I want the world....I want it....I want it.... [The sound of his panting fades.]"}',246);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d118fabd96ec','ch_a8c30604eb65','heading','{"level": 2, "text": "Scene Three"}',247);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_610f78c93750','ch_a8c30604eb65','text','{"text": "Mr Lamb''s garden [Garden sounds: the noise of a branch shifting;"}',248);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3c9c33d5f36','ch_a8c30604eb65','text','{"text": "apples thumping down;"}',249);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eafa21023308','ch_a8c30604eb65','text','{"text": "the branch shifting again. ]"}',250);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc45982e6f31','ch_a8c30604eb65','text','{"text": "MR LAMB: Steady. . . . that''s....got it. That''s it. . . [More apples fall] And again. That''s it....and.... [A creak. A crash. The ladder falls back, Mr Lamb with it. A thump. The branch swishes back. Creaks. Then silence. Derry opens the garden gate, still panting.]"}',251);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91c1626acdb1','ch_a8c30604eb65','text','{"text": "DERRY: You see, you see! I came back. You said I wouldn''t and they said. . . . but I came back, I wanted. . . . [He stops dead. Silence. ] Mr Lamb, Mr. . . . You''ve..... [He runs through the grass. Stops. Kneels] Mr Lamb, It''s all right. . . . You fell. . . . I''m here, Mr Lamb, It''s all right. [Silence] I came back. Lamey-Lamb. I did. . . . . come back. [Derry begins to weep. ]"}',252);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18235a0f0d58','ch_a8c30604eb65','heading','{"level": 2, "text": "The End"}',253);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_add09abb535e','ch_a8c30604eb65','list','{"ordered": false, "items": ["Susan Hill"]}',254);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_e3fab440a09d','bk_ncert_english','12-42-evans-tries-an-o-level','12. 42 Evans Tries an O-Level',NULL,'public',114,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43bd165ce423','ch_e3fab440a09d','text','{"text": "Dramatis Personae"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_356fde2f774a','ch_e3fab440a09d','text','{"text": "The Secretary of the Examinations Board"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_343159efcc62','ch_e3fab440a09d','text','{"text": "The Governor of HM Prison, Oxford"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_39229ebc0fce','ch_e3fab440a09d','text','{"text": "James Evans, a prisoner"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_502816b7d688','ch_e3fab440a09d','text','{"text": "Mr Jackson, a prison officer"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e7de55bdef7','ch_e3fab440a09d','text','{"text": "Mr Stephens, a prison officer"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2a86e69247a','ch_e3fab440a09d','text','{"text": "The Reverend S. McLeery, an invigilator"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df801b009b71','ch_e3fab440a09d','text','{"text": "Mr Carter, Detective Superintendent"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2aed9510c527','ch_e3fab440a09d','text','{"text": "Mr Bell, Detective Chief Inspector"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b4646c6b5187','ch_e3fab440a09d','text','{"text": "All precautions have been taken to see to it that the O-level German examination arranged in the prison for Evans does not provide him with any means of escape."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ffccd8977bf','ch_e3fab440a09d','text','{"text": "It was in early March when the Secretary of the Examinations Board received the call from Oxford Prison."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b78c317c3e7','ch_e3fab440a09d','text','{"text": "''It''s a slightly unusual request, Governor, but I don''t see why we shouldn''t try to help."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_66329a6745d0','ch_e3fab440a09d','text','{"text": "Just the one fellow, you say?'' ''That''s it. Chap called Evans. Started night classes in O-level German last September. Says he''s dead keen to get some sort of academic qualification.'' ''Is he any good?'' ''He was the only one in the class, so you can say he''s had individual tuition all the time, really. Would have cost him a packet if he''d been outside.'' ''Well, let''s give him a chance, shall we?'' ''That''s jolly kind of you. What exactly''s the procedure now?'' ''Oh, don''t worry about that. I''ll be"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79267beec451','ch_e3fab440a09d','text','{"text": "sending you all the forms and stuff. What''s his name, you say? Evans?'' ''James Roderick Evans.'' It sounded rather grand."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97be4aab1a5a','ch_e3fab440a09d','text','{"text": "''Just one thing, Governor. He''s not a violent sort of fellow, is he?"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0c1ec338537','ch_e3fab440a09d','text','{"text": "I don''t want to know his criminal record or anything like that, but — '' ''No. There''s no record of violence. Quite a pleasant sort of chap, they tell me. Bit of a card, really. One of the stars at the Christmas concert. Imitations, you know the sort of thing: Mike Yarwood stuff. No, he''s just a congenital kleptomaniac, that''s all.'' The Governor was tempted to add something else, but he thought better of it. He''d look after that particular side of things himself. ''Presumably,'' said the Secretary,"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3031b4df19b8','ch_e3fab440a09d','text','{"text": "''you can arrange a room where — '' ''No problem. He''s in a cell on his own. If you''ve no objections, he can sit the exam in there.'' ''That''s fine.'' ''And we could easily get one of the parsons from St. Mary Mags to invigilate, if that''s — '' ''Fine, yes. They seem to have a lot of parsons there, don''t they?'' The two men chuckled good-naturedly, and the Secretary had a final thought."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25d1982b2147','ch_e3fab440a09d','text','{"text": "''At least there''s one thing."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec4917a9773a','ch_e3fab440a09d','text','{"text": "You shouldn''t have much trouble keeping him incommunicado, should you?'' The Governor chuckled politely once more, reiterated his thanks, and slowly cradled the phone. Evans!"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e60ed264d4d9','ch_e3fab440a09d','text','{"text": "''Evans the Break'' as the prison officers called him."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7bd119f87194','ch_e3fab440a09d','text','{"text": "Thrice he''d escaped from prison, and but for the recent wave of unrest in the maximum-security establishments up north, he wouldn''t now be gracing the Governor''s premises in Oxford;"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec6ffa98a27e','ch_e3fab440a09d','text','{"text": "and the Governor was going to make absolutely certain that he wouldn''t be disgracing them. Not that Evans was a real burden: just a persistent, nagging presence. He''d be all right in Oxford, though: the Governor would see to that — would see to it personally. And besides, there was just a possibility that Evans was"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6db11aba185b','ch_e3fab440a09d','text','{"text": "genuinely interested in O-level German. Just a slight possibility. Just a very slight possibility. At 8.30 p.m. on Monday 7 June, Evans''s German teacher shook him by the hand in the heavily guarded Recreational Block, just across from D Wing."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a7651df5d6b','ch_e3fab440a09d','text','{"text": "''Guten Gluck, Herr Evans.'' ''Pardon?'' ''I said, ''Good luck''. Good luck for tomorrow.'' ''Oh. Thanks, er, I mean, er, Danke Schon.'' ''You haven''t a cat in hell''s chance of getting through, of course, but — '' ''I may surprise everybody,'' said Evans."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7af1dceab24','ch_e3fab440a09d','text','{"text": "At 8. 30 the following morning, Evans had a visitor. Two visitors, in fact. He tucked his grubby string-vest into his equally grubby trousers, and stood up from his bunk, smiling cheerfully."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e2263b0315af','ch_e3fab440a09d','text','{"text": "''Mornin'', Mr Jackson."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_38d1f42dc526','ch_e3fab440a09d','text','{"text": "This is indeed an honour.'' Jackson was the senior prison officer on D Wing, and he and Evans had already become warm enemies. At Jackson''s side stood Officer Stephens, a burly, surly-looking man, only recently recruited to the profession. Jackson nodded curtly. ''And how''s our little Einstein this morning, then?'' ''Wasn''t''e a mathematician, Mr Jackson?'' ''I think''e was a Jew, Mr. Jackson.'' Evans''s face was unshaven, and he wore a filthy-looking red-and-white bobble hat upon his head. ''Give me a"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5b28b90e8e1','ch_e3fab440a09d','text','{"text": "chance, Mr Jackson. I was just goin'' to shave when you bust in.'' ''Which reminds me.'' Jackson turned his eyes on Stephens."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3833de4e0423','ch_e3fab440a09d','text','{"text": "''Make sure you take his razor out of the cell when he''s finished scraping that ugly mug of his."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f7c8dfc3f42','ch_e3fab440a09d','text','{"text": "Clear? One of these days he''ll do us all a favour and cut his bloody throat.'' For a few seconds Evans looked thoughtfully at the man standing ramrod straight in front of him, a string of Second World War medals proudly paraded over his left breast-pocket."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d69d8c58cccc','ch_e3fab440a09d','text','{"text": "''Mr Jackson? Was it you who took my nail-scissors away?'' Evans had always worried about his hands."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f6cd9f95da89','ch_e3fab440a09d','text','{"text": "''And your nail-file, too.'' ''Look!'' For a moment Evans''s eyes smouldered dangerously, but Jackson was ready for him. ''Orders of the Governor, Evans.'' He leaned forward and leered, his voice dropping to a harsh, contemptuous whisper."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9ac11a1fa64e','ch_e3fab440a09d','text','{"text": "''You want to complain?'' Evans shrugged his shoulders lightly."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa27b210b298','ch_e3fab440a09d','text','{"text": "The crisis was over."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f9ac8212a37a','ch_e3fab440a09d','text','{"text": "''You''ve got half an hour to smarten yourself up, Evans — and take that bloody hat off!'' ''Me''at?"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da38eb728dec','ch_e3fab440a09d','text','{"text": "Huh!'' Evans put his right hand lovingly on top of the filthy woollen, and smiled sadly."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a7aad1b570b','ch_e3fab440a09d','text','{"text": "''D''you know, Mr Jackson, it''s the only thing that''s ever brought me any sort o'' luck in life. Kind o'' lucky charm, if you know what I mean."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40181e6fa691','ch_e3fab440a09d','text','{"text": "And today I thought — well, with me exam and all that. . .'' Buried somewhere in Jackson, was a tiny core of compassion;"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58171aca0a86','ch_e3fab440a09d','text','{"text": "and Evans knew it."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_84e727811962','ch_e3fab440a09d','text','{"text": "''Just this once, then, Shirley Temple.'' (If there was one thing that Jackson genuinely loathed about Evans it was his long, wavy hair."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e888abc3c646','ch_e3fab440a09d','text','{"text": ") ''And get shaving!'' At 8. 45 the same morning the Reverend Stuart McLeery left his bachelor flat in Broad Street and stepped out briskly towards Carfax. The weatherman reported temperatures considerably below the normal for early June, and a long black overcoat and a shallow-crowned clerical hat provided welcome protection from the steady drizzle which had set in half an hour earlier and which now spattered the thick lenses of his spectacles. In his right hand he was carrying a small brown"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_34ec4b1824f9','ch_e3fab440a09d','text','{"text": "suitcase, which contained all that he would need for his morning duties, including a sealed question paper envelope, a yellow invigilation form, a special''authentication'' card from the Examinations Board, a paper knife, a Bible (he was to speak to the Women''s Guild that afternoon on the Book of Ruth), and a current copy of The Church Times. The two-hour examination was scheduled to start at 9.15 a.m. Evans was lathering his face vigorously when Stephens brought in two small square tables, and"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ae57754ce6a','ch_e3fab440a09d','text','{"text": "set them opposite each other in the narrow space between the bunk on the one side and on the other a distempered stone wall. Next, Stephens brought in two hard chairs, the slightly less battered of which he placed in front of the table which stood nearer the cell door. Jackson put in a brief final appearance. ''Behave yourself, laddy!'' Evans turned and nodded."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_65f028b957aa','ch_e3fab440a09d','text','{"text": "''And these'' — (Jackson pointed to the pin-ups) — ''off!'' Evans turned and nodded again."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0bc77be1ee28','ch_e3fab440a09d','text','{"text": "''I was goin'' to take''em down anyway. A minister, isn''t''e? The chap comin'' to sit in, I mean.'' ''And how did you know that?'' asked Jackson quietly."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da2c9c60d13d','ch_e3fab440a09d','text','{"text": "''Well, I''ad to sign some forms, didn''t I? And I couldn''t''elp — '' Evans drew the razor carefully down his left cheek, and left a neat swath in the white lather."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f396a60e1243','ch_e3fab440a09d','text','{"text": "''Can I ask you something, Mr. Jackson? Why did they''ave to bug me in this cell?'' He nodded his head vaguely to a point above the door."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e952cc1f967','ch_e3fab440a09d','text','{"text": "''Not a very neat job,'' conceded Jackson."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25677f0bfb75','ch_e3fab440a09d','text','{"text": "''They''re not — they don''t honestly think I''m goin'' to try to — '' ''They''re taking no chances, Evans."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2a103c02a500','ch_e3fab440a09d','text','{"text": "Nobody in his senses would take any chance with you.'' ''Who''s goin'' to listen in?'' ''I''ll tell you who''s going to listen in, laddy. It''s the Governor himself, see? He don''t trust you a bloody inch — and nor do I. I''ll be watching you like a hawk, Evans, so keep your nose clean. Clear?'' He walked towards the door. Evans nodded. He''d already thought of that, and Number Two Handkerchief was lying ready on the bunk — a neatly folded square of off-white linen. ''Just one more thing, Einstein.'' ''Ya?"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c5cd3d1704e','ch_e3fab440a09d','text','{"text": "Wha''s''at?'' ''Good luck, old son.'' In the little lodge just inside the prison''s main gates, the Reverend S. McLeery signed his name neatly in the visitors'' book, and thence walked side by side with a silent prison officer across the exercise yard to D Wing, where he was greeted by Jackson. The Wing''s heavy outer door was unlocked, and locked behind them, the heavy inner door the same, and McLeery was handed into Stephens''s keeping."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2454fd608e28','ch_e3fab440a09d','text','{"text": "''Get the razor?'' murmured Jackson."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99db9583dba8','ch_e3fab440a09d','text','{"text": "Stephens nodded."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c1b6d42c770','ch_e3fab440a09d','text','{"text": "''Well, keep your eyes skinned. Clear?'' Stephens nodded again;"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_831b60672f40','ch_e3fab440a09d','text','{"text": "and McLeery, his feet clanging up the iron stairs, followed his new guide, and finally stood before a cell door, where Stephens opened the peep-hole and looked through."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b48e4e588aba','ch_e3fab440a09d','text','{"text": "''That''s him, sir.'' Evans, facing the door, sat quietly at the farther of the two tables, his whole attention riveted to a textbook of elementary German grammar."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5c11c28d065','ch_e3fab440a09d','text','{"text": "Stephens took the key from its ring, and the cell lock sprang back with a thudded, metallic twang. It was 9. 10 a. m. when the Governor switched on the receiver. He had instructed Jackson to tell Evans of the temporary little precaution — that was only fair. (As if Evans wouldn''t spot it!) But wasn''t it all a bit theatrical? Schoolboyish, almost? How on earth was Evans going to try anything on today? If he was so anxious to make another break, why in heaven''s name hadn''t he tried it from the"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4376e5ed7f91','ch_e3fab440a09d','text','{"text": "Recreational Block? Much easier. But he hadn''t. And there he was now — sitting in a locked cell, all the prison officers on the alert, two more locked doors between his cell and the yard, and a yard with a wall as high as a haystack. Yes, Evans was as safe as houses... Anyway, it wouldn''t be any trouble at all to have the receiver turned on for the next couple of hours or so. It wasn''t as if there was going to be anything to listen to, was it? Amongst other things, an invigilator''s duty was to"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f2369fb109be','ch_e3fab440a09d','text','{"text": "ensure that the strictest silence was observed. But. . . but still that little nagging doubt! Might Evans try to take advantage of McLeery? Get him to smuggle in a chisel or two, or a rope ladder, or — The Governor sat up sharply. It was all very well getting rid of any potential weapon that Evans could have used;"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53d292c2dd4c','ch_e3fab440a09d','text','{"text": "but what about McLeery? What if, quite unwittingly, the innocent McLeery had brought in something himself? A jack-knife, perhaps? And what if Evans held him hostage with such a weapon?"}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef41c48f1637','ch_e3fab440a09d','text','{"text": "The Governor reached for the phone. It was 9. 12 a. m. The examinee and the invigilator had already been introduced by Stephens when Jackson came back and shouted to McLeery through the cell door."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ece3aa543b84','ch_e3fab440a09d','text','{"text": "''Can you come outside a minute, sir? You too, Stephens.'' Jackson quickly explained the Governor''s worries, and McLeery patiently held out his arms at shoulder level whilst Jackson lightly frisked his clothes. ''Something hard here, sir.'' ''Ma reading glasses,'' replied McLeery, looking down at the spectacle case."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3b8ceaff10f','ch_e3fab440a09d','text','{"text": "Jackson quickly reassured him, and bending down on the landing thumb-flicked the catches on the suitcase. He picked up each envelope in turn, carefully passed his palms along their surfaces — and seemed satisfied. He riffled cursorily through a few pages of Holy Writ, and vaguely shook The Church Times. All right, so far. But one of the objects in McLeery''s suitcase was puzzling him sorely. ''Do you mind telling me why you''ve brought this, sir?'' He held up a smallish semi-inflated rubber ring,"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46c9a49f8033','ch_e3fab440a09d','text','{"text": "such as a young child with a waist of about twelve inches might have struggled into."}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7cdeb05df8fb','ch_e3fab440a09d','text','{"text": "''You thinking of going for a swim, sir?'' McLeery''s hitherto amiable demeanour was slightly ruffled by this tasteless little pleasantry, and he answered Jackson somewhat sourly. ''If ye must know, I suffer from haemorrhoids, and when I''m sitting down for any length o'' time —'' ''Very sorry, sir."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9ccd4ed2417f','ch_e3fab440a09d','text','{"text": "I didn''t mean to, er...'' The embarrassment was still reddening Jackson''s cheeks when he found the paper-knife at the bottom of the case. ''I think I''d better keep this though, if you don''t mind, that is, sir.'' It was 9. 18 a. m. before the Governor heard their voices again, and it was clear that the examination was going to be more than a little late in getting under way."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f187b919580d','ch_e3fab440a09d','text','{"text": "MCLEERY: ''Ye''ve got a watch?''"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f017b2e9c7d','ch_e3fab440a09d','text','{"text": "EVANS: ''Yes, sir.''"}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_645aebd5b6eb','ch_e3fab440a09d','text','{"text": "MCLEERY: ''I''ll be telling ye when to start, and again when ye''ve five minutes"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99b9b7e574d8','ch_e3fab440a09d','text','{"text": "left. A'' right?'' Silence."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc9b6067f9e4','ch_e3fab440a09d','text','{"text": "MCLEERY: ''There''s plenty more o'' this writing paper should ye need it.'' Silence."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_940ead20867d','ch_e3fab440a09d','text','{"text": "MCLEERY: ''Now. Write the name of the paper, 021-1, in the top left-hand corner.'' Silence."}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6368b2bcfc68','ch_e3fab440a09d','text','{"text": "MCLEERY: ''In the top right-hand corner write your index number-313. And in the box just below that, write your centre number-271. A'' right?'' Silence. 9. 20 a. m."}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_57e0463a60bf','ch_e3fab440a09d','text','{"text": "MCLEERY: ''I''m now going to — ''"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c2a10f2d5e4d','ch_e3fab440a09d','text','{"text": "EVANS: ''E''s not goin'' to stay''ere, is''e?''"}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cfe24f895719','ch_e3fab440a09d','text','{"text": "MCLEERY: ''I don''t know about that. I — '' STEPHENS: ''Mr Jackson''s"}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92101d56926a','ch_e3fab440a09d','text','{"text": "given me strict instructions to — ''"}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b70f2e8d13c4','ch_e3fab440a09d','text','{"text": "EVANS: ''How am I suppose to concentrate on my exam... with someone breathin'' down my neck? Christ! Sorry, sir, I didn''t mean — '' The Governor reached for the phone."}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1847e5c67c26','ch_e3fab440a09d','text','{"text": "''Jackson? Ah, good. Get Stephens out of that cell, will you? I think we''re perhaps overdoing things.'' ''As you wish, sir.'' The Governor heard the exchanges in the cell, heard the door clang once more, and heard McLeery announce that the examination had begun at last."}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_266b2927355f','ch_e3fab440a09d','text','{"text": "It was 9. 25 a. m. ;"}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f5f702e03bfe','ch_e3fab440a09d','text','{"text": "and there was a great calm. At 9. 40 a. m. the Examinations Board rang through, and the Assistant Secretary with special responsibility for modern languages asked to speak to the Governor. The examination had already started, no doubt? Ah, a quarter of an hour ago. Yes. Well, there was a correction slip which some fool had forgotten to place in the examination package. Very brief."}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca4951f4b3a4','ch_e3fab440a09d','text','{"text": "''Could the Governor please...? ''Yes, of course."}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f51f490a188','ch_e3fab440a09d','text','{"text": "I''ll put you straight through to Mr Jackson in D Wing. Hold the line a minute.'' Was this the sort of thing the Governor had feared? Was the phone call a fake? Some signal? Some secret message. . . ? But he could check on that immediately. He dialled the number of the Examinations Board, but heard only the staccato bleeps of a line engaged. But then the line was engaged, wasn''t it? Yes. Not very intelligent, that... Two minutes later he heard some whispered communications in the cell, and then"}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1883dc7e5189','ch_e3fab440a09d','text','{"text": "McLeery''s broad Scots voice: ''Will ye please stop writing a wee while, Mr Evans, and listen carefully. Candidates offering German, 021-1, should note the following correction. ''On page three, line fifteen, the fourth word should read goldenen, not, goldene;"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bf8b6f5a7b95','ch_e3fab440a09d','text','{"text": "and the whole phrase will therefore read zum goldenen Lowen, not zum goldene Lowen.'' I will repeat that. . .'' The Governor listened and smiled. He had taken German in the sixth form himself, and he remembered all about the agreements of"}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67b41fa5b9e5','ch_e3fab440a09d','text','{"text": "adjectives. And so did McLeery, by the sound of things, for the minister''s pronunciation was most impressive. But what about Evans? He probably didn''t know what an adjective was. The phone rang again. The Magistrates'' Court. They needed a prison van and a couple of prison officers. Remand case. And within two minutes the Governor was wondering whether that could be a hoax. He told himself not to be so silly. His imagination was beginning to run riot. Evans! For the first quarter of an hour"}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e16819c73386','ch_e3fab440a09d','text','{"text": "Stephens had dutifully peered through the peep-hole at intervals of one minute or so;"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_116024d2f195','ch_e3fab440a09d','text','{"text": "and after that, every two minutes. At 10.45 a.m. everything was still all right as he looked through the peephole once more. It took four or five seconds — no more. What was the point? It was always more or less the same. Evans, his pen between his lips, sat staring straight in front of him towards the door, seeking — it seemed — some sorely needed inspiration from somewhere. And opposite him McLeery, seated"}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a83863e689cb','ch_e3fab440a09d','text','{"text": "slightly askew from the table now: his face in semi-profile;"}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_516188036a44','ch_e3fab440a09d','text','{"text": "his hair (as Stephens had noticed earlier) amateurishly clipped pretty closely to the scalp;"}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b520a4f8e73d','ch_e3fab440a09d','text','{"text": "his eyes behind the pebble lenses peering short-sightedly at The Church Times;"}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_240a1aaf502d','ch_e3fab440a09d','text','{"text": "his right index finger hooked beneath the narrow clerical collar;"}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d1a73391e28','ch_e3fab440a09d','text','{"text": "and the fingers of the left hand, the nails meticulously manicured, slowly stroking the short black beard. At 10.50 a.m. the receiver crackled to life and the Governor realised he''d almost forgotten"}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_06622e39b277','ch_e3fab440a09d','text','{"text": "Evans for a few minutes."}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dfd1837935d3','ch_e3fab440a09d','text','{"text": "EVANS: ''Please, sir!'' (A whisper)"}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd0e477fff92','ch_e3fab440a09d','text','{"text": "EVANS: ''Please, sir!'' (Louder)"}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_29b2f7b00ed7','ch_e3fab440a09d','text','{"text": "EVANS: ''Would you mind if I put a blanket round me shoulders, sir? It''s a bit parky in''ere, isn''t it?'' Silence."}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa38e16782ab','ch_e3fab440a09d','text','{"text": "EVANS: ''There''s one on me bunk''ere, sir.''"}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c87ad7a1b1b1','ch_e3fab440a09d','text','{"text": "MCLEERY: ''Be quick about it.'' Silence. At 10. 51 a. m. Stephens was more than a little surprised to see a grey regulation blanket draped round Evans''s shoulders, and he frowned slightly and looked at the examinee more closely. But Evans, the pen still"}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_667f58f8614f','ch_e3fab440a09d','text','{"text": "between his teeth, was staring just as vacantly as before. Blankly beneath a blanket... Should Stephens report the slight irregularity? Anything at all fishy, hadn''t Jackson said? He looked through the peep-hole once again, and even as he did so Evans pulled the dirty blanket more closely to himself. Was he planning a sudden batman leap to suffocate McLeery in the blanket? Don''t be daft! There was never any sun on this side of the prison;"}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f085f658c282','ch_e3fab440a09d','text','{"text": "no heating, either, during the summer months, and it"}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b7f34a3f5feb','ch_e3fab440a09d','text','{"text": "could get quite chilly in some of the cells. Stephens decided to revert to his earlier every minute observation. At 11.20 a.m. the receiver once more crackled across the silence of the Governor''s office, and McLeery informed Evans that only five minutes remained. The examination was almost over now, but something still gnawed away quietly in the Governor''s mind. He reached for the phone once more. At 11.22 a.m. Jackson shouted along the corridor to Stephens. The Governor wanted to speak with him."}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4599d3f4385b','ch_e3fab440a09d','text','{"text": "''Hurry, man!'' Stephens picked up the phone apprehensively and listened to the rapidly spoken orders. Stephens himself was to accompany McLeery to the main prison gates. Understood? Stephens personally was to make absolutely sure that the door was locked on Evans after McLeery had left the cell. Understood? Understood. At 11. 25 a. m. the Governor heard the final exchanges."}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_708367e8371b','ch_e3fab440a09d','text','{"text": "MCLEERY: ''Stop writing, please.'' Silence."}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3562c9ec153f','ch_e3fab440a09d','text','{"text": "MCLEERY: ''Put your sheets in order and see they''re correctly numbered.'' Silence."}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b37be270e476','ch_e3fab440a09d','text','{"text": "Scraping of chairs and tables."}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_55640baa5ea9','ch_e3fab440a09d','text','{"text": "EVANS: ''Thank you very much, sir.''"}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_88f492a03aec','ch_e3fab440a09d','text','{"text": "MCLEERY: ''A'' right, was it?''"}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82b08ab5469c','ch_e3fab440a09d','text','{"text": "EVANS: ''Not too bad.''"}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_69096bf2fab2','ch_e3fab440a09d','text','{"text": "MCLEERY: ''Good... Mr Stephens!'' (Very loud) The Governor heard the door clang for the last time. The examination was over."}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fdb56681de81','ch_e3fab440a09d','text','{"text": "''How did he get on, do you think?'' asked Stephens as he walked beside McLeery to the main gates."}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_38d4eb170215','ch_e3fab440a09d','text','{"text": "''Och. I canna think he''s distinguished himself, I''m afraid.'' His Scots accent seemed broader than ever, and his long black overcoat, reaching almost to his knees, fostered the illusion that he had suddenly grown slimmer."}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_582f5baab1c9','ch_e3fab440a09d','text','{"text": "Stephens felt pleased that the Governor had asked him, and not Jackson, to see McLeery off the premises, and all in all the morning had gone pretty well. But something stopped him from making his way directly to the canteen for a belated cup of coffee. He wanted to take just one last look at Evans. It was like a programme he''d seen on TV — about a woman who could never really convince herself that she''d locked the front door when she''d gone to bed: often she''d got up twelve, fifteen, sometimes"}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e53175a8480','ch_e3fab440a09d','text','{"text": "twenty times to check the bolts. He re-entered D Wing, made his way along to Evans''s cell, and opened the peep-hole once more. Oh, no! CHRIST, NO! There, sprawled back in Evans''s chair was a man (for a semi second Stephens thought it must be Evans), a grey regulation blanket slipping from his shoulders, the front of his closely cropped, irregularly tufted hair awash with fierce red blood which had dripped already through the small black beard, and was even now spreading horribly over the white"}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e2c8dae9496','ch_e3fab440a09d','text','{"text": "clerical collar and down into the black clerical front. Stephens shouted wildly for Jackson: and the words appeared to penetrate the curtain of blood that veiled McLeery''s ears, for the minister''s hand felt feebly for a handkerchief from his pocket, and held it to his bleeding head, the blood seeping slowly through the white linen. He gave a long low moan, and tried to speak. But his voice trailed away, and by the time Jackson had arrived and despatched Stephens to ring the police and the"}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_323b3396ccce','ch_e3fab440a09d','text','{"text": "ambulance, the handkerchief was a sticky, squelchy wodge of cloth. McLeery slowly raised himself, his face twisted tightly with pain."}',116);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24b4794e1ad1','ch_e3fab440a09d','text','{"text": "''Dinna worry about the ambulance, man! I''m a'' right... I''m a'' right... Get the police! I know...I know where... he...'' He closed his eyes and another drip of blood splashed like a huge red raindrop on the wooden floor."}',117);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9eed187f9acd','ch_e3fab440a09d','text','{"text": "His hand felt along the table, found the German question paper, and grasped it tightly in his bloodstained hand."}',118);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1f3506bb58b','ch_e3fab440a09d','text','{"text": "''Get the Governor! I know... I know where Evans...'' Almost immediately sirens were sounding, prison officers barked orders, puzzled prisoners pushed their way along the corridors, doors were banged and bolted, and phones were ringing everywhere."}',119);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9096b5819543','ch_e3fab440a09d','text','{"text": "And within a minute McLeery, with Jackson and Stephens supporting him on either side, his face now streaked and caked with drying blood, was greeted in the prison yard by the Governor, perplexed and grim."}',120);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f78d82389b28','ch_e3fab440a09d','text','{"text": "''We must get you to hospital immediately. I just don''t — '' ''Ye''ve called the police?'' ''Yes, yes. They''re on their way."}',121);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3fd567b9772e','ch_e3fab440a09d','text','{"text": "But — '' ''I''m a'' right. I''m a'' right. Look! Look here!'' Awkwardly he opened the German question paper and thrust it before the Governor''s face. ''It''s there! D''ye see what I mean?'' The Governor looked down and realised what McLeery was trying to tell him. A photocopied sheet had been carefully and cleverly superimposed over the last (originally blank) page of the question paper."}',122);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba0df0bc9b04','ch_e3fab440a09d','text','{"text": "''Ye see what they''ve done, Governor."}',123);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b6ad175e854c','ch_e3fab440a09d','text','{"text": "Ye see. . .'' His voice trailed off again, as the Governor, dredging the layers of long neglected learning, willed himself to translate the German text before him: Sie sollen dem schon verabredeten Plan genau folgen. Der wichtige Zeitpunkt ist drei Minuten vor Ende des Examens. . ."}',124);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c29a257418d','ch_e3fab440a09d','text','{"text": "''You must follow the plan already somethinged. The vital point in time is three minutes before the end of the examination but something something — something something... Don''t hit him too hard — remember, he''s a minister! And don''t overdo the Scots accent when."}',125);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b9f5e621a993','ch_e3fab440a09d','text','{"text": ". .'' A fast-approaching siren wailed to its crescendo, the great doors of the prison yard were pushed back, and a white police car squealed to a jerky halt beside them. Detective Superintendent Carter swung himself out of the passenger seat and saluted the Governor."}',126);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04c8fd598891','ch_e3fab440a09d','text','{"text": "''What the hell''s happening, sir?'' And, turning to"}',127);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9985356392c2','ch_e3fab440a09d','text','{"text": "MCLEERY: ''Christ! Who''s hit him?'' But McLeery cut across whatever explanation the Governor might have given."}',128);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e9be3b4e1b78','ch_e3fab440a09d','text','{"text": "''Elsfield Way, officer! I know where Evans...'' He was breathing heavily, and leaned for support against the side of the car, where the imprint of his hand was left in tarnished crimson."}',129);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3fa18a4aa3f2','ch_e3fab440a09d','text','{"text": "In bewilderment Carter looked to the Governor for guidance."}',130);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c9a20716cc7','ch_e3fab440a09d','text','{"text": "''What — ?'' ''Take him with you, if you think he''ll be all right."}',131);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a569b9562bca','ch_e3fab440a09d','text','{"text": "He''s the only one who seems to know what''s happening.'' Carter opened the back door and helped McLeery inside;"}',132);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dde942c84665','ch_e3fab440a09d','text','{"text": "and within a few seconds the car leaped away in a spurt of gravel."}',133);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da2ec5aaeb37','ch_e3fab440a09d','text','{"text": "''Elsfield Way'', McLeery had said;"}',134);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2665f6aacd9d','ch_e3fab440a09d','text','{"text": "and there it was staring up at the Governor from the last few lines of the German text: ''From Elsfield Way drive to the Headington roundabout, where...'' Yes, of course."}',135);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a43579a737a8','ch_e3fab440a09d','text','{"text": "The Examinations Board was in Elsfield Way, and someone from the Board must have been involved in the escape plan from the very beginning: the question paper itself, the correction slip. . . The Governor turned to Jackson and Stephens."}',136);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9890da1290cd','ch_e3fab440a09d','text','{"text": "''I don''t need to tell you what''s happened, do I?'' His voice sounded almost calm in its scathing contempt."}',137);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_756bb452beb6','ch_e3fab440a09d','text','{"text": "''And which one of you two morons was it who took Evans for a nice little walk to the main gates and waved him bye-bye?'' ''It was me, sir,'' stammered Stephens."}',138);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_beabe678c1b5','ch_e3fab440a09d','text','{"text": "''Just like you told me, sir. I could have sworn — '' ''What? Just like I told you, you say? What the hell — ?'' ''When you rang, sir, and told me to — '' ''When was that?'' The Governor''s voice was a whiplash now. ''You know, sir."}',139);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bae0245cb509','ch_e3fab440a09d','text','{"text": "About twenty past eleven just before — '' ''You blithering idiot, man! It wasn''t me who rang you. Don''t you realise — '' But what was the use? He had used the telephone at that time, but only to try (unsuccessfully, once more) to get through to the Examinations Board. He shook his head in growing despair and turned on the senior prison officer. ''As for you, Jackson! How long have you been pretending you''ve got a brain, eh? Well, I''ll tell you something, Jackson. Your skull''s empty. Absolutely"}',140);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f89f9b7857a3','ch_e3fab440a09d','text','{"text": "empty!'' It was Jackson who had spent two hours in Evans''s cell the previous evening;"}',141);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_95cc16797433','ch_e3fab440a09d','text','{"text": "and it was Jackson who had confidently reported that there was nothing hidden away there — nothing at all. And yet Evans had somehow managed to conceal not only a false beard, a pair of spectacles, a dogcollar and all the rest of his clerical paraphernalia, but also some sort of weapon with which he''d given McLeery such a terrible blow across the head. Aurrgh! A prison van backed alongside, but the Governor made"}',142);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c70d7c89fef7','ch_e3fab440a09d','text','{"text": "no immediate move. He looked down again at the last line of the German: ''...to the Headington roundabout, where you go straight over and make your way to...to Neugraben.'' ''Neugraben''? Where on earth —?"}',143);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b9b69637eaf','ch_e3fab440a09d','text','{"text": "''New'' something."}',144);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_10fa18cf8c4d','ch_e3fab440a09d','text','{"text": "''Newgrave''?"}',145);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec2bbbabc9f9','ch_e3fab440a09d','text','{"text": "Never heard of it: There was a''Wargrave'', somewhere near Reading, but. . . No, it was probably a code word, or — And then it hit him. Newbury! God, yes! Newbury was a pretty big sort of place but — He rapped out his orders to the driver."}',146);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1a577677aea','ch_e3fab440a09d','text','{"text": "''St Aldates Police Station, and step on it! Take Jackson and Stephens here, and when you get there ask for Bell. Chief Inspector Bell. Got that?'' He leaped the stairs to his office three at a time, got Bell on the phone immediately, and put the facts before him."}',147);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c394e82d1a55','ch_e3fab440a09d','text','{"text": "''We''ll get him, sir,'' said Bell. ''We''ll get him, with a bit o''luck.'' The Governor sat back, and lit a cigarette."}',148);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44d834a09daf','ch_e3fab440a09d','text','{"text": "Ye gods! What a beautifully laid plan it had all been! What a clever fellow Evans was! Careless leaving that question paper behind;"}',149);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_87697fa68f07','ch_e3fab440a09d','text','{"text": "but then, they all made their mistakes somewhere along the line. Well, almost all of them. And that''s why very very shortly Mr clever-clever Evans would be back inside doing his once more. The phone on his desk erupted in a strident burst, and Superintendent Carter informed him that McLeery had spotted Evans driving off along Elsfield Way;"}',150);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_edd8d963b423','ch_e3fab440a09d','text','{"text": "they''d got the number of"}',151);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c454b2c7baec','ch_e3fab440a09d','text','{"text": "the car all right and had given chase immediately, but had lost him at the Headington roundabout;"}',152);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1668ab702ab0','ch_e3fab440a09d','text','{"text": "he must have doubled back into the city."}',153);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_308816fd57de','ch_e3fab440a09d','text','{"text": "''No,'' said the Governor quietly."}',154);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8bc55ef7e088','ch_e3fab440a09d','text','{"text": "''No, he''s on his way to Newbury.'' He explained his reasons for believing so, and left it at that."}',155);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1c952a23a3d','ch_e3fab440a09d','text','{"text": "It was a police job now — not his. He was just another good-for-a-giggle, gullible governor, that was all."}',156);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_216b4ecad150','ch_e3fab440a09d','text','{"text": "''By the way, Carter. I hope you managed to get McLeery to the hospital all right?'' ''Yes. He''s in the Radcliffe now."}',157);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c42fa0c6f8f5','ch_e3fab440a09d','text','{"text": "Really groggy, he was, when we got to the Examination offices, and they rang for the ambulance from there.'' The Governor rang the Radcliffe a few minutes later and asked for the accident department."}',158);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e403af416969','ch_e3fab440a09d','text','{"text": "''McLeery, you say?'' ''Yes. He''s a parson.'' ''I don''t think there''s anyone — '' ''Yes, there is. You''ll find one of your ambulances picked him up from Elsfield Way about — '' ''Oh, that."}',159);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e746904157e1','ch_e3fab440a09d','text','{"text": "Yes, we sent an ambulance all right, but when we got there, the fellow had gone. No one seemed to know where he was. Just vanished! Not a sign — '' But the Governor was no longer listening, and the truth seemed to hit him with an almost physical impact somewhere in the back of his neck. A quarter of an hour later they found the Reverend S. McLeery, securely bound and gagged, in his study in Broad Street. He''d been there, he said, since 8. 15 a. m. , when two men had called and. . . Enquiries in"}',160);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_893d66fc84a0','ch_e3fab440a09d','text','{"text": "Newbury throughout the afternoon produced nothing. Nothing at all. And by tea-time everyone in the prison knew what had happened. It had not been Evans, impersonating McLeery, who had walked out;"}',161);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_455d278e9255','ch_e3fab440a09d','text','{"text": "it had been Evans, impersonating McLeery, who had stayed in. The fish and chips were delicious, and after a gentle stroll round the centre of Chipping Norton, Evans decided to return to the hotel and have an early night. A smart new hat concealed the wreckage of his closely cropped hair, and he kept it"}',162);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c2a7a89b5682','ch_e3fab440a09d','text','{"text": "on as he walked up to the reception desk of the Golden Lion. It would take a good while for his hair to regain its former glories — but what the hell did that matter. He was out again, wasn''t he? A bit of bad luck, that, when Jackson had pinched his scissors, for it had meant a long and tricky operation with his only razor blade the previous night. Ah! But he''d had his good luck, too. Just think! If Jackson had made him take his bobble hat off! Phew! That really had been a close call. Still, old"}',163);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d05bcbd5bfc','ch_e3fab440a09d','text','{"text": "Jackson wasn''t such a bad fellow... One of the worst things — funny, really! — had been the beard. He''d always been allergic to sticking plaster, and even now his chin was irritatingly sore and red. The receptionist wasn''t the same girl who''d booked him in, but the change was definitely for the better. As he collected his key, he gave her his best smile, told her he wouldn''t be bothering with breakfast, ordered the Daily Express, and asked for an early-morning call at 6.45 a.m. Tomorrow was"}',164);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2673b881cca5','ch_e3fab440a09d','text','{"text": "going to be another busy day. He whistled softly to himself as he walked up the broad stairs... He''d sort of liked the idea of being dressed up as a minister dog collar and everything. Yes, it had been a jolly good idea for''McLeery'' to wear two black fronts, two collars. But that top collar! Phew! It had kept on slipping off the back stud;"}',165);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f4f14a24b2a8','ch_e3fab440a09d','text','{"text": "and there''d been that one panicky moment when''McLeery'' had only just got his hand up to his neck in time to stop the collars springing apart before"}',166);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d74d97aa742','ch_e3fab440a09d','text','{"text": "Stephens... Ah! They''d got that little problem worked out all right, though: a pen stuck in the mouth whenever the evil eye had appeared at the peep-hole. Easy! But all that fiddling about under the blanket with the black front and the stud at the back of the collar — that had been far more difficult than they''d ever bargained for... Everything else had gone beautifully smoothly, though. In the car he''d found everything they''d promised him: soap and water, clothes, the map — yes, the map, of"}',167);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_08a2f914dd68','ch_e3fab440a09d','text','{"text": "course. The Ordnance Survey Map of Oxfordshire... He''d got some good friends;"}',168);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80cef966dfce','ch_e3fab440a09d','text','{"text": "some very clever friends. Christ, ah! He unlocked his bedroom door and closed it quietly behind him — and then stood frozen to the spot, like a man who has just caught a glimpse of the Gorgon. Sitting on the narrow bed was the very last man in the world that Evans had expected — or wanted — to see."}',169);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_84f87f51986f','ch_e3fab440a09d','text','{"text": "''It''s not worth trying anything,'' said the Governor quietly, as Evans''s eyes darted desperately around the room."}',170);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_063ea3518947','ch_e3fab440a09d','text','{"text": "''I''ve got men all round the place.'' (Well, there were only two, really: but Evans needn''t know that.) He let the words sink in. ''Women, too."}',171);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff87421d3d36','ch_e3fab440a09d','text','{"text": "Didn''t you think the blonde girl in reception was rather sweet?'' Evans was visibly shaken. He sat down slowly in the only chair the small room could offer, and held his head between his hands. For several minutes there was utter silence. Finally, he spoke."}',172);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_969c590bcab3','ch_e3fab440a09d','text','{"text": "''It was that bloody correction slip, I s''pose.'' ''We-ell'' (the Governor failed to mask the deep satisfaction in his voice) ''there are a few people who know a little German.'' Slowly, very slowly, Evans relaxed."}',173);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec1448fa06c4','ch_e3fab440a09d','text','{"text": "He was beaten — and he knew it. He sat up at last, and managed to smile ruefully."}',174);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e9fcb9e48f5','ch_e3fab440a09d','text','{"text": "''You know, it wasn''t really a mistake."}',175);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e7c8a856364','ch_e3fab440a09d','text','{"text": "You see, we''adn''t been able to fix up any''otel, but we could''ve worked that some other way. No. The really important thing was for the phone to ring just before the exam finished — to get everyone out of the way for a couple of minutes. So we''ad to know exactly when the exam started, didn''t we?'' ''And, like a fool, I presented you with that little piece of information on a plate.'' ''Well, somebody did. So, you see, sir, that correction slip killed two little birds with a single stone, didn''t it?"}',176);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1a795694b291','ch_e3fab440a09d','text','{"text": "The name of the''otel for me, and the exact time the exam started for, er, for, er...'' The Governor nodded."}',177);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2114d56d222d','ch_e3fab440a09d','text','{"text": "''It''s a pretty common word.'' ''Good job it is pretty common, sir, or I''d never''ave known where to come to, would I?'' ''Nice name, though: zum goldenen Lowen.'' ''How did you know which Golden Lion it was? There''s''undreds of''em.'' ''Same as you, Evans. Index number 313;"}',178);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3955753854f5','ch_e3fab440a09d','text','{"text": "Centre number 271. Remember? Six figures? And if you take an Ordnance Survey Map for Oxfordshire, you find that the six-figure reference 313/271 lands you bang in the middle of Chipping Norton.'' ''Yea, you''re right."}',179);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a860d35f295d','ch_e3fab440a09d','text','{"text": "Huh! We''d''oped you''d run off to Newbury.'' ''We did.'' ''Well, that''s something, I s''pose.'' ''That question paper, Evans. Could you really understand all that German? I could hardly — '' ''Nah! Course I couldn''t. I knew roughly what it was all about, but we just''oped it''d throw a few spanners in the works — you know, sort of muddle everybody a bit.'' The Governor stood up."}',180);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff12f862cd09','ch_e3fab440a09d','text','{"text": "''Tell me one thing before we go. How on earth did you get all that blood to pour over your head?'' Evans suddenly looked a little happier."}',181);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d408681cfc7','ch_e3fab440a09d','text','{"text": "''Clever, sir. Very clever, that was — ''ow to get a couple o'' pints of blood into a cell, eh? When there''s none there to start off with, and when, er, and when the''invigilator'', shall we say, gets, searched before''e comes in. Yes, sir. You can well ask about that, and I dunno if I ought to tell you. After all, I might want to use that particular — '' ''Anything to do with a little rubber ring for piles, perhaps?'' Evans grinned feebly."}',182);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f74f67aa03e2','ch_e3fab440a09d','text','{"text": "''Clever, though, wasn''t it?'' ''Must have been a tricky job sticking a couple of pints''Nah!"}',183);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_437c7a32c1fe','ch_e3fab440a09d','text','{"text": "You''ve got it wrong, sir. No problem about that.'' ''No?'' ''Nah! It''s the clotting, you see. That''s the big trouble. We got the blood easy enough. Pig''s blood, it was — from the slaughter''ouse in Kidlington. But to stop it clotting you''ve got to mix yer actual blood'' (Evans took a breath) ''with one tenth of its own volume of 3. 8 per cent trisodium citrate! Didn''t know that, did you, sir?'' The Governor shook his head in a token of reluctant admiration."}',184);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4489408eb45a','ch_e3fab440a09d','text','{"text": "''We learn something new every day, they tell me. Come on, m''lad.'' Evans made no show of resistance, and side by side the two men walked slowly down the stairs."}',185);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a8da22573d7','ch_e3fab440a09d','text','{"text": "''Tell me, Evans. How did you manage to plan all this business? You''ve had no visitors — I''ve seen to that. You''ve had no letters — '' ''I''ve got lots of friends, though.'' ''What''s that supposed to mean?'' ''Me German teacher, for a start.'' ''You mean —? But he was from the Technical College.'' ''Was''e?'' Evans was almost enjoying it all now."}',186);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9fe76cd9a2e5','ch_e3fab440a09d','text','{"text": "''Ever check up on''im, sir?'' ''God Almighty! There''s far more going on than I — '' ''Always will be, sir.'' ''Everything ready?'' asked the Governor as they stood by the reception desk."}',187);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2268b25c5563','ch_e3fab440a09d','text','{"text": "''The van''s out the front, sir,'' said the pretty blonde receptionist. Evans winked at her;"}',188);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e82651b98acf','ch_e3fab440a09d','text','{"text": "and she winked back at him. It almost made his day. A silent prison officer handcuffed the recaptured Evans, and together the two men clambered awkwardly into the back seat of the prison van. ''See you soon, Evans.'' It was almost as if the Governor were saying farewell to an old friend after a cocktail party."}',189);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_14010f028022','ch_e3fab440a09d','text','{"text": "''Cheerio, sir. I, er, I was just wonderin''."}',190);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_363d5c886dda','ch_e3fab440a09d','text','{"text": "I know your German''s pretty good, sir, but do you know any more o'' these modern languages?'' ''Not very well. Why?'' Evans settled himself comfortably on the back seat, and grinned happily."}',191);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99151890aad1','ch_e3fab440a09d','text','{"text": "''Nothin'', really."}',192);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43f987cdb9bc','ch_e3fab440a09d','text','{"text": "I just''appened to notice that you''ve got some O-level Italian classes comin'' up next September, that''s all.'' ''Perhaps you won''t be with us next September, Evans.'' James Roderick Evans appeared to ponder the Governor''s words deeply. ''No. P''r''aps I won''t,'' he said. As the prison van turned right from Chipping Norton on to the Oxford road, the hitherto silent prison officer unlocked the handcuffs and leaned forward towards the driver, ''For Christ''s sake get a move on! It won''t take''em long to find"}',193);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59d1e377e460','ch_e3fab440a09d','text','{"text": "out —'' ''Where do ye suggest we make for?'' asked the driver, in a broad Scots accent. ."}',194);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_95a12084274f','ch_e3fab440a09d','text','{"text": "''What about Newbury?'' suggested Evans."}',195);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04c2fe2213fc','ch_e3fab440a09d','list','{"ordered": false, "items": ["Colin Dexter"]}',196);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_9e1bb63677f3','bk_ncert_english','12-43-memories-of-childhood','12. 43 Memories of Childhood',NULL,'public',115,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_163c758ea242','ch_9e1bb63677f3','text','{"text": "Before you read"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_233b0fa0f2a8','ch_9e1bb63677f3','text','{"text": "This unit presents autobiographical episodes from the lives of two women from marginalised communities who look back on their childhood, and reflect on their relationship with the mainstream culture. The first account is by an American Indian woman born in the late nineteenth century; the second is by a contemporary Tamil Dalit writer. Gertrude Simmons Bonnin, born in 1876, was an extraordinarily talented and educated Native American woman who struggled and triumphed in a time when severe prejudice prevailed towards Native American culture and women. As a writer, she adopted the pen name''Zitkala-Sa'' and in 1900 began publ ishing articles criticising the Carlisle Indian school. Her works criticised dogma, and her life as a Native American woman was dedicated against the evils of oppression. Bama is the pen-name of a Tamil Dalit woman from a Roman Catholic family. She has published three main works: an autobiography, ''Karukku'', 1992; a novel, ''Sangati'', 1994; and a collection of short stories, ''Kisumbukkaaran'', 1996. The following excerpt has been taken from''Karukku''. ''Karukku'' means''Palmyra'' leaves, which with their serrated edges on both sides, are like double-edged swords."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_185c6c69a3ea','ch_9e1bb63677f3','text','{"text": "By a felicitous pun, the Tamil word''Karukku'', containing the word''karu'', embryo or seed, also means freshness, newness."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0a84e16b54b','ch_9e1bb63677f3','text','{"text": "The cutting of my long hair"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_12fb858f368b','ch_9e1bb63677f3','text','{"text": "The first day in the land of apples was a bitter-cold one;"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25d4d26e0084','ch_9e1bb63677f3','text','{"text": "for the snow still covered the ground, and the trees were bare. A large bell rang for breakfast, its loud metallic voice crashing through the belfry overhead and into our sensitive ears. The annoying clatter of shoes on bare floors gave us no peace. The"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3a84fe0d5aa','ch_9e1bb63677f3','text','{"text": "constant clash of harsh noises, with an undercurrent of many voices murmuring an unknown tongue, made a bedlam within which I was securely tied. And though my spirit tore itself in struggling for its lost freedom, all was useless. A paleface woman, with white hair, came up after us. We were placed in a line of girls who were marching into the dining room. These were Indian girls, in stiff shoes and closely clinging dresses. The small girls wore sleeved aprons and shingled hair. As I walked"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a2f4b9fffb1','ch_9e1bb63677f3','text','{"text": "noiselessly in my soft moccasins, I felt like sinking to the floor, for my blanket had been stripped from my shoulders. I looked hard at the Indian girls, who seemed not to care that they were even more immodestly dressed than I, in their tightly fitting clothes. While we marched in, the boys entered at an opposite door. I watched for the three young braves who came in our party. I spied them in the rear ranks, looking as uncomfortable as I felt. A small bell was tapped, and each of the pupils"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d6e65923940b','ch_9e1bb63677f3','text','{"text": "drew a chair from under the table. Supposing this act meant they were to be seated, I pulled out mine and at once slipped into it from one side. But when I turned my head, I saw that I was the only one seated, and all the rest at our table remained standing. Just as I began to rise, looking shyly around to see how chairs were to be used, a second bell was sounded. All were seated at last, and I had to crawl back into my chair again. I heard a man''s voice at one end of the hall, and I looked"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f02e9435915','ch_9e1bb63677f3','text','{"text": "around to see him. But all the others hung their heads over their plates. As I glanced at the long chain of tables, I caught the eyes of a paleface woman upon me. Immediately I dropped my eyes, wondering why I was so keenly watched by the strange woman. The man ceased his mutterings, and then a third bell was tapped. Every one picked up his knife and fork and began eating. I began crying instead, for by this time I was afraid to venture anything more. But this eating by formula was not the"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22148272c6d5','ch_9e1bb63677f3','text','{"text": "hardest trial in that first day. Late in the morning, my friend Judewin gave me a terrible warning. Judewin knew a few words of English;"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eae730e5a71f','ch_9e1bb63677f3','text','{"text": "and she had overheard the paleface woman talk about cutting our long, heavy hair. Our mothers had taught us that only unskilled warriors who were captured had their hair shingled by the enemy. Among our people, short hair was worn by mourners, and shingled hair by cowards! We discussed our fate some moments, and when Judewin said, ''We have to submit, because"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_835bf41692da','ch_9e1bb63677f3','text','{"text": "they are strong,'' I rebelled. ''No, I will not submit! I will struggle first!'' I answered. I watched my chance, and when no one noticed, I disappeared. I crept up the stairs as quietly as I could in my squeaking shoes, — my moccasins had been exchanged for shoes. Along the hall I passed, without knowing whither I was going. Turning aside to an open door, I found a large room with three white beds in it. The windows were covered with dark green curtains, which made the room very dim. Thankful that"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ad8201b453b','ch_9e1bb63677f3','text','{"text": "no one was there, I directed my steps toward the corner farthest from the door. On my hands and knees I crawled under the bed, and huddled myself in the dark corner. From my hiding place I peered out, shuddering with fear whenever I heard footsteps near by. Though in the hall loud voices were calling my name, and I knew that even Judewin was searching for me, I did not open my mouth to answer. Then the steps were quickened and the voices became excited. The sounds came nearer and nearer. Women"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9e3cd0b577c','ch_9e1bb63677f3','text','{"text": "and girls entered the room. I held my breath and watched them open closet doors and peep behind large trunks. Some one threw up the curtains, and the room was filled with sudden light. What caused them to stoop and look under the bed I do not know. I remember being dragged out, though I resisted by kicking and scratching wildly. Inspite of myself, I was carried downstairs and tied fast in a chair. I cried aloud, shaking my head all the while until I felt the cold blades of the scissors against"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f8468f38f67c','ch_9e1bb63677f3','text','{"text": "my neck, and heard them gnaw off one of my thick braids. Then I lost my spirit. Since the day I was taken from my mother I had suffered extreme indignities. People had stared at me. I had been tossed about in the air like a wooden puppet. And now my long hair was shingled like a coward''s! In my anguish I moaned for my mother, but no one came to comfort me. Not a soul reasoned quietly with me, as my own mother used to do;"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f2aaa4ea46fe','ch_9e1bb63677f3','text','{"text": "for now I was only one of many little animals driven by a herder."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d72f1f226a3','ch_9e1bb63677f3','text','{"text": "We Too are Human Beings"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c75f23cc098a','ch_9e1bb63677f3','text','{"text": "When I was studying in the third class, I hadn''t yet heard people speak openly of untouchability. But I had already seen, felt, experienced and been humiliated by what it is. I was walking home from school one day, an old bag hanging from my shoulder. It was actually possible to walk the distance in ten minutes. But usually it would take me thirty minutes at the very least to reach home. It would take me from half an hour to an hour"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a405ebf7300','ch_9e1bb63677f3','text','{"text": "to dawdle along, watching all the fun and games that were going on, all the entertaining novelties and oddities is the streets, the shops and the bazaar. The performing monkey;"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c0569a3a916','ch_9e1bb63677f3','text','{"text": "the snake which the snakecharmer kept in its box and displayed from time to time;"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_63acdcc42759','ch_9e1bb63677f3','text','{"text": "the cyclist who had not got off his bike for three days, and who kept pedalling as hard as he could from break of day;"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59955d7dc369','ch_9e1bb63677f3','text','{"text": "the rupee notes that were pinned on to his shirt to spur him on;"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58ee4c6a811c','ch_9e1bb63677f3','text','{"text": "the spinning wheels;"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f76df1c0b36a','ch_9e1bb63677f3','text','{"text": "the Maariyaata temple, the huge bell"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_573adceb208c','ch_9e1bb63677f3','text','{"text": "hanging there;"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a99ee9a854d8','ch_9e1bb63677f3','text','{"text": "the pongal offerings being cooked in front of the temple;"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a789cd270b24','ch_9e1bb63677f3','text','{"text": "the dried fish stall by the statue of Gandhi;"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1a8d5a1a1fa','ch_9e1bb63677f3','text','{"text": "the sweet stall, the stall selling fried snacks, and all the other shops next to each other;"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e37d815ec61','ch_9e1bb63677f3','text','{"text": "the street light always demonstrating how it could change from blue to violet;"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ed40134cce00','ch_9e1bb63677f3','text','{"text": "the narikkuravan huntergypsy with his wild lemur in cages, selling needles, clay beads and instruments for cleaning out the ears — Oh, I could go on and on. Each thing would pull me to a stand-still and not"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2d928becd9ad','ch_9e1bb63677f3','text','{"text": "allow me to go any further. At times, people from various political parties would arrive, put up a stage and harangue us through their mikes. Then there might be a street play, or a puppet show, or a''no magic, no miracle'' stunt performance. All these would happen from time to time. But almost certainly there would be some entertainment or other going on. Even otherwise, there were the coffee clubs in the bazaar: the way each waiter cooled the coffee, lifting a tumbler high up and pouring its"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9ca32a43f2f9','ch_9e1bb63677f3','text','{"text": "contents into a tumbler held in his other hand. Or the way some people sat in front of the shops chopping up onion, their eyes turned elsewhere so that they would not smart. Or the almond tree growing there and its fruit which was occasionally blown down by the wind. All these sights taken together would tether my legs and stop me from going home. And then, according to the season, there would be mango, cucumber, sugar-cane, sweet-potato, palm-shoots, gram, palm-syrup and palm-fruit, guavas and"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f5bffc75593','ch_9e1bb63677f3','text','{"text": "jack-fruit. Every day I would see people selling sweet and savoury fried snacks, payasam, halva, boiled tamarind seeds and iced lollies. Gazing at all this, one day, I came to my street, my bag slung over my shoulder. At the opposite corner, though, a threshing floor had been set up, and the landlord watched the proceedings, seated on a piece of sacking spread over a stone ledge. Our people were hard at work, driving cattle in pairs, round and round, to tread out the grain from the straw. The"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_870e187c8843','ch_9e1bb63677f3','text','{"text": "animals were muzzled so that they wouldn''t help themselves to the straw. I stood for a while there, watching the fun. Just then, an elder of our street came along from the direction of the bazaar. The manner in which he was walking along made me want to double up. I wanted to shriek with laughter at the sight of such a big man carrying a small packet in that fashion. I guessed there was something like vadai or green banana bhajji in the packet, because the wrapping paper was stained with oil. He"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c940253574de','ch_9e1bb63677f3','text','{"text": "came along, holding out the packet by its string, without touching it. I stood there thinking to myself, if he holds it like that, won''t the package come undone, and the vadais fall out? The elder went straight up to the landlord, bowed low and extended the packet towards him, cupping the hand that held the string with his other hand. The landlord opened the parcel and began to eat the vadais. After I had watched all this, at last I went home. My elder brother was there. I told him the story in"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3cd4a4895096','ch_9e1bb63677f3','text','{"text": "all its comic detail. I fell about with laughter at the memory of a big man, and an elder at that, making such a game out of carrying the parcel. But Annan was not amused. Annan told me the man wasn''t being funny when he carried the package like that. He said everybody believed that they were upper caste and therefore must not touch us. If they did, they would be polluted. That''s why he had to carry the package by its string. When I heard this, I didn''t want to laugh any more, and I felt"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_95f52c59e700','ch_9e1bb63677f3','text','{"text": "terribly sad. How could they believe that it was disgusting if one of us held that package in his hands, even though the vadai had been wrapped first in a banana leaf, and then parcelled in paper? I felt so provoked and angry that I wanted to touch those wretched vadais myself straightaway. Why should we have to fetch and carry for these people, I wondered. Such an important elder of ours goes meekly to the shops to fetch snacks and hands them over reverently, bowing and shrinking, to this"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43281d727804','ch_9e1bb63677f3','text','{"text": "fellow who just sits there and stuffs them into his mouth. The thought of it infuriated me. How was it that these fellows thought so much of themselves? Because they had scraped four coins together, did that mean they must lose all human feelings? But we too are human beings. Our people should never run these petty errands for these fellows. We should work in their fields, take home our wages, and leave it at that. My elder brother, who was studying at a university, had come home for the"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c4816303ae2','ch_9e1bb63677f3','text','{"text": "holidays. He would often go to the library in our neighbouring village in order to borrow books. He was on his way home one day, walking along the banks of the irrigation tank. One of the landlord''s men came up behind him. He thought my Annan looked unfamiliar, and so he asked, ''Who are you, appa, what''s your name?'' Annan told him his name. Immediately the other man asked, ''Thambi, on which street do you live?'' The point of this was that if he knew on which street we lived, he would know our"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aec1494377a5','ch_9e1bb63677f3','text','{"text": "caste too. Annan told me all these things. And he added, ''Because we are born into this community, we are never given any honour or dignity or respect;"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d01f98b15b8','ch_9e1bb63677f3','text','{"text": "we are stripped of all that. But if we study and make progress, we can throw away these indignities. So study with care, learn all you can. If you are always ahead in your lessons, people will come to you of their own accord and attach themselves to you. Work hard and learn.'' The words that Annan spoke to me that day made a very deep impression"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_efa6b0b91a48','ch_9e1bb63677f3','text','{"text": "on me. And I studied hard, with all my breath and being, in a frenzy almost. As Annan had urged, I stood first in my class. And because of that, many people became my friends."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e205c1c4899','ch_9e1bb63677f3','list','{"ordered": false, "items": ["Zitkala-Sa and Bama"]}',44);
